insert into books (volume_id, book_no, title_ml, title_ar, start_page) values (2, 16, 'ഗ്രന്ഥകർത്താവിനെക്കുറിച്ച്', null, 1021) on conflict (volume_id, book_no) do update set title_ml=excluded.title_ml, title_ar=coalesce(excluded.title_ar, books.title_ar), start_page=excluded.start_page;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 1, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: صَلَّى رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي خَمِيصَةٍ لَهَا أَعْلَامٌ، فَقَالَ: "شَغَلَنِي أَعْلَامُ هَذِهِ، اذْهَبُوا بِهَا إِلَى أَبِي جَهْمٍ، وَأْتُونِي بِأَنْبِجَانِيَّتِهِ". (ق, د, ن, جه)', 'ആഇശ(റ): റസൂൽ(സ) വരയും കുറിയുമുള്ള രോമവസ്ത്രത്തിൽ നിസ്കരിച്ചു. ശേഷം അവിടന്ന് പറഞ്ഞു: "എന്നെ ഈ വരകൾ അശ്രദ്ധമാക്കി. ഇത് നിങ്ങൾ അബൂജഹ്മിന് കൊണ്ടുപോയി കൊടുക്കൂ. എനിക്ക് അദ്ദേഹത്തിന്റെ വരകളില്ലാത്ത രോമവസ്ത്രം കൊണ്ട് വരൂ." (ബു,മു,ദ,ന,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ق','د','ن','جه']::text[], array['ബു','മു','ദ','ന','ജ']::text[], null, null, 641, 641, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 2, 'عَنْ أَبِي بُرْدَةَ بْنِ أَبِي مُوسَى الْأَشْعَرِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: دَخَلْتُ عَلَى عَائِشَةَ رَضِيَ اللهُ عَنْهَا فَأَخْرَجَتْ لِي إِزَارًا غَلِيظًا مِنَ الَّتِي تُصْنَعُ بِالْيَمَنِ، وَكِسَاءً مِنْ هَذِهِ الْأَكْسِيَةِ الَّتِي تُدْعَى الْمُلَبَّدَةَ، وَأَقْسَمَتْ لِي: لَقُبِضَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِيهِمَا. (ق, د, ت, جه)', 'അബൂബുർദബ്നു അബീ മൂസൽ അശ്അരി(റ): ഞാൻ ആഇശ(റ)യുടെ അടുത്ത് ചെന്നു. അപ്പോൾ യമനിൽ ഉണ്ടാക്കപ്പെടുന്ന പരുപരുത്ത ഒരു തുണിയും ''മുലബ്വദ'' (കട്ടിയുള്ള, പരുപരുത്ത) എന്ന് വിളിക്കപ്പെടുന്ന വസ്ത്രങ്ങളിൽപ്പെട്ട ഒരു വസ്ത്രവും മഹതി എനിക്ക് എടുത്തുതന്നു. എന്നോടവർ സത്യം ചെയ്ത് പറഞ്ഞു: ഇവ രണ്ടിലുമായിരിക്കെയാണ് റസൂൽ(സ)യുടെ റൂഹ് പിടിക്കപ്പെട്ടത്. (ബു,മു,ദ,തു,ജ)', 'أَبِي بُرْدَةَ بْنِ أَبِي مُوسَى الْأَشْعَرِيِّ', 'അബൂബുർദബ്നു അബീ മൂസൽ അശ്അരി(റ)', null, null, array['ق','د','ت','جه']::text[], array['ബു','മു','ദ','തു','ജ']::text[], null, null, 641, 641, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 3, 'عَنْ عُبَادَةَ بْنِ الصَّامِتِ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ صَلَّى فِي شَمْلَةٍ قَدْ عَقَدَ عَلَيْهَا. (جه)', 'ഉബാദതുബ്നു സ്വാമിത്(റ): നിശ്ചയം, റസൂൽ(സ) ഉടമ്പടി ചെയ്യാൻ ഉപയോഗിച്ചിരുന്ന ഒരു ചെറിയ തലപ്പാവിൽ അവിടന്ന് നിസ്കരിച്ചു. (ജ)', 'عُبَادَةَ بْنِ الصَّامِتِ', 'ഉബാദതുബ്നു സ്വാമിത്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 641, 641, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 4, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: كُنْتُ مَعَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، وَعَلَيْهِ رِدَاءٌ نَجْرَانِيٌّ، غَلِيظُ الْحَاشِيَةِ. (ق, جه)', 'അനസുബ്നു മാലിക്(റ): ഞാൻ നബി(സ)യുടെ കൂടെയിരിക്കുകയായിരുന്നു. അവിടന്ന് പരുപരുത്ത കരയുള്ള ഒരു നജ്റാനിയൻ പുതപ്പ് മേനിയിലിട്ടിരുന്നു. (ബു,മു,ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['ق','جه']::text[], array['ബു','മു','ജ']::text[], null, null, 641, 641, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 5, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: مَا رَأَيْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَسُبُّ أَحَدًا، وَلَا يُطْوَى لَهُ ثَوْبٌ. فِي سَنَدِهِ ضَعِيفٌ. (جه)', 'ആഇശ(റ): റസൂൽ(സ) ഒരാളെയും ആക്ഷേപിക്കുന്നത് ഞാൻ കണ്ടിട്ടില്ല. അവിടത്തെ വസ്ത്രം ചുരുട്ടിവെക്കപ്പെടാറുമുണ്ടായിരുന്നില്ല. പരമ്പരയിൽ ബലഹീനതയുണ്ട്. (ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 641, 641, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 6, 'عَنْ سَهْلِ بْنِ سَعْدٍ السَّاعِدِيِّ رَضِيَ اللهُ عَنْهُ: أَنَّ امْرَأَةً جَاءَتْ إِلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِبُرْدَةٍ، قَالَتْ: يَا رَسُولَ اللَّهِ، إِنِّي نَسَجْتُ هَذِهِ بِيَدِي لِأَكْسُوَكَهَا. فَأَخَذَهَا رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مُحْتَاجًا إِلَيْهَا، فَخَرَجَ عَلَيْنَا فِيهَا وَإِنَّهَا لَإِزَارُهُ، فَجَاءَ فُلَانُ بْنُ فُلَانٍ - رَجُلٌ سَمَّاهُ يَوْمَئِذٍ - فَقَالَ: يَا رَسُولَ اللَّهِ، مَا أَحْسَنَ هَذِهِ الْبُرْدَةَ! اكْسُنِيهَا. قَالَ: "نَعَمْ". فَلَمَّا دَخَلَ طَوَاهَا وَأَرْسَلَ بِهَا إِلَيْهِ، فَقَالَ لَهُ الْقَوْمُ: وَاللَّهِ مَا أَحْسَنْتَ، كُسِيَهَا النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مُحْتَاجًا إِلَيْهَا، ثُمَّ سَأَلْتَهُ إِيَّاهَا؟ وَقَدْ عَلِمْتَ أَنَّهُ لَا يَرُدُّ سَائِلًا. فَقَالَ: إِنِّي وَاللَّهِ مَا سَأَلْتُهُ إِيَّاهَا لِأَلْبَسَهَا، وَلَكِنْ سَأَلْتُهُ إِيَّاهَا لِتَكُونَ كَفَنِي. فَقَالَ سَهْلٌ: فَكَانَتْ كَفَنُهُ يَوْمَ مَاتَ. (خ,جه)', 'സഹ്‌ലുബ്‌നു സഅ്ദുസ്സാഇദി(റ): ഒരു സ്ത്രീ റസൂൽ(സ)യുടെ അടുത്ത് ഒരു പുതപ്പ് കൊണ്ടു വന്നു. അവർ പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, ഇത് ഞാൻ അങ്ങയെ ധരിപ്പിക്കാൻ വേണ്ടി എന്റെ കൈകൊണ്ട് നെയ്തുണ്ടാക്കിയതാണ്. റസൂൽ(സ) അത് ആശയോടെ സ്വീകരിച്ചു. നബി(സ) അതു ധരിച്ച് ഞങ്ങളുടെ അടുത്തുവന്നു. തിരുമേനി(സ)യുടെ അരയുടുപ്പായിരുന്നു അത്. അപ്പോൾ ഒരാൾ (അന്ന് അദ്ദേഹം പേര് പറഞ്ഞിരുന്നു) വന്നുകൊണ്ട് പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, എന്തൊരു സൗന്ദര്യമാണ് ഈ പുതപ്പിന്! അതെന്നെ ധരിപ്പിച്ചാലും. നബി(സ) പറഞ്ഞു: "അതെ" നബി(സ) വീട്ടിൽ കടന്ന് അത് മടക്കിയിട്ട് അദ്ദേഹത്തിന് കൊടുത്തയച്ചു. അദ്ദേഹത്തോട് ആളുകൾ പറഞ്ഞു: അല്ലാഹുവാണ് സത്യം! നീ ചെയ്തത് ശരിയായില്ല. നബി(സ)ക്ക് അത് ആഗ്രഹമുണ്ടായിട്ട് ധരിപ്പിക്കപ്പെട്ടതാണ്. പിന്നെ എന്തിനാണ് നിങ്ങളത് ചോദിച്ചത്? ചോദിക്കുന്ന ആരെയും അവിടുന്ന് തട്ടില്ലെന്ന് തനിക്കറിയുന്നതല്ലേ. അദ്ദേഹം പറഞ്ഞു: അല്ലാഹുവാണ് സത്യം, ഞാൻ നബി(സ)യോട് പുതപ്പ് ധരിക്കാൻ വേണ്ടി ചോദിച്ചതല്ല. ഞാൻ നബി(സ) യോട് എന്റെ കഫൻപുടയാക്കാനാണത് ചോദിച്ചത്. സഹ്‌ല്(റ) പറയുന്നു: അദ്ദേഹം മരിച്ചപ്പോൾ അതായിരുന്നു അദ്ദേഹത്തിന്റെ കഫൻപുടവ. (ബു,ജ)', 'سَهْلِ بْنِ سَعْدٍ السَّاعِدِيِّ', 'സഹ്‌ലുബ്‌നു സഅ്ദുസ്സാഇദി(റ)', null, null, array['خ','جه']::text[], array['ബു','ജ']::text[], null, null, 641, 642, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 7, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ قَالَ: لَبِسَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الصُّوفَ، وَاحْتَذَى الْمَخْصُوفَ، وَلَبِسَ ثَوْبًا خَشِنًا خَشِنًا. فِي سَنَدِهِ ضَعِيفٌ، وَمُدَلِّسٌ عَنْعَنَهُ. (جه)', 'അനസ്(റ): റസൂൽ(സ) രോമവസ്ത്രം ധരിച്ചിട്ടുണ്ട്. ചെരട് കൊണ്ട് കെട്ടി ശരിയാക്കപ്പെട്ട ചെരുപ്പ് നബി(സ) ധരിച്ചിട്ടുണ്ട്. പരുപരുത്ത വസ്ത്രവും അവിടുന്ന് ധരിച്ചിട്ടുണ്ട്. പരമ്പരയിൽ ബലഹീനനും അൻഅനാക്കിപ്പറഞ്ഞ മുദല്ലിസുമുണ്ട്. (ജ)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 642, 642, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 8, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ أَحَبُّ الثِّيَابِ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْحِبَرَةُ. حَسَنٌ صَحِيحٌ. (ق,د,ت,ن)', 'അനസ്(റ): നബി(സ)ക്ക് ഏറ്റവും ഇഷ്ടപ്പെട്ട വസ്ത്രം (പച്ചയോ നീലയോ ചുകപ്പോ) വരകളുള്ള യമനിവസ്ത്രമായിരുന്നു. (ബു,മു,ദ,തു,ന)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['ق','د','ت','ن']::text[], array['ബു','മു','ദ','തു','ന']::text[], null, null, 642, 642, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 9, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا اسْتَجَدَّ ثَوْبًا سَمَّاهُ بِاسْمِهِ، عِمَامَةً أَوْ قَمِيصًا أَوْ رِدَاءً، ثُمَّ يَقُولُ: "اللَّهُمَّ لَكَ الْحَمْدُ، أَنْتَ كَسَوْتَنِيهِ، أَسْأَلُكَ خَيْرَهُ وَخَيْرَ مَا صُنِعَ لَهُ، وَأَعُوذُ بِكَ مِنْ شَرِّهِ وَمِنْ شَرِّ مَا صُنِعَ لَهُ». حَسَنٌ صَحِيحٌ. (د،ت،ن)', 'അബൂസഈദുൽ ഖുദ്‌രി(റ): റസൂൽ(സ) പുതുവസ്ത്രം ധരിക്കുകയാണെങ്കിൽ അതിന്റെ പേര് വിളിക്കുമായിരുന്നു. തലപ്പാവെന്നോ കുപ്പായമെന്നോ പുതപ്പെന്നോ, ഏത് ധരിക്കുന്നുവോ അതിന്റെ പേര് പറയും. പിന്നെ അവിടുന്ന് പറയും: "അല്ലാഹുവേ, നിനക്കാണ് സർവസ്തുതിയും. നീ തന്നെയത് ധരിപ്പിച്ചു. അതിനാൽ നിന്നോട് അതിന്റെ നന്മയും അതു നിർമ്മിക്കപ്പെട്ടതിന്റെ നന്മയും ചോദിക്കുന്നു. അതിന്റെ തിന്മയിൽനിന്നും അത് നിർമ്മിക്കപ്പെട്ടതിന്റെ തിന്മയിൽ നിന്നും ഞാൻ നിന്നോട് കാവൽ ചോദിക്കുന്നു." (ദ,തു,ന)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദുൽ ഖുദ്‌രി(റ)', null, null, array['د','ت','ن']::text[], array['ദ','തു','ന']::text[], null, null, 642, 643, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 10, 'عَنْ أَبِي أُمَامَةَ صُدَيِّ بْنِ عَجْلَانَ البَاهِلِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: لَبِسَ عُمَرُ بْنُ الخَطَّابِ ثَوْبًا جَدِيدًا، فَقَالَ: الْحَمْدُ لِلَّهِ الَّذِي كَسَانِي مَا أُوَارِي بِهِ عَوْرَتِي، وَأَتَجَمَّلُ بِهِ فِي حَيَاتِي. ثُمَّ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "مَنْ لَبِسَ ثَوْبًا جَدِيدًا فَقَالَ: الْحَمْدُ لِلَّهِ الَّذِي كَسَانِي مَا أُوَارِي بِهِ عَوْرَتِي وَأَتَجَمَّلُ بِهِ فِي جَلْوَتِي. ثُمَّ عَمَدَ إِلَى الثَّوْبِ الَّذِي أَخْلَقَ - أَوْ: أَلْقَى - فَتَصَدَّقَ بِهِ، كَانَ فِي كَنَفِ اللَّهِ وَفِي حِفْظِ اللَّهِ وَفِي سِتْرِ اللَّهِ، حَيًّا وَمَيِّتًا". قَالَهَا ثَلَاثًا. (ت،جه)', 'അബൂഉമാമ സുദയ്യുബ്‌നു ഇജ്‌ലാനിൽ ബാഹിലി(റ): ഉമറുബ്‌നുൽ ഖത്താബ്(റ) ഒരു പുതുവസ്ത്രം ധരിച്ചു. അന്നേരം അദ്ദേഹം പറഞ്ഞു: എന്റെ ഔറത്ത് മറക്കുന്നതും എന്റെ ജീവിതത്തിൽ ഞാൻ സൗന്ദര്യം സ്വീകരിക്കുന്നതുമായത് എന്നെ ധരിപ്പിച്ച അല്ലാഹുവിനാണ് സർവ്വസ്തുതിയും. പിന്നീട് അദ്ദേഹം പറഞ്ഞു: റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടു: "ആരെങ്കിലും പുതുവസ്ത്രം ധരിച്ച്, ഞാൻ ഔറത്ത് മറക്കുന്നതും എന്റെ കാഴ്ചയിൽ ഞാൻ സൗന്ദര്യം സ്വീകരിക്കുകയും ചെയ്യുന്നത് എന്നെ ധരിപ്പിച്ച അല്ലാഹുവിനാണ് സർവ്വസ്തുതിയും എന്ന് പറയുകയും പിന്നീട് നുരുമ്പുകയോ ഒഴിവാക്കുകയോ ചെയ്ത വസ്ത്രം ദാനം ചെയ്യുകയും ചെയ്താൽ അവൻ ജീവിക്കുമ്പോഴും മരിക്കുമ്പോഴും അല്ലാഹുവിന്റെ സംരക്ഷണത്തിലും കാവലിലും, മറയിലുമായിരിക്കും". നബി(സ) അത് മൂന്ന് പ്രാവശ്യം പറഞ്ഞു. (തു,ജ)', 'أَبِي أُمَامَةَ صُدَيِّ بْنِ عَجْلَانَ البَاهِلِيِّ', 'അബൂഉമാമ സുദയ്യുബ്‌നു ഇജ്‌ലാനിൽ ബാഹിലി(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 643, 643, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 11, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَأَى عَلَى عُمَرَ قَمِيصًا أَبْيَضَ، فَقَالَ: "ثَوْبُكَ هَذَا غَسِيلٌ أَمْ جَدِيدٌ؟". قَالَ: لَا، بَلْ غَسِيلٌ. قَالَ: "اِلْبَسْ جَدِيدًا، وَعِشْ حَمِيدًا، وَمُتْ شَهِيدًا". (جه)', 'ഇബ്‌നുഉമർ(റ): ഉമർ(റ) വെള്ള വസ്ത്രം ധരിച്ചിരിക്കുന്നത് നബി(സ) കണ്ടു. അവിടുന്ന് ചോദിച്ചു: "താങ്കളുടെ ഈ വസ്ത്രം കഴുകിയതാണോ അതോ പുതിയതാണോ?" ഉമർ(റ) പറഞ്ഞു: അല്ല, കഴുകിയതാണ്. റസൂൽ(സ) പറഞ്ഞു: "താങ്കൾ പുതിയത് ധരിക്കുക. സ്തുത്യർഹനായി ജീവിക്കുക, ശഹീദായി മരിക്കുക." (ജ)', 'ابْنِ عُمَرَ', 'ഇബ്‌നുഉമർ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 643, 643, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 12, 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ أَكَلَ طَعَامًا، ثُمَّ قَالَ: الْحَمْدُ لِلَّهِ الَّذِي أَطْعَمَنِي هَذَا الطَّعَامَ وَرَزَقَنِيهِ، مِنْ غَيْرِ حَوْلٍ مِنِّي وَلَا قُوَّةٍ، غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ وَمَا تَأَخَّرَ. وَمَنْ لَبِسَ ثَوْبًا فَقَالَ: الْحَمْدُ لِلَّهِ الَّذِي كَسَانِي هَذَا الثَّوْبَ وَرَزَقَنِيهِ، مِنْ غَيْرِ حَوْلٍ مِنِّي وَلَا قُوَّةٍ، غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ وَمَا تَأَخَّرَ". (د،ت،جه)', 'അനസ്(റ): റസൂൽ(സ) പറഞ്ഞു: "ആരെങ്കിലും ഭക്ഷണം കഴിച്ച് ''എന്റെ ഒരു ശക്തിയോ കഴിവോ കൂടാതെ ഈ ഭക്ഷണം എന്നെ ഭക്ഷിപ്പിക്കുകയും എനിക്ക് നൽകുകയും ചെയ്ത അല്ലാഹുവിനാണ് സർവ്വസ്തുതിയും'' എന്ന് പറഞ്ഞാൽ അവന്റെ മുൻകഴിഞ്ഞതും ശേഷം വരാനിരിക്കുന്നതുമായ ദോഷങ്ങൾ പൊറുക്കപ്പെടും. ആരെങ്കിലും വസ്ത്രം ധരിച്ച് ''എന്റെ ഒരു കഴിവോ ശക്തിയോ കൂടാതെ ഈ വസ്ത്രം എന്നെ ധരിപ്പിക്കുകയും എനിക്ക് നൽകുകയും ചെയ്ത അല്ലാഹുവിനാണ് സർവസ്തുതിയും'' എന്ന് പറഞ്ഞാൽ അവന്റെ മുൻകഴിഞ്ഞതും ചെയ്യാനിരിക്കുന്നതുമായ ദോഷങ്ങൾ പൊറുക്കപ്പെടും." (ദ,തു,ജ)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 643, 644, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 13, 'عَنْ أُمِّ خَالِدٍ بِنْتِ خَالِدِ بْنِ سَعِيدِ بْنِ الْعَاصِ رَضِيَ اللهُ عَنْهَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أُتِيَ بِكُسْوَةٍ فِيهَا خَمِيصَةٌ صَغِيرَةٌ، فَقَالَ: "مَنْ تَرَوْنَ أَحَقَّ بِهَذِهِ". فَسَكَتَ الْقَوْمُ، فَقَالَ: "ائْتُونِي بِأُمِّ خَالِدٍ". فَأُتِيَ بِهَا، فَأَلْبَسَهَا إِيَّاهَا، ثُمَّ قَالَ: "أَبْلِي وَأَخْلِقِي" مَرَّتَيْنِ، وَجَعَلَ يَنْظُرُ إِلَى عَلَمٍ فِي الْخَمِيصَةِ أَحْمَرَ أَوْ أَصْفَرَ وَيَقُولُ: "سَنَاهْ سَنَاهْ يَا أُمَّ خَالِدٍ". وَسَنَاهْ فِي كَلَامِ الْحَبَشَةِ: الْحَسَنُ. (خ,د)', 'ഉമ്മുഖാലിദ് ബിൻത് ഖാലിദുബ്നി സഈദുബ്നുൽ ആസ്(റ): റസൂൽ(സ)ക്ക് കുറച്ച് വസ്ത്രങ്ങൾ കൊണ്ടുവന്നു. അതിൽ വർണ്ണാഭമായ വരകളുള്ള ഒരു ചെറിയ വസ്ത്രവുമുണ്ട്. റസൂൽ(സ) ചോദിച്ചു: "ഇതിന് ഏറ്റവും അർഹനായി നിങ്ങൾ ആരെയാണ് കാണുന്നത്?" ജനങ്ങൾ ഒന്നും മിണ്ടിയില്ല. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങൾ ഉമ്മുഖാലിദിനെ കൊണ്ടുവരൂ." അവരെ കൊണ്ടുവന്നു. അപ്പോൾ അവിടുന്ന് അവരെ ആ വസ്ത്രം ധരിപ്പിച്ചു. ശേഷം റസൂൽ(സ) പറഞ്ഞു: "പഴകി നുരുമ്പുംവരെ നീയത് ഉപയോഗിക്കുക." രണ്ട് പ്രാവശ്യം അതാവർത്തിച്ചു. നബി(സ) വസ്ത്രത്തിന്റെ ചുവപ്പോ മഞ്ഞയോ നിറമുള്ള വരകളിലേക്ക് നോക്കാൻ തുടങ്ങി. എന്നിട്ട് പറഞ്ഞു: "ഉമ്മുഖാലിദേ, നന്നായിട്ടുണ്ട്, നന്നായിട്ടുണ്ട്." അബ്സീനിയൻ ഭാഷയിൽ ''സനാഹ്'' എന്നതിന്റെ അർത്ഥം നല്ലത് എന്നാണ്. (ബു,ദ)', 'أُمِّ خَالِدٍ بِنْتِ خَالِدِ بْنِ سَعِيدِ بْنِ الْعَاصِ', 'ഉമ്മുഖാലിദ് ബിൻത് ഖാലിദുബ്നി സഈദുബ്നുൽ ആസ്(റ)', null, null, array['خ','د']::text[], array['ബു','ദ']::text[], null, null, 644, 644, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 14, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "اِلْبَسُوا مِنْ ثِيَابِكُمُ الْبَيَاضَ، فَإِنَّهَا مِنْ خَيْرِ ثِيَابِكُمْ، وَكَفِّنُوا فِيهَا مَوْتَاكُمْ. وَإِنَّ خَيْرَ أَكْحَالِكُمُ الْإِثْمِدُ: يَجْلُو الْبَصَرَ، وَيُنْبِتُ الشَّعْرَ". (د,ت,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങൾ വെള്ള വസ്ത്രം ധരിക്കുക. കാരണം അതാണ് നിങ്ങളുടെ വസ്ത്രങ്ങളിൽ ഏറ്റവും ഉത്തമമായത്. നിങ്ങളിൽ നിന്ന് മരിച്ചവരെ വെള്ള വസ്ത്രത്തിൽ കഫൻ ചെയ്യുക. നിങ്ങൾ ഉപയോഗിക്കുന്ന സുറുമകളിൽ ഏറ്റവും ഉത്തമം നീല അഞ്ജനക്കല്ലാണ്. അത് കാഴ്ചശക്തി നൽകുകയും രോമം വളർത്തുകയും ചെയ്യും." (ദ,തു,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 644, 644, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 15, 'عَنْ سَمُرَةَ بْنِ جُنْدَبٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "اِلْبَسُوا ثِيَابَ الْبَيَاضِ، فَإِنَّهَا أَطْهَرُ وَأَطْيَبُ". (ت,جه)', 'സമുറതുബ്നു ജുൻദുബ്(റ): റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങൾ വെള്ള വസ്ത്രം ധരിക്കുക. അത് ഏറ്റവും ശുദ്ധവും നല്ലതുമാണ്." (തു,ജ)', 'سَمُرَةَ بْنِ جُنْدَبٍ', 'സമുറതുബ്നു ജുൻദുബ്(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 644, 644, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 16, 'عَنْ أَبِي الدَّرْدَاءِ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ أَحْسَنَ مَا زُرْتُمُ اللهَ بِهِ فِي قُبُورِكُمْ وَمَسَاجِدِكُمُ الْبَيَاضُ". فِي سَنَدِهِ انْقِطَاعٌ. (جه)', 'അബുദ്ദർദാഅ്(റ): റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങളുടെ ഖബ്റുകളിലും പള്ളികളിലും നിങ്ങൾ അല്ലാഹുവിനെ സന്ദർശിക്കുന്നതിനേറ്റവും നല്ലത് വെള്ള വസ്ത്രമാണ്." പരമ്പരയിൽ ''ഇൻഖിതാഉ''ണ്ട്. (ജ)', 'أَبِي الدَّرْدَاءِ', 'അബുദ്ദർദാഅ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 644, 644, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 17, 'عَنْ أَبِي ذَرٍّ رَضِيَ اللهُ عَنْهُ قَالَ: أَتَيْتُ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَعَلَيْهِ ثَوْبٌ أَبْيَضُ وَهُوَ نَائِمٌ، ثُمَّ أَتَيْتُهُ وَقَدِ اسْتَيْقَظَ، فَقَالَ: "مَا مِنْ عَبْدٍ قَالَ: لَا إِلَهَ إِلَّا اللهُ، ثُمَّ مَاتَ عَلَى ذَلِكَ إِلَّا دَخَلَ الْجَنَّةَ". قُلْتُ: وَإِنْ زَنَى وَإِنْ سَرَقَ؟ قَالَ: "وَإِنْ زَنَى وَإِنْ سَرَقَ". قُلْتُ: وَإِنْ زَنَى وَإِنْ سَرَقَ؟ قَالَ: "وَإِنْ زَنَى وَإِنْ سَرَقَ". قُلْتُ: وَإِنْ زَنَى وَإِنْ سَرَقَ؟ قَالَ: "وَإِنْ زَنَى وَإِنْ سَرَقَ". عَلَى رَغْمِ أَنْفِ أَبِي ذَرٍّ، وَكَانَ أَبُو ذَرٍّ إِذَا حَدَّثَ بِهَذَا، قَالَ: وَإِنْ رَغِمَ أَنْفُ أَبِي ذَرٍّ. (خ)', 'അബൂദർറ്(റ): ഞാൻ നബി(സ)യുടെ അടുക്കൽ ചെന്നു. നബി(സ) വെള്ള വസ്ത്രം ധരിച്ച് ഉറങ്ങുകയാണ്. പിന്നീട് നബി(സ) ഉണർന്നപ്പോൾ ഞാനവിടെ ചെന്നു. അപ്പോൾ അവിടുന്ന് പറഞ്ഞു: "അല്ലാഹു അല്ലാതെ ഒരു ആരാധ്യനില്ലെന്ന് ഒരു അടിമ പറയുകയും അപ്രകാരം മരിക്കുകയും ചെയ്താൽ അവൻ സ്വർഗ്ഗത്തിൽ പ്രവേശിക്കുന്നതാണ്." ഞാൻ ചോദിച്ചു: അവൻ വ്യഭിചരിച്ചാലും മോഷ്ടിച്ചാലും? റസൂൽ(സ) പറഞ്ഞു: "അതെ, അവൻ വ്യഭിചരിച്ചാലും മോഷ്ടിച്ചാലും." ഞാൻ വീണ്ടും ചോദിച്ചു: അവൻ വ്യഭിചരിച്ചാലും മോഷ്ടിച്ചാലും? റസൂൽ(സ) പറഞ്ഞു: "അവൻ വ്യഭിചരിച്ചാലും മോഷ്ടിച്ചാലും." വീണ്ടും ഞാൻ ചോദിച്ചു: അവൻ വ്യഭിചരിച്ചാലും മോഷ്ടിച്ചാലും? തിരുമേനി(സ) പറഞ്ഞു: "അവൻ വ്യഭിചരിക്കുകയും മോഷ്ടിക്കുകയും ചെയ്തിട്ടുണ്ടെങ്കിലും ശരി." അബൂദർറിനത് ഇഷ്ടപ്പെട്ടിട്ടില്ലെങ്കിലും വിരോധമില്ല. ഈ ഹദീസ് ഉധരിക്കുമ്പോൾ ''അബൂദർറിനത് ഇഷ്ടപ്പെട്ടിട്ടില്ലെങ്കിലും'' എന്ന് അബൂദർറ്(റ) പറയുമായിരുന്നു. (ബു)', 'أَبِي ذَرٍّ', 'അബൂദർറ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 645, 645, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 18, 'عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا يَنْظُرُ اللَّهُ يَوْمَ الْقِيَامَةِ إِلَى مَنْ جَرَّ ثَوْبَهُ خُيَلَاءَ". حَسَنٌ صَحِيحٌ. (ق, د, ت, ن, جه)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): റസൂൽ(സ) പറഞ്ഞു: "അഹങ്കാരപൂർവം വസ്ത്രം നിലത്ത് വലിച്ചവനെ അന്ത്യനാളിൽ അല്ലാഹു നോക്കുകയില്ല." (ബു,മു,ദ,തു,ന,ജ)', 'عَبْدِ اللَّهِ بْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 645, 645, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 19, 'عَنْ أَبِي سَعِيدٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ جَرَّ إِزَارَهُ مِنَ الْخُيَلَاءِ لَمْ يَنْظُرِ اللَّهُ إِلَيْهِ يَوْمَ الْقِيَامَةِ". قَالَ: فَلَقِيتُ ابْنَ عُمَرَ بِالْبَلَاطِ، فَذَكَرْتُ لَهُ حَدِيثَ أَبِي سَعِيدٍ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ، وَأَشَارَ إِلَى أُذُنَيْهِ: سَمِعَتْهُ أُذُنَايَ، وَوَعَاهُ قَلْبِي. في سنده ضعيف. (جه)', 'അബൂസഈദ്(റ): നബി(സ) പറഞ്ഞു: "അഹങ്കാരത്തോടെ ഒരാൾ തന്റെ തുണി വലിച്ചിഴച്ചാൽ അന്ത്യനാളിൽ അല്ലാഹു അവനെ നോക്കുകയില്ല." അദ്ദേഹം പറയുന്നു: ഞാൻ ഇബ്നുഉമർ(റ)വിനെ ബലാഥിൽ വെച്ച് കണ്ടുമുട്ടി. ഞാനദ്ദേഹത്തിന് നബി(സ)യിൽ നിന്നുള്ള അബൂസഈദ്(റ)വിന്റെ ഹദീസ് പറഞ്ഞുകൊടുത്തു. തന്റെ ചെവിയിലേക്ക് ആംഗ്യം കാണിച്ച് കൊണ്ട് അദ്ദേഹം പറഞ്ഞു: അത് എന്റെ രണ്ട് ചെവികൾ കേൾക്കുകയും എന്റെ ഹൃദയം സൂക്ഷിക്കുകയും ചെയ്തിരിക്കുന്നു. പരമ്പരയിൽ ബലഹീനനുണ്ട്. (ജ)', 'أَبِي سَعِيدٍ', 'അബൂസഈദ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 645, 645, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 20, 'عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "بَيْنَا رَجُلٌ يَجُرُّ إِزَارَهُ مِنَ الْخُيَلَاءِ خُسِفَ بِهِ، فَهُوَ يَتَجَلْجَلُ فِي الْأَرْضِ إِلَى يَوْمِ الْقِيَامَةِ". (ن)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): റസൂൽ(സ) പറഞ്ഞു: "അഹങ്കാരത്തോടെ ഒരാൾ തന്റെ തുണി വലിച്ചിഴക്കുന്നതിനിടക്ക് അവനെ ഭൂമി വിഴുങ്ങി, അവൻ അന്ത്യദിനം വരെ ഭൂമിയിൽ താഴ്ന്നുകൊണ്ടിരിക്കും." (ന)', 'عَبْدِ اللَّهِ بْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 645, 645, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 21, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِنَّ اللهَ عَزَّ وَجَلَّ لَا يَنْظُرُ إِلَى مُسْبِلِ الْإِزَارِ". (ن)', 'ഇബ്‌നുഅബ്ബാസ്(റ): നബി(സ) പറഞ്ഞു: "തുണി ഞെരിയാണിക്ക് താഴെ താഴ്ത്തുന്നവനിലേക്ക് അല്ലാഹു നോക്കുകയില്ല." (ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്‌നുഅബ്ബാസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 646, 646, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 22, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "الْإِسْبَالُ فِي الْإِزَارِ وَالْقَمِيصِ وَالْعِمَامَةِ، مَنْ جَرَّ مِنْهَا شَيْئًا خُيَلَاءَ لَا يَنْظُرُ اللَّهُ إِلَيْهِ يَوْمَ الْقِيَامَةِ". (د،ن،جه)', 'ഇബ്‌നുഉമർ(റ): നബി(സ) പറഞ്ഞു: "വലിച്ചിഴക്കൽ തുണിയിലും ഖമീസിലും തലപ്പാവിലും ബാധകമാണ്. ആരെങ്കിലും അഹങ്കാരപൂർവ്വം ഇവയിൽ ഏതെങ്കിലും വലിച്ചിഴച്ചാൽ അല്ലാഹു അവനെ അന്ത്യദിനത്തിൽ നോക്കുകയില്ല." (ദ,ന,ജ)', 'ابْنِ عُمَرَ', 'ഇബ്‌നുഉമർ(റ)', null, null, array['د','ن','جه']::text[], array['ദ','ന','ജ']::text[], null, null, 646, 646, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 23, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ جَرَّ ثَوْبَهُ مِنَ الْخُيَلَاءِ لَا يَنْظُرُ اللَّهُ إِلَيْهِ يَوْمَ الْقِيَامَةِ". قَالَ أَبُو بَكْرٍ رَضِيَ اللَّهُ عَنْهُ: يَا رَسُولَ اللَّهِ، إِنَّ أَحَدَ شِقَّيْ إِزَارِي يَسْتَرْخِي إِلَّا أَنْ أَتَعَاهَدَ ذَلِكَ مِنْهُ؟ فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِنَّكَ لَسْتَ مِمَّنْ يَصْنَعُ ذَلِكَ خُيَلَاءَ". (ن)', 'ഇബ്‌നുഉമർ(റ): നബി(സ) പറഞ്ഞു: "അഹങ്കാരത്തോടെ ആരെങ്കിലും തന്റെ വസ്ത്രം വലിച്ചിഴച്ചാൽ അന്ത്യനാളിൽ അവനെ അല്ലാഹു നോക്കുകയില്ല." അബൂബക്കർ(റ) പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, എന്റെ തുണിയുടെ രണ്ടുഭാഗങ്ങളിൽ ഒരു ഭാഗം ഞാനത് സൂക്ഷിച്ചില്ലെങ്കിൽ താഴും. അപ്പോൾ നബി(സ) പറഞ്ഞു: "നിങ്ങളത് അഹങ്കാരത്തോടെ ചെയ്യുന്നവരിൽപ്പെട്ടവരല്ല." (ന)', 'ابْنِ عُمَرَ', 'ഇബ്‌നുഉമർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 646, 646, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 24, 'عَنْ جَابِرِ بْنِ سُلَيْمٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: رَأَيْتُ رَجُلًا يَصْدُرُ النَّاسُ عَنْ رَأْيِهِ، لَا يَقُولُ شَيْئًا إِلَّا صَدَرُوا عَنْهُ، قُلْتُ: مَنْ هَذَا؟ قَالُوا: هَذَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، قُلْتُ: عَلَيْكَ السَّلَامُ يَا رَسُولَ اللَّهِ، مَرَّتَيْنِ، قَالَ: "لَا تَقُلْ: عَلَيْكَ السَّلَامُ، فَإِنَّ عَلَيْكَ السَّلَامُ تَحِيَّةُ الْمَيِّتِ، قُلِ: السَّلَامُ عَلَيْكَ". قَالَ: قُلْتُ: أَنْتَ رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ؟ قَالَ: "أَنَا رَسُولُ اللَّهِ الَّذِي إِذَا أَصَابَكَ ضُرٌّ فَدَعَوْتَهُ كَشَفَهُ عَنْكَ، وَإِنْ أَصَابَكَ عَامُ سَنَةٍ فَدَعَوْتَهُ أَنْبَتَهَا لَكَ، وَإِذَا كُنْتَ بِأَرْضٍ قَفْرَاءَ أَوْ فَلَاةٍ فَضَلَّتْ رَاحِلَتُكَ فَدَعَوْتَهُ رَدَّهَا عَلَيْكَ". قَالَ: قُلْتُ: اعْهَدْ إِلَيَّ، قَالَ: "لَا تَسُبَّنَّ أَحَدًا"، قَالَ: فَمَا سَبَبْتُ بَعْدَهُ حُرًّا وَلَا عَبْدًا وَلَا بَعِيرًا وَلَا شَاةً، قَالَ: "وَلَا تَحْقِرَنَّ شَيْئًا مِنَ الْمَعْرُوفِ، وَأَنْ تُكَلِّمَ أَخَاكَ وَأَنْتَ مُنْبَسِطٌ إِلَيْهِ وَجْهُكَ، إِنَّ ذَلِكَ مِنَ الْمَعْرُوفِ. وَارْفَعْ إِزَارَكَ إِلَى نِصْفِ السَّاقِ، فَإِنْ أَبَيْتَ فَإِلَى الْكَعْبَيْنِ، وَإِيَّاكَ وَإِسْبَالَ الْإِزَارِ فَإِنَّهَا مِنَ الْمَخِيلَةِ، وَإِنَّ اللَّهَ لَا يُحِبُّ الْمَخِيلَةَ. وَإِنِ امْرُؤٌ شَتَمَكَ وَعَيَّرَكَ بِمَا يَعْلَمُ فِيكَ فَلَا تُعَيِّرْهُ بِمَا تَعْلَمُ فِيهِ، فَإِنَّمَا وَبَالُ ذَلِكَ عَلَيْهِ". (د،ت)', 'ജാബിറുബ്‌നു സുലൈം(റ): ജനങ്ങൾ പൂർണ്ണമായും അഭിപ്രായം അംഗീകരിക്കുന്ന ഒരു മനുഷ്യനെ ഞാൻ കണ്ടു. അദ്ദേഹം പറയുന്നതെല്ലാം ജനങ്ങൾ സ്വീകരിക്കുന്നുണ്ട്. ഞാൻ ചോദിച്ചു: ഇതാരാണ്? അവർ പറഞ്ഞു: ഇത് അല്ലാഹുവിന്റെ ദൂതരാണ്. ഞാൻ രണ്ട് പ്രാവശ്യം ''അല്ലാഹുവിന്റെ റസൂലേ, അലൈക്കസ്സലാം'' എന്നുപറഞ്ഞു. നബി(സ) പറഞ്ഞു: "നിങ്ങൾ ''അലൈക്കസ്സലാം'' എന്നു പറയരുത്. ''അലൈക്കസ്സലാം'' എന്നത് മയ്യിത്തിനുള്ള അഭിവാദ്യമാകുന്നു. നിങ്ങൾ ''അസ്സലാമു അലൈക്ക'' എന്ന് പറയുക." ഞാൻ ചോദിച്ചു: നിങ്ങൾ അല്ലാഹുവിന്റെ റസൂലാണോ? നബി(സ) പറഞ്ഞു: "നിങ്ങൾക്ക് വല്ല ബുദ്ധിമുട്ട് വരികയും നിങ്ങളവനെ വിളിക്കുകയും ചെയ്താൽ നിങ്ങളുടെ ബുദ്ധിമുട്ട് നീക്കിത്തരുന്ന, നിങ്ങൾക്ക് ഒരു ക്ഷാമകാലം വരികയും നിങ്ങളവനെ വിളിക്കുകയും ചെയ്താൽ നിങ്ങൾക്ക് ഐശ്വര്യം നൽകുന്ന, നിങ്ങളൊരു തരിശുഭൂമിയിലോ മരുഭൂമിയിലോ ആകുകയും നിങ്ങളുടെ വാഹനം നഷ്ടപ്പെടുകയും നിങ്ങളവനെ വിളിക്കുകയും ചെയ്താൽ നിങ്ങളുടെ വാഹനം തിരിച്ച് നൽകുന്നവനായ അല്ലാഹുവിന്റെ ദൂതനാണ് ഞാൻ.'''' ഞാൻ പറഞ്ഞു: അങ്ങെന്നോട് കരാർചെയ്യുക. നബി(സ) പറഞ്ഞു: “താങ്കളാരെയും ഒരിക്കലും ആക്ഷേപിക്കരുത്.'''' നിവേദകൻ പറയുന്നു: അതിന് ശേഷം ഒരു സ്വതന്ത്രനെയോ അടിമയെയോ ഒട്ടകത്തെയോ ആടിനെയോ ഞാൻ ചീത്തപറഞ്ഞിട്ടില്ല. നബി(സ) പറഞ്ഞു: "നിങ്ങൾ ഒരു നന്മയും നിസ്സാരമാക്കരുത്. നിന്റെ സഹോദരനോട് പുഞ്ചിരിക്കുന്ന മുഖത്തോടെ സംസാരിക്കുക. അത് നന്മയാണ്. കണങ്കാലിന്റെ പകുതിവരെ നിങ്ങൾ തുണി ഉയർത്തുക. അതിന് നിങ്ങൾക്ക് കഴിയില്ലെങ്കിൽ ഞെരിയാണി വരെ. തുണി ഞെരിയാണിക്ക് താഴെ താഴുന്നത് നിങ്ങൾ സൂക്ഷിക്കുക. അത് അഹങ്കാരമാണ്. അല്ലാഹു അഹങ്കാരം ഇഷ്ടപ്പെടുന്നില്ല. ആരെങ്കിലും നിങ്ങളെ ആക്ഷേപിക്കുകയോ അവനറിയുന്ന താങ്കളുടെ ന്യൂനതകൾ വെളിവാക്കുകയോ ചെയ്താൽ നിങ്ങളറിയുന്ന അവനിലെ ന്യൂനതകൾ നിങ്ങൾ വെളിപ്പെടുത്തരുത്. കാരണം അതിന്റെ നാശം അവന് മാത്രമാണ്.'''' (ദ,തു)', 'جَابِرِ بْنِ سُلَيْمٍ', 'ജാബിറുബ്‌നു സുലൈം(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 646, 647, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 25, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: بَيْنَمَا رَجُلٌ يُصَلِّي مُسْبِلًا إِزَارَهُ، فَقَالَ لَهُ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "اذْهَبْ فَتَوَضَّأْ". فَذَهَبَ فَتَوَضَّأَ، ثُمَّ جَاءَ، فَقَالَ: "اذْهَبْ فَتَوَضَّأْ". فَقَالَ لَهُ رَجُلٌ: يَا رَسُولَ اللهِ، مَا لَكَ أَمَرْتَهُ أَنْ يَتَوَضَّأَ؟ ثُمَّ سَكَتَّ عَنْهُ، قَالَ: "إِنَّهُ كَانَ يُصَلِّي وَهُوَ مُسْبِلٌ إِزَارَهُ، وَإِنَّ اللهَ لَا يَقْبَلُ صَلَاةَ رَجُلٍ مُسْبِلٍ". (د)', 'അബൂഹുറൈറ(റ): ഒരാൾ തുണി വലിച്ചിഴച്ച് നിസ്കരിക്കുമ്പോൾ അയാളോട് റസൂൽ(സ) പറഞ്ഞു: “നിങ്ങൾ പോയി വുളു ചെയ്യുക.'''' അയാൾ പോയി വുളു ചെയ്തു. പിന്നെ അയാൾ വന്നു. നബി(സ) പറഞ്ഞു: “നിങ്ങൾ പോയി വുളു ചെയ്യുക.'''' അപ്പോൾ നബി(സ)യോട് ഒരാൾ ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, അങ്ങെന്താണ് അദ്ദേഹത്തോട് വുളു ചെയ്യാൻ കൽപിച്ചത്? പിന്നെ അവിടുന്ന് മൗനവലംബിച്ചു. നബി(സ) പറഞ്ഞു: “അയാൾ തുണി വലിച്ചിഴച്ച് നിസ്കരിക്കുകയായിരുന്നു. തുണി വലിച്ചിഴച്ചവന്റെ നിസ്കാരം അല്ലാഹു സ്വീകരിക്കുകയില്ല.'''' (ദ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 647, 647, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 26, 'عَنْ أَبِي ذَرٍّ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ قَالَ: "ثَلَاثَةٌ لَا يُكَلِّمُهُمُ اللهُ، وَلَا يَنْظُرُ إِلَيْهِمْ يَوْمَ الْقِيَامَةِ، وَلَا يُزَكِّيهِمْ، وَلَهُمْ عَذَابٌ أَلِيمٌ". قُلْتُ: مَنْ هُمْ يَا رَسُولَ اللهِ، قَدْ خَابُوا وَخَسِرُوا؟ فَأَعَادَهَا ثَلَاثًا، قُلْتُ: مَنْ هُمْ يَا رَسُولَ اللهِ، خَابُوا وَخَسِرُوا؟ فَقَالَ: "الْمُسْبِلُ، وَالْمَنَّانُ، وَالْمُنْفِقُ سِلْعَتَهُ بِالْحَلِفِ الْكَاذِبِ. أَوْ: الْفَاجِرِ". وَفِي رِوَايَةٍ قَالَ: "الْمَنَّانُ الَّذِي لَا يُعْطِي شَيْئًا إِلَّا مَنَّهُ". (م،د،ت،ن،جه)', 'അബൂദർറ്(റ): നബി(സ) പറഞ്ഞു: “മൂന്ന് പേരോട് അന്ത്യദിനത്തിൽ അല്ലാഹു സംസാരിക്കുകയോ അവരിലേക്ക് നോക്കുകയോ അവരെ സംസ്കരിക്കുകയോ ചെയ്യുകയില്ല. അവർക്ക് വേദനാജനകമായ ശിക്ഷയുമുണ്ട്.'''' ഞാൻ ചോദിച്ചു: അവരാരാണ്? അല്ലാഹുവിന്റെ റസൂലേ! തീർച്ചയായും അവർ നിരാശരായവരും പരാജയപ്പെട്ടവരുമാണ്. അവിടുന്ന് അത് മൂന്നാവർത്തി പറഞ്ഞു. ഞാൻ ചോദിച്ചു: അവരാരാണ് അല്ലാഹുവിന്റെ റസൂലേ? അവർ നിരാശരായവരും പരാജയപ്പെട്ടവരുമാണല്ലോ? നബി(സ) പറഞ്ഞു: “തുണി ഞെരിയാണിക്ക് താഴെയിറക്കുന്നവൻ, ചെയ്ത നന്മ എടുത്തുപറയുന്നവൻ, കള്ള സത്യം ചെയ്ത് ചരക്ക് വിൽക്കുന്നവൻ. മറ്റൊരു നിവേദനത്തിൽ: ''മന്നാൻ'' എന്നാൽ കൊടുത്തതെല്ലാം എടുത്ത് പറയുന്നവനാണ്.'''' (മു,ദ,തു,ന,ജ)', 'أَبِي ذَرٍّ', 'അബൂദർറ്(റ)', null, null, array['م','د','ت','ن','جه']::text[], array['മു','ദ','തു','ന','ജ']::text[], null, null, 647, 647, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=8 and h.hadith_no=26), 1, 'وَفِي رِوَايَةٍ قَالَ: "الْمَنَّانُ الَّذِي لَا يُعْطِي شَيْئًا إِلَّا مَنَّهُ". (م،د،ت،ن،جه)', 'മറ്റൊരു നിവേദനത്തിൽ: ''മന്നാൻ'' എന്നാൽ കൊടുത്തതെല്ലാം എടുത്ത് പറയുന്നവനാണ്.'''' (മു,ദ,തു,ന,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 27, 'عَنْ قَيْسِ بْنِ بِشْرٍ التَّغْلِبِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: أَخْبَرَنِي أَبِي - وَكَانَ جَلِيسًا لِأَبِي الدَّرْدَاءِ رَضِيَ اللهُ عَنْهُ - قَالَ: كَانَ بِدِمَشْقَ رَجُلٌ مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُقَالُ لَهُ ابْنُ الْحَنْظَلِيَّةِ، وَكَانَ رَجُلًا مُتَوَحِّدًا قَلَّمَا يُجَالِسُ النَّاسَ، إِنَّمَا هُوَ صَلَاةٌ، فَإِذَا فَرَغَ فَإِنَّمَا هُوَ تَسْبِيحٌ وَتَكْبِيرٌ حَتَّى يَأْتِيَ أَهْلَهُ، فَمَرَّ بِنَا وَنَحْنُ عِنْدَ أَبِي الدَّرْدَاءِ، فَقَالَ لَهُ أَبُو الدَّرْدَاءِ: كَلِمَةً تَنْفَعُنَا وَلَا تَضُرُّكَ. قَالَ: بَعَثَ رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ سَرِيَّةً، فَقَدِمَتْ، فَجَاءَ رَجُلٌ مِنْهُمْ فَجَلَسَ فِي الْمَجْلِسِ الَّذِي يَجْلِسُ فِيهِ رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ لِرَجُلٍ إِلَى جَنْبِهِ: لَوْ رَأَيْتَنَا حِينَ الْتَقَيْنَا نَحْنُ وَالْعَدُوُّ، فَحَمَلَ فُلَانٌ فَطَعَنَ، فَقَالَ: خُذْهَا مِنِّي وَأَنَا الْغُلَامُ الْغِفَارِيُّ، كَيْفَ تَرَى فِي قَوْلِهِ؟ قَالَ: مَا أَرَاهُ إِلَّا قَدْ بَطَلَ أَجْرُهُ، فَسَمِعَ بِذَلِكَ آخَرُ، فَقَالَ: مَا أَرَى بِذَلِكَ بَأْسًا، فَتَنَازَعَا حَتَّى سَمِعَ رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: "سُبْحَانَ اللَّهِ، لَا بَأْسَ أَنْ يُؤْجَرَ وَيُحْمَدَ". فَرَأَيْتُ أَبَا الدَّرْدَاءِ سُرَّ بِذَلِكَ، وَجَعَلَ يَرْفَعُ رَأْسَهُ إِلَيْهِ وَيَقُولُ: أَنْتَ سَمِعْتَ ذَلِكَ مِنْ رَسُولِ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ؟ فَيَقُولُ: نَعَمْ، فَمَا زَالَ يُعِيدُ عَلَيْهِ حَتَّى إِنِّي لَأَقُولُ: لَيَبْرُكَنَّ عَلَى رُكْبَتَيْهِ، قَالَ: فَمَرَّ بِنَا يَوْمًا آخَرَ، فَقَالَ لَهُ أَبُو الدَّرْدَاءِ: كَلِمَةً تَنْفَعُنَا وَلَا تَضُرُّكَ. قَالَ: قَالَ لَنَا رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "الْمُنْفِقُ عَلَى الْخَيْلِ كَالْبَاسِطِ يَدَهُ بِالصَّدَقَةِ لَا يَقْبِضُهَا". ثُمَّ مَرَّ بِنَا يَوْمًا آخَرَ، فَقَالَ لَهُ أَبُو الدَّرْدَاءِ: كَلِمَةً تَنْفَعُنَا وَلَا تَضُرُّكَ. قَالَ: قَالَ لَنَا رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "نِعْمَ الرَّجُلُ خُرَيْمٌ الْأَسَدِيُّ، لَوْلَا طُولُ جُمَّتِهِ وَإِسْبَالُ إِزَارِهِ". فَبَلَغَ ذَلِكَ خُرَيْمًا فَعَجِلَ فَأَخَذَ شَفْرَةً فَقَطَعَ بِهَا جُمَّتَهُ إِلَى أُذُنَيْهِ، وَرَفَعَ إِزَارَهُ إِلَى أَنْصَافِ سَاقَيْهِ. ثُمَّ مَرَّ بِنَا يَوْمًا آخَرَ، فَقَالَ لَهُ أَبُو الدَّرْدَاءِ: كَلِمَةً تَنْفَعُنَا وَلَا تَضُرُّكَ. فَقَالَ سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "إِنَّكُمْ قَادِمُونَ عَلَى إِخْوَانِكُمْ، فَأَصْلِحُوا رِحَالَكُمْ، وَأَصْلِحُوا لِبَاسَكُمْ، حَتَّى تَكُونُوا كَأَنَّكُمْ شَامَةٌ - كَالشَّامَةِ - فِي النَّاسِ، فَإِنَّ اللَّهَ لَا يُحِبُّ الْفُحْشَ وَلَا التَّفَحُّشَ". (د)', 'ഖൈസുബ്നു ബിശ്രിത്തഅ്ലബി(റ): എന്നോടെന്റെ പിതാവ് - അദ്ദേഹം അബുദ്ദർദാഅ്(റ)വിന്റെ സഹവാസിയായിരുന്നു - പറഞ്ഞു: ഇബ്നുൽ ഹൻളലിയ്യ(റ) എന്ന് പേരുള്ള നബി(സ)യുടെ ഒരു സ്വഹാബി ഡമസ്കസിൽ ജീവിച്ചിരുന്നു. ജനങ്ങളോട് അല്പം മാത്രം സഹവസിച്ചിരുന്ന ഒരു ഏകാന്തവാസിയായിരുന്നു അദ്ദേഹം. അദ്ദേഹമെപ്പോഴും നിസ്കാരത്തിലായിരിക്കും. നിസ്കാരത്തിൽ നിന്ന് വിരമിച്ചാൽ കുടുംബത്തിനടുത്ത് ചെല്ലുന്നത് വരെ തസ്ബീഹിലോ, തക്ബീറിലോ ആയിരിക്കും. ഞങ്ങൾ അബുദ്ദർദാഅ്(റ)വിന്റെ അടുത്തിരിക്കുമ്പോൾ അദ്ദേഹം ഞങ്ങളുടെ അരികിലൂടെ നടന്ന് പോയി. അദ്ദേഹത്തോട് അബുദ്ദർദാഅ്(റ) പറഞ്ഞു: ഞങ്ങൾക്കുപകരിക്കുന്ന, നിങ്ങൾക്ക് ഉപദ്രവമാകാത്ത ഒരു കാര്യം പറഞ്ഞുതന്നാലും. അദ്ദേഹം പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂൽ(സ) ഒരു യുദ്ധസംഘത്തെ അയച്ചു. യുദ്ധസംഘം മടങ്ങിവന്നു. അവരിലൊരാൾ വന്നുകൊണ്ട് റസൂൽ(സ) ഇരിക്കുന്നിടത്തിരുന്നു. തന്റെ ഒരു ഭാഗത്തിരിക്കുന്ന ഒരാളോടദ്ദേഹം പറഞ്ഞു: ഞങ്ങളും ശത്രുക്കളും ഏറ്റുമുട്ടുന്നത് നിങ്ങൾ കണ്ടിരുന്നുവെങ്കിൽ. ഒരാൾ കുന്തമെടുത്ത് കുത്തിക്കൊണ്ട് പറഞ്ഞു: എന്നിൽ നിന്നത് പിടിക്കുക. ഞാൻ ഗിഫാരിസന്താനമാണ്. അദ്ദേഹത്തിന്റെ വാക്കിനെക്കുറിച്ചെന്താണ് താങ്കളുടെ അഭിപ്രായം? കൂടെയിരിക്കുന്ന ആൾ പറഞ്ഞു: അദ്ദേഹത്തിന്റെ പ്രതിഫലം നഷ്ടപ്പെട്ടതായി ഞാൻ കാണുന്നു. ഇത് വേറെയൊരാൾ കേട്ടു. അദ്ദേഹം പറഞ്ഞു: ഇതിൽ ഞാനൊരു പ്രശ്നവും കാണുന്നില്ല. അങ്ങനെ അവർ രണ്ട് പേരും തർക്കിക്കുകയും അങ്ങനെ റസൂൽ(സ) അത് കേൾക്കുകയും ചെയ്തു. റസൂൽ(സ) പറഞ്ഞു: "സുബ്ഹാനല്ലാഹ്, അവൻ പ്രതിഫലം ലഭിക്കുന്നതിലും അവൻ പ്രശംസിക്കപ്പെടുന്നതിലും തെറ്റില്ല." ഇത് കേട്ട് അബുദ്ദർദാഅ്(റ) സന്തുഷ്ടനായത് ഞാൻ കണ്ടു. അബുദ്ദർദാഅ്(റ) അദ്ദേഹത്തോട് തലയുയർത്തിക്കൊണ്ട് ചോദിച്ചു: നിങ്ങളിത് റസൂൽ(സ)യിൽ നിന്ന് കേട്ടിട്ടുണ്ടോ? അദ്ദേഹം പറഞ്ഞു: അതെ. ''അദ്ദേഹം മുട്ടുകുത്തും'' എന്ന് ഞാൻ വിചാരിക്കുന്നതു വരെ അദ്ദേഹമതാവർത്തിച്ചുകൊണ്ടിരുന്നു. നിവേദകൻ പറയുന്നു: മറ്റൊരു ദിവസം അദ്ദേഹം ഞങ്ങളുടെ അരികിലൂടെ നടന്നുപോയി. അപ്പോഴദ്ദേഹത്തോട് അബുദ്ദർദാഅ്(റ) ചോദിച്ചു: ഞങ്ങൾക്ക് ഉപകാരപ്പെടുന്ന, നിങ്ങൾക്ക് ഉപദ്രവമാകാത്ത ഒരു വാക്യം പറഞ്ഞുതരുമോ? അദ്ദേഹം പറഞ്ഞു: ഞങ്ങളോട് റസൂൽ(സ) പറഞ്ഞു: "കുതിരക്ക് വേണ്ടി ചെലവഴിക്കുന്നവൻ കൈപിടിച്ച് വെക്കാതെ ധർമ്മം ചെയ്ത്കൊണ്ടേയിരിക്കുന്നവനെപ്പോലെയാണ്." മറ്റൊരു ദിവസം ഞങ്ങളുടെ അരികിലൂടെ അദ്ദേഹം നടന്നുപോയി. അബുദ്ദർദാഅ്(റ) ചോദിച്ചു: ഞങ്ങൾക്കുപകരിക്കുന്ന, നിങ്ങൾക്ക് ഉപദ്രവമാകാത്ത ഒരു വാക്ക് പറഞ്ഞുതരാമോ? അദ്ദേഹം പറഞ്ഞു: ഞങ്ങളോട് റസൂൽ(സ) പറഞ്ഞു: "തോളിലേക്ക് താഴുന്ന നീളൻ മുടിയും ഞെരിയാണിക്ക് താഴെ തുണി വലിച്ചിഴക്കലുമില്ലെങ്കിൽ ''ഖുറൈമുൽ അസദി'' എത്ര നല്ല മനുഷ്യനാണ്." ഖുറൈം(റ) ഈ വിവരം അറിഞ്ഞു. അദ്ദേഹം ധൃതി പിടിച്ച് ഒരു കത്രികയെടുത്ത് മുടി ചെവി വരെ മുറിച്ച് കളഞ്ഞു. കണങ്കാലിന്റെ പകുതിവരെ തുണി ഉയർത്തുകയും ചെയ്തു. പിന്നീട് ഒരു ദിവസം ഞങ്ങളുടെ അടുത്ത്കൂടി അദ്ദേഹം നടന്നുപോയി. അപ്പോൾ അബുദ്ദർദാഅ്(റ) അദ്ദേഹത്തോട് ചോദിച്ചു: ഞങ്ങൾക്കുപകരിക്കുന്ന നിങ്ങൾക്ക് ബുദ്ധിമുട്ടാകാത്ത ഒരു കാര്യം പറഞ്ഞുതരാമോ? അപ്പോൾ അദ്ദേഹം പറഞ്ഞു: റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടു: "നിങ്ങൾ നിങ്ങളുടെ സഹോദരങ്ങളുടെ അടുത്തേക്ക് പോകുന്നവരാണ്. അതിനാൽ നിങ്ങൾ ജനങ്ങളിലെ ഉന്നതരെന്ന പോലെ നിങ്ങളുടെ വാഹനങ്ങളെ നന്നാക്കുക, വസ്ത്രങ്ങളും നന്നാക്കുക. അല്ലാഹു ദൂഷ്യത്തെയോ മോശമാകുന്നതോ ഇഷ്ടപ്പെടുന്നില്ല." (ദ)', 'قَيْسِ بْنِ بِشْرٍ التَّغْلِبِيِّ', 'ഖൈസുബ്നു ബിശ്രിത്തഅ്ലബി(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 647, 649, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 28, 'عَنْ مُحَمَّدِ بْنِ زِيَادٍ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ أَبَا هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ - وَرَأَى رَجُلًا يَجُرُّ إِزَارَهُ، فَجَعَلَ يَضْرِبُ الْأَرْضَ بِرِجْلِهِ، وَهُوَ أَمِيرٌ عَلَى الْبَحْرَيْنِ - وَهُوَ يَقُولُ: جَاءَ الْأَمِيرُ جَاءَ الْأَمِيرُ، قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ اللهَ لَا يَنْظُرُ إِلَى مَنْ يَجُرُّ إِزَارَهُ بَطَرًا". (م)', 'മുഹമ്മദുബ്നു സിയാദ്(റ): അബൂഹുറൈറ(റ) പറയുന്നത് ഞാൻ കേട്ടു: അദ്ദേഹം ബഹ്റൈനിലെ അമീറായിരിക്കെ, തുണി വലിച്ചിഴക്കുന്ന ഒരാളെ കണ്ടു. അപ്പോഴദ്ദേഹം (അതിനോടുള്ള വെറുപ്പ് പ്രകടിപ്പിക്കാനായി) കാൽ കൊണ്ട് നിലത്ത് ചവിട്ടുകയും ഇപ്രകാരം പറയുകയും ചെയ്തു: അമീറ് വന്നിരിക്കുന്നു. അമീറ് വന്നിരിക്കുന്നു. റസൂൽ(സ) പറഞ്ഞിട്ടുണ്ട്: "തീർച്ചയായും അഹന്തയോടെ തുണി വലിച്ചിഴക്കുന്നവനിലേക്ക് അല്ലാഹു നോക്കുകയില്ല." (മു)', 'مُحَمَّدِ بْنِ زِيَادٍ', 'മുഹമ്മദുബ്നു സിയാദ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 649, 649, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 29, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "قَالَ اللهُ عَزَّ وَجَلَّ: الْكِبْرِيَاءُ رِدَائِي، وَالْعَظَمَةُ إِزَارِي، فَمَنْ نَازَعَنِي وَاحِدًا مِنْهُمَا قَذَفْتُهُ فِي النَّارِ". (م,د,جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹു പറഞ്ഞിരിക്കുന്നു: അഹങ്കാരം എന്റെ മേൽവസ്ത്രമാണ്, ഔന്നത്യം എന്റെ തുണിയാണ്. അതിൽ ഏതെങ്കിലുമൊന്നിൽ ആരെങ്കിലും എന്നോട് തർക്കിച്ചാൽ ഞാനവനെ നരകത്തിലെറിയും." (മു,ദ,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','د','جه']::text[], array['മു','ദ','ജ']::text[], null, null, 649, 649, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=7 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 30, 'عَنْ عَبْدِ اللهِ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا يَدْخُلُ الْجَنَّةَ مَنْ كَانَ فِي قَلْبِهِ مِثْقَالُ حَبَّةٍ مِنْ خَرْدَلٍ مِنْ كِبْرٍ، وَلَا يَدْخُلُ النَّارَ مَنْ كَانَ فِي قَلْبِهِ مِثْقَالُ خَرْدَلَةٍ مِنْ إِيمَانٍ". (م,د,ت)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): റസൂൽ(സ) പറഞ്ഞു: "ഹൃദയത്തിൽ കടുക്മണിത്തൂക്കം അഹങ്കാരമുള്ളവൻ സ്വർഗ്ഗത്തിൽ പ്രവേശിക്കുകയില്ല. ഒരു കടുകുമണിത്തൂക്കം ഈമാൻ ഹൃദയത്തിലുള്ളവൻ നരകത്തിൽ പ്രവേശിക്കുകയില്ല." (മു,ദ,തു)', 'عَبْدِ اللهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['م','د','ت']::text[], array['മു','ദ','തു']::text[], null, null, 649, 649, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=7 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 31, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَجُلًا أَتَى النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، وَكَانَ رَجُلًا جَمِيلًا، فَقَالَ: يَا رَسُولَ اللهِ، إِنِّي رَجُلٌ حُبِّبَ إِلَيَّ الْجَمَالُ، وَأُعْطِيتُ مِنْهُ مَا تَرَى، حَتَّى مَا أُحِبُّ أَنْ يَفُوقَنِي أَحَدٌ، إِمَّا قَالَ: بِشِرَاكِ نَعْلِي، وَإِمَّا قَالَ: بِشِسْعِ نَعْلِي، أَفَمِنَ الْكِبْرِ ذَلِكَ؟ قَالَ: "لَا، وَلَكِنَّ الْكِبْرَ مَنْ بَطِرَ الْحَقَّ وَغَمَطَ النَّاسَ". (م, د)', 'അബൂഹുറൈറ(റ): ഒരാൾ നബി(സ)യുടെ അടുത്ത് വന്നു. ഒരു സുന്ദരനായ മനുഷ്യനായിരുന്നു അയാൾ. അദ്ദേഹം പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, സൗന്ദര്യം എനിക്ക് പ്രിയങ്കരമാക്കപ്പെട്ടിരിക്കുന്നു. ആ സൗന്ദര്യത്തിൽ നിന്ന് അങ്ങ് കാണുന്നത് എനിക്ക് നൽകപ്പെട്ടിരിക്കുന്നു. എന്റെ ചെരുപ്പിന്റെ വള്ളിയിൽ പോലും ആരും എന്നെ കവച്ചുവെക്കുന്നത് എനിക്ക് ഇഷ്ടമല്ല. (ചെരുപ്പിന്റെ വള്ളിക്ക് ''ശിറാക്'' എന്ന പദമാണോ അതോ ''ശിസ്അ്'' എന്ന പദമാണോ പറഞ്ഞതെന്ന് നിവേദകൻ സംശയിക്കുന്നു) ഇത് അഹങ്കാരത്തിൽ പെട്ടതാണോ? റസൂൽ(സ) പറഞ്ഞു: "അല്ല, അഹങ്കാരമെന്നത് സത്യത്തെ നിരാകരിക്കലും ജനങ്ങളെ നിസ്സാരമാക്കലുമാണ്." (മു,ദ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','د']::text[], array['മു','ദ']::text[], null, 'ചെരുപ്പിന്റെ വള്ളിക്ക് ''ശിറാക്'' എന്ന പദമാണോ അതോ ''ശിസ്അ്'' എന്ന പദമാണോ പറഞ്ഞതെന്ന് നിവേദകൻ സംശയിക്കുന്നു', 649, 650, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=7 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 32, 'عَنْ حُذَيْفَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَوْضِعُ الْإِزَارِ إِلَى أَنْصَافِ السَّاقَيْنِ وَالْعَضَلَةِ، فَإِنْ أَبَيْتَ فَأَسْفَلَ فَإِنْ أَبَيْتَ فَمِنْ وَرَاءِ السَّاقِ، وَلَا حَقَّ لِلْكَعْبَيْنِ فِي الْإِزَارِ". (ن)', 'ഹുദൈഫ(റ): റസൂൽ(സ) പറഞ്ഞു: "തുണിയുടെ സ്ഥാനം രണ്ട് കണങ്കാലുകളുടെയും അവിടത്തെ മാംസത്തിന്റെയും പകുതിവരെയാണ്. അതിന് നിനക്കായില്ലെങ്കിൽ താഴ്ഭാഗം വരെ. അതിനും നിനക്കായില്ലെങ്കിൽ കണങ്കാലിന്റെ പുറം ഭാഗത്തുകൂടെ. രണ്ട് ഞെരിയാണികൾക്കും തുണിയിൽ ഒരു പങ്കുമില്ല." (ന)', 'حُذَيْفَةَ', 'ഹുദൈഫ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 650, 650, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 33, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِزْرَةُ الْمُسْلِمِ إِلَى نِصْفِ السَّاقِ، وَلَا حَرَجَ -أَوْ: لَا جُنَاحَ- فِيمَا بَيْنَهُ وَبَيْنَ الْكَعْبَيْنِ، مَا كَانَ أَسْفَلَ مِنَ الْكَعْبَيْنِ فَهُوَ فِي النَّارِ، مَنْ جَرَّ إِزَارَهُ بَطَرًا لَمْ يَنْظُرِ اللهُ إِلَيْهِ". (د, جه)', 'അബൂസഈദിൽ ഖുദ്‌രി(റ): റസൂൽ(സ) പറഞ്ഞു: "മുസ്‌ലിമിന്റെ തുണി കണങ്കാലിന്റെ പകുതിവരെയാണ്. അതിന്റെയും രണ്ട് ഞെരിയാണികൾക്കുമിടയിൽ കുഴപ്പമില്ല. രണ്ട് ഞെരിയാണികൾക്ക് താഴെയുള്ളത് നരകത്തിലാണ്. അഹങ്കാരത്തോടെ തുണിവലിച്ചിഴച്ചവനിലേക്ക് അല്ലാഹു നോക്കുകയില്ല." (ദ,ജ)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദിൽ ഖുദ്‌രി(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 650, 650, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 34, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: مَا قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي الْإِزَارِ فَهُوَ فِي الْقَمِيصِ. (د)', 'ഇബ്‌നുഉമർ(റ): തുണിയുടെ വിഷയത്തിൽ റസൂൽ(സ) പറഞ്ഞത് ഖമീസിലും ബാധകമാണ്. (ദ)', 'ابْنِ عُمَرَ', 'ഇബ്‌നുഉമർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 650, 650, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 35, 'عَنْ عِكْرِمَةَ رَضِيَ اللهُ عَنْهُ: أَنَّهُ رَأَى ابْنَ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا يَأْتَزِرُ، فَيَضَعُ حَاشِيَةَ إِزَارِهِ مِنْ مُقَدَّمِهِ عَلَى ظَهْرِ قَدَمَيْهِ، وَيَرْفَعُ مِنْ مُؤَخَّرِهِ، قُلْتُ: لِمَ تَأْتَزِرُ هَذِهِ الْإِزْرَةَ؟ قَالَ: رَأَيْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَأْتَزِرُهَا. (د)', 'ഇക്‌രിമ(റ): ഇബ്‌നുഅബ്ബാസ്(റ) തുണിയെടുക്കുന്നത് അദ്ദേഹം കണ്ടു. തുണിയുടെ മുൻഭാഗം കാൽപാദങ്ങളിൽ വെക്കുന്നു. പിൻഭാഗം ഉയർത്തുന്നു. ഞാൻ ചോദിച്ചു: നിങ്ങളെന്തിനാണ് ഇങ്ങനെ തുണിയെടുക്കുന്നത്? അദ്ദേഹം പറഞ്ഞു: റസൂൽ(സ) ഇങ്ങനെ തുണിയെടുക്കുന്നത് ഞാൻ കണ്ടിട്ടുണ്ട്. (ദ)', 'عِكْرِمَةَ', 'ഇക്‌രിമ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 650, 650, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 36, 'عَنْ حُذَيْفَةَ رَضِيَ اللهُ عَنْهُ قَالَ: أَخَذَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِأَسْفَلِ عَضَلَةِ سَاقِي أَوْ سَاقِهِ، فَقَالَ: "هَذَا مَوْضِعُ الْإِزَارِ، فَإِنْ أَبَيْتَ فَأَسْفَلَ، فَإِنْ أَبَيْتَ فَأَسْفَلَ، فَإِنْ أَبَيْتَ فَلَا حَقَّ لِلْإِزَارِ فِي الْكَعْبَيْنِ". (د, ت, ن, جه)', 'ഹുദൈഫ(റ): റസൂൽ(സ) എന്റെ അല്ലെങ്കിൽ അവിടത്തെ കണങ്കാലിലെ മാംസ പേശിയുടെ താഴ്ഭാഗത്ത് തൊട്ടിട്ടു പറഞ്ഞു: "ഇത് തുണിയുടെ സ്ഥാനമാണ്. അതിന് നിനക്ക് കഴിഞ്ഞില്ലെങ്കിൽ അൽപം താഴെ അതിനും നിനക്കായില്ലെങ്കിൽ അതിനും താഴെ. അതിനും നിങ്ങൾക്കായില്ലെങ്കിൽ തുണിക്ക് ഞെരിയാണിയിൽ ഒരവകാശവുമില്ല." (ദ, തു, ന, ജ)', 'حُذَيْفَةَ', 'ഹുദൈഫ(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 650, 651, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 37, 'عَنِ الْمُغِيرَةِ بْنِ شُعْبَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "يَا سُفْيَانَ بْنَ سَهْلٍ، لَا تُسْبِلْ، فَإِنَّ اللهَ لَا يُحِبُّ الْمُسْبِلِينَ". (جه)', 'മുഗീറതുബ്നു ശുഅ്ബ(റ): റസൂൽ(സ) പറഞ്ഞു: "സുഫ്‌യാനുബ്നു സഹ്ലേ, താങ്കൾ വസ്ത്രം ഞെരിയാണിക്ക് താഴെ താഴ്ത്തരുത്. ഞെരിയാണിക്ക് താഴെ വസ്ത്രം താഴ്ത്തുന്നവരെ അല്ലാഹു ഇഷ്ടപ്പെടുന്നില്ല." (ജ)', 'الْمُغِيرَةِ بْنِ شُعْبَةَ', 'മുഗീറതുബ്നു ശുഅ്ബ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 651, 651, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 38, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَا تَحْتَ —وَفِي رِوَايَةٍ: مَا أَسْفَلَ— الْكَعْبَيْنِ مِنَ الْإِزَارِ فَفِي النَّارِ". (خ, ن)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "രണ്ട് ഞെരിയാണികൾക്ക് താഴെയുള്ള തുണി നരകത്തിലാണ്." (ബു, ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ','ن']::text[], array['ബു','ന']::text[], null, null, 651, 651, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=8 and h.hadith_no=38), 1, 'وَفِي رِوَايَةٍ: مَا أَسْفَلَ— الْكَعْبَيْنِ مِنَ الْإِزَارِ فَفِي النَّارِ". (خ, ن)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 39, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: مَرَرْتُ عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَفِي إِزَارِي اسْتِرْخَاءٌ، فَقَالَ: "يَا عَبْدَ اللَّهِ، ارْفَعْ إِزَارَكَ". فَرَفَعْتُهُ، ثُمَّ قَالَ: "زِدْ". فَزِدْتُ، فَمَا زِلْتُ أَتَحَرَّاهَا بَعْدُ، فَقَالَ بَعْضُ الْقَوْمِ: [إِلَى] أَيْنَ؟ فَقَالَ: أَنْصَافِ السَّاقَيْنِ. (م)', 'ഇബ്നുഉമർ(റ): ഞാൻ റസൂൽ(സ)യുടെ അരികിലൂടെ നടന്നുപോയി, എന്റെ തുണി അൽപ്പം താഴ്ന്നിട്ടുണ്ട്. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "ഓ അബ്ദുല്ലാഹ്, നിന്റെ തുണിയുയർത്തുക." ഞാനത് ഉയർത്തി. നബി(സ) വീണ്ടും പറഞ്ഞു: "ഇനിയും കയറ്റുക." ഞാൻ കുറച്ചു കൂടി കയറ്റി. അതിനു ശേഷം ഞാനത് സൂക്ഷിച്ച് കൊണ്ടിരുന്നു. ചിലയാളുകൾ ചോദിച്ചു. ഏത് വരെയാണ്? അപ്പോൾ അദ്ദേഹം പറഞ്ഞു: കണങ്കാലുകളുടെ പകുതി വരെ. (മു)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['م']::text[], array['മു']::text[], 'إِلَى', null, 651, 651, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 40, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا لَبِسَ قَمِيصًا بَدَأَ بِمَيَامِنِهِ. (ت, ن)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) ഖമീസ് ധരിക്കുമ്പോൾ വലത് ഭാഗം കൊണ്ട് തുടങ്ങുമായിരുന്നു. (തു, ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ت','ن']::text[], array['തു','ന']::text[], null, null, 651, 651, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 41, 'عَنْ أُمِّ سَلَمَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كَانَ أَحَبُّ الثِّيَابِ إِلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ القَمِيصَ. وَفِي رِوَايَةٍ قَالَتْ: لَمْ يَكُنْ ثَوْبٌ أَحَبَّ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنْ قَمِيصٍ. (د,ت,ن)', 'ഉമ്മുസലമ(റ): റസൂൽ(സ)ക്ക് ഏറ്റവും ഇഷ്ടപ്പെട്ട വസ്ത്രം ഖമീസാണ്. മറ്റൊരു നിവേദനത്തിൽ കാണാം: റസൂൽ(സ)ക്ക് ഖമീസിനേക്കാൾ ഇഷ്ടപ്പെട്ട വസ്ത്രം ഉണ്ടായിരുന്നില്ല. (ദ,തു,ന)', 'أُمِّ سَلَمَةَ', 'ഉമ്മുസലമ(റ)', null, null, array['د','ت','ن']::text[], array['ദ','തു','ന']::text[], null, null, 652, 652, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=8 and h.hadith_no=41), 1, 'وَفِي رِوَايَةٍ قَالَتْ: لَمْ يَكُنْ ثَوْبٌ أَحَبَّ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنْ قَمِيصٍ. (د,ت,ن)', 'മറ്റൊരു നിവേദനത്തിൽ കാണാം: റസൂൽ(സ)ക്ക് ഖമീസിനേക്കാൾ ഇഷ്ടപ്പെട്ട വസ്ത്രം ഉണ്ടായിരുന്നില്ല. (ദ,തു,ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 42, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَلْبَسُ قَمِيصًا قَصِيرَ الْيَدَيْنِ وَالطُّولِ. فِي سَنَدِهِ ضَعِيفٌ. (جه)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂൽ(സ) കൈ ചെറുതായ, നീളം കുറഞ്ഞ ഖമീസാണ് ധരിച്ചിരുന്നത്. ഈ ഹദീസിന്റെ പരമ്പരയിൽ ബലഹീനനുണ്ട്. (ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 652, 652, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 43, 'عَنْ أَسْمَاءَ بِنْتِ يَزِيدَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: كَانَتْ يَدُ كُمِّ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَى الرُّسُغِ. (د)', 'അസ്മാഉബിൻത് യസീദ്(റ): റസൂൽ(സ)യുടെ കുപ്പായക്കൈ മണിക്കണ്ഠം വരെയായിരുന്നു. (ദ)', 'أَسْمَاءَ بِنْتِ يَزِيدَ', 'അസ്മാഉബിൻത് യസീദ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 652, 652, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 44, 'عَنْ أَبِي بُرْدَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: أَخْرَجَتْ إِلَيْنَا عَائِشَةُ رَضِيَ اللَّهُ عَنْهَا كِسَاءً مُلَبَّدًا وَإِزَارًا غَلِيظًا، فَقَالَتْ: قُبِضَ رُوحُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي هَذَيْنِ. حَسَنٌ صَحِيحٌ. (ت)', 'അബൂബുർദ(റ): ആഇശ(റ) കട്ടിയുള്ള പരുപരുത്ത ഒരു വസ്ത്രവും പരുപരുത്ത ഒരു തുണിയും തന്നു. അവർ പറഞ്ഞു: ഇവ രണ്ടിലുമായിരിക്കുമ്പോഴാണ് റസൂൽ(സ)യുടെ റൂഹ് പിടിക്കപ്പെട്ടത്. (തു)', 'أَبِي بُرْدَةَ', 'അബൂബുർദ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 652, 652, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 45, 'عَنِ ابْنِ مَسْعُودٍ رَضِيَ اللَّهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "كَانَ عَلَى مُوسَى يَوْمَ كَلَّمَهُ رَبُّهُ كِسَاءُ صُوفٍ، وَجُبَّةُ صُوفٍ، وَكُمَّةُ صُوفٍ، وَسَرَاوِيلُ صُوفٍ، وَكَانَتْ نَعْلَاهُ مِنْ جِلْدِ حِمَارٍ مَيِّتٍ". (ت)', 'ഇബ്നുമസ്ഊദ്(റ): നബി(സ) പറഞ്ഞു: "മൂസാനബി(സ)യോട് തന്റെ നാഥൻ സംസാരിച്ച ദിവസം മൂസാ നബി(അ)മിന്റെ ശരീരത്തിൽ രോമത്തിന്റെ വസ്ത്രവും രോമത്തിന്റെ ജുബ്ബയും രോമത്തിന്റെ കുപ്പായക്കയ്യും രോമത്തിന്റെ പൈജാമയുമുണ്ടായിരുന്നു. മൂസാ നബി(അ)മിന്റെ ചെരുപ്പുകൾ ചത്ത കഴുതയുടെ തോൽ കൊണ്ടുണ്ടാക്കപ്പെട്ടതായിരുന്നു." (തു)', 'ابْنِ مَسْعُودٍ', 'ഇബ്നുമസ്ഊദ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 652, 652, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 46, 'عَنْ أَبِي بُرْدَةَ رَضِيَ اللَّهُ عَنْهُ عَنْ أَبِيهِ، أَبِي مُوسَى رَضِيَ اللَّهُ عَنْهُ، قَالَ: قَالَ لِي: يَا بُنَيَّ، لَوْ شَهِدْتَنَا وَنَحْنُ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، إِذَا أَصَابَتْنَا السَّمَاءُ، لَحَسِبْتَ أَنَّ رِيحَنَا رِيحُ الضَّأْنِ. (د,ت,جه)', 'അബൂബുർദ(റ): അബൂമൂസ(റ)വിനെ ഉധരിച്ച് പറയുന്നു: എന്നോടദ്ദേഹം പറഞ്ഞു: എന്റെ പൊന്നുമോനേ, ഞങ്ങൾ റസൂൽ(സ)യുടെ കൂടെ ഇരിക്കുമ്പോൾ മഴ പെയ്താൽ ഞങ്ങളുടെ വാസന ആടിന്റെ വാസനയാണെന്ന് നീ ധരിക്കും. (ദ,തു,ജ)', 'أَبِي بُرْدَةَ', 'അബൂബുർദ(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 652, 652, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 47, 'عَنْ عُبَادَةَ بْنِ الصَّامِتِ رَضِيَ اللَّهُ عَنْهُ قَالَ: خَرَجَ عَلَيْنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ذَاتَ يَوْمٍ وَعَلَيْهِ جُبَّةٌ رُومِيَّةٌ مِنْ صُوفٍ، ضَيِّقَةُ الْكُمَّيْنِ، فَصَلَّى بِنَا فِيهَا، لَيْسَ عَلَيْهِ شَيْءٌ غَيْرُهَا. فِيهِ انْقِطَاعٌ وَضَعْفٌ. (جه)', 'ഉബാദതുബ്നു സ്വാമിത്(റ): ഒരു ദിവസം റസൂൽ(സ) രോമത്താലുള്ള കൈ ഇടുങ്ങിയ രോമം കൊണ്ടുള്ള റോമൻ വസ്ത്രം ധരിച്ച് ഞങ്ങളുടെയടുത്തേക്ക് വന്നു. അത് ധരിച്ച് നബി(സ) ഞങ്ങൾക്ക് ഇമാമായി നസ്കരിച്ചു. അതല്ലാതെ മറ്റൊന്നും റസൂൽ(സ)യുടെ ശരീരത്തിലില്ല. ഹദീസിന്റെ പരമ്പരയിൽ ഇൻഖിതാഉം (നിവേദകൻ മുറിഞ്ഞ അവസ്ഥ) ബലഹീനതയുമുണ്ട്. (ജ)', 'عُبَادَةَ بْنِ الصَّامِتِ', 'ഉബാദതുബ്നു സ്വാമിത്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 652, 653, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 48, 'عَنْ سَلْمَانَ الْفَارِسِيِّ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ تَوَضَّأَ، فَقَلَبَ جُبَّةَ صُوفٍ كَانَتْ عَلَيْهِ، فَمَسَحَ بِهَا وَجْهَهُ. (جه)', 'സൽമാനുൽ ഫാരിസി(റ): റസൂൽ(സ) വുളു ചെയ്തു. നബി(സ)യുടെ ദേഹത്തുണ്ടായിരുന്ന രോമത്താലുള്ള ജുബ്ബ പുറം മറിച്ചു. എന്നിട്ടത് കൊണ്ട് നബി(സ) അവിടുത്തെ മുഖം തടവി. (ജ)', 'سَلْمَانَ الْفَارِسِيِّ', 'സൽമാനുൽ ഫാരിസി(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 653, 653, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 49, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ، قَالَ: رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَسِمُ غَنَمًا فِي آذَانِهَا، وَرَأَيْتُهُ مُتَّزِرًا بِكِسَاءٍ. (ق،د،جه)', 'അനസുബ്നു മാലിക്(റ): റസൂൽ(സ) ആടിന് ചെവിയിൽ അടയാളം വെക്കുന്നത് ഞാൻ കണ്ടു. നബി(സ) ചെറിയ വസ്ത്രം തുണിയാക്കി ധരിച്ചതായി കണ്ടു. (ബു,മു,ദ,ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['ق','د','جه']::text[], array['ബു','മു','ദ','ജ']::text[], null, null, 653, 653, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 50, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا، قَالَتْ: خَرَجَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَعَلَيْهِ مِرْطٌ مُرَحَّلٌ مِنْ شَعْرٍ أَسْوَدَ. (م،د،ت)', 'ആഇശ(റ): കറുത്ത രോമത്താലുള്ള, കൂടാരത്തിന്റെ ചിത്രമുള്ള കമ്പിളി വസ്ത്രം ധരിച്ച് നബി(സ) പുറത്തു പോയി. (മു,ദ,തു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['م','د','ت']::text[], array['മു','ദ','തു']::text[], null, null, 653, 653, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=14 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 51, 'عَنْ عُتْبَةَ بْنِ عَبْدٍ السُّلَمِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: اسْتَكْسَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَكَسَانِي خَيْشَتَيْنِ، فَلَقَدْ رَأَيْتُنِي وَأَنَا أَكْسَى أَصْحَابِي. (د)', 'ഉത്ബതുബ്നു അബ്ദിസ്സുലമീ(റ): ഞാൻ റസൂൽ(സ)യോട് വസ്ത്രം തരണമെന്നപേക്ഷിച്ചു. അപ്പോൾ അവിടന്ന് ലോലമായി നെയ്തെടുത്ത പരുക്കൻ നൂലുകളുള്ള രണ്ട് വസ്ത്രങ്ങൾ എന്നെ ധരിപ്പിച്ചു. അപ്പോൾ എന്റെ സ്നേഹിതന്മാരേക്കാൾ മുന്തിയ വസ്ത്രമുള്ളവനായി ഞാൻ എന്നെ കണ്ടു. (ദ)', 'عُتْبَةَ بْنِ عَبْدٍ السُّلَمِيِّ', 'ഉത്ബതുബ്നു അബ്ദിസ്സുലമീ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 653, 653, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=14 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 52, 'عَنْ قُرَّةَ بْنِ إِيَاسٍ الْمُزَنِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: أَتَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي رَهْطٍ مِنْ مُزَيْنَةَ، فَبَايَعْنَاهُ، وَإِنَّ قَمِيصَهُ لَمُطْلَقُ الْأَزْرَارِ، قَالَ: فَبَايَعْتُهُ، ثُمَّ أَدْخَلْتُ يَدِي فِي جَيْبِ قَمِيصِهِ فَمَسَسْتُ الْخَاتَمَ. قَالَ عُرْوَةُ: فَمَا رَأَيْتُ مُعَاوِيَةَ وَلَا ابْنَهُ قَطُّ إِلَّا مُطْلِقَيْ أَزْرَارِهِمَا، فِي شِتَاءٍ وَلَا حَرٍّ، وَلَا يُزَرِّرَانِ أَزْرَارَهُمَا أَبَدًا. (د،جه)', 'ഖുർറതുബ്നു ഇയാസുൽ മുസ്നി(റ): ''മുസൈന'' ഗോത്രത്തിലെ ഒരു സംഘത്തോടൊപ്പം ഞാൻ റസൂൽ(സ)യുടെ അടുത്ത് ചെന്നു. ഞങ്ങൾ റസൂൽ(സ)യുമായി ബൈഅത്ത് ചെയ്തു. നിശ്ചയം നബി(സ)യുടെ ഖമീസ് കുടുക്കുകൾ അഴിച്ചിടപ്പെട്ട നിലയിലായിരുന്നു. ഞാൻ റസൂൽ(സ)യുമായി ബൈഅത്ത് ചെയ്തു. പിന്നെ അവിടുത്തെ ഖമീസിന്റെ തലയുടെ ഭാഗത്തുള്ള ദ്വാരത്തിലൂടെ ഞാനെന്റെ കൈ പ്രവേശിപ്പിക്കുകയും പ്രവാചകത്വത്തിന്റെ അടയാളത്തിൽ തൊടുകയും ചെയ്തു. ഉർവ്വ(റ) പറയുന്നു: മുആവിയ(റ)യെയോ, അദ്ദേഹത്തിന്റെ പുത്രനെയോ, ശൈത്യകാലത്തും ഉഷ്ണകാലത്തും കുടുക്കുകൾ അഴിച്ചിട്ടതായല്ലാതെ ഞാൻ കണ്ടിട്ടില്ല. അവർ തീരെ കുടുക്ക് വെക്കാറുണ്ടായിരുന്നില്ല. (ദ,ജ)', 'قُرَّةَ بْنِ إِيَاسٍ الْمُزَنِيِّ', 'ഖുർറതുബ്നു ഇയാസുൽ മുസ്നി(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 653, 654, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 53, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ دَخَلَ عَامَ الْفَتْحِ مَكَّةَ وَعَلَيْهِ عِمَامَةٌ سَوْدَاءُ. (م,د,ت,ن,جه)', 'ജാബിർ(റ): നിശ്ചയം റസൂൽ(സ) മക്കാ വിജയത്തിന്റെ വർഷത്തിൽ കറുത്ത തലപ്പാവ് ധരിച്ച് മക്കയിൽ പ്രവേശിച്ചു. (മു,ദ,തു,ന,ജ)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['م','د','ت','ن','جه']::text[], array['മു','ദ','തു','ന','ജ']::text[], null, null, 654, 654, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 54, 'عَنْ عَمْرِو بْنِ حُرَيْثٍ رَضِيَ اللهُ عَنْهُ عَنْ أَبِيهِ قَالَ: رَأَيْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى الْمِنْبَرِ وَعَلَيْهِ عِمَامَةٌ سَوْدَاءُ، قَدْ أَرْخَى طَرَفَهَا بَيْنَ كَتِفَيْهِ. (م,د,ن,جه)', 'അംറുബ്നു ഹുറൈസ്(റ) പിതാവിൽ നിന്നും നിവേദകനം ചെയ്യുന്നു: കറുത്ത തലപ്പാവ് ധരിച്ച് കൊണ്ട് റസൂൽ(സ) മിമ്പറിൽ നിൽക്കുന്നത് ഞാൻ കണ്ടു. നബി(സ) അതിന്റെയൊരു ഭാഗം രണ്ട് തോളുകൾക്കിടയിൽ താഴ്ത്തിയിട്ടുണ്ട്. (മു,ദ,ന,ജ)', 'عَمْرِو بْنِ حُرَيْثٍ', 'അംറുബ്നു ഹുറൈസ്(റ)', null, null, array['م','د','ن','جه']::text[], array['മു','ദ','ന','ജ']::text[], null, null, 654, 654, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 55, 'عَنْ رُكَانَةَ رَضِيَ اللهُ عَنْهُ: صَارَعَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَصَرَعَهُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. قَالَ رُكَانَةُ: وَسَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "فَرْقُ مَا بَيْنَنَا وَبَيْنَ الْمُشْرِكِينَ الْعَمَائِمُ عَلَى الْقَلَانِسِ". (د,ت)', 'റുകാന(റ): അദ്ദേഹം നബി(സ)യോട് മൽപ്പിടുത്തം നടത്തി. അപ്പോൾ നബി(സ) അദ്ദേഹത്തെ വീഴ്ത്തി. റുകാന(റ) പറയുന്നു: നബി(സ) പറയുന്നത് ഞാൻ കേട്ടിട്ടുണ്ട്: "നമുക്കും മുശ്രിക്കുകൾക്കുമിടയിലുള്ള വ്യത്യാസം തൊപ്പികൾക്കു മീതെയുള്ള തലപ്പാവാണ്." (ദ,തു)', 'رُكَانَةَ', 'റുകാന(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 654, 654, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 56, 'عَنْ عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ رَضِيَ اللهُ عَنْهُ قَالَ: عَمَّمَنِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَسَدَلَهَا بَيْنَ يَدَيَّ وَمِنْ خَلْفِي. (د)', 'അബ്ദുറഹ്മാനുബ്നി ഔഫ്(റ): റസൂൽ(സ) എന്നെ തലപ്പാവ് ധരിപ്പിച്ചു, എന്റെ മുന്നിലും പിന്നിലുമായി അത് താഴ്ത്തിയിട്ടു. (ദ)', 'عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ', 'അബ്ദുറഹ്മാനുബ്നി ഔഫ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 654, 654, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 57, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا اعْتَمَّ سَدَلَ عِمَامَتَهُ بَيْنَ كَتِفَيْهِ. وَكَانَ ابْنُ عُمَرَ يَسْدِلُ عِمَامَتَهُ بَيْنَ كَتِفَيْهِ. حَسَنٌ غَرِيبٌ. (ت)', 'ഇബ്നുഉമർ(റ): നബി(സ) തലപ്പാവ് ധരിച്ചാൽ അവിടുത്തെ തലപ്പാവ് രണ്ട് തോളുകൾക്കിടയിലായി താഴ്ത്തിയിടും. ഇബ്നുഉമർ(റ)വും തന്റെ തലപ്പാവ് രണ്ട് തോളുകൾക്കിടയിൽ താഴ്ത്തിയിടും. ഹദീസ് ഹസനും ഗരീബുമാണ്. (തു)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 654, 654, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 58, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ دَخَلَ يَوْمَ فَتْحِ مَكَّةَ وَعَلَيْهِ عِمَامَةٌ سَوْدَاءُ، بِغَيْرِ إِحْرَامٍ. وفي رواية قَالَ: دَخَلَ النَّبِيُّ صلى الله عليه وسلم يَوْمَ الْفَتْحِ وَعَلَيْهِ عِمَامَةٌ سَوْدَاءُ. (ن)', 'ജാബിർ(റ): മക്കാ വിജയത്തിന്റെ ദിനത്തിൽ, ഇഹ്റാം ചെയ്യാതെ കറുത്ത തലപ്പാവ് ധരിച്ച് നബി(സ) പ്രവേശിച്ചു. മറ്റൊരു നിവേദനത്തിൽ കാണാം: ഫത്ഹിന്റെ ദിവസം നബി(സ) കറുത്ത തലപ്പാവ് ധരിച്ച് കൊണ്ട് പ്രവേശിച്ചു. (ന)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 655, 655, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=18 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=8 and h.hadith_no=58), 1, 'وَفِي رِوَايَةٍ قَالَ: دَخَلَ النَّبِيُّ صلى الله عليه وسلم يَوْمَ الْفَتْحِ وَعَلَيْهِ عِمَامَةٌ سَوْدَاءُ. (ن)', 'മറ്റൊരു നിവേദനത്തിൽ കാണാം: ഫത്ഹിന്റെ ദിവസം നബി(സ) കറുത്ത തലപ്പാവ് ധരിച്ച് കൊണ്ട് പ്രവേശിച്ചു. (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 59, 'عَنْ عَمْرِو بْنِ حُرَيْثٍ رَضِيَ اللهُ عَنْهُ قَالَ: رَأَيْتُ عَلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عِمَامَةً حَرْقَانِيَّةً. (ن)', 'അംറുബ്നു ഹുറൈസ്(സ): നബി(സ)യുടെ ശിരസ്സിൽ കരിഞ്ഞതുപോലെ കറുത്ത തലപ്പാവ് ഞാൻ കണ്ടു. (ന)', 'عَمْرِو بْنِ حُرَيْثٍ', null, null, null, array['ن']::text[], array['ന']::text[], null, null, 655, 655, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=19 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 60, 'عَنِ ابْنِ عُمَرَ رَضِيَ الله عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ جَرَّ ثَوْبَهُ مِنَ الْخُيَلَاءِ لَمْ يَنْظُرِ اللَّهُ إِلَيْهِ". قَالَتْ أُمُّ سَلَمَةَ: يَا رَسُولَ اللهِ، فَكَيْفَ تَصْنَعُ النِّسَاءُ بِذُيُولِهِنَّ؟ قَالَ: "تُرْخِينَهُ شِبْرًا". قَالَتْ: إِذًا تَنْكَشِفُ أَقْدَامُهُنَّ. قَالَ: "تُرْخِينَهُ ذِرَاعًا لَا تَزِدْنَ عَلَيْهِ". (ن)', 'ഇബ്നുഉമർ(റ): റസൂൽ(സ) പറഞ്ഞു: "ഒരാൾ അഹങ്കാരത്തോടെ, തന്റെ വസ്ത്രം വലിച്ചിഴച്ചാൽ, അല്ലാഹു അവനിലേക്ക് നോക്കുകയില്ല". ഉമ്മു സലമ(റ) ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, സ്ത്രീകൾ അവരുടെ വസ്ത്രത്തിന്റെ താഴ്ഭാഗമെന്താണ് ചെയ്യുക? നബി(സ) പറഞ്ഞു: "നിങ്ങൾക്കത് ഒരു ചാൺ താഴ്ത്താം." അവർ പറഞ്ഞു: അപ്പോൾ അവരുടെ കാലുകൾ വെളിവാകുമല്ലോ? നബി(സ) പറഞ്ഞു: "ഒരു മുഴം നിങ്ങൾക്ക് താഴ്ത്താം. അതിനേക്കാൾ അധികരിപ്പിക്കരുത്." (ന)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 655, 655, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 61, 'عَنْ صَفِيَّةَ، عَنْ أُمِّ سَلَمَةَ، رَضِيَ الله عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَمَّا ذُكِرَ فِي الْإِزَارِ مَا ذُكِرَ قَالَتْ أُمُّ سَلَمَةَ: فَكَيْفَ بِالنِّسَاءِ؟ قَالَ: "يُرْخِينَ شِبْرًا". قَالَتْ: إِذًا تَبْدُوَ أَقْدَامُهُنَّ. قَالَ: "فَذِرَاعًا لَا يَزِدْنَ عَلَيْهِ". (ن)', 'സ്വഫിയ്യ(റ): ഉമ്മുസലമ(റ)യെ കുറിച്ച് ഉധരിക്കുന്നു: നബി(സ) തുണിയെ കുറിച്ച് പറയാനുള്ളതെല്ലാം പറഞ്ഞു കഴിഞ്ഞപ്പോൾ ഉമ്മുസലമ(റ) ചോദിച്ചു: അപ്പോൾ സ്ത്രീകളോ? നബി(സ) പറഞ്ഞു: "അവർ ഒരു ചാൺ താഴ്ത്തട്ടെ". ഉമ്മു സലമ(റ) പറഞ്ഞു: അപ്പോൾ അവരുടെ പാദങ്ങൾ വെളിവാകുമല്ലോ. റസൂൽ(സ) പറഞ്ഞു: "എങ്കിൽ ഒരു മുഴം. കൂടുതലാക്കരുത്." (ന)', 'صَفِيَّةَ، عَنْ أُمِّ سَلَمَةَ،', 'സ്വഫിയ്യ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 655, 655, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 62, 'عَنِ ابْنِ عُمَرَ رَضِيَ الله عَنْهُمَا: أَنَّ أَزْوَاجَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَخَّصَ لَهُنَّ فِي الذَّيْلِ ذِرَاعًا، فَكُنَّ يَأْتِينَا فَنَذْرَعُ لَهُنَّ بِالْقَصَبِ ذِرَاعًا. (د،جه)', 'ഇബ്‌നുഉമർ(റ): നബി(സ)യുടെ പത്നിമാർക്ക് വസ്ത്രത്തിന്റെ കര ഒരു മുഴമാക്കാൻ ഇളവ് നൽകപ്പെട്ടിരിക്കുന്നു. അവർ ഞങ്ങളുടെ അടുത്ത് വരികയും ഞങ്ങൾ അവർക്ക് വേണ്ടി ചൂരൽ കൊണ്ട് ഒരു മുഴം അളക്കുകയും ചെയ്യുമായിരുന്നു. (ദ,ജ)', 'ابْنِ عُمَرَ', 'ഇബ്‌നുഉമർ(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 655, 656, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 63, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ لِفَاطِمَةَ أَوْ لِأُمِّ سلمة رَضِيَ اللهُ عَنْهُمَا: "ذَيْلُكِ ذِرَاعٌ". في سنده ضعيف (جه)', 'അബൂഹുറൈറ(റ): നബി(സ) ഫാത്വിമ(റ)യോടോ ഉമ്മുസലമ(റ)യോടോ പറഞ്ഞു: "നിന്റെ വസ്ത്രത്തിന്റെ താഴ്ഭാഗം ഒരു മുഴമാണ്." പരമ്പരയിൽ ബലഹീനനുണ്ട്. (ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 656, 656, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 64, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ، عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: فِي ذُيُولِ النِّسَاءِ: "شِبْرًا". فَقَالَتْ عَائِشَةُ: إِذًا تَخْرُجُ سُوقُهُنَّ. قَالَ: "فَذِرَاعٌ". في سنده ضعيف. (جه)', 'അബൂഹുറൈറ(റ) പറയുന്നു: നബി(സ) സ്ത്രീകളുടെ വസ്ത്രത്തിന്റെ താഴ്ഭാഗത്തെക്കുറിച്ച് പറഞ്ഞു: "ഒരു ചാൺ". അപ്പോൾ ആഇശ(റ) പറഞ്ഞു: അപ്പോൾ അവരുടെ കണങ്കാൽ വെളിവാകും. നബി(സ) പറഞ്ഞു: "എന്നാൽ ഒരു മുഴം." പരമ്പരയിൽ ബലഹീനനുണ്ട്. (ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 656, 656, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 65, 'عَنْ أُمِّ سلمة رَضِيَ اللهُ عَنْهَا: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ شَبَّرَ لِفَاطِمَةَ شِبْرًا مِنْ نِطَاقِهَا. (د،ت،ن،جه)', 'ഉമ്മുസലമ(റ): നബി(സ) ഫാത്വിമ(റ) ബീവിക്ക് അവരുടെ പാവാടക്ക് ഒരു ചാൺ കണക്കാക്കിക്കൊടുത്തു. (ദ,തു,ന,ജ)', 'أُمِّ سلمة', 'ഉമ്മുസലമ(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 656, 656, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 66, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: رَخَّصَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لِأُمَّهَاتِ الْمُؤْمِنِينَ فِي الذَّيْلِ شِبْرًا، ثُمَّ اسْتَزَدْنَهُ، فَزَادَهُنَّ شِبْرًا، فَكُنَّ يُرْسِلْنَ إِلَيْنَا، فَنَذْرَعُ لَهُنَّ ذِرَاعًا. (د،ن،جه)', 'ഇബ്‌നുഉമർ(റ): നബി(സ) ഉമ്മഹാതുൽ മുഅ്മിനീങ്ങൾക്ക് വസ്ത്രത്തിന്റെ താഴ്ഭാഗത്തിൽ ഒരു ചാൺ ഇളവ് നൽകിയിരുന്നു. പിന്നീടവർ അവിടുത്തോട് കൂട്ടാൻ ആവശ്യപ്പെട്ടു. അപ്പോൾ അവർക്ക് ഒരു ചാൺ കൂട്ടിക്കൊടുത്തു. അവർ ഞങ്ങളുടെ അടുത്തേക്ക് ആളെ അയക്കുമായിരുന്നു. അപ്പോൾ ഞങ്ങൾ അവർക്ക് ഒരു മുഴം അളന്ന് കൊടുക്കും. (ദ,ന,ജ)', 'ابْنِ عُمَرَ', 'ഇബ്‌നുഉമർ(റ)', null, null, array['د','ن','جه']::text[], array['ദ','ന','ജ']::text[], null, null, 656, 656, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 67, 'عَنْ سُوَيْدِ بْنِ قَيْسٍ رَضِيَ اللهُ عَنْهُ قَالَ: أَتَانَا النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فساومنا سراويل. (جه)', 'സുവൈദുബ്നു ഖൈസ്(റ): നബി(സ) ഞങ്ങളുടെ അടുത്ത് വന്ന് ഞങ്ങളോട് പൈജാമകൾക്ക് വില പറഞ്ഞു. (ജ)', 'سُوَيْدِ بْنِ قَيْسٍ', 'സുവൈദുബ്നു ഖൈസ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 656, 656, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 68, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّهُ سَمِعَ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: بِعَرَفَاتٍ: "مَنْ لَمْ يَجِدْ إِزَارًا فَلْيَلْبَسِ السَّرَاوِيلَ، وَمَنْ لَمْ يَجِدْ نَعْلَيْنِ فَلْيَلْبَسْ خُفَّيْنِ". (ن)', 'ഇബ്‌നുഅബ്ബാസ്(റ): നബി(സ) അറഫയിൽ വെച്ച് പറയുന്നത് അദ്ദേഹം കേട്ടു: "തുണി കിട്ടാത്തവൻ പൈജാമ ധരിക്കട്ടെ. ചെരുപ്പുകൾ കിട്ടാത്തവൻ രണ്ട് ഖുഫ്ഫകൾ ധരിക്കട്ടെ". (ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്‌നുഅബ്ബാസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 656, 656, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 69, 'عَنْ أَبِي مُوسَى الْأَشْعَرِيِّ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "حُرِّمَ لِبَاسُ الْحَرِيرِ وَالذَّهَبِ عَلَى ذُكُورِ أُمَّتِي، وَأُحِلَّ لِإِنَاثِهِمْ". حَسَنٌ صَحِيحٌ (ت،ن)', 'അബൂമൂസൽ അശ്അരി(റ): റസൂൽ(സ) പറയുന്നു: "എന്റെ സമുദായത്തിലെ പുരുഷന്മാർക്ക് സ്വർണ്ണവും പട്ടും നിഷിദ്ധമാക്കപ്പെട്ടിരിക്കുന്നു. സ്ത്രീകൾക്കത് അനുവദനീയവുമാണ്". (തു,ന)', 'أَبِي مُوسَى الْأَشْعَرِيِّ', 'അബൂമൂസൽ അശ്അരി(റ)', null, null, array['ت','ن']::text[], array['തു','ന']::text[], null, null, 657, 657, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 70, 'عَنْ سُوَيْدِ بْنِ غَفَلَةَ رَضِيَ اللَّهُ عَنْهُ، عَنْ عُمَرَ رَضِيَ اللَّهُ عَنْهُ: أَنَّهُ خَطَبَ بِالْجَابِيَةِ فَقَالَ: نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الْحَرِيرِ إِلَّا مَوْضِعَ أُصْبُعَيْنِ أَوْ ثَلَاثٍ أَوْ أَرْبَعٍ. حَسَنٌ صَحِيحٌ (م،ت)', 'സുവൈദുബിൻ ഗഫല(റ): ഉമർ(റ) ജാബിയ എന്ന സ്ഥലത്ത് വെച്ച് പ്രസംഗിച്ചു: റസൂൽ(സ) പട്ട് നിഷിദ്ധമാക്കിയിരിക്കുന്നു. രണ്ടോ മൂന്നോ അല്ലെങ്കിൽ നാലോ വിരലുകളുടെ സ്ഥലം ഒഴികെ. (മു,തു)', 'سُوَيْدِ بْنِ غَفَلَةَ', 'സുവൈദുബിൻ ഗഫല(റ)', null, null, array['م','ت']::text[], array['മു','തു']::text[], null, null, 657, 657, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 71, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ عُمَرَ بْنَ الْخَطَّابِ رَضِيَ اللَّهُ عَنْهُ رَأَى حُلَّةَ سِيَرَاءَ عِنْدَ بَابِ الْمَسْجِدِ تُبَاعُ، فَقَالَ: يَا رَسُولَ اللَّهِ، لَوِ اشْتَرَيْتَ هَذِهِ فَلَبِسْتَهَا يَوْمَ الْجُمُعَةِ، وَلِلْوَفْدِ إِذَا قَدِمُوا عَلَيْكَ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِنَّمَا يَلْبَسُ هَذِهِ مَنْ لَا خَلَاقَ لَهُ فِي الْآخِرَةِ". ثُمَّ جَاءَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنْهَا حُلَلٌ، فَأَعْطَى عُمَرَ مِنْهَا حُلَّةً، فَقَالَ عُمَرُ: يَا رَسُولَ اللَّهِ، كَسَوْتَنِيهَا وَقَدْ قُلْتَ فِي حُلَّةِ عُطَارِدٍ مَا قُلْتَ؟ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِنِّي لَمْ أَكْسُكَهَا لِتَلْبَسَهَا". فَكَسَاهَا عُمَرُ أَخًا لَهُ مُشْرِكًا بِمَكَّةَ. وَفِي رِوَايَةٍ قَالَ: حُلَّةَ إِسْتَبْرَقٍ، ثُمَّ أَرْسَلَ إِلَيْهِ بِجُبَّةِ دِيبَاجٍ، وَقَالَ: "تَبِيعُهَا وَتُصِيبُ بِهَا حَاجَتَكَ". (ق،د،ن)', 'അബ്ദുല്ലാഹിബിൻ ഉമർ(റ): പള്ളിയുടെ വാതിലിന്റെയടുത്ത് പട്ടിൽ നെയ്ത, ശരീരം മുഴുവൻ മറക്കുന്ന ഒരു വസ്ത്രം വിൽക്കുന്നത് ഉമറുബ്നുൽഖത്താബ്(റ) കണ്ടു. ഉടനെ അവർ പറഞ്ഞു: തിരുദൂതരേ, അവിടന്ന് ഇത് വാങ്ങിയിരുന്നെങ്കിൽ, വെള്ളിയാഴ്ചയും നിവേദകസംഘം അവിടുത്തേക്ക് വരുമ്പോഴും ധരിക്കാമല്ലോ. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "പാരത്രികലോകത്ത് ഒരു വിഹിതവുമില്ലാത്തവൻ മാത്രമാണ് ഇത് ധരിക്കുക." ശേഷം അതിൽ നിന്ന് കുറച്ച് വസ്ത്രങ്ങൾ റസൂൽ(സ)ക്ക് എത്തി. നബി(സ) അതിൽ നിന്ന് ഒന്ന് ഉമർ(റ)വിന് നൽകി. അപ്പോൾ ഉമർ(റ) പറഞ്ഞു: തിരുദൂതരേ, അവിടന്ന് എന്നെ ഇത് ധരിപ്പിക്കുകയാണോ, അങ്ങ് ആ വ്യാപാരിയുടെ വസ്ത്രത്തെക്കുറിച്ച് ഇങ്ങനെ പറഞ്ഞിരുന്നല്ലോ? അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "ഞാൻ നിങ്ങൾക്കത് ധരിക്കാൻ വേണ്ടിയല്ല തന്നത്." അപ്പോൾ ഉമർ(റ) മക്കയിലുള്ള, മുശ്രിക്കായ തന്റെ സഹോദരനെ അത് ധരിപ്പിച്ചു. മറ്റൊരു റിപ്പോർട്ടിൽ നിവേദകൻ പറയുന്നു: ഇസ്തബ്റഖ് എന്ന ഇനം പട്ടിന്റെ ഒരു വസ്ത്രം, ശേഷം ദീബാജ് എന്ന ഇനം പട്ടിന്റെ ജുബ്ബ അദ്ദേഹത്തിന് കൊടുത്തയച്ചു. റസൂൽ(സ) പറഞ്ഞു: "താങ്കൾ അത് വിറ്റ് ആവശ്യം നിറവേറ്റുക". (ബു,മു,ദ,ന).', 'ابْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബിൻ ഉമർ(റ)', null, null, array['ق','د','ن']::text[], array['ബു','മു','ദ','ന']::text[], null, null, 657, 657, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=23 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=8 and h.hadith_no=71), 1, 'وَفِي رِوَايَةٍ قَالَ: حُلَّةَ إِسْتَبْرَقٍ، ثُمَّ أَرْسَلَ إِلَيْهِ بِجُبَّةِ دِيبَاجٍ، وَقَالَ: "تَبِيعُهَا وَتُصِيبُ بِهَا حَاجَتَكَ". (ق،د،ن)', 'മറ്റൊരു നിവേദനിൽ നിവേദകൻ പറയുന്നു: ഇസ്തബ്റഖ് എന്ന ഇനം പട്ടിന്റെ ഒരു വസ്ത്രം, ശേഷം ദീബാജ് എന്ന ഇനം പട്ടിന്റെ ജുബ്ബ അദ്ദേഹത്തിന് കൊടുത്തയച്ചു. റസൂൽ(സ) പറഞ്ഞു: "താങ്കൾ അത് വിറ്റ് ആവശ്യം നിറവേറ്റുക". (ബു,മു,ദ,ന).');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 72, 'عَنْ أَبِي عُثْمَانَ النَّهْدِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَتَبَ عُمَرُ - رَضِيَ اللَّهُ عَنْهُ - إِلَى عُتْبَةَ ابْنِ فَرْقَدٍ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنِ الْحَرِيرِ إِلَّا مَا كَانَ هَكَذَا وَهَكَذَا: أَصْبُعَيْنِ، وَثَلَاثَةٍ وَأَرْبَعَةٍ. (ق،د،ن،جه)', 'അബൂഉസ്മാനന്നഹ്ദി(റ): ഉത്ബതുബ്നു ഫർഖദ്(റ)വിന് ഉമർ(റ) എഴുതി: ഇതുപോലെ രണ്ടോ മൂന്നോ നാലോ വിരലുകളുടെ അളവല്ലാത്ത പട്ട് നബി(സ) നിരോധിച്ചിരിക്കുന്നു. (ബു,മു,ദ,ന,ജ)', 'أَبِي عُثْمَانَ النَّهْدِيِّ', 'അബൂഉസ്മാനന്നഹ്ദി(റ)', null, null, array['ق','د','ن','جه']::text[], array['ബു','മു','ദ','ന','ജ']::text[], null, null, 657, 658, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=23 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 73, 'عَنْ عَلِيٍّ رَضِيَ اللَّهُ عَنْهُ قَالَ: أُهْدِيَتْ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حُلَّةٌ سِيَرَاءُ، فَأَرْسَلَ بِهَا إِلَيَّ، فَلَبِسْتُهَا فَأَتَيْتُهُ، فَرَأَيْتُ الْغَضَبَ فِي وَجْهِهِ، وَقَالَ: "إِنِّي لَمْ أُرْسِلْ بِهَا إِلَيْكَ لِتَلْبَسَهَا". وَأَمَرَنِي فَأَطَرْتُهَا بَيْنَ نِسَائِي. (م،د،ن)', 'അലി(റ): പട്ടില്‍ നെയ്ത ഒരു വസ്ത്രം റസൂല്‍(സ)ക്ക് സമ്മാനിക്കപ്പെട്ടു. അവിടന്നതെനിക്ക് അയച്ചു തന്നു. ഞാനതു ധരിച്ച് തിരുസന്നിധിയില്‍ ചെന്നു. അപ്പോള്‍ അവിടുത്തെ മുഖത്ത് ഞാന്‍ ദേഷ്യം കണ്ടു. ശേഷം റസൂല്‍(സ) പറഞ്ഞു: "ഞാന്‍ നിങ്ങള്‍ക്കത് അയച്ച് തന്നത് താങ്കളത് ധരിക്കാനല്ല." ഉടനെ അവിടുത്തെ കല്‍പന പ്രകാരം എന്റെ ഭാര്യമാര്‍ക്കിടയില്‍ ഞാനത് വീതിച്ചു. (മു,ദ,ന)', 'عَلِيٍّ', 'അലി(റ)', null, null, array['م','د','ن']::text[], array['മു','ദ','ന']::text[], null, null, 658, 658, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=23 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 74, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: سَمِعْتُ عُمَرَ يَذْكُرُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ لَبِسَ الْحَرِيرَ فِي الدُّنْيَا لَمْ يَلْبَسْهُ فِي الْآخِرَةِ". حَسَنٌ صَحِيحٌ. (م،ت،ن)', 'ഇബ്‌നുഉമര്‍(റ): ഉമര്‍(റ) പറയുന്നത് ഞാന്‍ കേട്ടു: നബി(സ) പറഞ്ഞു: "ദുന്‍യാവില്‍ പട്ട് ധരിച്ചവന്‍ ആഖിറത്തില്‍ അത് ധരിക്കുകയില്ല." (മു,തു,ന)', 'ابْنِ عُمَرَ', 'ഇബ്‌നുഉമര്‍(റ)', null, null, array['م','ت','ن']::text[], array['മു','തു','ന']::text[], null, null, 658, 658, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=23 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 75, 'عَنِ الْبَرَاءِ رَضِيَ اللَّهُ عَنْهُ قَالَ: نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الدِّيبَاجِ وَالْحَرِيرِ وَالْإِسْتَبْرَقِ. (جه)', 'ബറാഅ്(റ): റസൂല്‍(സ) ദീബാജും ഇസ്തബ്‌റഖും ഹരീറും (പട്ടിന്റെ മൂന്ന് ഇനങ്ങള്‍) നിരോധിച്ചിരിക്കുന്നു. (ജ)', 'الْبَرَاءِ', 'ബറാഅ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 658, 658, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=23 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 76, 'عَنْ حُذَيْفَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ لُبْسِ الْحَرِيرِ وَالذَّهَبِ، وَقَالَ: "هُوَ لَهُمْ فِي الدُّنْيَا، وَلَنَا فِي الْآخِرَةِ". (جه)', 'ഹുദൈഫ(റ): പട്ടും സ്വര്‍ണ്ണവും ധരിക്കല്‍ റസൂല്‍(സ) നിരോധിച്ചിരിക്കുന്നു. നബി(സ) പറയുന്നു: "അത് ദുന്‍യാവില്‍ അവര്‍ക്കും ആഖിറത്തില്‍ നമുക്കുമാണ്." (ജ)', 'حُذَيْفَةَ', 'ഹുദൈഫ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 658, 658, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=23 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 77, 'عَنْ عُمَرَ رَضِيَ اللَّهُ عَنْهُ: أَنَّهُ كَانَ يَنْهَى عَنِ الْحَرِيرِ وَالدِّيبَاجِ، إِلَّا مَا كَانَ هَكَذَا. ثُمَّ أَشَارَ بِإِصْبَعِهِ، ثُمَّ الثَّانِيَةِ، ثُمَّ الثَّالِثَةِ، ثُمَّ الرَّابِعَةِ، فَقَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَنْهَانَا عَنْهُ. (جه)', 'ഉമര്‍(റ): അദ്ദേഹം പട്ടും ദീബാജും നിരോധിച്ചിരുന്നു, ഈ കണക്കൊഴികെ. ശേഷം ഉമര്‍(റ) തന്റെ ഒരു വിരല്‍ കൊണ്ട്, പിന്നെ രണ്ടാമത്തെ, പിന്നെ മൂന്നാമത്തെ, പിന്നെ നാലാമത്തെ വിരല്‍ കൊണ്ടും സൂചിപ്പിക്കുമായിരുന്നു. എന്നിട്ട് പറയും: റസൂല്‍(സ) ഞങ്ങള്‍ക്കത് നിരോധിച്ചിരുന്നു. (ജ)', 'عُمَرَ', 'ഉമര്‍(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 658, 658, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=23 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 78, 'عَنْ عَلِيِّ(بن أبي طالب) رَضِيَ اللَّهُ عَنْهُ: أَنَّ أُكَيْدِرَ دَوْمَةَ أَهْدَى إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ثَوْبَ حَرِيرٍ، فَأَعْطَاهُ عَلِيًّا [كَرَّمَ اللَّهُ وَجْهَهُ] فَقَالَ: "شَقِّقْهُ خُمُرًا بَيْنَ الْفَوَاطِمِ". (م)', 'അലി(റ): ഉകൈദിര്‍ ദൂമ(റ) നബി(സ)ക്ക് പട്ട് വസ്ത്രം ഹദ്‌യ നല്‍കി. അപ്പോള്‍ റസൂല്‍(സ) അത് അലി(റ)വിന് നല്‍കിയിട്ട് പറഞ്ഞു: "ഫാതിമമാര്‍ക്കിടയില്‍ താങ്കളതിനെ തലമക്കനയായി വീതിക്കുക." (മു)', 'عَلِيِّ(بن أبي طالب)', 'അലി(റ)', null, null, array['م']::text[], array['മു']::text[], 'كَرَّمَ اللَّهُ وَجْهَهُ', null, 658, 658, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=24 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 79, 'عَنْ عَلِيِّ بْنِ أَبِي طَالِبٍ رَضِيَ اللهُ عَنْهُ قَالَ: أَخَذَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ حَرِيرًا بِشِمَالِهِ، وَذَهَبًا بِيَمِينِهِ، ثُمَّ رَفَعَ بِهِمَا يَدَيْهِ فَقَالَ: "إِنَّ هَذَيْنِ حَرَامٌ عَلَى ذُكُورِ أُمَّتِي، حِلٌّ لِإِنَاثِهِمْ". (د،ن،جه)', 'അലിയ്യുബ്‌നു അബീത്വാലിബ്‌(റ): റസൂൽ(സ) അവിടുത്തെ ഇടതു കയ്യിൽ പട്ടും വലതു കയ്യിൽ സ്വർണ്ണവും എടുത്ത് അത് ഉയർത്തിക്കൊണ്ട് പറഞ്ഞു: "ഇവ രണ്ടും എന്റെ സമുദായത്തിലെ പുരുഷന്മാർക്ക് നിഷിദ്ധവും സ്ത്രീകൾക്ക് അനുവദനീയവുമാണ്". (ദ,ന,ജ)', 'عَلِيِّ بْنِ أَبِي طَالِبٍ', 'അലിയ്യുബ്‌നു അബീത്വാലിബ്‌(റ)', null, null, array['د','ن','جه']::text[], array['ദ','ന','ജ']::text[], null, null, 659, 659, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 80, 'عَنْ عَلِيٍّ رَضِيَ اللهُ عَنْهُ: أَنَّهُ أُهْدِيَ لِرَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ حُلَّةٌ مَكْفُوفَةٌ بِحَرِيرٍ، إِمَّا سَدَاهَا وَإِمَّا لُحْمَتُهَا، فَأَرْسَلَ بِهَا إِلَيَّ، فَأَتَيْتُهُ فَقُلْتُ: يَا رَسُولَ اللهِ، مَا أَصْنَعُ بِهَا؟ أَلْبَسُهَا؟ قَالَ: "لَا، وَلَكِنِ اجْعَلْهَا خُمُرًا بَيْنَ الْفَوَاطِمِ". (جه)', 'അലി(റ): വീതിയിലോ നീളത്തിലോ പട്ടു കൊണ്ട് കര വെക്കപ്പെട്ട ഒരു വസ്ത്രം റസൂൽ(സ)ക്ക് ഹദ്‌യ നൽകപ്പെട്ടു. അപ്പോൾ അവിടന്നതനിക്ക് അയച്ചുതന്നു. നബി(സ)യുടെ സന്നിധിയിൽ ചെന്ന് ഞാൻ ചോദിച്ചു: തിരുദൂതരേ, ഇതുകൊണ്ട് ഞാൻ എന്താണ് ചെയ്യേണ്ടത്? ഇത് ധരിക്കാൻ പറ്റുമോ? റസൂൽ(സ) പറഞ്ഞു: "പറ്റുകയില്ല. പക്ഷേ താങ്കളത് ഫാത്വിമമാർക്കിടയിൽ തലമക്കനയായി വീതിക്കുക".(ജ)', 'عَلِيٍّ', 'അലി(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 659, 659, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 81, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ: أَنَّهُ رَأَى عَلَى أُمِّ كُلْثُومٍ بِنْتِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بُرْدَ سِيَرَاءَ. وَالسِّيَرَاءُ الْمُضَلَّعُ بِالْقَزِّ. (ن)', 'അനസുബ്‌നു മാലിക്(റ): നബി(സ)യുടെ പുത്രി ഉമ്മുകുൽസും(റ)യുടെ ശരീരത്തിൽ പട്ട് കലർത്തിനെയ്ത വസ്ത്രം ഞാൻ കണ്ടു. ''സിയറാഅ്'' എന്ന് പറഞ്ഞാൽ പട്ട് കൊണ്ട് ചിത്രപ്പണി ചെയ്ത വസ്ത്രമാണ്. (ന)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്‌നു മാലിക്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 659, 659, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 82, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ قَالَ: رَأَيْتُ عَلَى زَيْنَبَ بِنْتِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَمِيصَ حَرِيرٍ سِيَرَاءَ. (ن،جه)', 'അനസ്(റ): റസൂൽ(സ)യുടെ മകളായ സൈനബ്(റ)യുടെ ശരീരത്തിൽ പട്ടിൽ നെയ്ത ഒരു ഖമീസ് ഞാൻ കണ്ടു. (ന,ജ)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['ن','جه']::text[], array['ന','ജ']::text[], null, null, 659, 659, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 83, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: كُنَّا نَنْزِعُهُ عَنِ الْغِلْمَانِ، وَنَتْرُكُهُ عَلَى الْجَوَارِي. (د)', 'ജാബിർ(റ): ഞങ്ങൾ അത് ആൺകുട്ടികളിൽ നിന്ന് അഴിക്കുകയും പെൺകുട്ടികൾക്ക് ഇട്ടുകൊടുക്കുകയും ചെയ്യുമായിരുന്നു. (ദ)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 659, 659, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 84, 'عَنْ عُمَرَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنِ الْحَرِيرِ إِلَّا هَكَذَا، وَأَشَارَ بِإِصْبَعَيْهِ اللَّتَيْنِ تَلِيَانِ الْإِبْهَامَ، يَعْنِي الْأَعْلَامَ. (خ)', 'ഉമർ(റ): റസൂൽ(സ) പട്ട് നിരോധിച്ചിരിക്കുന്നു, ഈ തോതൊഴികെ. നബി(സ) അവിടുത്തെ ചൂണ്ടുവിരലും നടുവിരലും ചൂണ്ടിക്കാണിച്ചു. അഥവാ ഭംഗിക്ക് വേണ്ടിയുള്ള കരയാണ് അവിടന്നുദ്ദേശിക്കുന്നത്. (ബു)', 'عُمَرَ', 'ഉമർ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 659, 659, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 85, 'عَنْ حُذَيْفَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: نَهَانَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ نَشْرَبَ فِي آنِيَةِ الذَّهَبِ وَالْفِضَّةِ، وَأَنْ نَأْكُلَ فِيهَا، وَعَنْ لُبْسِ الْحَرِيرِ، وَالدِّيبَاجِ وَأَنْ نَجْلِسَ عَلَيْهِ. (خ)', 'ഹുദൈഫ(റ): സ്വർണ്ണത്തിന്റെയും വെള്ളിയുടെയും പാത്രത്തിൽ കുടിക്കലും ഭക്ഷിക്കലും, പട്ടും ദീബാജും (ഒരു ഇനം പട്ട്) ധരിക്കലും, അതിൽ ഇരിക്കലും നബി(സ) ഞങ്ങൾക്ക് നിരോധിച്ചിരിക്കുന്നു. (ബു)', 'حُذَيْفَةَ', 'ഹുദൈഫ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 660, 660, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 86, 'عَنْ خَلِيفَةَ بْنِ كَعْبٍ رَضِيَ اللَّهُ عَنْهُ [أَبِي ذُبْيَانَ] قَالَ: سَمِعْتُ عَبْدَ اللَّهِ بْنَ الزُّبَيْرِ يَخْطُبُ يَقُولُ: أَلَا لَا تُلْبِسُوا نِسَاءَكُمُ الْحَرِيرَ، فَإِنِّي سَمِعْتُ عُمَرَ بْنَ الْخَطَّابِ يَقُولُ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَا تَلْبَسُوا الْحَرِيرَ، فَإِنَّهُ مَنْ لَبِسَهُ فِي الدُّنْيَا لَمْ يَلْبَسْهُ فِي الْآخِرَةِ". (م)', 'ഖലീഫതുബ്നു കഅ്ബ്(റ) (അബൂദിബ്‌യാൻ): അബ്ദുല്ലാഹിബ്നു സുബൈർ(റ) പ്രസംഗിക്കുന്നത് ഞാൻ കേട്ടു: അറിയുക, നിങ്ങളുടെ സ്ത്രീകളെ നിങ്ങൾ പട്ട് ധരിപ്പിക്കരുത്. കാരണം ഉമർ(റ) പറയുന്നത് ഞാൻ കേട്ടിട്ടുണ്ട്: റസൂൽ(സ) പറഞ്ഞിരിക്കുന്നു: "നിങ്ങൾ പട്ട് ധരിക്കരുത്. കാരണം ദുൻയാവിൽ അത് ധരിച്ചവൻ ആഖിറത്തിൽ അത് ധരിക്കുകയില്ല." (മു)', 'خَلِيفَةَ بْنِ كَعْبٍ', 'ഖലീഫതുബ്നു കഅ്ബ്(റ)', null, null, array['م']::text[], array['മു']::text[], 'أَبِي ذُبْيَانَ', null, 660, 660, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=27 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 87, 'عَنْ عِمْرَانَ بْنِ حِطَّانَ رَضِيَ اللَّهُ عَنْهُ: أَنَّهُ سَأَلَ عَبْدَ اللَّهِ بْنَ عَبَّاسٍ عَنْ لُبْسِ الْحَرِيرِ، فَقَالَ: سَلْ عَائِشَةَ. فَسَأَلْتُ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: سَلْ عَبْدَ اللَّهِ ابْنَ عُمَرَ. فَسَأَلْتُ ابْنَ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا فَقَالَ: حَدَّثَنِي أَبُو حَفْصٍ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ لَبِسَ الْحَرِيرَ فِي الدُّنْيَا فَلَا خَلَاقَ لَهُ فِي الْآخِرَةِ". (ن)', 'ഇംറാനുബ്നു ഹിത്വാൻ(റ): അദ്ദേഹം അബ്ദുല്ലാഹിബ്നു അബ്ബാസ്(റ)വിനോട് പട്ട് ധരിക്കുന്നതിനെ കുറിച്ച് ചോദിച്ചു. അപ്പോൾ അദ്ദേഹം പറഞ്ഞു: നീ ആഇശ(റ)യോട് ചോദിക്കുക. അങ്ങനെ ഞാൻ ആഇശ(റ)യോട് ചോദിച്ചപ്പോൾ അവർ പറഞ്ഞു: നീ അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)വിനോട് ചോദിക്കുക. ഞാൻ ഇബ്നുഉമർ(റ)വിനോട് ചോദിച്ചു. അദ്ദേഹം പറഞ്ഞു: എന്നോട് അബൂഹഫ്സ് (ഉമർ-റ-) പറഞ്ഞിട്ടുണ്ട്: റസൂൽ(സ) പറഞ്ഞിരിക്കുന്നു: "ദുൻയാവിൽ ആരെങ്കിലും പട്ട് ധരിച്ചാൽ ആഖിറത്തിൽ അവന് ഒരു വിഹിതവും ഉണ്ടാവുകയില്ല." (ന)', 'عِمْرَانَ بْنِ حِطَّانَ', 'ഇംറാനുബ്നു ഹിത്വാൻ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 660, 660, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=27 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 88, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِنَّمَا يَلْبَسُ الْحَرِيرَ مَنْ لَا خَلَاقَ لَهُ". (ن)', 'ഇബ്നുഉമർ(റ): റസൂലുല്ലാഹി(സ) അരുളി: "(നന്മയിൽ നിന്ന്) ഒരു വിഹിതവുമില്ലാത്തവർ മാത്രമാണ് പട്ട് ധരിക്കുക." (ന)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 660, 660, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=27 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 89, 'عَنْ عَلِيٍّ الْبَارِقِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: أَتَتْنِي امْرَأَةٌ تَسْتَفْتِينِي، فَقُلْتُ لَهَا: هَذَا ابْنُ عُمَرَ. فَاتَّبَعَتْهُ تَسْأَلُهُ، وَاتَّبَعْتُهَا أَسْمَعُ مَا يَقُولُ، قَالَتْ: أَفْتِنِي فِي الْحَرِيرِ؟ قَالَ: نَهَى عَنْهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. (ن)', 'അലിയ്യുൽ ബാരിഖി(റ): ഫത്വ ചോദിച്ച് ഒരു സ്ത്രീ എന്റെയടുത്തു വന്നു. ഞാൻ അവളോട് പറഞ്ഞു: ഇവിടെയിതാ ഇബ്നുഉമർ(റ). അപ്പോൾ ആ സ്ത്രീ ഇബ്നുഉമർ(റ)വിനോട് ചോദിച്ചു കൊണ്ട് പിന്തുടർന്നു. അദ്ദേഹം എന്താണ് പറയുന്നതെന്നറിയാൻ ഞാൻ അവളെയും പിന്തുടർന്നു. അവൾ പറഞ്ഞു: പട്ടിന്റെ വിഷയത്തിൽ എനിക്ക് ഫത്വ തന്നാലും. അദ്ദേഹം പറഞ്ഞു: റസൂൽ(സ) അത് നിരോധിച്ചിരിക്കുന്നു. (ന)', 'عَلِيٍّ الْبَارِقِيِّ', 'അലിയ്യുൽ ബാരിഖി(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 660, 660, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=27 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 90, 'عَنْ عَلِيِّ بْنِ أَبِي طَالِبٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنْ لُبْسِ الْقَسِّيِّ، وَعَنْ لُبْسِ الْمُعَصْفَرِ، وَعَنْ تَخَتُّمِ الذَّهَبِ، وَعَنِ الْقِرَاءَةِ فِي الرُّكُوعِ. وَفِي رِوَايَةٍ: وَالسُّجُودِ. وَفِي رِوَايَةٍ: وَلَا أَقُولُ نَهَاكُمْ. (م،د،ت،ن،جه)', 'അലിയ്യുബ്‌നു അബീത്വാലിബ്(റ): ഖസ്സിയ്യ് (മിസ്റിൽ നിന്ന് കൊണ്ടുവരുന്ന ഒരു പട്ട്വസ്ത്രം), മഞ്ഞച്ചായം മുക്കിയ വസ്ത്രം, സ്വർണ്ണമോതിരം എന്നിവ ധരിക്കലും റുകൂഇൽ ഖുർആൻ ഓതലും - മറ്റൊരു റിപ്പോർട്ടിൽ: സുജൂദിലും - റസൂൽ(സ) നിരോധിച്ചിരിക്കുന്നു. മറ്റൊരു റിപ്പോർട്ടിൽ: നിങ്ങൾക്ക് നിരോധിച്ചിരിക്കുന്നുവെന്ന് ഞാൻ പറയുന്നില്ല. (മു,ദ,തു,ന,ജ)', 'عَلِيِّ بْنِ أَبِي طَالِبٍ', 'അലിയ്യുബ്‌നു അബീത്വാലിബ്(റ)', null, null, array['م','د','ت','ن','جه']::text[], array['മു','ദ','തു','ന','ജ']::text[], null, null, 660, 661, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=27 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=8 and h.hadith_no=90), 1, 'وَفِي رِوَايَةٍ: وَالسُّجُودِ.', 'മറ്റൊരു നിവേദനിൽ: സുജൂദിലും - റസൂൽ(സ) നിരോധിച്ചിരിക്കുന്നു.');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=8 and h.hadith_no=90), 2, 'وَفِي رِوَايَةٍ: وَلَا أَقُولُ نَهَاكُمْ. (م،د،ت،ن،جه)', 'മറ്റൊരു നിവേദനിൽ: നിങ്ങൾക്ക് നിരോധിച്ചിരിക്കുന്നുവെന്ന് ഞാൻ പറയുന്നില്ല. (മു,ദ,തു,ന,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 91, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ مَلِكَ الرُّومِ أَهْدَى إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مُسْتَقَةً مِنْ سُنْدُسٍ، فَلَبِسَهَا، فَكَأَنِّي أَنْظُرُ إِلَى يَدَيْهِ تَذَبْذَبَانِ، ثُمَّ بَعَثَ بِهَا إِلَى جَعْفَرٍ فَلَبِسَهَا ثُمَّ جَاءَهُ، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِنِّي لَمْ أُعْطِكَهَا لِتَلْبَسَهَا". قَالَ: فَمَا أَصْنَعُ بِهَا؟ قَالَ: "أَرْسِلْ بِهَا إِلَى أَخِيكَ النَّجَاشِيِّ". (د)', 'അനസുബ്‌നു മാലിക്(റ): റോമിലെ രാജാവ് നബി(സ)ക്ക് മിനുസമുള്ള വിലപിടിച്ച നീണ്ട കയ്യുള്ള ഒരു പട്ട് വസ്ത്രം സമ്മാനിച്ചു. അപ്പോൾ അവിടന്നത് ധരിച്ചു. അതിന്റെ ഇളകിക്കൊണ്ടിരിക്കുന്ന രണ്ട് കൈകളിലേക്ക് ഞാനിപ്പോഴും നോക്കുന്നത് പോലെ. പിന്നെ അത് ജഅ്ഫർ(റ)വിന് കൊടുത്തയച്ചു. അദ്ദേഹം അത് ധരിച്ച് തിരുസന്നിധിയിൽ വന്നപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങൾ അത് ധരിക്കാനായിരുന്നില്ല ഞാൻ തന്നത്." അദ്ദേഹം ചോദിച്ചു: എങ്കിൽ ഞാനിതെന്ത് ചെയ്യും? അവിടന്ന് പറഞ്ഞു: "അത് താങ്കളുടെ സഹോദരനായ നജാശിക്ക് കൊടുത്തയക്കുക." (ദ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്‌നു മാലിക്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 661, 661, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=27 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 92, 'عَنْ عِمْرَانَ بْنِ حُصَيْنٍ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ نَبِيَّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا أَرْكَبُ الْأُرْجُوَانَ وَلَا أَلْبَسُ الْمُعَصْفَرَ، وَلَا أَلْبَسُ الْقَمِيصَ الْمُكَفَّفَ بِالْحَرِيرِ. أَلَا وَطِيبُ الرِّجَالِ رِيحٌ لَا لَوْنَ لَهُ، أَلَا وَطِيبُ النِّسَاءِ لَوْنٌ لَا رِيحَ لَهُ". (د،ت)', 'ഇംറാനുബ്‌നു ഹുസൈൻ(റ): നബി(സ) പറഞ്ഞു: "ഒട്ടകത്തിന്റെ ജീനിക്കടിയിൽ വെക്കുന്ന വസ്ത്രത്തിൽ ഞാൻ യാത്ര ചെയ്യുകയില്ല. ചായം മുക്കപ്പെട്ട വസ്ത്രം ഞാൻ ധരിക്കുകയില്ല. പട്ടുകൊണ്ട് കര വെക്കപ്പെട്ട ഖമീസും ഞാൻ ധരിക്കുകയില്ല. അറിയുക, പുരുഷൻമാരുടെ സുഗന്ധം വാസനയുള്ളതും നിറമില്ലാത്തതുമാണ്. അറിയുക, സ്ത്രീകളുടെ സുഗന്ധം നിറമുള്ളതും വാസന ഇല്ലാത്തതുമാകുന്നു." (ദ,തു)', 'عِمْرَانَ بْنِ حُصَيْنٍ', 'ഇംറാനുബ്‌നു ഹുസൈൻ(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 661, 661, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=27 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 93, 'عَنْ أَبِي رَيْحَانَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ عَشْرٍ: عَنِ الْوَشْرِ، وَالْوَشْمِ، وَالنَّتْفِ، وَعَنْ مُكَامَعَةِ الرَّجُلِ الرَّجُلَ بِغَيْرِ شِعَارٍ، وَعَنْ مُكَامَعَةِ الْمَرْأَةِ الْمَرْأَةَ بِغَيْرِ شِعَارٍ، وَأَنْ يَجْعَلَ الرَّجُلُ فِي أَسْفَلِ ثِيَابِهِ حَرِيرًا مِثْلَ الْأَعَاجِمِ، أَوْ يَجْعَلَ عَلَى مَنْكِبَيْهِ حَرِيرًا مِثْلَ الْأَعَاجِمِ، وَعَنِ النُّهْبَى، وَعَنْ رُكُوبِ النُّمُورِ، وَلُبُوسِ الْخَاتَمِ إِلَّا لِذِي سُلْطَانٍ. (د،ن)', 'അബൂറൈഹാന(റ): റസൂൽ(സ) പത്ത് കാര്യങ്ങൾ നിരോധിച്ചിരിക്കുന്നു: പല്ല് മൂർച്ചയാക്കൽ, പച്ചകുത്തൽ, മുഖത്തെ മുടി പറിച്ചു കളയൽ, അടിവസ്ത്രമില്ലാതെ ഒരു പുരുഷൻ മറ്റൊരു പുരുഷനോടൊപ്പം കിടക്കൽ, അടിവസ്ത്രമില്ലാതെ ഒരു സ്ത്രീ മറ്റൊരു സ്ത്രീയുടെ കൂടെ കിടക്കൽ, അനറബികൾ ചെയ്യുന്നത് പോലെ വസ്ത്രങ്ങൾക്കടിയിൽ പട്ട് വെക്കൽ, അല്ലെങ്കിൽ അനറബികളെപ്പോലെ തന്റെ ചുമലുകളിൽ പട്ട് വെക്കൽ, കൊള്ളചെയ്യൽ, പുലികളെ യാത്രക്ക് ഉപയോഗിക്കൽ, അധികാരമില്ലാത്തവൻ മോതിരം ധരിക്കൽ. (ദ,ന)', 'أَبِي رَيْحَانَةَ', 'അബൂറൈഹാന(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 661, 661, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=27 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 94, 'عَنْ عَلِيٍّ رَضِيَ اللَّهُ عَنْهُ قَالَ: نُهِيَ عَنْ مَيَاثِرِ الْأُرْجُوَانِ. (د)', 'അലി(റ): യാത്രക്കാരൻ ഒട്ടകത്തിന്റെ ജീനിക്കടിയിൽ വെക്കുന്ന (അതിൽ പട്ടും ദീബാജും ഉണ്ടാകും) വസ്ത്രം നിരോധിക്കപ്പെട്ടിരിക്കുന്നു. (ദ)', 'عَلِيٍّ', 'അലി(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 661, 661, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=27 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 95, 'عَنْ عَلِيٍّ رَضِيَ اللَّهُ عَنْهُ قَالَ: نَهَانِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ خَاتَمِ الذَّهَبِ، وَعَنْ لُبْسِ الْقَسِّيِّ وَالْمِيثَرَةِ الْحَمْرَاءِ. (د،ت،ن،جه)', 'അലി(റ): സ്വർണ്ണമോതിരവും ഖസിയ്യ് വസ്ത്രവും (മിസ്റിൽ നിന്നും കൊണ്ടു വരുന്ന ഒരു പട്ട് വസ്ത്രം) ജീനിക്കടിയിൽ വെക്കുന്ന ചുവന്ന വസ്ത്രവും റസൂൽ(സ) എനിക്ക് നിരോധിച്ചിരിക്കുന്നു. (ദ,തു,ന,ജ)', 'عَلِيٍّ', 'അലി(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 662, 662, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=27 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 96, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ صَلَّى فِي خَمِيصَةٍ لَهَا أَعْلَامٌ، فَنَظَرَ إِلَى أَعْلَامِهَا، فَلَمَّا سَلَّمَ قَالَ: "اذْهَبُوا بِخَمِيصَتِي هَذِهِ إِلَى أَبِي جَهْمٍ، فَإِنَّهَا أَلْهَتْنِي آنِفًا فِي صَلَاتِي، وَأْتُونِي بِأَنْبِجَانِيَّتِهِ". (ق،د،ن،جه)', 'ആഇശ(റ): വരകളുള്ള രോമത്തിന്റെ വസ്ത്രത്തിൽ റസൂൽ(സ) നിസ്കരിച്ചു. അങ്ങനെ റസൂൽ(സ) അതിലെ വരകളിലേക്ക് നോക്കി. ശേഷം സലാം ചൊല്ലിയപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "എന്റെ ഈ വരകളുള്ള രോമത്തിന്റെ വസ്ത്രവുമായി നിങ്ങൾ അബൂജഹ്മിന്റെയടുത്ത് പോവുക. കാരണം അത് എന്റെ നിസ്കാരത്തിൽ എന്നെ കുറച്ച് അശ്രദ്ധനാക്കിയിരിക്കുന്നു. അദ്ദേഹത്തിന്റെ വരകളില്ലാത്ത പരുക്കൻ വസ്ത്രം എനിക്ക് കൊണ്ടുവരിക." (ബു,മു,ദ,ന,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ق','د','ن','جه']::text[], array['ബു','മു','ദ','ന','ജ']::text[], null, null, 662, 662, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=27 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 97, 'عَنِ الْبَرَاءِ ابْنِ عَازِبٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: أَمَرَنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِسَبْعٍ وَنَهَانَا عَنْ سَبْعٍ: نَهَانَا عَنْ خَوَاتِيمِ الذَّهَبِ، وَعَنْ آنِيَةِ الْفِضَّةِ، وَعَنِ الْمَيَاثِرِ، وَالْقَسِّيَّةِ، وَالْإِسْتَبْرَقِ، وَالدِّيبَاجِ، وَالْحَرِيرِ. (ن)', 'ബറാഉബ്നു ആസിബ്(റ): റസൂൽ(സ) ഞങ്ങളോട് ഏഴ് കാര്യങ്ങൾ കൽപിക്കുകയും ഏഴ് കാര്യങ്ങൾ നിരോധിക്കുകയും ചെയ്തിട്ടുണ്ട്. സ്വർണ്ണമോതിരം, വെള്ളിപ്പാത്രങ്ങൾ, ജീനിക്കടിയിൽ വെക്കുന്ന പട്ടുവസ്ത്രം, ഖസ്സിയ്യ് (മിസ്റിൽ നിന്നും കൊണ്ടുവരുന്ന ഒരുതരം പട്ടുവസ്ത്രം), ഇസ്തബ്റഖ്, ദീബാജ്, ഹരീർ (പട്ടിന്റെ മൂന്ന് ഇനം) ഇവയാണവ. (ന)', 'الْبَرَاءِ ابْنِ عَازِبٍ', 'ബറാഉബ്നു ആസിബ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 662, 662, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=27 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 98, 'عَنْ عُقْبَةَ بْنِ عَامِرٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: أُهْدِيَ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَرُّوجُ حَرِيرٍ، فَلَبِسَهُ ثُمَّ صَلَّى فِيهِ، ثُمَّ انْصَرَفَ فَنَزَعَهُ نَزْعًا شَدِيدًا كَالْكَارِهِ لَهُ، ثُمَّ قَالَ: "لَا يَنْبَغِي هَذَا لِلْمُتَّقِينَ". (م)', 'ഉഖ്ബതുബ്നു ആമിർ(റ): റസൂൽ(സ)ക്ക് പട്ടിന്റെ രോമവസ്ത്രം സമ്മാനിക്കപ്പെട്ടു. അപ്പോൾ തന്നെ അത് ധരിക്കുകയും അതിൽ നിസ്കരിക്കുകയും ചെയ്തു. ശേഷം അവിടന്ന് വന്ന് അത് പെട്ടെന്ന് അഴിച്ചുവെച്ചു, അതിനെ വെറുക്കുന്നത് പോലെ. പിന്നെ തിരുമേനി(സ) പറഞ്ഞു: "ഇത് ഭയഭക്തിയുള്ളവർക്ക് യോജിച്ചതല്ല". (മു)', 'عُقْبَةَ بْنِ عَامِرٍ', 'ഉഖ്ബതുബ്നു ആമിർ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 662, 662, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=28 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 99, 'عَنْ أَبِي عُثْمَانَ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَتَبَ إِلَيْنَا عُمَرُ وَنَحْنُ بِأَذْرَبِيجَانَ: يَا عُتْبَةُ بْنَ فَرْقَدٍ، إِنَّهُ لَيْسَ مِنْ كَدِّكَ وَلَا مِنْ كَدِّ أَبِيكَ وَلَا مِنْ كَدِّ أُمِّكَ، فَأَشْبِعِ الْمُسْلِمِينَ فِي رِحَالِهِمْ مِمَّا تَشْبَعُ مِنْهُ فِي رَحْلِكَ، وَإِيَّاكُمْ وَالتَّنَعُّمَ وَزِيَّ أَهْلِ الشِّرْكِ وَلُبُوسَ الْحَرِيرِ، فَإِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنْ لُبُوسِ الْحَرِيرِ قَالَ: إِلَّا هَكَذَا، وَرَفَعَ لَنَا رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِصْبَعَيْهِ الْوُسْطَى وَالسَّبَّابَةَ وَضَمَّهُمَا. قَالَ زُهَيْرٌ: قَالَ عَاصِمٌ: هَذَا فِي الْكِتَابِ، قَالَ: وَرَفَعَ زُهَيْرٌ إِصْبَعَيْهِ. (م)', 'അബൂഉസ്മാൻ(റ): ഞങ്ങൾ അദർബൈജാൻ എന്ന സ്ഥലത്തായിരിക്കെ ഉമർ(റ) ഞങ്ങൾക്കെഴുതി: ഓ ഉഖ്ബതുബ്നു ഫർഖദ്, അത് നിന്റെയോ നിന്റെ പിതാവിന്റെയോ മാതാവിന്റെയോ അധ്വാനത്തിൽ പെട്ടതല്ല. അതുകൊണ്ട് നീ നിന്റെ കൂടാരത്തിൽ വെച്ച് വയറ് നിറക്കും പോലെ മുസ്‌ലിംകൾക്ക് അവരുടെ കൂടാരങ്ങളിൽ വെച്ച് വയറ് നിറപ്പിക്കുക. സുഖ ജീവിതവും മുശ്രികുകളുടെ വേഷവിധാനവും പട്ട് ധരിക്കുന്നതും നിങ്ങൾ സൂക്ഷിക്കുക. കാരണം റസൂൽ(സ) ഈ തോതല്ലാതെ പട്ട് ധരിക്കൽ നിരോധിച്ചിരിക്കുന്നു. തിരുമേനി(സ) അവിടുത്തെ നടുവിരലും ചൂണ്ടു വിരലും ഞങ്ങൾക്ക് ഉയർത്തി എന്നിട്ട് അതിനെ കൂട്ടിപ്പിടിച്ചു. സുഹൈർ(റ) പറയുന്നു: ആസിം(റ) പറയുന്നു: ഇത് ഗ്രന്ഥത്തിലുള്ളതാണ്. നിവേദകൻ പറയുന്നു: സുഹൈർ(റ)വും തന്റെ രണ്ട് വിരലുകൾ ഉയർത്തി. (മു)', 'أَبِي عُثْمَانَ', 'അബൂഉസ്മാൻ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 662, 663, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=29 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 100, 'عَنْ سُوَيْدِ بْنِ غَفَلَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ عُمَرَ بْنَ الْخَطَّابِ رَضِيَ اللهُ عَنْهُ خَطَبَ بِالْجَابِيَةِ فَقَالَ: نَهَى نَبِيُّ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَنْ لُبْسِ الْحَرِيرِ، إِلَّا مَوْضِعَ إِصْبَعَيْنِ أَوْ ثَلَاثٍ أَوْ أَرْبَعٍ. (م)', 'സുവൈദുബ്നു ഗഫല(റ): ജാബിയ എന്ന സ്ഥലത്ത് വെച്ച് ഉമറുബ്നുൽ ഖത്താബ്(റ) പ്രസംഗിച്ചു: പട്ട് ധരിക്കൽ നബി(സ) നിരോധിച്ചിരിക്കുന്നു. രണ്ടോ മൂന്നോ നാലോ വിരലിന്റെ സ്ഥലം ഒഴികെ. (മു)', 'سُوَيْدِ بْنِ غَفَلَةَ', 'സുവൈദുബ്നു ഗഫല(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 663, 663, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=29 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 101, 'عَنْ وَاقِدِ بْنِ عَمْرِو بْنِ سَعْدِ بْنِ مُعَاذٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَدِمَ أَنَسُ بْنُ مَالِكٍ رَضِيَ اللهُ عَنْهُ فَأَتَيْتُهُ، فَقَالَ: مَنْ أَنْتَ؟ فَقُلْتُ: أَنَا وَاقِدُ بْنُ عَمْرِو بْنِ سَعْدِ بْنِ مُعَاذٍ. قَالَ: فَبَكَى وَقَالَ: إِنَّكَ لَشَبِيهٌ بِسَعْدٍ، وَإِنَّ سَعْدًا كَانَ مِنْ أَعْظَمِ النَّاسِ وَأَطْوَلِهِمْ، وَإِنَّهُ بُعِثَ إِلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ جُبَّةٌ مِنْ دِيبَاجٍ مَنْسُوجٌ فِيهَا الذَّهَبُ، فَلَبِسَهَا رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَصَعِدَ الْمِنْبَرَ، فَقَامَ أَوْ قَعَدَ، فَجَعَلَ النَّاسُ يَلْمِسُونَهَا، فَقَالُوا: مَا رَأَيْنَا كَالْيَوْمِ ثَوْبًا قَطُّ. فَقَالَ: "أَتَعْجَبُونَ مِنْ هَذِهِ؟ لَمَنَادِيلُ سَعْدٍ فِي الْجَنَّةِ خَيْرٌ مِمَّا تَرَوْنَ". حَسَنٌ صَحِيحٌ. (ق،ت،ن)', 'വാഖിദുബിൻ അംറിബ്നി സഅ്ദിബ്നി മുആദ്(റ): അനസുബ്നു മാലിക്(റ) വന്നപ്പോൾ ഞാൻ അദ്ദേഹത്തിന്റെയടുത്ത് ചെന്നു. അദ്ദേഹം ചോദിച്ചു: നിങ്ങൾ ആരാണ്?. ഞാൻ പറഞ്ഞു: ഞാൻ വാഖിദുബ്നു അംറിബ്നി സഅ്ദി ബിൻ മുആദാണ്. നിവേദകൻ പറയുന്നു: അപ്പോഴദ്ദേഹം കരഞ്ഞു; എന്നിട്ട് പറഞ്ഞു: താങ്കൾ സഅ്ദ്(റ)വിനോട് സാമ്യമുള്ളവനാകുന്നു. സഅ്ദ്(റ) ജനങ്ങളിൽ മഹത്വമുള്ളവനും ഉയർന്നവനുമായിരുന്നു. സ്വർണ്ണത്തിൽ നെയ്ത ഒരു ദീബാജിന്റെ വസ്ത്രം നബി(സ)ക്ക് അയക്കപ്പെട്ടപ്പോൾ റസൂൽ(സ) അത് ധരിച്ച് മിമ്പറിൽ കയറി. അപ്പോൾ ജനങ്ങളത് തൊട്ടു നോക്കാൻ തുടങ്ങി. അവർ പറഞ്ഞു: ഇതുവരെ ഇന്നത്തെ പോലെ ഒരു വസ്ത്രവും ഞങ്ങൾ കണ്ടിട്ടില്ല. അപ്പോൾ റസൂൽ(സ) ചോദിച്ചു: "ഇതിൽ നിങ്ങൾക്ക് അത്ഭുതമുണ്ടോ? സ്വർഗ്ഗത്തിൽ സഅ്ദ്(റ)വിന്റെ ഉഉറുമാലുകൾ നിങ്ങൾ ഈ കാണുന്നതിനേക്കാൾ ഉത്തമമായതാണ്". (ബു,മു,തു,ന)', 'وَاقِدِ بْنِ عَمْرِو بْنِ سَعْدِ بْنِ مُعَاذٍ', 'വാഖിദുബിൻ അംറിബ്നി സഅ്ദിബ്നി മുആദ്(റ)', null, null, array['ق','ت','ن']::text[], array['ബു','മു','തു','ന']::text[], null, null, 663, 663, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=30 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 102, 'عَنْ وَاقِدِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُ قَالَ: دَخَلْتُ عَلَى أَنَسِ بْنِ مَالِكٍ - رَضِيَ اللهُ عَنْهُ - حِينَ قَدِمَ الْمَدِينَةَ فَسَلَّمْتُ عَلَيْهِ، فَقَالَ: مِمَّنْ أَنْتَ؟ قُلْتُ: أَنَا وَاقِدُ بْنُ عَمْرِو بْنِ سَعْدِ بْنِ مُعَاذٍ. قَالَ: إِنَّ سَعْدًا كَانَ أَعْظَمَ النَّاسِ وَأَطْوَلَهُ. ثُمَّ بَكَى فَأَكْثَرَ الْبُكَاءَ، ثُمَّ قَالَ: إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَعَثَ إِلَى أُكَيْدِرِ صَاحِبِ دُومَةَ بَعْثًا، فَأَرْسَلَ إِلَيْهِ بِجُبَّةِ دِيبَاجٍ مَنْسُوجَةٍ فِيهَا الذَّهَبُ، فَلَبِسَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ثُمَّ قَامَ عَلَى الْمِنْبَرِ وَقَعَدَ فَلَمْ يَتَكَلَّمْ وَنَزَلَ، فَجَعَلَ النَّاسُ يَلْمِسُونَهَا بِأَيْدِيهِمْ، فَقَالَ: "أَتَعْجَبُونَ مِنْ هَذِهِ؟ لَمَنَادِيلُ سَعْدٍ فِي الْجَنَّةِ أَحْسَنُ مِمَّا تَرَوْنَ". (ن)', 'വാഖിദുബ്നു അംറ്(റ): അനസുബ്നു മാലിക്(റ) മദീനയിൽ വന്നപ്പോൾ ഞാൻ അദ്ദേഹത്തിന്റെയടുക്കൽ ചെന്ന് സലാം ചൊല്ലി. അപ്പോൾ അദ്ദേഹം ചോദിച്ചു: നിങ്ങൾ ആരിൽ പെട്ടവനാണ്? ഞാൻ പറഞ്ഞു: ഞാൻ വാഖിദുബ്നു അംറിബ്നി സഅ്ദി ബിൻ മുആദാണ്. അദ്ദേഹം പറഞ്ഞു: നിശ്ചയം സഅ്ദ്(റ) ജനങ്ങളിൽ വെച്ചേറ്റവും മഹാനും ഉയർന്നവനുമായിരുന്നു. ശേഷം അദ്ദേഹം കരഞ്ഞു, ധാരാളം കരഞ്ഞു. എന്നിട്ട് പറഞ്ഞു: നിശ്ചയം റസൂൽ(സ) ഉദുമത്തിലെ ഭരണകർത്താവായ ഉകൈദരിലേക്ക് ഒരു സൈന്യത്തെ അയച്ചു. അപ്പോൾ അദ്ദേഹം സ്വർണ്ണത്തിൽ നെയ്ത ദീബാജിന്റെ ഒരു ജുബ്ബ അവിടുത്തേക്കയച്ചു. അങ്ങനെ റസൂൽ(സ) അത് ധരിക്കുകയും പിന്നീട് മിമ്പറിൽ കയറി നിൽക്കുകയും ഇരിക്കുകയും ഒന്നും തന്നെ പറയാതെ താഴെയിറങ്ങുകയും ചെയ്തു. ജനങ്ങൾ അത് കൈകൾ കൊണ്ട് തൊട്ടുനോക്കാൻ തുടങ്ങി. അപ്പോൾ റസൂൽ(സ) ചോദിച്ചു: "ഇതിൽ നിങ്ങൾക്ക് അത്ഭുതമുണ്ടോ? സ്വർഗ്ഗത്തിൽ സഅ്ദിന്റെ ഉറുമാലുകൾ നിങ്ങൾ ഈ കാണുന്നതിനേക്കാൾ മികച്ചതാണ്." (ന)', 'وَاقِدِ بْنِ عَمْرٍو', 'വാഖിദുബ്നു അംറ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 663, 664, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=31 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 103, 'عَنْ عَبْدِ اللَّهِ بْنِ عُكَيْمٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: اسْتَسْقَى حُذَيْفَةُ رَضِيَ اللَّهُ عَنْهُ، فَأَتَاهُ دِهْقَانٌ بِمَاءٍ فِي إِنَاءٍ مِنْ فِضَّةٍ، فَحَذَفَهُ ثُمَّ اعْتَذَرَ إِلَيْهِمْ مِمَّا صَنَعَ بِهِ وَقَالَ: إِنِّي نَهَيْتُهُ، سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "لَا تَشْرَبُوا فِي إِنَاءِ الذَّهَبِ وَالْفِضَّةِ، وَلَا تَلْبَسُوا الدِّيبَاجَ وَلَا الْحَرِيرَ، فَإِنَّهَا لَهُمْ فِي الدُّنْيَا وَلَنَا فِي الْآخِرَةِ". (ن)', 'അബ്ദുല്ലാഹിബ്നു ഉകൈം(റ): ഹുദൈഫ(റ) കുടിക്കാൻ വെള്ളം ആവശ്യപ്പെട്ടപ്പോൾ നാട്ടിലെ പ്രമാണി ഒരു വെള്ളി പാത്രത്തിൽ വെള്ളം കൊണ്ടു വന്നുകൊടുത്തു. അപ്പോൾ അദ്ദേഹമത് എറിഞ്ഞുകളഞ്ഞു. താൻ ചെയ്തതിന്റെ കാരണം അവരെ ബോധ്യപ്പിച്ചുകൊണ്ട് പറഞ്ഞു: നിശ്ചയം എനിക്കത് വിലക്കപ്പെട്ടിരിക്കുന്നു റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടിട്ടുണ്ട്. "നിങ്ങൾ സ്വർണ്ണത്തിന്റെയും വെള്ളിയുടെയും പാത്രത്തിൽ കുടിക്കരുത്. ദീബാജും പട്ടും നിങ്ങൾ ധരിക്കരുത്. അത് ദുൻയാവിൽ അവർക്കും ആഖിറത്തിൽ നമുക്കുമുള്ളതാണ്". (ന)', 'عَبْدِ اللَّهِ بْنِ عُكَيْمٍ', 'അബ്ദുല്ലാഹിബ്നു ഉകൈം(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 664, 664, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=32 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 104, 'عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُ قَالَ: لَبِسَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَوْمًا قَبَاءً مِنْ دِيبَاجٍ أُهْدِيَ لَهُ، ثُمَّ أَوْشَكَ أَنْ يَنْزِعَهُ، فَأَرْسَلَ بِهِ إِلَى عُمَرَ بْنِ الْخَطَّابِ رَضِيَ اللَّهُ عَنْهُ، فَقِيلَ لَهُ: قَدْ أَوْشَكَ مَا نَزَعْتَهُ يَا رَسُولَ اللَّهِ؟ فَقَالَ: نَهَانِي عَنْهُ جِبْرِيلُ [عَلَيْهِ السَّلَام]. فَجَاءَهُ عُمَرُ [رَضِيَ اللَّهُ عَنْهُ] يَبْكِي، فَقَالَ: يَا رَسُولَ اللَّهِ، كَرِهْتَ أَمْرًا وَأَعْطَيْتَنِيهِ، فَمَا لِي؟ قَالَ: "إِنِّي لَمْ أُعْطِكَهُ لِتَلْبَسَهُ، إِنَّمَا أَعْطَيْتُكَهُ تَبِيعُهُ". فَبَاعَهُ بِأَلْفَيْ دِرْهَمٍ. (م)', 'ജാബിറുബ്നു അബ്ദില്ലാഹ്(റ): ഒരു ദിവസം നബി(സ) തനിക്ക് സമ്മാനിക്കപ്പെട്ട, മുൻ വശം തുറന്ന ഒരു ദീബാജിന്റെ വസ്ത്രം ധരിച്ചു. പിന്നെ പെട്ടെന്നഴിച്ച് ഉമറുബ്നുൽ ഖത്താബ്(റ)വിന് കൊടുത്തയച്ചു. റസൂൽ(സ) യോട് ചോദിക്കപ്പെട്ടു: തിരുദൂതരേ, എന്താണ് അവിടന്ന് പെട്ടെന്ന് അത് അഴിച്ചു വെച്ചത്? തിരുമേനി(സ) പറഞ്ഞു: "ജിബ്‌രീൽ(അ) എനിക്കത് നിരോധിച്ചിരിക്കുന്നു". ഉടനെ ഉമർ(റ) കരഞ്ഞ് കൊണ്ട് തിരുമേനി(സ)യുടെ സന്നിധിയിൽ വന്ന് ചോദിച്ചു: തിരുദൂതരേ, അങ്ങ് ഇഷ്ടപ്പെടാത്ത ഒന്ന് എനിക്ക് നൽകുകയാണോ? ഞാനെന്താണ് ചെയ്യുക? നബി(സ) പറഞ്ഞു: "താങ്കളത് ധരിക്കാനല്ല ഞാൻ തന്നത്. അത് വിൽക്കാനാണ് ഞാൻ താങ്കൾക്ക് തന്നത്". ഉടനെ ഉമർ(റ) അത് രണ്ടായിരം ദിർഹമിന് വിറ്റു. (മു)', 'جَابِرِ بْنِ عَبْدِ اللَّهِ', 'ജാബിറുബ്നു അബ്ദില്ലാഹ്(റ)', null, null, array['م']::text[], array['മു']::text[], 'رَضِيَ اللَّهُ عَنْهُ', null, 664, 665, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=33 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 105, 'عَنْ أَبِي عُثْمَانَ النَّهْدِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: كُنَّا مَعَ عُتْبَةَ بْنِ فَرْقَدٍ، فَجَاءَ كِتَابُ عُمَرَ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا يَلْبَسُ الْحَرِيرَ إِلَّا مَنْ لَيْسَ لَهُ مِنْهُ شَيْءٌ فِي الْآخِرَةِ، إِلَّا هَكَذَا". وَقَالَ أَبُو عُثْمَانَ بِأُصْبُعَيْهِ اللَّتَيْنِ تَلِيَانِ الْإِبْهَامَ، فَرَأَيْتُهُمَا أَزْرَارَ الطَّيَالِسَةِ حَتَّى رَأَيْتُ الطَّيَالِسَةَ. (ن)', 'അബൂഉസ്മാനന്നഹ്ദീ(റ): ഞങ്ങൾ ഉത്ബതുബ്നു ഫർഖദ്(റ)വിന്റെ കൂടെയായിരുന്നപ്പോൾ ഉമർ(റ)വിന്റെ കത്ത് വന്നു: റസൂൽ(സ) പറഞ്ഞിട്ടുണ്ട്: "പാരത്രിക ലോകത്ത് പട്ടിൽ നിന്നൊരു വിഹിതവും ലഭിക്കാത്തവനല്ലാതെ, ഇത്ര അളവൊഴികെ, പട്ട് ധരിക്കുകയില്ല" അബൂഉസ്മാൻ(റ) തള്ള വിരലിനോടടുത്തുള്ള രണ്ട് വിരലുകൾ സൂചിപ്പിച്ച് പറഞ്ഞു: അങ്ങനെ (അനറബികൾക്ക് പരിചിതമായ, പ്രത്യേകക്കാർ ധരിക്കാറുള്ള) ''ത്വയാലിസ് '' എന്ന വസ്ത്രം കണ്ടപ്പോൾ, ഇതിന്റെ ബട്ടനുകളുടെ തോതാണ് റസൂൽ(സ) പട്ടിലനുവദിച്ച തോതെന്ന് എനിക്ക് മനസ്സിലായി. (ന)', 'أَبِي عُثْمَانَ النَّهْدِيِّ', 'അബൂഉസ്മാനന്നഹ്ദീ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 665, 665, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=34 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 106, 'عَنْ عُمَرَ رَضِيَ اللَّهُ عَنْهُ: أَنَّهُ لَمْ يُرَخِّصْ فِي الدِّيبَاجِ إِلَّا مَوْضِعَ أَرْبَعِ أَصَابِعَ. (ن)', 'ഉമർ(റ): ദീബാജിൽ നാല് വിരലുകളുടെ സ്ഥലമല്ലാതെ ഇളവ് ചെയ്യപ്പെട്ടിട്ടില്ല. (ന)', 'عُمَرَ', 'ഉമർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 665, 665, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=34 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 107, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَخَّصَ لِلزُّبَيْرِ بْنِ الْعَوَّامِ، وَلِعَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ فِي قَمِيصَيْنِ مِنْ حَرِيرٍ، مِنْ وَجَعٍ كَانَ بِهِمَا، حِكَّةٍ. (ق،د،ن،جه)', 'അനസുബ്നുമാലിക്(റ): സുബൈറുബിനുൽ അവ്വാം(റ)വിനും അബ്ദുർറഹ്മാനുബ്നു ഔഫ്(റ)വിനും ചൊറി പിടിച്ച് വേദനയുണ്ടായത് കാരണം പട്ടിന്റെ രണ്ട് ഖമീസുകൾ ധരിക്കാമെന്ന് റസൂൽ(സ) ഇളവ് നൽകി. (ബു,മു,ദ,ന,ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നുമാലിക്(റ)', null, null, array['ق','د','ن','جه']::text[], array['ബു','മു','ദ','ന','ജ']::text[], null, null, 665, 665, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=34 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 108, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَخَّصَ لِعَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ، وَالزُّبَيْرِ بْنِ الْعَوَّامِ، فِي الْقُمُصِ الْحَرِيرِ فِي السَّفَرِ، مِنْ حِكَّةٍ كَانَتْ بِهِمَا أَوْ وَجَعٍ كَانَ بِهِمَا. وَفِي رِوَايَةٍ: شَكَوْا إِلَى رَسُولِ اللَّهِ الْقَمْلَ. (م)', 'അനസുബ്നു മാലിക്(റ): അബ്ദുർറഹ്മാനുബിൻ ഔഫ്(റ)വിനും സുബൈറുബിനുൽ അവ്വാം(റ)വിനും യാത്രയിൽ പട്ടിന്റെ ഖമീസുകൾ ധരിക്കാമെന്ന് റസൂൽ(സ) ഇളവ് നൽകി. അവർക്ക് ചൊറിയോ വേദനയോ ഉണ്ടായിരുന്നത് കാരണമാണത്. മറ്റൊരു റിപ്പോർട്ടിൽ: അവർ പേൻശല്യമുണ്ടെന്ന് റസൂൽ(സ)യോട് പരാതിപ്പെട്ടിരുന്നു. (മു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 665, 665, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=34 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=8 and h.hadith_no=108), 1, 'وَفِي رِوَايَةٍ: شَكَوْا إِلَى رَسُولِ اللَّهِ الْقَمْلَ. (م)', 'മറ്റൊരു നിവേദനിൽ: അവർ പേൻശല്യമുണ്ടെന്ന് റസൂൽ(സ)യോട് പരാതിപ്പെട്ടിരുന്നു. (മു)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 109, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ: أَنَّ عَبْدَ الرَّحْمَنِ بْنَ عَوْفٍ وَالزُّبَيْرَ بْنَ الْعَوَّامِ شَكَيَا الْقَمْلَ إِلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي غَزَاةٍ لَهُمَا: فَرَخَّصَ لَهُمَا فِي قُمُصِ الْحَرِيرِ، قَالَ: وَرَأَيْتُهُ عَلَيْهِمَا. حَسَنٌ صَحِيحٌ. (ق،د،ت،ن،جه)', 'അനസുബ്നു മാലിക്(റ): ഒരു യുദ്ധവേളയിൽ അബ്ദുർറഹ്മാനുബിൻ ഔഫ്(റ)വും സുബൈറുബിനുൽ അവ്വാം(റ)വും പേൻശല്യമുണ്ടെന്ന് നബി(സ)യോട് പരാതി പറഞ്ഞു. അപ്പോൾ അവർക്ക് രണ്ട് പേർക്കും പട്ടിന്റെ ഖമീസ് ധരിക്കാൻ ഇളവ് നൽകി. അനസ്(റ) പറയുന്നു: ഞാനത് അവരിൽ കാണുകയും ചെയ്തു. (ബു,മു,ദ,തു,ന,ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 666, 666, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=35 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 110, 'عَنْ أَبِي عُمَرَ رَضِيَ اللهُ عَنْهُ -مَوْلَى أَسْمَاءَ رَضِيَ اللهُ عَنْهَا- قَالَ: رَأَيْتُ ابْنَ عُمَرَ اشْتَرَى عِمَامَةً لَهَا عَلَمٌ، فَدَعَا بِالْجَلَمَيْنِ فَقَصَّهُ، فَدَخَلْتُ عَلَى أَسْمَاءَ فَذَكَرْتُ ذَلِكَ لَهَا، فَقَالَتْ: بُؤْسًا لِعَبْدِ اللَّهِ، يَا جَارِيَةُ، هَاتِي جُبَّةَ رَسُولِ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. فَجَاءَتْ بِجُبَّةٍ مَكْفُوفَةِ الْكُمَّيْنِ وَالْجَيْبِ وَالْفَرْجَيْنِ بِالدِّيبَاجِ. (جه)', 'അബൂഉമർ(റ) - അസ്മാഅ്(റ)യുടെ അടിമ: ഇബ്നുഉമർ(റ) വരയുള്ള തലപ്പാവ് വാങ്ങുന്നത് ഞാൻ കണ്ടു. ശേഷം അദ്ദേഹം കത്രിക കൊണ്ടുവന്ന് അത് മുറിച്ചു. അപ്പോൾ ഞാൻ അസ്മാ(റ)യുടെ അടുത്ത് പോയി വിഷയം പറഞ്ഞു. അവർ പറഞ്ഞു: അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)വിന്റെ കാര്യം അത്ഭുതം, അടിമപ്പെണ്ണേ, റസൂൽ(സ)യുടെ ജുബ്ബ കൊണ്ടുവരിക. അപ്പോൾ അവൾ ഒരു ജുബ്ബ കൊണ്ടു വന്നു. അതിന്റെ രണ്ട് കയ്യും കീശയും രണ്ട് ഭാഗങ്ങളും ദീബാജ് (ഒരുതരം പട്ട്) കൊണ്ട് തൊങ്ങൽ വെക്കപ്പെട്ടിരുന്നു. (ജ)', 'أَبِي عُمَرَ', 'അബൂഉമർ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 666, 666, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=36 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 111, 'عَنْ عَبْدِ اللَّهِ أَبِي عُمَرَ رَضِيَ اللهُ عَنْهُ -مَوْلَى أَسْمَاءِ بِنْتِ أَبِي بَكْرٍ رَضِيَ اللهُ عَنْهُمَا- قَالَ: رَأَيْتُ ابْنَ عُمَرَ فِي السُّوقِ اشْتَرَى ثَوْبًا شَامِيًّا، فَرَأَى فِيهِ خَيْطًا أَحْمَرَ، فَرَدَّهُ، فَأَتَيْتُ أَسْمَاءَ فَذَكَرْتُ ذَلِكَ لَهَا، فَقَالَتْ: يَا جَارِيَةُ، نَاوِلِينِي جُبَّةَ رَسُولِ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. فَأَخْرَجَتْ جُبَّةَ طَيَالِسَةٍ، مَكْفُوفَةَ الْجَيْبِ وَالْكُمَّيْنِ وَالْفَرْجَيْنِ بِالدِّيبَاجِ. (م،د،جه)', 'അബ്ദുല്ലാഹിബ്നു അബൂഉമർ(റ) - അസ്മാഉ ബിൻത് അബൂബക്കർ(റ)വിന്റെ അടിമ: ഇബ്നുഉമർ(റ) അങ്ങാടിയിൽ നിന്ന് സിറിയൻ നിർമ്മിതമായൊരു വസ്ത്രം വാങ്ങുന്നത് ഞാൻ കണ്ടു. അതിൽ ചുവപ്പ് നൂൽ കണ്ടപ്പോൾ അദ്ദേഹം അത് മടക്കിക്കൊടുത്തു. ഞാൻ അസ്മാഅ്(റ)വിനോട് കാര്യം പറഞ്ഞു. അവർ പറഞ്ഞു: ഓ അടിമപ്പെണ്ണേ, റസൂൽ(സ)യുടെ ജുബ്ബ കൊണ്ടു വരൂ. അപ്പോൾ അവൾ പരുത്ത ഒരു ജുബ്ബ കൊണ്ടുവന്നു. അതിന്റെ കീശയും രണ്ടുകയ്യും ഇരുഭാഗങ്ങളും ദീബാജ് കൊണ്ട് തൊങ്ങൽ വെക്കപ്പെട്ടതായിരുന്നു. (മു,ദ,ജ)', 'عَبْدِ اللَّهِ أَبِي عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു അബൂഉമർ(റ)', null, null, array['م','د','جه']::text[], array['മു','ദ','ജ']::text[], null, null, 666, 666, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=36 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 112, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: إِنَّمَا نَهَى رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَنِ الثَّوْبِ الْمُصْمَتِ مِنَ الْحَرِيرِ، فَأَمَّا الْعَلَمُ مِنَ الْحَرِيرِ وَسَدَى الثَّوْبِ فَلَا بَأْسَ بِهِ. (د)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂൽ(സ) നിരോധിച്ചത് മുഴുവനായും പട്ടുള്ള വസ്ത്രമാണ്. അതിനാൽ പട്ട് കൊണ്ടുള്ള വരകളും, വസ്ത്രത്തിന്റെ നീളത്തിലുള്ള നൂലുകളും കുഴപ്പമില്ല. (ദ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 666, 666, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=36 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 113, 'عَنْ عَبْدِ اللهِ رَضِيَ اللهُ عَنْهُ مَوْلَى أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ، وَكَانَ خَالَ وَلَدِ عَطَاءٍ قَالَ: أَرْسَلَتْنِي أَسْمَاءُ إِلَى عَبْدِ اللهِ بْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمْ، فَقَالَتْ: بَلَغَنِي أَنَّكَ تُحَرِّمُ أَشْيَاءَ ثَلَاثَةً: الْعَلَمَ فِي الثَّوْبِ، وَمِيثَرَةَ الْأُرْجُوَانِ، وَصَوْمَ رَجَبٍ كُلِّهِ؟ فَقَالَ لِي عَبْدُ اللهِ: أَمَّا مَا ذَكَرْتَ مِنْ رَجَبٍ فَكَيْفَ بِمَنْ يَصُومُ الْأَبَدَ؟ وَأَمَّا مَا ذَكَرْتَ مِنَ الْعَلَمِ فِي الثَّوْبِ: فَإِنِّي سَمِعْتُ عُمَرَ بْنَ الْخَطَّابِ يَقُولُ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "إِنَّمَا يَلْبَسُ الْحَرِيرَ مَنْ لَا خَلَاقَ لَهُ". فَخِفْتُ أَنْ يَكُونَ الْعَلَمُ مِنْهُ. وَأَمَّا مِيثَرَةُ الْأُرْجُوَانِ: فَهَذِهِ مِيثَرَةُ عَبْدِ اللهِ. فَإِذَا هِيَ أُرْجُوَانٌ. فَرَجَعْتُ إِلَى أَسْمَاءَ فَخَبَّرْتُهَا، فَقَالَتْ: هَذِهِ جُبَّةُ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَأَخْرَجَتْ إِلَيَّ جُبَّةَ طَيَالِسَةٍ كِسْرَوَانِيَّةٍ، لَهَا لِبْنَةُ دِيبَاجٍ، وَفَرْجَيْهَا مَكْفُوفَيْنِ بِالدِّيبَاجِ، فَقَالَتْ: هَذِهِ كَانَتْ عِنْدَ عَائِشَةَ حَتَّى قُبِضَتْ، فَلَمَّا قُبِضَتْ قَبَضْتُهَا، وَكَانَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَلْبَسُهَا، فَنَحْنُ نَغْسِلُهَا لِلْمَرْضَى يُسْتَشْفَى بِهَا. (م)', 'അബ്ദുല്ലാഹ്(റ) - അസ്മാഉബിന്ത് അബീബക്ർ(റ)വിന്റെ അടിമ; അദ്ദേഹം അത്വാഇന്റെ മകന്റെ അമ്മാവനായിരുന്നു. അദ്ദേഹം പറയുന്നു: അസ്മാഉബിന്ത് അബീബക്കർ(റ) എന്നെ അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)വിന്റെ അടുത്തേക്കയച്ചു. എന്നിട്ടവർ പറഞ്ഞു: താങ്കൾ മൂന്ന് കാര്യങ്ങൾ നിഷിദ്ധമാക്കുന്നതായി ഞാൻ അറിഞ്ഞു: വസ്ത്രത്തിലെ വര, ജീനിക്കടിയിൽ വെക്കുന്ന ഉർജുവാൻ പട്ടിന്റെ വസ്ത്രം, റജബ് മാസം മുഴുവൻ നോമ്പ് അനുഷ്ഠിക്കൽ. അപ്പോൾ അബ്ദുല്ല(റ) എന്നോട് പറഞ്ഞു: താങ്കൾ റജബിനെക്കുറിച്ച് പറഞ്ഞുവല്ലോ, എങ്കിൽ കാലം മുഴുവൻ നോമ്പ് നോൽക്കുന്നവരോ? പിന്നെ വസ്ത്രത്തിലെ വരകളെക്കുറിച്ച് പറഞ്ഞത്. നിശ്ചയം, ഉമർ(റ) പറയുന്നത് ഞാൻ കേട്ടിട്ടുണ്ട്: റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടു: "ഭാഗ്യമില്ലാത്തവൻ മാത്രമാണ് പട്ട് ധരിക്കുക". അത് കൊണ്ട് പട്ടിനാലുള്ള വരയും അതിൽ പെടുമോ എന്ന് ഞാൻ ഭയക്കുന്നു. പിന്നെ ജീനിക്കടിയിൽ വെക്കുന്ന പട്ടു വസ്ത്രം, ഇതാ അബ്ദുല്ലായുടെ ജീനിക്കടിയിൽ വെക്കുന്ന വസ്ത്രം. അത് ഉർജുവാനായിരുന്നു. ഞാൻ മടങ്ങിവന്ന് അസ്മാഅ്(റ)യോട് കാര്യം പറഞ്ഞു. അപ്പോൾ അവർ പറഞ്ഞു: ഇത് റസൂൽ(സ)യുടെ ജുബ്ബയാകുന്നു. അവർ പരുത്ത കിസ്റാവസ്ത്രം എനിക്ക് കാണിച്ച് തന്നു. അതിന്റെ കഴുത്തും രണ്ട് ഭാഗങ്ങളും ദീബാജ് കൊണ്ട് തൊങ്ങൽ വെക്കപ്പെട്ടതായിരുന്നു. എന്നിട്ടവർ പറഞ്ഞു: ആഇശ(റ) വഫാത്താകുന്നത് വരെ അവരുടെ പക്കലായിരുന്നു ഇത്. വഫാത്തായപ്പോൾ അത് ഞാനെടുത്തു. നബി(സ) ഇത് ധരിക്കാറുണ്ടായിരുന്നു. രോഗികൾക്ക് സുഖം ലഭിക്കാൻ ഞങ്ങൾ അതു കഴുകിക്കൊടുക്കുമായിരുന്നു. (മു)', 'عَبْدِ اللهِ', 'അബ്ദുല്ലാഹ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 667, 667, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=37 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 114, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: رَأَى عُمَرُ رَضِيَ اللهُ عَنْهُ عُطَارِدًا التَّمِيمِيَّ يُقِيمُ بِالسُّوقِ حُلَّةَ سِيَرَاءَ، وَكَانَ رَجُلًا يَغْشَى الْمُلُوكَ وَيُصِيبُ مِنْهُمْ، فَقَالَ عُمَرُ: يَا رَسُولَ اللهِ، إِنِّي رَأَيْتُ عُطَارِدًا يُقِيمُ فِي السُّوقِ حُلَّةَ سِيَرَاءَ، فَلَوِ اشْتَرَيْتَهَا فَلَبِسْتَهَا لِوُفُودِ الْعَرَبِ إِذَا قَدِمُوا عَلَيْكَ، وَأَظُنُّهُ قَالَ: وَلَبِسْتَهَا يَوْمَ الْجُمُعَةِ. فَقَالَ لَهُ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنَّمَا يَلْبَسُ الْحَرِيرَ فِي الدُّنْيَا مَنْ لَا خَلَاقَ لَهُ فِي الْآخِرَةِ". فَلَمَّا كَانَ بَعْدَ ذَلِكَ أُتِيَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِحُلَلِ سِيَرَاءَ، فَبَعَثَ إِلَى عُمَرَ بِحُلَّةٍ، وَبَعَثَ إِلَى أُسَامَةَ بْنِ زَيْدٍ بِحُلَّةٍ، وَأَعْطَى عَلِيَّ بْنَ أَبِي طَالِبٍ حُلَّةً وَقَالَ: "شَقِّقْهَا خُمُرًا بَيْنَ نِسَائِكَ". قَالَ: فَجَاءَ عُمَرُ بِحُلَّتِهِ يَحْمِلُهَا، فَقَالَ: يَا رَسُولَ اللهِ، بَعَثْتَ إِلَيَّ بِهَذِهِ، وَقَدْ قُلْتَ بِالأَمْسِ فِي حُلَّةِ عُطَارِدٍ مَا قُلْتَ؟ فَقَالَ: "نِّي لَمْ أَبْعَثْ بِهَا إِلَيْكَ لِتَلْبَسَهَا، وَلَكِنِّي بَعَثْتُ بِهَا إِلَيْكَ لِتُصِيبَ بِهَا". وَأَمَّا أُسَامَةُ فَرَاحَ فِي حُلَّتِهِ، فَنَظَرَ إِلَيْهِ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ نَظَرًا عَرَفَ أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَدْ أَنْكَرَ مَا صَنَعَ، فَقَالَ: يَا رَسُولَ اللهِ، مَا تَنْظُرُ إِلَيَّ، فَأَنْتَ بَعَثْتَ إِلَيَّ بِهَا؟ فَقَالَ: "إِنِّي لَمْ أَبْعَثْ إِلَيْكَ لِتَلْبَسَهَا، وَلَكِنِّي بَعَثْتُ بِهَا إِلَيْكَ لِتُشَقِّقَهَا خُمُرًا بَيْنَ نِسَائِكَ". (م)', 'ഇബ്നുഉമർ(റ): അങ്ങാടിയിൽ വരകളുള്ള പട്ട്വസ്ത്രവുമായി നിൽക്കുന്ന ഒരു തമീമി കച്ചവടക്കാരനെ ഉമർ(റ) കണ്ടു. അദ്ദേഹം രാജാക്കൻമാരുടെ സന്നിധിയിൽ പോയി സമ്മാനങ്ങൾ സ്വീകരിക്കുന്നവനായിരുന്നു. അപ്പോൾ ഉമർ(റ) പറഞ്ഞു: തിരുദൂതരേ, അങ്ങാടിയിൽ പട്ടിന്റെ വരകളുള്ള വസ്ത്രവുമായി നിൽക്കുന്ന ഒരു കച്ചവടക്കാരനെ ഞാൻ കണ്ടു. അങ്ങ് അത് വാങ്ങി, അറബികളുടെ നിവേദക സംഘങ്ങൾ അങ്ങയുടെ അടുത്ത് വരുമ്പോൾ അത് ധരിക്കുകയാണെങ്കിൽ (വളരെ നന്നാകും). ഇബ്നുഉമർ(റ) പറയുന്നു: വെള്ളിയാഴ്ച അത് ധരിക്കുകയും ചെയ്തിരുന്നെങ്കിൽ എന്നുകൂടി അദ്ദേഹം പറഞ്ഞുവെന്ന് ഞാൻ വിചാരിക്കുന്നു. അപ്പോൾ ഉമർ(റ)വിനോട് റസൂൽ(സ) പറഞ്ഞു: "ആഖിറത്തിൽ ഒരു വിഹിതവുമില്ലാത്തവൻ മാത്രമാണ് ദുനിയാവിൽ പട്ട് ധരിക്കുന്നത്". അതിന്റെ ശേഷം റസൂൽ(സ)ക്ക് പട്ടിന്റെ വരകളുള്ള വസ്ത്രങ്ങൾ സമ്മാനിക്കപ്പെട്ടു. അപ്പോൾ റസൂൽ(സ) അതിൽ നിന്ന് ഒന്ന് ഉമർ(റ)വിനും ഒന്ന് ഉസാമതുബ്നു സൈദ്(റ)വിനും അയച്ചുകൊടുത്തു. അലിയ്യുബ്നു അബീത്വാലിബ്(റ)വിനും ഒന്നു കൊടുത്തു. അവിടന്ന് പറയുകയും ചെയ്തു: "താങ്കളുടെ ഭാര്യമാർക്കിടയിൽ മുഖമക്കനയായി ഇത് വീതിക്കുക." നിവേദകൻ പറയുന്നു: ഉമർ(റ) തന്റെ വസ്ത്രവുമായി വന്നു ചോദിച്ചു: തിരുദൂതരേ, അവിടന്ന് ഇതെനിക്ക് അയച്ചു തന്നു. ഇന്നലെ ആ കച്ചവടക്കാരന്റെ വസ്ത്രത്തെ കുറിച്ച് അങ്ങ് പറയേണ്ടതെല്ലാം പറഞ്ഞിരുന്നല്ലോ? അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "ഞാൻ താങ്കൾക്കത് ധരിക്കാനല്ല കൊടുത്തയച്ചത്, മറിച്ച് അത് വിറ്റ് കാശെടുക്കാനാണ്." അപ്പോൾ ഉസാമ(റ) തന്റെ പട്ടുവസ്ത്രം ധരിച്ചു വന്നിരിക്കുന്നു. റസൂൽ(സ) അദ്ദേഹത്തിന്റെ വസ്ത്രത്തിലേക്ക് നോക്കി. അപ്പോൾ അദ്ദേഹത്തിന് മനസ്സിലായി താൻ ചെയ്തത് റസൂൽ(സ)ക്ക് ഇഷ്ടമായിട്ടില്ലെന്ന്. അപ്പോൾ അദ്ദേഹം ചോദിച്ചു: തിരുദൂതരേ, എന്താണ് അങ്ങ് എന്നെ നോക്കുന്നത്? അങ്ങ് തന്നെയല്ലേ ഇതെനിക്ക് കൊടുത്തയച്ചത്? റസൂൽ(സ) പറഞ്ഞു: "താങ്കൾ അത് ധരിക്കാനല്ലായിരുന്നു ഞാൻ കൊടുത്തയച്ചത്. മറിച്ച് താങ്കളുടെ ഭാര്യമാർക്കിടയിൽ മുഖമക്കനയാക്കി വീതിക്കാനായിരുന്നു." (മു)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 667, 668, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=38 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 115, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّ عُمَرَ رَضِيَ اللهُ عَنْهُ خَرَجَ، فَرَأَى حُلَّةَ إِسْتَبْرَقٍ تُبَاعُ فِي السُّوقِ، فَأَتَى رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا رَسُولَ اللهِ، اشْتَرِهَا فَالْبَسْهَا يَوْمَ الْجُمُعَةِ وَحِينَ يَقْدَمُ عَلَيْكَ الْوَفْدُ. فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنَّمَا يَلْبَسُ هَذَا مَنْ لَا خَلَاقَ لَهُ". ثُمَّ أُتِيَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِثَلَاثِ حُلَلٍ مِنْهَا، فَكَسَا عُمَرَ حُلَّةً وَكَسَا عَلِيًّا حُلَّةً وَكَسَا أُسَامَةَ حُلَّةً، فَأَتَاهُ فَقَالَ: يَا رَسُولَ اللهِ، قُلْتَ فِيهَا مَا قُلْتَ، ثُمَّ بَعَثْتَ إِلَيَّ؟ فَقَالَ: "بِعْهَا وَاقْضِ بِهَا حَاجَتَكَ، أَوْ شَقِّقْهَا خُمُرًا بَيْنَ نِسَائِكَ". (ن)', 'ഇബ്നുഉമർ(റ): ഉമർ(റ) പുറത്തിറങ്ങിയപ്പോൾ അങ്ങാടിയിൽ കസവുപട്ടിന്റെ വസ്ത്രം വിൽക്കപ്പെടുന്നത് കണ്ടു. ഉടനെ റസൂൽ(സ)യുടെ അടുത്തുചെന്ന് പറഞ്ഞു: തിരുദൂതരേ, അത് വാങ്ങിയാലും. വെള്ളിയാഴ്ചയും അങ്ങയുടെ അടുത്ത് നിവേദക സംഘങ്ങൾ വരുമ്പോഴും അത് ധരിക്കാമല്ലോ. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "ഭാഗ്യമില്ലാത്തവർ മാത്രമാണ് ഇത് ധരിക്കുക". ശേഷം അതിൽ നിന്ന് മൂന്നെണ്ണം റസൂൽ(സ)ക്ക് നൽകപ്പെട്ടു. അപ്പോൾ നബി(സ) ഒന്ന് ഉമർ(റ)വിനെ ധരിപ്പിച്ചു. ഒന്ന് അലി(റ)വിനെയും ധരിപ്പിച്ചു. മറ്റൊന്ന് ഉസാമ(റ)വിനെയും ധരിപ്പിച്ചു. അപ്പോൾ ഉമർ(റ) നബി(സ)യുടെ തിരുസന്നിധിയിൽ ചെന്ന് ചോദിച്ചു. തിരുദൂതരേ, ഇതിൽ അങ്ങ് പലതും പറഞ്ഞിരുന്നല്ലോ. പിന്നെ എനിക്ക് അയച്ചു തരികയും ചെയ്തുവല്ലോ? റസൂൽ(സ) പറഞ്ഞു: "താങ്കൾ അത് വിൽക്കുക, താങ്കളുടെ ആവശ്യങ്ങൾ വീട്ടുക, അല്ലെങ്കിൽ താങ്കളുടെ ഭാര്യമാർക്കിടയിൽ മുഖമക്കനയായി വീതിക്കുക." (ന)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 668, 669, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=39 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 116, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: نَهَى رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَنْ لِبْسَتَيْنِ: أَنْ يَحْتَبِيَ الرَّجُلُ مُفْضِيًا بِفَرْجِهِ إِلَى السَّمَاءِ، وَيَلْبَسَ ثَوْبَهُ وَأَحَدُ جَانِبَيْهِ خَارِجٌ، وَيُلْقِيَ ثَوْبَهُ عَلَى عَاتِقِهِ. (خ،د،ن)', 'അബൂഹുറൈറ(റ): റസൂലുല്ലാഹി(സ) രണ്ട് തരത്തിലുള്ള വസ്ത്ര ധാരണം നിരോധിച്ചിരിക്കുന്നു. തന്റെ ഗുഹ്യസ്ഥാനം ആകാശത്തേക്ക് ആക്കി കൊണ്ട് (വെളിവാക്കിക്കൊണ്ട്) ചുറ്റിപ്പൂതക്കൽ, തന്റെ ഒരു വശം വെളിയിലായിരിക്കും വിധം വസ്ത്രം ധരിച്ച് തന്റെ വസ്ത്രം ചുമലിലേക്കിടൽ. (ബു,ദ,ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ','د','ن']::text[], array['ബു','ദ','ന']::text[], null, null, 669, 669, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=40 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 117, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ نَهَى أَنْ يَأْكُلَ الرَّجُلُ بِشِمَالِهِ، أَوْ يَمْشِيَ فِي نَعْلٍ وَاحِدَةٍ، وَأَنْ يَشْتَمِلَ الصَّمَّاءَ وَأَنْ يَحْتَبِيَ فِي ثَوْبٍ وَاحِدٍ كَاشِفًا عَنْ فَرْجِهِ. (م)', 'ജാബിർ(റ): ഒരാൾ തന്റെ ഇടതുകൈ കൊണ്ട് ഭക്ഷിക്കലും ഒറ്റച്ചെരുപ്പിൽ നടക്കലും വസ്ത്രം കൊണ്ട് മൂടിയിരിക്കലും ഒറ്റവസ്ത്രത്തിൽ ഗുഹ്യസ്ഥാനം വെളിവാക്കി മുട്ടുകെട്ടിയിരിക്കലും റസൂൽ(സ) നിരോധിച്ചിരിക്കുന്നു. (മു)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 669, 669, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=40 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 118, 'عَنْ أَبِي رِمْثَةَ رَضِيَ اللهُ عَنْهُ قَالَ: انْطَلَقْتُ مَعَ أَبِي نَحْوَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَرَأَيْتُ عَلَيْهِ بُرْدَيْنِ أَخْضَرَيْنِ. (د،ت،ن)', 'അബൂരിംസ(റ): ഞാനെന്റെ പിതാവിന്റെ കൂടെ നബി(സ)യുടെ അടുത്തേക്ക് പോയി. അപ്പോൾ അവിടുത്തെ ശരീരത്തിൽ രണ്ട് പച്ചപ്പൂതപ്പുകൾ ഞാൻ കണ്ടു. (ദ,തു,ന)', 'أَبِي رِمْثَةَ', 'അബൂരിംസ(റ)', null, null, array['د','ت','ن']::text[], array['ദ','തു','ന']::text[], null, null, 669, 669, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=41 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 119, 'عَنْ عَبْدِ اللهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُمَا قَالَ: هَبَطْنَا مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مِنْ ثَنِيَّةٍ، فَالْتَفَتَ إِلَيَّ وَعَلَيَّ رَيْطَةٌ مُضَرَّجَةٌ بِالْعُصْفُرِ، فَقَالَ: "مَا هَذِهِ الرَّيْطَةُ عَلَيْكَ". فَعَرَفْتُ مَا كَرِهَ، فَأَتَيْتُ أَهْلِي وَهُمْ يَسْجُرُونَ تَنُّورًا لَهُمْ، فَقَذَفْتُهَا فِيهِ، ثُمَّ أَتَيْتُهُ مِنَ الْغَدِ، فَقَالَ: "يَا عَبْدَ اللهِ، مَا فَعَلَتِ الرَّيْطَةُ"، فَأَخْبَرْتُهُ، فَقَالَ: "أَلَا كَسَوْتَهَا بَعْضَ أَهْلِكَ، فَإِنَّهُ لَا بَأْسَ بِهِ لِلنِّسَاءِ". (د،جه)
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=8 and h.hadith_no=119), 1, 'وَفِي رِوَايَةٍ قَالَ: رَآنِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَعَلَيَّ ثَوْبٌ مَصْبُوغٌ بِعُصْفُرٍ مُوَرَّدٌ، فَقَالَ: "مَا هَذَا؟". فَانْطَلَقْتُ فَأَحْرَقْتُهُ، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَا صَنَعْتَ بِثَوْبِكَ؟". فَقُلْتُ: أَحْرَقْتُهُ، قَالَ: "أَفَلَا كَسَوْتَهُ بَعْضَ أَهْلِكَ؟". (د)', 'മറ്റൊരു നിവേദനിൽ: പുഷ്പത്തിന്റെ മഞ്ഞനിറം പൂശിയ വസ്ത്രം എന്റെ മേൽ ഉണ്ടായിരിക്കെ റസൂലുല്ലാഹി(സ) എന്നെ കണ്ടു. അപ്പോൾ അവിടുന്ന് ചോദിച്ചു: "എന്താണത്?" ഉടൻ ഞാൻ പോയി അത് കത്തിച്ചുകളഞ്ഞു. നബി(സ) ചോദിച്ചു: "നിന്റെ വസ്ത്രം നീ എന്ത് ചെയ്തു?" ഞാൻ പറഞ്ഞു: ഞാനത് കത്തിച്ചു കളഞ്ഞു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "അത് നിന്റെ ഏതെങ്കിലും ഭാര്യക്ക് നൽകാമായിരുന്നില്ലേ?" (ദ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 120, 'عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو رَضِيَ اللَّهُ عَنْهُمَا قَالَ: مَرَّ عَلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَجُلٌ عَلَيْهِ ثَوْبَانِ أَحْمَرَانِ، فَسَلَّمَ عَلَيْهِ، فَلَمْ يَرُدَّ عَلَيْهِ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. (د،ت)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): ചുവന്ന രണ്ട് വസ്ത്രങ്ങൾ ധരിച്ച് ഒരാൾ നബി(സ)യുടെ അടുക്കലൂടെ നടന്ന് പോയി. അയാൾ നബി(സ)യോട് സലാം പറഞ്ഞപ്പോൾ അവിടുന്ന് സലാം മടക്കിയില്ല. (ദ,തു)', 'عَبْدِ اللَّهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 670, 670, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=42 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 121, 'عَنْ رَافِعِ بْنِ خَدِيجٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: خَرَجْنَا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي سَفَرٍ، فَرَأَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى رَوَاحِلِنَا وَعَلَى إِبِلِنَا أَكْسِيَةً فِيهَا خُيُوطُ عِهْنٍ حُمْرٌ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَلَا أَرَى هَذِهِ الْحُمْرَةَ قَدْ عَلَتْكُمْ". فَقُمْنَا سِرَاعًا لِقَوْلِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَتَّى نَفَرَ بَعْضُ إِبِلِنَا، فَأَخَذْنَا الْأَكْسِيَةَ فَنَزَعْنَاهَا عَنْهَا. (د)', 'റാഫിഉബ്നു ഖദീജ്(റ): ഞങ്ങൾ റസൂലുല്ലാഹി(സ)യുടെ കൂടെ യാത്ര പുറപ്പെട്ടു. അപ്പോൾ ഞങ്ങളുടെ ഒട്ടകക്കട്ടിലിലും ചില യാത്രാ ഒട്ടകങ്ങളിലും ചുവന്ന ചായം പിടിപ്പിച്ച കമ്പിളി വസ്ത്രങ്ങൾ അവിടുന്ന് കണ്ടു. അപ്പോൾ റസൂലുല്ലാഹി(സ) പറഞ്ഞു: "ഈ ചുവപ്പ് നിറം നിങ്ങളെക്കാൾ ഉയർന്നതായി ഞാൻ കാണുന്നില്ലേ." റസൂലുല്ലാഹി(സ)യുടെ ആ ശബ്ദം കേട്ട് ഞങ്ങൾ പെട്ടെന്ന് നിന്നുപോയി. ഞങ്ങളുടെ ചില ഒട്ടകങ്ങൾ വിരണ്ടോടുകയുമുണ്ടായി. ഉടൻ ഞങ്ങൾ ആ വസ്ത്രങ്ങൾ അവയിൽ നിന്ന് അഴിച്ചുകളഞ്ഞു. (ദ)', 'رَافِعِ بْنِ خَدِيجٍ', 'റാഫിഉബ്നു ഖദീജ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 670, 670, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=42 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 122, 'عَنْ حُرَيْثِ بْنِ الْأَبْجَرِ السَّلِيعِيِّ رَضِيَ اللَّهُ عَنْهُ: أَنَّ امْرَأَةً مِنْ بَنِي أَسَدٍ قَالَتْ: كُنْتُ يَوْمًا عِنْدَ زَيْنَبَ رَضِيَ اللَّهُ عَنْهَا امْرَأَةِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَنَحْنُ نَصْبُغُ ثِيَابًا لَهَا بِمَغْرَةٍ، فَبَيْنَا نَحْنُ كَذَلِكَ إِذْ طَلَعَ عَلَيْنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَلَمَّا رَأَى الْمَغْرَةَ رَجَعَ، فَلَمَّا رَأَتْ ذَلِكَ زَيْنَبُ عَلِمَتْ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَدْ كَرِهَ مَا فَعَلَتْ، فَأَخَذَتْ فَغَسَلَتْ ثِيَابَهَا وَوَارَتْ كُلَّ حُمْرَةٍ، ثُمَّ إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَجَعَ، فَاطَّلَعَ، فَلَمَّا لَمْ يَرَ شَيْئًا دَخَلَ. (د)', 'ഹുറൈസുബ്‌നുൽ അബഹിസ്സലീഹീ(റ): ബനൂഅസദിൽപ്പെട്ട ഒരുസ്ത്രീ പറഞ്ഞു: ഒരു ദിവസം ഞാൻ റസൂലുല്ലാഹി(സ)യുടെ ഭാര്യ സൈനബ്(റ)യുടെ അടുക്കളയിലായിരുന്നു. മഹതിക്കായി ഞങ്ങൾ വസ്ത്രങ്ങളിൽ കാവി നിറം പിടിപ്പിക്കുകയായിരുന്നു. അങ്ങനെയിരിക്കെ, റസൂലുല്ലാഹി(സ) ഞങ്ങൾക്ക് മുന്നിൽ പ്രത്യക്ഷപ്പെട്ടു. കാവിനിറം കണ്ട പാടെ അവിടന്ന് തിരിച്ച് പോയി. ഇത് കണ്ട സൈനബ്(റ)ന്, റസൂലുല്ലാഹി(സ) താൻ ചെയ്തതിൽ അതൃപ്തനാണെന്ന് മനസ്സിലായി. മഹതി ആ വസ്ത്രങ്ങൾ എടുത്ത് അലക്കി മുഴുവൻ ചുവപ്പും കഴുകിക്കളഞ്ഞു. പിന്നീട് റസൂലുല്ലാഹി(സ) മടങ്ങി വന്നു, ഒന്നും കാണാതിരുന്നതിനാൽ അവിടന്ന് അകത്ത് കയറി. (ദ)', 'حُرَيْثِ بْنِ الْأَبْجَرِ السَّلِيعِيِّ', 'ഹുറൈസുബ്‌നുൽ അബഹിസ്സലീഹീ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 670, 671, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=42 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 123, 'عَنِ الْبَرَاءِ رَضِيَ اللَّهُ عَنْهُ قَالَ: مَا رَأَيْتُ مِنْ ذِي لِمَّةٍ، فِي حُلَّةٍ حَمْرَاءَ، أَحْسَنَ مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، لَهُ شَعَرٌ يَضْرِبُ مَنْكِبَيْهِ، بَعِيدُ مَا بَيْنَ الْمَنْكِبَيْنِ، لَمْ يَكُنْ بِالْقَصِيرِ وَلَا بِالطَّوِيلِ. حَسَنٌ صَحِيحٌ (ق,د,ت,ن,جه)', 'ബറാഅ്(റ): ചുവന്ന മുഴുവസ്ത്രം ധരിച്ച് ചെവിയിലേക്ക് തൂങ്ങിക്കിടക്കുന്ന മുടിയുള്ളവരിൽ റസൂലുല്ലാഹി(സ)യേക്കാൾ ഭംഗിയുള്ള ഒരാളെയും ഞാൻ കണ്ടിട്ടില്ല. അവിടത്തേക്ക് ഇരു തോളുകൾക്കുമിടയിലായി, ഇരുതോളുകളിലുമടിക്കുന്ന മുടിയുണ്ട്. അവിടന്ന് നീളം കൂടിയവരോ, നീളം കുറഞ്ഞവരോ അല്ല. (ബു,മു,ദ,തു,ന,ജ)', 'الْبَرَاءِ', 'ബറാഅ്(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 671, 671, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=42 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 124, 'عَنْ بُرَيْدَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَخْطُبُ، فَأَقْبَلَ حَسَنٌ وَحُسَيْنٌ عَلَيْهِمَا السَّلَام عَلَيْهِمَا قَمِيصَانِ أَحْمَرَانِ، يَعْثُرَانِ وَيَقُومَانِ، فَنَزَلَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَخَذَهُمَا فَوَضَعَهُمَا فِي حِجْرِهِ، فَقَالَ: "صَدَقَ اللَّهُ وَرَسُولُهُ: إِنَّمَا أَمْوَالُكُمْ وَأَوْلَادُكُمْ فِتْنَةٌ، رَأَيْتُ هَذَيْنِ فَلَمْ أَصْبِرْ". ثُمَّ أَخَذَ فِي خُطْبَتِهِ. (د,ت,ن,جه)', 'ബുറൈദ(റ): റസൂലുല്ലാഹി(സ) ഖുത്ബ നടത്തുന്നത് ഞാൻ കണ്ടു. അപ്പോൾ ചുവന്ന ഖമീസുകൾ ധരിച്ച് ഹസൻ(റ), ഹുസൈൻ(റ) എന്നിവർ വീണും എണീറ്റും കടന്നു വന്നു. അപ്പോൾ നബി(സ) ഇറങ്ങിവന്ന് അവരിരുവരെയും എടുത്ത് തന്റെ മടിയിൽ വെച്ചു. എന്നിട്ട് പറഞ്ഞു: "അല്ലാഹുവും അവന്റെ റസൂലും സത്യം പറഞ്ഞു: തീർച്ചയായും നിങ്ങളുടെ സമ്പത്തും സന്താനങ്ങളും പരീക്ഷണം മാത്രമാണ്, ഞാൻ ഇവർ രണ്ട് പേരെയും കണ്ടു, എനിക്ക് ക്ഷമിക്കാൻ കഴിഞ്ഞില്ല." പിന്നീട് അവിടന്ന് ഖുത്ബ തുടർന്നു. (ദ,തു,ന,ജ)', 'بُرَيْدَةَ', 'ബുറൈദ(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 671, 671, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=42 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 125, 'عَنِ الْبَرَاءِ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَهُ شَعَرٌ يَبْلُغُ شَحْمَةَ أُذُنَيْهِ، وَرَأَيْتُهُ فِي حُلَّةٍ حَمْرَاءَ، لَمْ أَرَ شَيْئًا قَطُّ أَحْسَنَ مِنْهُ. (ق,د,ت,ن,جه)', 'ബറാഅ്(റ): റസൂലുല്ലാഹി(സ)ക്ക് തന്റെ ഇരുചെവികളുടെയും കുന്നിവരെയെത്തുന്ന മുടിയുണ്ടായിരുന്നു. ഞാനവിടത്തെ ചുവന്ന മുഴു വസ്ത്രത്തിൽ കണ്ടു, അതിനേക്കാൾ ഭംഗിയുള്ള മറ്റൊന്നും തന്നെ ഇത് വരെ ഞാൻ കണ്ടിട്ടില്ല. (ബു,മു,ദ,തു,ന,ജ)', 'الْبَرَاءِ', 'ബറാഅ്(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 671, 671, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=42 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 126, 'عَنْ عَامِرِ بْنِ عَمْرٍو الْمُزَنِيِّ رَضِيَ اللَّهُ عَنْهُ: قَالَ: رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِمِنًى يَخْطُبُ عَلَى بَغْلَةٍ وَعَلَيْهِ بُرْدٌ أَحْمَرُ، وَعَلِيٌّ رَضِيَ اللَّهُ عَنْهُ أَمَامَهُ يُعَبِّرُ عَنْهُ. (د)', 'ആമിറുബ്‌നു അംറിൽ മുസ്നി(റ): മിനായിൽ വെച്ച് കോവർ കഴുതയുടെ പുറത്തിരുന്ന് പ്രസംഗിക്കുന്ന റസൂൽ(സ)യെ ഞാൻ കണ്ടു. അവിടുത്തെ ശരീരത്തിൽ ചുവന്ന പുതപ്പുണ്ടായിരുന്നു. അവിടുത്തെ മുമ്പിൽ അലി(റ) അവിടുത്തെ സംസാരം വിശദീകരിച്ച് കൊണ്ടിരിക്കുന്നുണ്ടായിരുന്നു. (ദ)', 'عَامِرِ بْنِ عَمْرٍو الْمُزَنِيِّ', 'ആമിറുബ്‌നു അംറിൽ മുസ്നി(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 671, 671, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=42 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 127, 'عَنْ جَابِرِ بْنِ سَمُرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: رَأَيْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي لَيْلَةٍ إِضْحِيَانٍ، فَجَعَلْتُ أَنْظُرُ إِلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَإِلَى الْقَمَرِ، وَعَلَيْهِ حُلَّةٌ حَمْرَاءُ، فَإِذَا هُوَ عِنْدِي أَحْسَنُ مِنَ الْقَمَرِ. حَسَنٌ. (ت)', 'ജാബിറുബ്നു സമുറ(റ): മേഘമില്ലാത്ത നിലാവുള്ള ഒരു രാത്രിയിൽ ഞാൻ റസൂലുല്ലാഹി(സ)യെ കണ്ടു. ഞാൻ റസൂലുല്ലാഹി(സ)യിലേക്കും ചന്ദ്രനിലേക്കും നോക്കിക്കൊണ്ടിരുന്നു. അവിടുത്തെ ശരീരത്തിൽ ചുവന്ന മുഴുവസ്ത്രമുണ്ടായിരുന്നു. അന്നേരം തിരുമേനി(സ) ചന്ദ്രനേക്കാൾ ഭംഗിയുള്ളതായി എനിക്ക് തോന്നി. (തു)', 'جَابِرِ بْنِ سَمُرَةَ', 'ജാബിറുബ്നു സമുറ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 672, 672, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=42 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 128, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: صَنَعْتُ لِرَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بُرْدَةً سَوْدَاءَ، فَلَبِسَهَا فَلَمَّا عَرِقَ فِيهَا وَجَدَ رِيحَ الصُّوفِ فَقَذَفَهَا، قَالَ: وَكَانَ تُعْجِبُهُ الرِّيحُ الطَّيِّبَةُ. (د)', 'ആഇശ(റ): ഞാൻ റസൂലുല്ലാഹി(സ)ക്കായി ഒരു കറുത്ത പുതപ്പുണ്ടാക്കി. തിരുമേനി(സ) അത് ധരിച്ചു. അവിടുന്ന് വിയർത്തപ്പോൾ കമ്പിളിയുടെ വാസന വന്നു. ഉടൻ അതഴിച്ച് വെച്ചു. നിവേദകൻ പറഞ്ഞു: അവിടുന്ന് നല്ല വാസന ഇഷ്ടപ്പെടുന്നവരായിരുന്നു. (ദ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 672, 672, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=43 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 129, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: خَرَجَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ ذَاتَ غَدَاةٍ وَعَلَيْهِ مِرْطٌ مِنْ شَعْرٍ أَسْوَدَ. حَسَنٌ صَحِيحٌ. (م,د,ت)', 'ആഇശ(റ): ഒരു ദിവസം രാവിലെ നബി(സ) ഒരു കറുത്ത രോമവസ്ത്രം മേലിലിട്ട് പുറപ്പെട്ടു. (മു,ദ,തു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['م','د','ت']::text[], array['മു','ദ','തു']::text[], null, null, 672, 672, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=43 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 130, 'عَنْ قَيْلَةَ بِنْتِ مَخْرَمَةَ رَضِيَ اللهُ عَنْهَا أَنَّهَا قَالَتْ: قَدِمْنَا عَلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ... فَذَكَرَتِ الْحَدِيثَ بِطُولِهِ حَتَّى جَاءَ رَجُلٌ وَقَدِ ارْتَفَعَتِ الشَّمْسُ، فَقَالَ: السَّلَامُ عَلَيْكَ يَا رَسُولَ اللهِ. فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "وَعَلَيْكَ السَّلَامُ وَرَحْمَةُ اللهِ". وَعَلَيْهِ -تَعْنِي النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ- أَسْمَالُ مُلَيَّتَيْنِ كَانَتَا بِزَعْفَرَانٍ، وَقَدْ نَفَضَتَا، وَمَعَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَسِيبُ نَخْلَةٍ. (د,ت)', 'ഖൈലതബിൻതു മഖ്റമ(റ): ഞങ്ങൾ റസൂലുല്ലാഹി(സ)യുടെ അടുക്കൽ വന്നു. (എന്നിട്ടവർ ഹദീസ് മുഴുവൻ പറഞ്ഞു) അങ്ങനെയിരിക്കെ ഒരാൾ വന്നു. സൂര്യൻ ഉദിച്ചുകഴിഞ്ഞിരുന്നു. അദ്ദേഹം പറഞ്ഞു: അല്ലാഹുവിന്റെ ദൂതരേ, അസ്സലാമു അലൈക്കും. അപ്പോൾ റസൂലുല്ലാഹി(സ) പ്രതിവചിച്ചു: "വഅലൈക്കസ്സലാം വറഹ്മത്തുല്ലാഹി". വ്യക്തമായി കാണാൻ പറ്റാത്ത ചെറിയ രണ്ട് കുങ്കുമത്തുള്ളി അവിടുത്തെ - മഹതി നബി(സ)യെയാണുദ്ദേശിക്കുന്നത് - ശരീരത്തിലുണ്ടായിരുന്നു. അവ വറ്റിപ്പോയിരുന്നു. ഒരു ഈത്തപ്പനമട്ടൽ നബി(സ)യുടെ അടുത്തുണ്ടായിരുന്നു. (ദ,തു)', 'قَيْلَةَ بِنْتِ مَخْرَمَةَ', 'ഖൈലതബിൻതു മഖ്റമ(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 672, 672, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=44 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 131, 'عَنْ قَيْسِ بْنِ سَعْدٍ رَضِيَ اللهُ عَنْهُ قَالَ: أَتَانَا النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَوَضَعْنَا لَهُ مَاءً يَتَبَرَّدُ بِهِ، فَاغْتَسَلَ. ثُمَّ أَتَيْتُهُ بِمِلْحَفَةٍ صَفْرَاءَ، فَرَأَيْتُ أَثَرَ الْوَرْسِ عَلَى عُكَنِهِ. (جه)', 'ഖൈസുബ്നു സഅ്ദ്(റ): നബി(സ) ഞങ്ങളുടെ അടുക്കൽ വന്നു, അപ്പോൾ ഞങ്ങൾ അവിടുത്തേക്ക് തണുപ്പിനായി വെള്ളം വെച്ചുകൊടുത്തു. അവിടുന്ന് കുളിച്ചു. പിന്നീട് ഞാനൊരു മഞ്ഞ വിരിപ്പുമായി തിരുമേനിയുടെ അടുത്തേക്ക് ചെന്നു. അപ്പോൾ ഞാൻ അവിടുത്തെ വയറിന്റെ മടക്കുകളിൽ മഞ്ഞനിറത്തിന്റെ പാട് കണ്ടു. (ജ)', 'قَيْسِ بْنِ سَعْدٍ', 'ഖൈസുബ്നു സഅ്ദ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 672, 673, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=44 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 132, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا: كَانَ يَصْبُغُ لِحْيَتَهُ بِالصُّفْرَةِ حَتَّى تَمْتَلِئَ ثِيَابُهُ مِنَ الصُّفْرَةِ، فَقِيلَ لَهُ: لِمَ تَصْبُغُ بِالصُّفْرَةِ؟ فَقَالَ: إِنِّي رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَصْبُغُ بِهَا، وَلَمْ يَكُنْ شَيْءٌ أَحَبَّ إِلَيْهِ مِنْهَا، وَقَدْ كَانَ يَصْبُغُ ثِيَابَهُ كُلَّهَا حَتَّى عِمَامَتَهُ. (ق,د,ن)', 'ഇബ്നുഉമർ(റ): അദ്ദേഹം തന്റെ വസ്ത്രങ്ങൾ മഞ്ഞയിൽ നിറയുമാറ് തന്റെ താടിയിൽ മഞ്ഞ നിറം പിടിപ്പിക്കാറുണ്ടായിരുന്നു. അപ്പോൾ അദ്ദേഹത്തോട് ചോദിച്ചു: താങ്കൾ എന്തുകൊണ്ടാണ് മഞ്ഞനിറം പിടിപ്പിക്കുന്നത്? അദ്ദേഹം പറഞ്ഞു: നിശ്ചയം, നബി(സ) ഈ നിറം പിടിപ്പിക്കുന്നത് ഞാൻ കണ്ടിട്ടുണ്ട്. അവിടുത്തേക്ക് അതിനേക്കാൾ ഇഷ്ടപ്പെട്ട മറ്റൊന്നുമുണ്ടായിരുന്നില്ല. അവിടുന്ന് തന്റെ തലപ്പാവടക്കമുള്ള എല്ലാ വസ്ത്രങ്ങളും ചായം മുക്കാറുണ്ടായിരുന്നു. (ബു,മു,ദ,ന)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ق','د','ن']::text[], array['ബു','മു','ദ','ന']::text[], null, null, 673, 673, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=45 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 133, 'عَنِ الْبَرَاءِ بْنِ عَازِبٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: أَمَرَنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِسَبْعٍ وَنَهَانَا عَنْ سَبْعٍ: أَمَرَنَا بِاتِّبَاعِ الْجَنَازَةِ، وَعِيَادَةِ الْمَرِيضِ، وَتَشْمِيتِ الْعَاطِسِ، وَإِجَابَةِ الدَّاعِي، وَنَصْرِ الْمَظْلُومِ، وَإِبْرَارِ الْقَسَمِ، وَرَدِّ السَّلَامِ. وَنَهَانَا عَنْ سَبْعٍ: عَنْ خَاتَمِ الذَّهَبِ، أَوْ: حَلْقَةِ الذَّهَبِ، وَآنِيَةِ الْفِضَّةِ، وَلُبْسِ الْحَرِيرِ، وَالدِّيبَاجِ، وَالإِسْتَبْرَقِ، وَالْقَسِّيِّ. حَسَنٌ صَحِيحٌ. (ق,د,ت,جه)', 'ബറാഉബ്നു ആസിബ്(റ): റസൂലുല്ലാഹി(സ) ഞങ്ങളോട് ഏഴ് കാര്യങ്ങൾ കൽപിക്കുകയും ഏഴ് കാര്യങ്ങൾ നിരോധിക്കുകയും ചെയ്തു. ജനാസയെ അനുഗമിക്കാനും, രോഗിയെ സന്ദർശിക്കാനും, തുമ്മിയവന് അല്ലാഹുവിന്റെ കാരുണ്യം തേടി പ്രാർത്ഥിക്കാനും, ക്ഷണിച്ചവന് ഉത്തരം ചെയ്യാനും, അക്രമിക്കപ്പെട്ടവനെ സഹായിക്കാനും, സത്യം ചെയ്താൽ അത് പാലിക്കാനും, സലാം മടക്കാനും അവിടുന്ന് ഞങ്ങളോട് കൽപിച്ചു. സ്വർണ്ണമോതിരവും, അല്ലെങ്കിൽ സ്വർണ്ണവളയം; വെള്ളിപ്പാത്രവും, ഹരീർ, ദീബാജ്, ഇസ്തബ്റഖ്, ഖസിയ്യ് എന്നീ വിവിധ തരം പട്ട് വസ്ത്രങ്ങൾ ധരിക്കലും അവിടുന്ന് നിരോധിച്ചു. (ബു,മു,ദ,തു,ജ)', 'الْبَرَاءِ بْنِ عَازِبٍ', 'ബറാഉബ്നു ആസിബ്(റ)', null, null, array['ق','د','ت','جه']::text[], array['ബു','മു','ദ','തു','ജ']::text[], null, null, 673, 673, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=46 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 134, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الْمُفَدَّمِ. (جه)', 'ഇബ്നുഉമർ(റ): മഞ്ഞ ചായം നന്നായി പിടിപ്പിച്ച വസ്ത്രം റസൂൽ(സ) നിരോധിച്ചിരിക്കുന്നു. (ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 673, 673, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=46 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 135, 'عَنْ عَلِيٍّ رَضِيَ اللَّهُ عَنْهُ قَالَ: نَهَانِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - وَلَا أَقُولُ نَهَاكُمْ - عَنْ لُبْسِ الْمُعَصْفَرِ. (م,د,ت,ن,جه)', 'അലി(റ): മഞ്ഞച്ചായം മുക്കിയ വസ്ത്രം ധരിക്കുന്നത് എനിക്ക് റസൂലുല്ലാഹി(സ) നിരോധിച്ചു- നിങ്ങൾക്കും നിരോധിച്ചു എന്ന് ഞാൻ പറയുന്നില്ല. (മു,ദ,തു,ന,ജ)', 'عَلِيٍّ', 'അലി(റ)', null, null, array['م','د','ت','ن','جه']::text[], array['മു','ദ','തു','ന','ജ']::text[], null, null, 673, 674, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=46 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 136, 'عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو رَضِيَ اللَّهُ عَنْهُمَا: أَنَّهُ رَآهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَعَلَيْهِ ثَوْبَانِ مُعَصْفَرَانِ، فَقَالَ: "هَذِهِ ثِيَابُ الْكُفَّارِ، فَلَا تَلْبَسْهَا". وَفِي رِوَايَةٍ: أَنَّهُ أَتَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَعَلَيْهِ ثَوْبَانِ مُعَصْفَرَانِ، فَغَضِبَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَقَالَ: "اذْهَبْ فَاطْرَحْهُمَا عَنْكَ". قَالَ: أَيْنَ يَا رَسُولَ اللَّهِ؟ قَالَ: "فِي النَّارِ". (ن)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): മഞ്ഞച്ചായം മുക്കിയ രണ്ട് വസ്ത്രങ്ങൾ അദ്ദേഹത്തിന്റെ ശരീരത്തിലുണ്ടായിരിക്കെ അദ്ദേഹത്തെ റസൂലുല്ലാഹി(സ) കണ്ടു. അവിടന്നരുളി: "ഇത് കാഫിറുകളുടെ വസ്ത്രമാണ്, അതിനാൽ ഇത് ധരിക്കരുത്." മറ്റൊരു റിപ്പോർട്ടിൽ: തന്റെ മേൽ മഞ്ഞച്ചായം മുക്കിയ രണ്ട് വസ്ത്രങ്ങളുണ്ടായിരിക്കെ അദ്ദേഹം നബി(സ)യുടെ തിരുസന്നിധിയിലേക്ക് ചെന്നു. അപ്പോൾ നബി(സ)ക്ക് ദേഷ്യം പിടിച്ചു. അവിടന്ന് പറഞ്ഞു. "പോകൂ, ആ രണ്ട് വസ്ത്രങ്ങളും ഒഴിവാക്കൂ." അദ്ദേഹം പറഞ്ഞു: അല്ലാഹുവിന്റെ ദൂതരേ, എവിടെ ഒഴിവാക്കണം? അവിടന്നരുളി: "തീയിൽ." (ന)', 'عَبْدِ اللَّهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 674, 674, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=46 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=8 and h.hadith_no=136), 1, 'وَفِي رِوَايَةٍ: أَنَّهُ أَتَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَعَلَيْهِ ثَوْبَانِ مُعَصْفَرَانِ، فَغَضِبَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَقَالَ: "اذْهَبْ فَاطْرَحْهُمَا عَنْكَ". قَالَ: أَيْنَ يَا رَسُولَ اللَّهِ؟ قَالَ: "فِي النَّارِ". (ن)', 'മറ്റൊരു നിവേദനിൽ: തന്റെ മേൽ മഞ്ഞച്ചായം മുക്കിയ രണ്ട് വസ്ത്രങ്ങളുണ്ടായിരിക്കെ അദ്ദേഹം നബി(സ)യുടെ തിരുസന്നിധിയിലേക്ക് ചെന്നു. അപ്പോൾ നബി(സ)ക്ക് ദേഷ്യം പിടിച്ചു. അവിടന്ന് പറഞ്ഞു. "പോകൂ, ആ രണ്ട് വസ്ത്രങ്ങളും ഒഴിവാക്കൂ." അദ്ദേഹം പറഞ്ഞു: അല്ലാഹുവിന്റെ ദൂതരേ, എവിടെ ഒഴിവാക്കണം? അവിടന്നരുളി: "തീയിൽ." (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 137, 'عَنْ عَلِيٍّ رَضِيَ اللَّهُ عَنْهُ قَالَ: نَهَانِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ خَاتَمِ الذَّهَبِ، وَعَنْ لُبُوسِ الْقَسِّيِّ وَالْمُعَصْفَرِ، وَقِرَاءَةِ الْقُرْآنِ وَأَنَا رَاكِعٌ. (ن)', 'അലി(റ): സ്വർണ്ണമോതിരവും, ഖസിയ്യ് (ഒരു തരം പട്ട്) വസ്ത്രവും മഞ്ഞച്ചായം മുക്കിയ വസ്ത്രധാരണവും, കുനിഞ്ഞ് നിന്ന് ഖുർആൻ ഓതലും എനിക്ക് റസൂലുല്ലാഹി(സ) നിരോധിച്ചു. (ന)', 'عَلِيٍّ', 'അലി(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 674, 674, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=46 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 138, 'عَنِ الْمِسْوَرِ بْنِ مَخْرَمَةَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قَسَمَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَقْبِيَةً وَلَمْ يُعْطِ مَخْرَمَةَ شَيْئًا، فَقَالَ مَخْرَمَةُ: يَا بُنَيَّ، انْطَلِقْ بِنَا إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. فَانْطَلَقْتُ مَعَهُ، قَالَ: ادْخُلْ فَادْعُهُ لِي، قَالَ: فَدَعَوْتُهُ، فَخَرَجَ إِلَيْهِ وَعَلَيْهِ قَبَاءٌ مِنْهَا، فَقَالَ: "خَبَأْتُ هَذَا لَكَ". قَالَ: فَنَظَرَ إِلَيْهِ مَخْرَمَةُ، فَقَالَ: "رَضِيَ مَخْرَمَةُ". (ق,د,ت,ن)', 'മിസ്‌വറുബ്നു മഖ്റമ(റ): മുഴുകൈയുള്ള വസ്ത്രങ്ങൾ റസൂലുല്ലാഹി(സ) വീതം വെച്ചപ്പോൾ മഖ്റമക്കൊന്നും നൽകിയില്ല. അപ്പോൾ മഖ്റമ(റ) പറഞ്ഞു: എന്റെ കുഞ്ഞിമോനേ, നമ്മെക്കൂട്ടി നീ റസൂലുല്ലാഹി(സ)യുടെ തിരുസന്നിധിയിലേക്ക് പോവുക. ഞാൻ അദ്ദേഹത്തിന്റെ കൂടെപ്പോയി. അദ്ദേഹം എന്നോട് പറഞ്ഞു: നീ അകത്ത് കടന്ന് നബി(സ)യെ എനിക്ക് വേണ്ടി വിളിക്കൂ. നിവേദകൻ പറയുന്നു: ഞാൻ അവിടത്തെ വിളിച്ചു. ഉടൻ തിരുമേനി(സ) അവയിൽ നിന്നുള്ള മുഴുകൈ വസ്ത്രങ്ങളിൽ നിന്നൊരു വസ്ത്രവുമായി അദ്ദേഹത്തിന്റെ അടുത്തേക്ക് ഇറങ്ങി വന്നു. എന്നിട്ട് പറഞ്ഞു: "ഇത് ഞാൻ നിനക്കായി മറച്ച് വെച്ചതാണ്." നിവേദകൻ പറയുന്നു: മഖ്റമ അതിലേക്ക് നോക്കി. അപ്പോൾ നബി(സ) പറഞ്ഞു: "മഖ്റമക്ക് തൃപ്തിയായി." (ബു,മു,ദ,തു,ന)', 'الْمِسْوَرِ بْنِ مَخْرَمَةَ', 'മിസ്‌വറുബ്നു മഖ്റമ(റ)', null, null, array['ق','د','ت','ن']::text[], array['ബു','മു','ദ','തു','ന']::text[], null, null, 674, 674, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=47 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 139, 'عَنْ خَبَّابِ بْنِ الْأَرَتِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: شَكَوْنَا إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - وَهُوَ مُتَوَسِّدٌ بُرْدَةٌ لَهُ فِي ظِلِّ الْكَعْبَةِ - فَقُلْنَا أَلَا تَسْتَنْصِرُ لَنَا؟ أَلَا تَدْعُو اللَّهَ لَنَا؟ (ت)', 'ഖബ്ബാബുബ്നുൽ അറത്ത്(റ): ഞങ്ങൾ റസൂലുല്ലാഹി(സ)യോട് ആവലാതി പറഞ്ഞു. അവിടന്ന് കഅ്ബയുടെ നിഴലിൽ തന്റെ വരയുള്ള വസ്ത്രം തലയിണയാക്കി കിടക്കുകയായിരുന്നു. ഞങ്ങൾ പറഞ്ഞു: അവിടന്ന് ഞങ്ങൾക്ക് വേണ്ടി സഹായം തേടുന്നില്ലേയോ? അവിടന്ന് ഞങ്ങൾക്ക് വേണ്ടി അല്ലാഹുവിനോട് പ്രാർത്ഥിക്കുന്നില്ലേയോ? (തു)', 'خَبَّابِ بْنِ الْأَرَتِّ', 'ഖബ്ബാബുബ്നുൽ അറത്ത്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 674, 675, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=48 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 140, 'عَنْ سَهْلِ بْنِ سَعْدٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: جَاءَتِ امْرَأَةٌ بِبُرْدَةٍ - قَالَ سَهْلٌ: هَلْ تَدْرُونَ مَا الْبُرْدَةُ؟ قَالُوا: نَعَمْ، هَذِهِ الشَّمْلَةُ مَنْسُوجٌ فِي حَاشِيَتِهَا - فَقَالَتْ: يَا رَسُولَ اللَّهِ، إِنِّي نَسَجْتُ هَذِهِ بِيَدِي أَكْسُوكَهَا. فَأَخَذَهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مُحْتَاجًا إِلَيْهَا، فَخَرَجَ إِلَيْنَا وَإِنَّهَا لَإِزَارُهُ. (ت)', 'സഹ്‌ലുബ്നു സഅ്ദ്(റ): ഒരു സ്ത്രീ വരയുള്ള വസ്ത്രവുമായി വന്നു - സഹ്‌ല്(റ) ചോദിച്ചു: ബുർദ എന്താണെന്ന് നിങ്ങൾക്കറിയാമോ? അവർ പറഞ്ഞു: അതെ, വക്കുകൾ തുന്നപ്പെട്ട ഈ മുഴു വസ്ത്രമാണ് - സ്ത്രീ പറഞ്ഞു: അല്ലാഹുവിന്റെ ദൂതരേ, ഇത് അങ്ങയെ ധരിപ്പിക്കാൻ വേണ്ടി ഞാനെന്റെ കൈകൊണ്ട് നെയ്തതാണ്. അപ്പോൾ റസൂലുല്ലാഹി(സ) ആശയോടെ അത് വാങ്ങി. പിന്നീട് അവിടന്ന് ഞങ്ങളുടെ അടുത്തേക്ക് പുറപ്പെട്ടു. അപ്പോൾ അത് അവിടത്തെ അരയുടുപ്പായിരുന്നു. (തു)', 'سَهْلِ بْنِ سَعْدٍ', 'സഹ്‌ലുബ്നു സഅ്ദ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 675, 675, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=48 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 141, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا زَوْجِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حِينَ تُوُفِّيَ سُجِّيَ بِبُرْدِ حِبَرَةٍ. (خ)', 'ആഇശ(റ): റസൂലുല്ലാഹി(സ) വഫാത്തായപ്പോൾ, വർണ്ണാഭമായ അലങ്കാര വസ്ത്രത്തിൽ മറക്കപ്പെട്ടിരുന്നു. (ബു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 675, 675, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=48 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 142, 'عَنْ قَتَادَةَ قَالَ: قُلْنَا لِأَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ: أَيُّ اللِّبَاسِ كَانَ أَحَبَّ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، أَوْ: أَعْجَبَ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؟ قَالَ: الْحِبَرَةُ. (ق,د,ت,ن)', 'ഖതാദ(റ): ഞങ്ങൾ അനസ്(റ)വിനോട് ചോദിച്ചു: നബി(സ)ക്ക് ഏറ്റവും ഇഷ്ടപ്പെട്ട വസ്ത്രം ഏതായിരുന്നു? അദ്ദേഹം പറഞ്ഞു: വർണാഭമായ അലങ്കാര വസ്ത്രം. (ബു,മു,ദ,തു,ന)', 'قَتَادَةَ قَالَ', 'ഖതാദ(റ)', null, null, array['ق','د','ت','ن']::text[], array['ബു','മു','ദ','തു','ന']::text[], null, null, 675, 675, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=48 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 143, 'عَنِ الْبَرَاءِ رَضِيَ اللَّهُ عَنْهُ قَالَ: رَأَيْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَعَلَيْهِ حُلَّةٌ حَمْرَاءُ مُتَرَجِّلًا، لَمْ أَرَ قَبْلَهُ وَلَا بَعْدَهُ أَحَدًا هُوَ أَجْمَلُ مِنْهُ. (ن)', 'ബറാഅ്(റ): നബി(സ) നന്നായി മുടി ചീകി ചുവന്ന മുഴുവസ്ത്രം ധരിച്ച് ഒട്ടകത്തിൽ നിന്നിറങ്ങി വരുന്നത് ഞാൻ കണ്ടു. അതിന് മുമ്പോ ശേഷമോ അവിടത്തേക്കാൾ ഭംഗിയുള്ള ഒരാളെയും ഞാൻ കണ്ടിട്ടില്ല. (ന)', 'الْبَرَاءِ', 'ബറാഅ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 675, 675, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=49 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 144, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ مَلِكَ ذِي يَزَنَ أَهْدَى إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حُلَّةً أَخَذَهَا بِثَلَاثَةٍ وَثَلَاثِينَ بَعِيرًا، أَوْ: ثَلَاثٍ وَثَلَاثِينَ نَاقَةً، فَقَبِلَهَا. (د)', 'അനസുബ്നു മാലിക്(റ): ദുയസൻ രാജാവ് പല്ല് മുളക്കാത്ത മുപ്പത്തിമൂന്ന് ഒട്ടകങ്ങൾ (അല്ലെങ്കിൽ മുപ്പത്തിമൂന്ന് പെണ്ണൊട്ടകം) കൊടുത്ത് വാങ്ങിയ ഒരു മുഴുവസ്ത്രം നബി(സ)ക്ക് സമ്മാനിച്ചു. തിരുമേനി(സ) അത് സ്വീകരിക്കുകയും ചെയ്തു. (ദ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 675, 676, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=50 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 145, 'عَنْ إِسْحَاقَ بْنِ عَبْدِ اللَّهِ بْنِ الْحَارِثِ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ اشْتَرَى حُلَّةً بِضْعَةَ وَعِشْرِينَ قَلُوصًا، فَأَهْدَاهَا إِلَى ذِي يَزَنَ. مرسل. (د)', 'ഇസ്ഹാഖുബ്നു അബ്ദില്ലാഹിബ്നിൽ ഹാരിസ്(റ): റസൂലുല്ലാഹി(സ) പ്രായം കുറഞ്ഞ ഇരുപതിൽപരം പെണ്ണൊട്ടകങ്ങൾക്ക് പകരം ഒരു മുഴുവസ്ത്രം വാങ്ങി. എന്നിട്ടത് ദൂയസൻ രാജാവിന് ഹദ്‌യ നൽകി. ഹദീസ് മുർസലാണ്. (ദ)', 'إِسْحَاقَ بْنِ عَبْدِ اللَّهِ بْنِ الْحَارِثِ', 'ഇസ്ഹാഖുബ്നു അബ്ദില്ലാഹിബ്നിൽ ഹാരിസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 676, 676, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=50 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 146, 'عَنْ أَبِي بُرْدَةَ قَالَ: دَخَلْتُ عَلَى عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا، فَأَخْرَجَتْ إِلَيْنَا إِزَارًا غَلِيظًا مِمَّا يُصْنَعُ بِالْيَمَنِ، وَكِسَاءً مِنَ الَّتِي يُسَمُّونَهَا الْمُلَبَّدَةَ، فَأَقْسَمَتْ بِاللَّهِ: إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قُبِضَ فِي هَذَيْنِ الثَّوْبَيْنِ. (م،د)', 'അബൂബുർദ(റ): ഞാൻ ആഇശ(റ)യുടെ അടുക്കലേക്ക് കടന്ന് വന്നപ്പോൾ മഹതി ഞങ്ങൾക്ക് യമനിൽ നിർമ്മിച്ച ഒരു പരുക്കൻ വസ്ത്രവും മുലബ്ബദ (കഷ്ണം വെക്കപ്പെട്ട വസ്ത്രം) എന്ന് വിളിക്കപ്പെടുന്ന വസ്ത്രവും പുറത്തെടുത്തു തന്നു. എന്നിട്ട് അല്ലാഹുവിനെക്കൊണ്ട് സത്യം ചെയ്ത് പറഞ്ഞു: നിശ്ചയം ഈ രണ്ട് വസ്ത്രങ്ങളിലായിരിക്കെയാണ് റസൂലുല്ലാഹി(സ) വഫാത്തായത്. (മു,ദ)', 'أَبِي بُرْدَةَ قَالَ', 'അബൂബുർദ(റ)', null, null, array['م','د']::text[], array['മു','ദ']::text[], null, null, 676, 676, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=51 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 147, 'عَنْ عَبْدِ اللَّهِ بْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: لَمَّا خَرَجَتِ الْحَرُورِيَّةُ أَتَيْتُ عَلِيًّا رَضِيَ اللَّهُ عَنْهُ، فَقَالَ: ائْتِ هَؤُلَاءِ الْقَوْمَ، فَلَبِسْتُ أَحْسَنَ مَا يَكُونُ مِنْ حُلَلِ الْيَمَنِ. وَكَانَ ابْنُ عَبَّاسٍ رَجُلًا جَمِيلًا جَهِيْرًا، قَالَ: فَأَتَيْتُهُمْ، فَقَالُوا: مَرْحَبًا بِكَ يَا ابْنَ عَبَّاسٍ، مَا هَذِهِ الْحُلَّةُ؟ قَالَ: مَا تَعِيبُونَ عَلَيَّ؟ لَقَدْ رَأَيْتُ عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَحْسَنَ مَا يَكُونُ مِنَ الْحُلَلِ. (د)', 'അബ്ദുല്ലാഹിബ്നു അബ്ബാസ്(റ): ഹറൂരിക്കാർ പുറപ്പെട്ടപ്പോൾ ഞാൻ അലി(റ)വിന്റെ അടുക്കൽ ചെന്നു. നീ ഇക്കൂട്ടരുടെ അടുക്കൽ ചെല്ലുക എന്ന് അലി(റ) പറഞ്ഞു. അപ്പോൾ ഞാൻ യമനിൽ നിർമ്മിതമായ ഏറ്റവും സുന്ദരമായ ഒരു മുഴുവസ്ത്രം ധരിച്ചു. ഇബ്നുഅബ്ബാസ്(റ) ഭംഗിയുള്ളവരും ഉയർന്ന ശബ്ദമുള്ളവരും ആയിരുന്നു. ഇബ്നുഅബ്ബാസ്(റ) പറയുന്നു: ഞാൻ അവരിലേക്ക് ചെന്നു. അവർ ചോദിച്ചു: ഇബ്നു അബ്ബാസിന് അഭിവാദ്യങ്ങൾ, ഏതാണീ മുഴുവസ്ത്രം? അദ്ദേഹം ചോദിച്ചു: നിങ്ങളെന്നെ മോശപ്പെടുത്തുകയാണോ? തീർച്ചയായും ഞാൻ റസൂലുല്ലാഹി(സ)യുടെ മേൽ ഏറ്റവും നല്ല മുഴുവസ്ത്രങ്ങൾ കണ്ടിട്ടുണ്ട്. (ദ)', 'عَبْدِ اللَّهِ بْنِ عَبَّاسٍ', 'അബ്ദുല്ലാഹിബ്നു അബ്ബാസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 676, 676, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=51 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 148, 'عَنْ جَابِرِ بْنِ سُلَيْمٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: أَتَيْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهُوَ مُحْتَبٍ بِشَمْلَةٍ، وَقَدْ وَقَعَ هُدْبُهَا عَلَى قَدَمَيْهِ. (د)', 'ജാബിറുബ്നു സുലൈം(റ): ഞാൻ നബി(സ)യുടെ അടുക്കൽ ചെന്നപ്പോൾ അവിടുന്ന് ഒരു മുഴുവസ്ത്രം കൊണ്ട് ചുറ്റിപ്പൂതച്ചിരിക്കുകയാണ്. അതിന്റെ കര അവിടുത്തെ ഇരു പാദങ്ങൾക്ക് മേലെയായിരുന്നു. (ദ)', 'جَابِرِ بْنِ سُلَيْمٍ', 'ജാബിറുബ്നു സുലൈം(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 676, 676, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=52 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 149, 'عَنْ سَعْدٍ - الرَّازِي الدَّشْتَكِي - رَضِيَ اللهُ عَنْهُ قَالَ: رَأَيْتُ رَجُلًا بِبُخَارَى عَلَى بَغْلَةٍ بَيْضَاءَ، وَعَلَيْهِ عِمَامَةُ خَزّ سَوْدَاءُ، فَقَالَ: كَسَانِيَهَا رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. (د)', 'സഅ്ദ് അർറാസി ദശ്തകി(റ): ബുഖാറയിൽ വെച്ച് കോവർകഴുതയുടെ പുറത്ത് സഞ്ചരിക്കുന്ന ഒരു മനുഷ്യനെ ഞാൻ കണ്ടു. പട്ടും രോമവും ചേർത്ത് നെയ്ത ഒരു കറുത്ത തലപ്പാവും അയാൾ ധരിച്ചിട്ടുണ്ട്. അയാൾ പറഞ്ഞു: ഇതെന്നെ റസൂലുല്ലാഹി(സ) ധരിപ്പിച്ചതാണ്. (ദ)', 'سَعْدٍ - الرَّازِي الدَّشْتَكِي -', 'സഅ്ദ് അർറാസി ദശ്തകി(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 677, 677, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=53 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 150, 'عَنْ عَبْدِ الرَّحْمَنِ بْنِ غَنْمٍ الْأَشْعَرِيِّ قَالَ: حَدَّثَنِي أَبُو عَامِرٍ - أَوْ أَبُو مَالِكٍ - رَضِيَ اللَّهُ عَنْهُمَا: أَنَّهُ سَمِعَ رَسُولَ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "لَيَكُونَنَّ مِنْ أُمَّتِي أَقْوَامٌ يَسْتَحِلُّونَ الْخَزَّ وَالْحَرِيرَ". وَذَكَرَ كَلَامًا، قَالَ: "يُمْسَخُ مِنْهُمْ آخَرُونَ قِرَدَةً وَخَنَازِيرَ إِلَى يَوْمِ الْقِيَامَةِ". (د)', 'അബ്ദുറഹ്‌മാനുബ്‌നു ഗൻമിൽ അശ്അരി(റ): എനിക്ക് അബൂ ആമിർ - അല്ലെങ്കിൽ അബൂമാലിക് - ഹദീസ് പറഞ്ഞുതന്നു. അദ്ദേഹം റസൂലുല്ലാഹി(സ) പറയുന്നത് കേട്ടു: "പട്ട് വസ്ത്രവും, രോമവും പട്ടും ചേർത്ത് നിർമ്മിച്ച വസ്ത്രവും ഹലാലാക്കുന്ന ഒരു കൂട്ടർ എന്റെ ഉമ്മത്തിൽ ഉണ്ടാവുക തന്നെ ചെയ്യും." അവിടന്ന് പറഞ്ഞ ഒരു വചനം കൂടി അദ്ദേഹം ഓർത്തു. അവിടന്ന് പറഞ്ഞു: "അവരിൽ നിന്ന് മറ്റുചിലർ അന്ത്യനാൾ വരെ കുരങ്ങൻമാരും പന്നികളുമായി കോലം മാറ്റപ്പെടും." (ദ)', 'عَبْدِ الرَّحْمَنِ بْنِ غَنْمٍ الْأَشْعَرِيِّ قَالَ', 'അബ്ദുറഹ്‌മാനുബ്‌നു ഗൻമിൽ അശ്അരി(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 677, 677, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=53 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 151, 'عَنِ الْمُغِيرَةِ بْنِ شُعْبَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَبِسَ جُبَّةً رُومِيَّةً ضَيِّقَةَ الْكُمَّيْنِ. حَسَنٌ صَحِيحٌ. (ت)', 'മുഗീറതുബ്നു ശുഅ്ബ(റ): നബി(സ) റോമിൽ നിർമ്മിതമായ, രണ്ട് മുൻകൈകളും ഇടുങ്ങിയ ജുബ്ബ ധരിച്ചു. (തു)', 'الْمُغِيرَةِ بْنِ شُعْبَةَ', 'മുഗീറതുബ്നു ശുഅ്ബ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 677, 677, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=54 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 152, 'عَنِ الْمُغِيرَةِ بْنِ شُعْبَةَ رضي الله عنه قال: أَهْدَى دِحْيَةُ الْكَلْبِيُّ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خُفَّيْنِ، فَلَبِسَهُمَا. (ت،ن)', 'മുഗീറത്തുബ്നു ശുഅ്ബ(റ): കണങ്കാൽ മറയുന്ന രണ്ട് പാദരക്ഷകൾ റസൂലുല്ലാഹി(സ)ക്ക് ദിഹ്‌യതുൽ കൽബി(റ) ഹദ്‌യ നൽകിയപ്പോൾ അവിടന്ന് അവ ധരിച്ചു. (തു,ന)', 'الْمُغِيرَةِ بْنِ شُعْبَةَ', 'മുഗീറത്തുബ്നു ശുഅ്ബ(റ)', null, null, array['ت','ن']::text[], array['തു','ന']::text[], null, null, 677, 677, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=54 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 153, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: خَرَجَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ذَاتَ غَدَاةٍ، وَعَلَيْهِ مِرْطٌ مُرَجَّلٌ مِنْ شَعْرٍ أَسْوَدَ. (م)', 'ആഇശ(റ): കൂടാരത്തിന്റെ ചിത്രമുള്ള കറുത്ത രോമത്താലുള്ള ഒരു വസ്ത്രം മേലിലിട്ട് നബി(സ) ഒരു പ്രഭാതത്തിൽ പുറത്തുപോയി. (മു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 677, 677, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=55 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 154, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: بَيْنَا نَحْنُ جُلُوسٌ فِي بَيْتِنَا فِي نَحْرِ الظَّهِيرَةِ قَالَ قَائِلٌ لِأَبِي بَكْرٍ رَضِيَ اللَّهُ عَنْهُ: هَذَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مُقْبِلًا مُتَقَنِّعًا، فِي سَاعَةٍ لَمْ يَكُنْ يَأْتِينَا فِيهَا، فَجَاءَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَاسْتَأْذَنَ فَأُذِنَ لَهُ، فَدَخَلَ. (خ,د)', 'ആഇശ(റ): ഉച്ചസമയത്ത് ഞങ്ങൾ വീട്ടിലിരിക്കെ ഒരാൾ അബൂബക്കർ(റ)വിനോട് പറഞ്ഞു: റസൂലുല്ലാഹി(സ) ഇതാ നമ്മുടെ പക്കൽ വരാറില്ലാത്ത ഒരു സമയത്ത് മൂടിപ്പുതച്ച് കടന്ന് വരുന്നു. അങ്ങനെ റസൂലുല്ലാഹി(സ) വന്നു, പ്രവേശനാനുമതി ചോദിച്ചു. അവിടുത്തേക്ക് സമ്മതം നൽകപ്പെട്ടു. തിരുമേനി(സ) അകത്തുകടക്കുകയും ചെയ്തു. (ബു,ദ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['خ','د']::text[], array['ബു','ദ']::text[], null, null, 678, 678, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=55 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 155, 'عَنْ جَابِرٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: لَمَّا تَزَوَّجْتُ قَالَ لِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "اتَّخَذْتَ أَنْمَاطًا". قُلْتُ: وَأَنَّى لَنَا أَنْمَاطٌ؟ قَالَ: "أَمَا إِنَّهَا سَتَكُونُ". قَالَ جَابِرٌ: وَعِنْدَ امْرَأَتِي نَمَطٌ، فَأَنَا أَقُولُ: نَحِّيهِ عَنِّي، وَتَقُولُ: قَدْ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِنَّهَا سَتَكُونُ". (م)', 'ജാബിർ(റ): ഞാൻ വിവാഹിതനായപ്പോൾ റസൂലുല്ലാഹി(സ) എന്നോട് പറഞ്ഞു: "നീ ഫാഷൻ വസ്ത്രങ്ങൾ ഉണ്ടാക്കിയോ?" ഞാൻ പറഞ്ഞു: ഞങ്ങൾക്കെവിടെ നിന്നാണ് ഫാഷൻ വസ്ത്രം? അവിടന്ന് പറഞ്ഞു: "അവ ഉണ്ടാകുകതന്നെ ചെയ്യും." ജാബിർ(റ) പറഞ്ഞു: എന്റെ ഭാര്യയുടെ പക്കൽ ഒരു ഫാഷൻ വസ്ത്രം ഉണ്ട്. ഞാൻ പറയും: എന്റെ അടുത്ത് നിന്ന് അത് മാറ്റിവെക്കൂ. അവൾ പറയും: തീർച്ചയായും റസൂലുല്ലാഹി(സ) പറഞ്ഞിട്ടുണ്ട്: "പിന്നീട് അവ ഉണ്ടാകുക തന്നെ ചെയ്യും." (മു)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 678, 678, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=56 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 156, 'عَنْ مَالِكِ بْنِ نَضْلَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: دَخَلْتُ عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَرَآنِي سَيِّئَ الْهَيْئَةِ، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "هَلْ لَكَ مِنْ شَيْءٍ؟". قَالَ: نَعَمْ، مِنْ كُلِّ الْمَالِ قَدْ آتَانِي اللَّهُ. فَقَالَ: "إِذَا كَانَ لَكَ مَالٌ فَلْيُرَ عَلَيْكَ". (ن)', 'മാലികുബ്നു നള്ല(റ): അദ്ദേഹം പറഞ്ഞു: ഞാൻ റസൂലുല്ലാഹി(സ)യുടെ അടുക്കൽ കടന്നു ചെന്നപ്പോൾ അവിടന്ന് എന്നെ മോശപ്പെട്ട നിലയിൽ കണ്ടു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "നിങ്ങൾക്കെന്തെങ്കിലും ഉണ്ടോ?" അദ്ദേഹം പറഞ്ഞു: അതെ, എല്ലാവിധ സമ്പത്തുകളും അല്ലാഹു എനിക്ക് നൽകിയിട്ടുണ്ട്. അപ്പോൾ തിരുമേനി(സ) പറഞ്ഞു: "നിനക്ക് സമ്പത്തുണ്ടെങ്കിൽ നിന്നിൽ കാണിക്കപ്പെടട്ടെ." (ന)', 'مَالِكِ بْنِ نَضْلَةَ', 'മാലികുബ്നു നള്ല(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 678, 678, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=57 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 157, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَنَّهُ لَعَنَ الْمُتَشَبِّهَاتِ مِنَ النِّسَاءِ بِالرِّجَالِ، وَالْمُتَشَبِّهِينَ مِنَ الرِّجَالِ بِالنِّسَاءِ. (خ,د,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): പുരുഷൻമാരോട് സാദൃശ്യം പുലർത്തുന്ന സ്ത്രീകളെയും, സ്ത്രീകളോട് സാദൃശ്യം പുലർത്തുന്ന പുരുഷൻമാരെയും നബി(സ) ശപിച്ചിരിക്കുന്നു. (ബു,ദ,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['خ','د','جه']::text[], array['ബു','ദ','ജ']::text[], null, null, 678, 679, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=58 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 158, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: لَعَنَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ الرَّجُلَ يَلْبَسُ لِبْسَةَ الْمَرْأَةِ، وَالْمَرْأَةَ تَلْبَسُ لِبْسَةَ الرَّجُلِ. (د)', 'അബൂഹുറൈറ(റ): സ്ത്രീവേഷം ധരിക്കുന്ന പുരുഷൻമാരെയും ആൺവസ്ത്രം ധരിക്കുന്ന സ്ത്രീകളെയും റസൂലുല്ലാഹി(സ) ശപിച്ചിരിക്കുന്നു. (ദ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 679, 679, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=58 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 159, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قِيلَ لَهَا: إِنَّ امْرَأَةً تَلْبَسُ النَّعْلَ، فَقَالَتْ: لَعَنَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ الرَّجُلَةَ مِنَ النِّسَاءِ. (د)', 'ആഇശ(റ): പുരുഷൻമാരുടെ ചെരുപ്പ് ധരിക്കുന്ന സ്ത്രീയെ സംബന്ധിച്ച് മഹതിയോട് ചോദിക്കപ്പെട്ടപ്പോൾ മഹതി പറഞ്ഞു: സ്ത്രീകളിൽ ആണത്തം പ്രകടിപ്പിക്കുന്നവരെ(വേഷത്തിൽ) റസൂലുല്ലാഹി(സ) ശപിച്ചിരിക്കുന്നു. (ദ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 679, 679, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=58 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 160, 'عَنْ دِحْيَةَ بْنِ خَلِيفَةَ الْكَلْبِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: أُتِيَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِقُبَاطِيَّ، فَأَعْطَانِي مِنْهَا قُبْطِيَّةً، فَقَالَ: "اصْدَعْهَا صَدْعَيْنِ، فَاقْطَعْ أَحَدَهُمَا قَمِيصًا، وَأَعْطِ الْآخَرَ امْرَأَتَكَ تَخْتَمِرُ بِهِ". فَلَمَّا أَدْبَرَ قَالَ: "وَأْمُرِ امْرَأَتَكَ أَنْ تَجْعَلَ تَحْتَهُ ثَوْبًا لَا يَصِفُهَا". (د)', 'ദിഹ്‌യത്തുബ്നു ഖലീഫത്തിൽ കൽബി(റ): കുറച്ച് ഈജിപ്ഷ്യൻ ചണത്തുണികൾ റസൂലുല്ലാഹി(സ)ക്ക് കൊണ്ടുവരപ്പെട്ടപ്പോൾ അവിടന്നെനിക്ക് അതിൽ നിന്നൊന്ന് തന്നു. എന്നിട്ട് പറഞ്ഞു: "ഇത് നിങ്ങൾ രണ്ട് കഷ്ണമായി ഭാഗിക്കുക, അവയിലൊന്ന് കൊണ്ട് നിങ്ങൾ നീളക്കുപ്പായം നെയ്യുക. മറ്റേത് നിങ്ങളുടെ ഭാര്യക്ക് മുഖമക്കനക്കായി നൽകുക." അദ്ദേഹം പിന്തിരിഞ്ഞ് പോന്നപ്പോൾ അവിടന്ന് പറഞ്ഞു: "നിന്റെ ഭാര്യയോട് അവളുടെ രൂപലാവണ്യം കാണിക്കാത്ത ഒരു വസ്ത്രം ഇതിനടിയിൽ ധരിക്കാൻ കൽപിക്കുക." (ദ)', 'دِحْيَةَ بْنِ خَلِيفَةَ الْكَلْبِيِّ', 'ദിഹ്‌യത്തുബ്നു ഖലീഫത്തിൽ കൽബി(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 679, 679, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=59 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 161, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "صِنْفَانِ مِنْ أَهْلِ النَّارِ لَمْ أَرَهُمَا: قَوْمٌ مَعَهُمْ سِيَاطٌ كَأَذْنَابِ الْبَقَرِ، يَضْرِبُونَ بِهَا النَّاسَ. وَنِسَاءٌ كَاسِيَاتٌ عَارِيَاتٌ، مُمِيلَاتٌ مَائِلَاتٌ، رُءُوسُهُنَّ كَأَسْنِمَةِ الْبُخْتِ الْمَائِلَةِ، لَا يَدْخُلْنَ الْجَنَّةَ وَلَا يَجِدْنَ رِيحَهَا، وَإِنَّ رِيحَهَا لَيُوجَدُ مِنْ مَسِيرَةِ كَذَا وَكَذَا". (م)', 'അബൂഹുറൈറ(റ): റസൂലുല്ലാഹി(സ) പറഞ്ഞു: "രണ്ട് വിഭാഗം നരകത്തിലാണ്. ഞാൻ അവരെ കാണാതിരിക്കട്ടെ. പശുവിന്റെ വാൽ പോലുള്ള ചാട്ടവാറുകൾ കൂടെ വെക്കുകയും അതുകൊണ്ട് മനുഷ്യരെ അടിക്കുകയും ചെയ്യുന്ന കൂട്ടരും, നഗ്നത കാണിക്കും വിധം വസ്ത്രം ധരിക്കുകയും, ചാഞ്ചാടുകയും മുഖം മുടി നീക്കുകയും ചെയ്യുന്ന സ്ത്രീകളും (ആണ് അവർ). ആ സ്ത്രീകളുടെ തല ചാഞ്ഞ്നടക്കുന്ന ഒട്ടകത്തിന്റെ പുഞ്ഞകൾ പോലെയാണ്. ആ സ്ത്രീകൾ സ്വർഗ്ഗത്തിൽ പ്രവേശിക്കുകയോ അതിന്റെ വാസന അവരനുഭവിക്കുകയോ ഇല്ല. ഇന്നാലിന്ന ദൂരത്തോളം എത്തുന്നതാണ് സ്വർഗ്ഗവാസന." (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 679, 679, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=60 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 162, 'عَنْ أُمِّ سَلَمَةَ رَضِيَ اللَّهُ عَنْهَا: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ دَخَلَ عَلَيْهَا وَهِيَ تَخْتَمِرُ، فَقَالَ: "لَيَّةً لَا لَيَّتَيْنِ". (د)', 'ഉമ്മുസലമ(റ): മുഖമക്കന ധരിച്ചു കൊണ്ടിരിക്കെ, മഹതിയുടെ അടുക്കൽ നബി(സ) കടന്നു വന്നു. അപ്പോൾ അവിടന്ന് പറഞ്ഞു: "ഒരു ചുരുളാക്ക്, രണ്ട് ചുരുളുകളല്ല." (ദ)', 'أُمِّ سَلَمَةَ', 'ഉമ്മുസലമ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 680, 680, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=61 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 163, 'عَنْ جَابِرٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ أُمَّ سَلَمَةَ اسْتَأْذَنَتْ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي الْحِجَامَةِ، فَأَمَرَ أَبَا طَيْبَةَ أَنْ يَحْجُمَهَا، قَالَ: حَسِبْتُ أَنَّهُ قَالَ: كَانَ أَخَاهَا مِنَ الرَّضَاعَةِ، أَوْ غُلَامًا لَمْ يَحْتَلِمْ. (م,د,جه)', 'ജാബിർ(റ): ഉമ്മുസലമ(റ) റസൂലുല്ലാഹി(സ)യോട് കൊമ്പുവെക്കാൻ സമ്മതം ചോദിച്ചു. അപ്പോൾ അവിടന്ന് അബൂത്വയ്ബയോട് മഹതിക്ക് കൊമ്പ് വെക്കാൻ കൽപിച്ചു. ജാബിർ(റ) പറഞ്ഞു: അത് അവരുടെ (മഹതിയുടെ) മുലകുടിബന്ധത്തിൽപ്പെട്ട സഹോദരനാണെന്നോ അല്ലെങ്കിൽ പ്രായപൂർത്തിയാകാത്ത കുട്ടിയാണ് എന്നോ അവിടന്ന് പറഞ്ഞതായി എനിക്ക് തോന്നുന്നു. (മു,ദ,ജ)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['م','د','جه']::text[], array['മു','ദ','ജ']::text[], null, null, 680, 680, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=62 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 164, 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَتَى فَاطِمَةَ بِعَبْدٍ كَانَ قَدْ وَهَبَهُ لَهَا، قَالَ: وَعَلَى فَاطِمَةَ رَضِيَ اللَّهُ عَنْهَا ثَوْبٌ: إِذَا قَنَّعَتْ بِهِ رَأْسَهَا لَمْ يَبْلُغْ رِجْلَيْهَا، وَإِذَا غَطَّتْ بِهِ رِجْلَيْهَا لَمْ يَبْلُغْ رَأْسَهَا، فَلَمَّا رَأَى النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَا تَلْقَى قَالَ: "إِنَّهُ لَيْسَ عَلَيْكِ بَأْسٌ، إِنَّمَا هُوَ أَبُوكِ وَغُلَامُكِ". (د)', 'അനസ്(റ): നബി(സ) ഫാത്തിമ(റ)ക്ക് നൽകിയിരുന്ന ഒരു അടിമയുമായി അവിടന്ന് ഫാത്തിമ(റ)യുടെ അടുത്ത് വന്നു. നിവേദകൻ പറയുന്നു: ഫാത്തിമ(റ)യുടെ ശരീരത്തിൽ ഒരു വസ്ത്രമുണ്ടായിരുന്നു. അതുകൊണ്ട് തല മറച്ചാൽ കാൽ വരെ എത്തുകയില്ല. കാൽ മറച്ചാൽ തല വരെയും എത്തില്ല. ഫാത്തിമ(റ)ക്ക് വന്ന ഈ അവസ്ഥ കണ്ടപ്പോൾ നബി(സ) പറഞ്ഞു: "നിശ്ചയം നിനക്കൊരു പ്രശ്നവും ഇല്ല. തീർച്ചയായും ഇത് നിന്റെ പിതാവും നിന്റെ അടിമയും മാത്രമാകുന്നു." (ദ)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 680, 680, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=62 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 165, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا: أَنَّ أَسْمَاءَ بِنْتَ أَبِي بَكْرٍ دَخَلَتْ عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَعَلَيْهَا ثِيَابٌ رِقَاقٌ، فَأَعْرَضَ عَنْهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَقَالَ: "يَا أَسْمَاءُ، إِنَّ المَرْأَةَ إِذَا بَلَغَتِ الْمَحِيضَ لَمْ تَصْلُحْ أَنْ يُرَى مِنْهَا إِلَّا هَذَا وَهَذَا"، وَأَشَارَ إِلَى وَجْهِهِ وَكَفَّيْهِ. (مرسل) (د)', 'ആഇശ(റ): നേരിയ വസ്ത്രം ധരിച്ച് അസ്മാഉബിൻത് അബൂബക്കർ(റ) നബി(സ)യുടെ അടുക്കൽ വന്നു. അപ്പോൾ നബി(സ) അവരിൽ നിന്ന് തിരിഞ്ഞ് കളഞ്ഞു. എന്നിട്ട് നബി(സ) പറഞ്ഞു: "അസ്മാഅ്(റ), നിശ്ചയം, സ്ത്രീക്ക് ആർത്തവ പ്രായമെത്തിയാൽ അവളിൽ നിന്ന് ഇതും ഇതുമല്ലാതെ ഒന്നും കാണപ്പെടാൻ പാടില്ല." അവിടന്ന് തന്റെ മുഖവും മുൻകയ്യും ആംഗ്യം കാണിച്ചു. ഹദീസ് മുർസലാണ്. (ദ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 680, 680, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=63 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 166, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا: أَنَّهَا ذَكَرَتْ نِسَاءَ الْأَنْصَارِ، فَأَثْنَتْ عَلَيْهِنَّ، وَقَالَتْ لَهُنَّ مَعْرُوفًا، وَقَالَتْ: لَمَّا نَزَلَتْ سُورَةُ النُّورِ عَمِدْنَ إِلَى حُجُورٍ -أَوْ حُجُوزٍ- شَكَّ أَبُو كَامِلٍ فَشَقَقْنَهُنَّ، فَاتَّخَذْنَهُ خُمُرًا. (د)', 'ആഇശ(റ): മഹതി അൻസാരിസ്ത്രീകളെക്കുറിച്ച് പറഞ്ഞു. അവരെ പുകഴ്ത്തി, അവരെക്കുറിച്ച് നല്ലത് മാത്രം പറഞ്ഞു. എന്നിട്ട് പറഞ്ഞു. ''നൂർ'' സൂറത്തിറങ്ങിയപ്പോൾ അവർ റൂമുകളിലേക്ക് അല്ലെങ്കിൽ വിരികളിലേക്ക് ചെന്ന് അവ മുറിക്കുകയും മുഖമറയാക്കുകയും ചെയ്തു. (''ഹുജൂർ'' എന്നാണോ ''ഹുജൂസ്'' എന്നാണോ പറഞ്ഞതെന്ന് നിവേദകൻ സംശയിക്കുന്നു). (ദ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, '''ഹുജൂർ'' എന്നാണോ ''ഹുജൂസ്'' എന്നാണോ പറഞ്ഞതെന്ന് നിവേദകൻ സംശയിക്കുന്നു', 681, 681, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=64 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 167, 'عَنْ أُمِّ سَلَمَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: لَمَّا نَزَلَتْ: {يُدْنِينَ عَلَيْهِنَّ مِنْ جَلَابِيبِهِنَّ} خَرَجَ نِسَاءُ الْأَنْصَارِ كَأَنَّ عَلَى رُءُوسِهِنَّ الْغِرْبَانَ مِنَ الْأَكْسِيَةِ. (د)', 'ഉമ്മുസലമ(റ): ''അവർ അവരുടെ മുഖമറ താഴ്ത്തിയിടട്ടെ'' എന്ന സൂക്തം ഇറങ്ങിയപ്പോൾ അൻസാരിസ്ത്രീകൾ പുറപ്പെട്ടു. വസ്ത്രങ്ങൾ കാരണം അവരുടെ തലകളിൽ കാക്കകളിരിക്കുന്നത് പോലെ തോന്നിച്ചു. (ദ)', 'أُمِّ سَلَمَةَ', 'ഉമ്മുസലമ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 681, 681, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=64 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 168, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا أَنَّهَا قَالَتْ: يَرْحَمُ اللَّهُ نِسَاءَ الْمُهَاجِرَاتِ الْأُوَلَ، لَمَّا أَنْزَلَ اللَّهُ: {وَلْيَضْرِبْنَ بِخُمُرِهِنَّ عَلَى جُيُوبِهِنَّ} شَقَّقْنَ أَكْنَفَ -أَكْتَفَ- مُرُوطِهِنَّ، فَاخْتَمَرْنَ بِهَا. (د)', 'ആഇശ(റ): ആദ്യകാല മുഹാജിറുകളായ സ്ത്രീകളെ അല്ലാഹു അനുഗ്രഹിക്കട്ടെ. ''അവരുടെ തലമക്കന അവരുടെ നെഞ്ചിൽ തട്ടിക്കട്ടെ.'' എന്ന ആയത്ത് അല്ലാഹു ഇറക്കിയപ്പോൾ (ആ സ്ത്രീകൾ) നന്നായി മറയ്ക്കാവുന്നതും വളരെ തിങ്ങിയതുമായ മുഴുവസ്ത്രങ്ങൾ മുറിക്കുകയും അവ കൊണ്ട് അവർ തലമക്കനയുണ്ടാക്കുകയും ചെയ്തു. (ദ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 681, 681, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=65 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 169, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُ: {وَقُلْ لِلْمُؤْمِنَاتِ يَغْضُضْنَ مِنْ أَبْصَارِهِنَّ} الْآيَةَ، فَنُسِخَ وَاسْتُثْنِيَ مِنْ ذَلِكَ: {وَالْقَوَاعِدُ مِنَ النِّسَاءِ اللَّاتِي لَا يَرْجُونَ نِكَاحًا} الْآيَةَ (النور: ٦٠) (د)', 'ഇബ്നുഅബ്ബാസ്(റ): ''മുഅ്മിനുകളായ സ്ത്രീകളോട് അവരുടെ കാഴ്ചയെ താഴ്ത്താൻ താങ്കൾ പറയുക'' എന്ന ആയത്ത് നസ്ഖ് ചെയ്യപ്പെട്ടു (ദുർബലമാക്കപ്പെട്ടു) അതിൽ നിന്ന് ''പ്രസവം മാറി കല്യാണമാഗ്രഹിക്കാത്ത സ്ത്രീകൾ'' (നൂർ: 60) എന്നത് ഒഴിച്ച് നിർത്തുകയും ചെയ്തു. (ദ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, 'ദുർബലമാക്കപ്പെട്ടു', 681, 681, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=66 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 170, 'عَنْ أُمِّ سَلَمَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: كُنْتُ عِنْدَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَعِنْدَهُ مَيْمُونَةُ، فَأَقْبَلَ ابْنُ أُمِّ مَكْتُومٍ، وَذَلِكَ بَعْدَ أَنْ أُمِرْنَا بِالْحِجَابِ، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "احْتَجِبَا مِنْهُ". فَقُلْنَا: يَا رَسُولَ اللَّهِ، أَلَيْسَ أَعْمَى، لَا يُبْصِرُنَا وَلَا يَعْرِفُنَا؟ فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَفَعَمْيَاوَانِ أَنْتُمَا؟ أَلَسْتُمَا تُبْصِرَانِهِ؟". (د،ت)', 'ഉമ്മുസലമ(റ): ഞാൻ റസൂലുല്ലാഹി(സ)യുടെ കൂടെയായിരുന്നു. മൈമൂന(റ)യും അവിടുത്തെ അടുത്തുണ്ടായിരുന്നു. അപ്പോൾ ഇബ്നു ഉമ്മിമക്തൂം(റ) കടന്നുവന്നു. ഞങ്ങളോട് മറ പാലിക്കാൻ കൽപിക്കപ്പെട്ട ശേഷമായിരുന്നു ഇത്. അപ്പോൾ നബി(സ) പറഞ്ഞു: "നിങ്ങളിരുവരും അയാളിൽ നിന്ന് മറയുക." ഞങ്ങൾ ചോദിച്ചു: അല്ലാഹുവിന്റെ ദൂതരേ, അദ്ദേഹം അന്ധനല്ലെയോ? അയാൾ ഞങ്ങളെ കാണുകയും അറിയുകയുമില്ലല്ലോ? അപ്പോൾ നബി(സ) ചോദിച്ചു: "നിങ്ങൾ രണ്ട് പേരും അന്ധരാണോ? നിങ്ങളിരുവരും അദ്ദേഹത്തെ കാണുന്നില്ലേ?" (ദ,തു)', 'أُمِّ سَلَمَةَ', 'ഉമ്മുസലമ(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 681, 682, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=66 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 171, 'عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو رَضِيَ اللَّهُ عَنْهُمَا، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِذَا زَوَّجَ أَحَدُكُمْ عَبْدَهُ أَمَتَهُ فَلَا يَنْظُرْ إِلَى عَوْرَتِهَا". وَ فِي رِوَايَةٍ: "إِذَا زَوَّجَ أَحَدُكُمْ خَادِمَهُ، عَبْدَهُ أَوْ أَجِيرَهُ، فَلَا يَنْظُرْ إِلَى مَا دُونَ السُّرَّةِ وَفَوْقَ الرُّكْبَةِ". (د)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങളാരെങ്കിലും തന്റെ അടിമക്ക് തന്റെ അടിമപ്പെണ്ണിനെ വിവാഹം ചെയ്ത് കൊടുത്താൽ പിന്നീടവളുടെ നഗ്നതയിലേക്ക് നോക്കരുത്."
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=8 and h.hadith_no=171), 1, null, 'മറ്റൊരു നിവേദനിൽ: "നിങ്ങളിലാരെങ്കിലും തന്റെ സേവകൻ അടിമയെ, അല്ലെങ്കിൽ കൂലിപ്പണിക്കാരനെ വിവാഹം ചെയ്തുകൊടുത്താൽ പിന്നീട് അവന്റെ മുട്ട് പൊക്കിളിനിടയിലുള്ളത് നോക്കരുത്." (ദ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 172, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: كَانَ يَدْخُلُ عَلَى أَزْوَاجِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مُخَنَّثٌ، فَكَانُوا يَعُدُّونَهُ مِنْ غَيْرِ أُولِي الْإِرْبَةِ، فَدَخَلَ عَلَيْنَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَوْمًا وَهُوَ عِنْدَ بَعْضِ نِسَائِهِ، وَهُوَ يَنْعَتُ امْرَأَةً، فَقَالَ: إِنَّهَا إِذَا أَقْبَلَتْ أَقْبَلَتْ بِأَرْبَعٍ، وَإِذَا أَدْبَرَتْ أَدْبَرَتْ بِثَمَانٍ. فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَلَا أَرَى هَذَا يَعْلَمُ مَا هَاهُنَا، لَا يَدْخُلَنَّ عَلَيْكُنَّ هَذَا". فَحَجَبُوهُ. وَفِي رِوَايَةٍ: وَأَخْرَجَهُ فَكَانَ بِالْبَيْدَاءِ، يَدْخُلُ كُلَّ جُمُعَةٍ يَسْتَطْعِمُ. وَفِي رِوَايَةٍ: فَقِيلَ يَا رَسُولَ اللَّهِ، إِنَّهُ إِذَنْ يَمُوتُ مِنَ الْجُوعِ. فَأَذِنَ لَهُ أَنْ يَدْخُلَ فِي كُلِّ جُمُعَةٍ مَرَّتَيْنِ، فَيَسْأَلَ ثُمَّ يَرْجِعَ. (م،د)', 'ആഇശ(റ): ഒരു നപുംസകം നബി(സ)യുടെ ഭാര്യമാരുടെ അടുക്കൽ വരാറുണ്ടായിരുന്നു. അവരയാളെ കെട്ടുബന്ധമില്ലാത്തവരിൽ കണക്കാക്കിയിരുന്നു. (ഒരിക്കൽ) ഇയാൾ നബി(സ)യുടെ ചില പത്നിമാരുടെ അടുത്ത് ഒരു സ്ത്രീയെ വർണ്ണിച്ചുകൊണ്ട് പറഞ്ഞു: അവൾ മുന്നിട്ട് വരുമ്പോൾ (വയറിന്) നാല് മടക്കും തിരിഞ്ഞ് പോകുമ്പോൾ പിറകിൽ (ഇരുവശത്തായി) എട്ടു മടക്കുമുണ്ട്. അന്നേരം നബി(സ) കടന്ന് വന്നു. അപ്പോൾ അവിടന്ന് പറഞ്ഞു: "ഇയാൾ ഇവിടുത്തെ കാര്യങ്ങൾ മനസ്സിലാക്കുന്നത് ഞാൻ കാണുന്നല്ലോ. നിങ്ങൾക്കിടയിൽ ഇയാൾ ഒരിക്കലും കടന്ന് വരരുത്." അപ്പോൾ അവർ അയാളെ അകറ്റിനിർത്തി.
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=8 and h.hadith_no=172), 1, 'وَفِي رِوَايَةٍ: وَأَخْرَجَهُ فَكَانَ بِالْبَيْدَاءِ، يَدْخُلُ كُلَّ جُمُعَةٍ يَسْتَطْعِمُ.', 'മറ്റൊരു നിവേദനിൽ: അവിടന്ന് അയാളെ പുറത്താക്കി. അയാൾ മരുഭൂമിയിലായിരുന്നു. എല്ലാ വെള്ളിയാഴ്ചയും ഭക്ഷണം ചോദിച്ച് വരും.');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=8 and h.hadith_no=172), 2, 'وَفِي رِوَايَةٍ: فَقِيلَ يَا رَسُولَ اللَّهِ، إِنَّهُ إِذَنْ يَمُوتُ مِنَ الْجُوعِ. فَأَذِنَ لَهُ أَنْ يَدْخُلَ فِي كُلِّ جُمُعَةٍ مَرَّتَيْنِ، فَيَسْأَلَ ثُمَّ يَرْجِعَ. (م،د)', 'മറ്റൊരു നിവേദനിൽ: അപ്പോൾ ചോദിക്കപ്പെട്ടു: അല്ലാഹുവിന്റെ ദൂതരേ, ഇങ്ങനെയെങ്കിൽ അയാൾ തീർച്ചയായും വിശന്ന് മരിക്കില്ലേ. അപ്പോൾ അയാൾക്ക് ആഴ്ചയിൽ രണ്ട് പ്രാവശ്യം കടന്ന് വരാൻ അവിടന്ന് അനുമതി നൽകി. അങ്ങനെ അയാൾ ചോദിക്കുകയും മടങ്ങുകയും ചെയ്യും. (മു,ദ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 173, 'عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "كُلُوا وَاشْرَبُوا وَتَصَدَّقُوا وَالْبَسُوا، مَا لَمْ يُخَالِطْهُ إِسْرَافٌ أَوْ مَخِيلَةٌ". (ن,جه)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): റസൂലുല്ലാഹി(സ) പറഞ്ഞു: "നിങ്ങൾ തിന്നുകയും കുടിക്കുകയും ദാനം ചെയ്യുകയും വസ്ത്രം ധരിക്കുകയും ചെയ്യുക. അതിൽ അഹങ്കാരമോ അമിതവ്യയമോ വന്ന് ചേരാത്ത കാലമത്രയും." (ന,ജ)', 'عَبْدِ اللَّهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['ن','جه']::text[], array['ന','ജ']::text[], null, null, 683, 683, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=68 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 174, 'عَنْ أَبِي ذَرٍّ رَضِيَ اللَّهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ لَبِسَ ثَوْبَ شُهْرَةٍ أَعْرَضَ اللَّهُ عَنْهُ حَتَّى يَضَعَهُ مَتَى وَضَعَهُ". (جه)', 'അബൂദർറ്(റ): നബി(സ) പറഞ്ഞു: "ആരെങ്കിലും പ്രസിദ്ധിക്ക് വേണ്ടി വസ്ത്രം ധരിച്ചാൽ അവനത് അഴിച്ച് വെക്കും വരെ അവനെത്തൊട്ട് അല്ലാഹു തിരിഞ്ഞു കളയുന്നതാണ്." (ദ)', 'أَبِي ذَرٍّ', 'അബൂദർറ്(റ)', null, null, array['جه']::text[], array['ദ']::text[], null, null, 683, 683, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=69 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 175, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا - يَرْفَعُهُ - قَالَ: "مَنْ لَبِسَ ثَوْبَ شُهْرَةٍ أَلْبَسَهُ اللَّهُ يَوْمَ الْقِيَامَةِ ثَوْبًا مِثْلَهُ - وَفِي رِوَايَةٍ: ثَوْبَ مَذَلَّةٍ - ثُمَّ تُلَهَّبُ فِيهِ النَّارُ". (جه)', 'ഇബ്നുഉമർ(റ): (''മർഫൂഅ്'' ആക്കിപ്പറയുന്നു): "ആരെങ്കിലും ഖ്യാതിക്ക് വേണ്ടി വസ്ത്രധാരണം ചെയ്താൽ അല്ലാഹു അവനെ അന്ത്യനാളിൽ അതുപോലുള്ള വസ്ത്രം ധരിപ്പിക്കും -മറ്റൊരു ഉദ്ധരണിയിൽ: നിന്ദ്യതയുടെ വസ്ത്രം- പിന്നീട് തീ അതിൽ ആളിക്കത്തും." (ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 683, 683, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=69 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=8 and h.hadith_no=175), 1, 'وَفِي رِوَايَةٍ: ثَوْبَ مَذَلَّةٍ - ثُمَّ تُلَهَّبُ فِيهِ النَّارُ". (جه)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 176, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ تَشَبَّهَ بِقَوْمٍ فَهُوَ مِنْهُمْ". (د)', 'ഇബ്നുഉമർ(റ): റസൂലുല്ലാഹി(സ) പറഞ്ഞു: "ആരെങ്കിലും ഒരു കൂട്ടരോട് സാദൃശ്യം പുലർത്തിയാൽ അവൻ അവരിൽ പെട്ടവനാണ്." (ദ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 683, 683, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=69 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 177, 'عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: أَتَانَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَرَأَى رَجُلًا شَعِثًا قَدْ تَفَرَّقَ شَعْرُهُ فَقَالَ: "أَمَا كَانَ يَجِدُ هَذَا مَا يُسَكِّنُ بِهِ شَعْرَهُ". وَرَأَى رَجُلًا آخَرَ وَعَلَيْهِ ثِيَابٌ وَسِخَةٌ فَقَالَ: أَمَا كَانَ هَذَا يَجِدُ مَاءً يَغْسِلُ بِهِ ثَوْبَهُ". (د)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): റസൂലുല്ലാഹി(സ) ഞങ്ങളുടെ അടുക്കലേക്ക് വന്നപ്പോൾ മുടി ചിന്നഭിന്നമായി ജടകുത്തിയ ഒരാളെ കണ്ടു. അവിടുന്ന് ചോദിച്ചു: "ഇയാൾക്ക് തന്റെ മുടി ഒതുക്കാൻ ഒന്നും കിട്ടിയില്ലേ." അവിടുന്ന് മറ്റൊരാളെയും കണ്ടു. അയാളുടെ ശരീരത്തിൽ ചെളിയുള്ള ഒരു വസ്ത്രവുമുണ്ട്. അപ്പോൾ അവിടന്ന് പറഞ്ഞു: "ഇയാൾക്ക് വസ്ത്രം അലക്കുവാനുള്ളതൊന്നും കിട്ടിയില്ലേ?" (ദ)', 'جَابِرِ بْنِ عَبْدِ اللَّهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 683, 684, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=70 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 178, 'عَنْ مَالِكِ بْنِ نَضْلَةَ رَضِيَ اللهُ عَنْهُ قَالَ: أَتَيْتُ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي ثَوْبٍ دُونٍ، فَقَالَ: "أَلَكَ مَالٌ". قَالَ: نَعَمْ، قَالَ: "مِنْ أَيِّ الْمَالِ". قَالَ: قَدْ آتَانِي اللهُ مِنَ الْإِبِلِ وَالْغَنَمِ وَالْخَيْلِ وَالرَّقِيقِ. قَالَ: "فَإِذَا آتَاكَ اللهُ مَالًا فَلْيُرَ أَثَرُ نِعْمَةِ اللهِ عَلَيْكَ وَكَرَامَتِهِ". (د)', 'മാലികുബ്നു നള്ല(റ): ഞാൻ നബി(സ)യുടെ അടുക്കൽ താഴ്ന്നതരം വസ്ത്രം ധരിച്ച് ചെന്നു. അവിടന്ന് പറഞ്ഞു: "നിനക്ക് സമ്പത്തില്ലേ." അദ്ദേഹം പറഞ്ഞു: അതെ. അവിടന്ന് ചോദിച്ചു: "ഏത് തരം സമ്പത്താണ് നിനക്കുള്ളത്?" അദ്ദേഹം പറഞ്ഞു: എനിക്കല്ലാഹു ഒട്ടകവും ആടുകളും കുതിരകളും അടിമകളും തന്നിട്ടുണ്ട്. അവിടന്ന് അരുളി: "നിനക്കല്ലാഹു സമ്പത്ത് തന്നിട്ടുണ്ടെങ്കിൽ അവൻ നിനക്ക് തന്ന അനുഗ്രഹത്തിന്റെയും ഔദാര്യത്തിന്റെയും പ്രതിഫലനം നിന്നിൽ കാണട്ടെ." (ദ)', 'مَالِكِ بْنِ نَضْلَةَ', 'മാലികുബ്നു നള്ല(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 684, 684, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=70 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 179, 'عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ الله عَنْهُمَا قَالَ: ذَكَرَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْفِرَاشَ فَقَالَ: "فِرَاشٌ لِلرَّجُلِ، وَفِرَاشٌ لِلْمَرْأَةِ، وَفِرَاشٌ لِلضَّيْفِ، وَالرَّابِعُ لِلشَّيْطَانِ". (م,د,ن)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): റസൂലുല്ലാഹി(സ) വിരിപ്പിനെക്കുറിച്ച് പറഞ്ഞു: "ഒരു വിരിപ്പ് ആണിനും ഒരു വിരിപ്പ് അവന്റെ ഭാര്യക്കും, ഒരു വിരിപ്പ് അതിഥിക്കും, നാലാമത്തേത് ശൈത്വാനും ആണ്". (മു,ദ,ന)', 'جَابِرِ بْنِ عَبْدِ اللَّهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['م','د','ن']::text[], array['മു','ദ','ന']::text[], null, null, 684, 684, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=71 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 180, 'عَنْ جَابِرِ بْنِ سَمُرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: دَخَلْتُ عَلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي بَيْتِهِ فَرَأَيْتُهُ مُتَّكِئًا عَلَى وِسَادَةٍ عَلَى يَسَارِهِ. (د,ت)', 'ജാബിറുബ്നു സമുറ(റ): ഞാൻ നബി(സ)യുടെ വീട്ടിലേക്ക് കടന്ന് ചെന്നു. അപ്പോൾ അവിടന്ന് ഇടത് ഭാഗം ഒരു തലയണയുടെ മേൽ ചാരികിടക്കുന്നതായി ഞാൻ കണ്ടു. (ദ,തു)', 'جَابِرِ بْنِ سَمُرَةَ', 'ജാബിറുബ്നു സമുറ(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 684, 684, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=71 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 181, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّهُ رَأَى رُفْقَةً مِنْ أَهْلِ الْيَمَنِ رِحَالُهُمُ الْأَدَمُ، فَقَالَ: مَنْ أَحَبَّ أَنْ يَنْظُرَ إِلَى أَشْبَهِ رُفْقَةٍ كَانُوا بِأَصْحَابِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَلْيَنْظُرْ إِلَى هَؤُلَاءِ. (د)', 'ഇബ്നുഉമർ(റ): അദ്ദേഹം യമനിൽ നിന്നുള്ള ഒരു പറ്റം കൂട്ടുകാരെക്കണ്ടു. അവരുടെ ഒട്ടകക്കട്ടിലുകൾ തോൽ കൊണ്ട് നിർമിച്ചതാണ്. അപ്പോൾ അദ്ദേഹം പറഞ്ഞു: നബി(സ)യുടെ അനുചരൻമാരോട് ഏറ്റവും സദൃശ്യമുള്ള കൂട്ടുകാരെ കാണാൻ ആരെങ്കിലും ഇഷ്ടപ്പെടുന്നുവെങ്കിൽ ഇവരിലേക്ക് നോക്കിക്കൊള്ളുക. (ദ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 684, 684, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=71 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 182, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كَانَتْ وِسَادَةُ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ الَّتِي يَنَامُ عَلَيْهَا بِاللَّيْلِ مِنْ أَدَمٍ، حَشْوُهَا لِيفٌ. وَفِي رِوَايَةٍ قَالَتْ: كَانَتْ ضِجْعَةُ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مِنْ أَدَمٍ، حَشْوُهَا لِيفٌ. (م,د,جه)', 'ആഇശ(റ): രാത്രിയിൽ നബി(സ) ഉറങ്ങിയിരുന്ന തലയിണ തോൽ കൊണ്ടുണ്ടാക്കിയതായിരുന്നു. അത് ചകിരിനാർ നിറച്ചതാണ്. മറ്റൊരു റിപ്പോർട്ടിൽ: ''വിസാദത്'' (തലയിണ) എന്ന പദത്തിന് പകരം ''ളിജ്അത്'' (കിടക്കുന്ന വിരി) എന്ന പദമാണുള്ളത്. (മു,ദ,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['م','د','جه']::text[], array['മു','ദ','ജ']::text[], null, null, 684, 684, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=71 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=8 and h.hadith_no=182), 1, 'وَفِي رِوَايَةٍ قَالَتْ: كَانَتْ ضِجْعَةُ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مِنْ أَدَمٍ، حَشْوُهَا لِيفٌ. (م,د,جه)', 'മറ്റൊരു നിവേദനിൽ: ''വിസാദത്'' (തലയിണ) എന്ന പദത്തിന് പകരം ''ളിജ്അത്'' (കിടക്കുന്ന വിരി) എന്ന പദമാണുള്ളത്. (മു,ദ,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 183, 'عَنْ أُمِّ سَلَمَةَ رَضِيَ اللهُ عَنْهُ قَالَتْ: كَانَ فِرَاشُهَا حِيَالَ مَسْجِدِ رَسُولِ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. (د,جه)', 'ഉമ്മു സലമ(റ): മഹതിയുടെ വിരിപ്പ് റസൂലുല്ലാഹി(സ)യുടെ പള്ളിയുടെ എതിർ വശത്തായിരുന്നു. (ദ,ജ)', 'أُمِّ سَلَمَةَ', 'ഉമ്മു സലമ(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 684, 684, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=71 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 184, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: إِنَّمَا كَانَ فِرَاشُ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الَّذِي يَنَامُ عَلَيْهِ مِنْ أَدَمٍ حَشْوُهُ لِيفٌ. حَسَنٌ صَحِيحٌ. (د,ت,جه)', 'ആഇശ(റ): നബി(സ) ഉറങ്ങിയിരുന്ന വിരിപ്പ് തോൽ കൊണ്ട് മാത്രമുള്ളതായിരുന്നു. അതിൽ നിറയെ ചകിരിനാരായിരുന്നു. (ദ,തു,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 685, 685, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=72 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 185, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَا يُصَلِّي فِي لُحُفِنَا، وفي رواية: مَلَاحِفِنَا. (ت)', 'ആഇശ(റ): റസൂലുല്ലാഹി(സ) ഞങ്ങളുടെ പുതപ്പിൽ നിസ്കരിക്കാറില്ലായിരുന്നു. മറ്റൊരു റിപ്പോർട്ടിൽ: ഞങ്ങളുടെ വിരിപ്പുകളിൽ. (തു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 685, 685, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=73 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=8 and h.hadith_no=185), 1, 'وَفِي رِوَايَةٍ: مَلَاحِفِنَا. (ت)', 'മറ്റൊരു നിവേദനിൽ: ഞങ്ങളുടെ വിരിപ്പുകളിൽ. (തു)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 186, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "أَيُّمَا إِهَابٍ دُبِغَ فَقَدْ طَهُرَ". (م,د,ت,ن,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂലുല്ലാഹി(സ) പറയുന്നത് ഞാൻ കേട്ടു: "ഏത് തോലാണെങ്കിലും ഊറക്കിടപ്പെട്ടാൽ തീർച്ചയായും അത് ശുദ്ധമാകും." (മു,ദ,തു,ന,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['م','د','ت','ن','جه']::text[], array['മു','ദ','തു','ന','ജ']::text[], null, null, 685, 685, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=74 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 187, 'عَنِ ابْنِ عَبَّاسٍ، عَنْ مَيْمُونَةَ رَضِيَ اللَّهُ عَنْهُمْ: أَنَّ شَاةً لِمَوْلَاةِ مَيْمُونَةَ مَرَّ بِهَا، يَعْنِي النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، قَدْ أُعْطِيَتْهَا مِنَ الصَّدَقَةِ، مَيْتَةً، فَقَالَ: "هَلَّا أَخَذُوا إِهَابَهَا فَدَبَغُوهُ، فَانْتَفَعُوا بِهِ". فَقَالُوا: يَا رَسُولَ اللَّهِ، إِنَّهَا مَيْتَةٌ؟ قَالَ: "إِنَّمَا حَرُمَ أَكْلُهَا". (م,د,ن,جه)', 'ഇബ്നുഅബ്ബാസ്(റ) മൈമൂന(റ)യിൽ നിന്നും നിവേദനം ചെയ്യുന്നു: മൈമൂന(റ)യുടെ ഭൃത്യയുടെ ചത്ത ആടിന്റെ അരികിലൂടെ നബി(സ) നടക്കുകയുണ്ടായി. ആ ആട് മഹതിക്ക് സദഖയായി നൽകപ്പെട്ടതായിരുന്നു. അപ്പോൾ അവിടന്ന് പറഞ്ഞു: "അവർക്കതിന്റെ തൊലിയെടുത്ത് ഊറക്കിട്ട് അതിന്റെ ഉപകാരമെടുത്തുകൂടേ?" അവർ ചോദിച്ചു: അല്ലാഹുവിന്റെ ദൂതരേ, അത് ശവമാണല്ലോ? അവിടന്നരുളി: "അതിനെ ഭക്ഷിക്കൽ മാത്രമാണ് നിഷിദ്ധമാക്കപ്പെട്ടത്." (മു,ദ,ന,ജ)', 'ابْنِ عَبَّاسٍ، عَنْ مَيْمُونَةَ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['م','د','ن','جه']::text[], array['മു','ദ','ന','ജ']::text[], null, null, 685, 685, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=74 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 188, 'عَنْ سَلْمَانَ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَانَ لِبَعْضِ أُمَّهَاتِ الْمُؤْمِنِينَ شَاةٌ، فَمَاتَتْ، فَمَرَّ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَيْهَا، فَقَالَ: "مَا ضَرَّ أَهْلَ هَذِهِ لَوْ انْتَفَعُوا بِإِهَابِهَا". فِي سنده ضعيف. (جه)', 'സൽമാൻ(റ): ഉമ്മഹാതുൽ മുഅ്മിനീങ്ങളിൽ ഒരു മഹതിയുടെ ആട് ചത്തു. തദവസരത്തിൽ നബി(സ) അതിന്നരികിലൂടെ നടക്കുകയുണ്ടായി. അപ്പോൾ അവിടന്ന് പറഞ്ഞു: "ഇതിന്റെ തോൽ കൊണ്ട് ഉപകാരമെടുത്തിരുന്നെങ്കിൽ ഇതിന്റെ ആളുകൾക്ക് ഒരു പ്രശ്നവുമില്ല."പരമ്പരയിൽ ബലഹീനനുണ്ട്.) (ജ)', 'سَلْمَانَ', 'സൽമാൻ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 685, 685, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=74 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 189, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: أَمَرَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنْ يُسْتَمْتَعَ بِجُلُودِ الْمَيْتَةِ إِذَا دُبِغَتْ. (د،ن،جه)', 'ആഇശ(റ): ജഡത്തോലുകൾ ഊറക്കിടപ്പെട്ടാൽ അത് കൊണ്ട് ഉപകാരമെടുക്കാൻ റസൂലുല്ലാഹി(സ) കൽപിച്ചിരിക്കുന്നു. (ദ,ന,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د','ن','جه']::text[], array['ദ','ന','ജ']::text[], null, null, 686, 686, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=74 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 190, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: مَاتَتْ شَاةٌ، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لِأَهْلِهَا: "أَلَّا نَزَعْتُمْ جِلْدَهَا، ثُمَّ دَبَغْتُمُوهُ فَاسْتَمْتَعْتُمْ بِهِ". حسن صحيح. (ق،د،ت،ن،جه)', 'ഇബ്നുഅബ്ബാസ്(റ): ഒരാട് ചത്തപ്പോൾ റസൂലുല്ലാഹി(സ) അതിന്റെ ആളുകളോട് പറഞ്ഞു: "നിങ്ങൾക്കതിന്റെ തോൽ ഉരിഞ്ഞ് പിന്നീട് അത് ഊറക്കിട്ട് ഉപകാരമെടുത്തുകൂടേ." (ബു,മു,ദ,തു,ന,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 686, 686, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=74 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 191, 'عَنْ سَلَمَةَ بْنِ الْمُحَبَّقِ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي غَزْوَةِ تَبُوكَ أَتَى عَلَى بَيْتٍ فَإِذَا قِرْبَةٌ مُعَلَّقَةٌ، فَسَأَلَ الْمَاءَ، فَقَالُوا: يَا رَسُولَ اللهِ، إِنَّهَا مَيْتَةٌ: فَقَالَ: "دِبَاغُهَا طَهُورُهَا". (د،ن)', 'സലമതുബ്നുൽ മുഹബ്ബഖ്(റ): തബൂക് യുദ്ധത്തിൽ റസൂലുല്ലാഹി(സ) ഒരു വീട്ടിൽ ചെന്നപ്പോൾ അവിടെ കെട്ടിത്തൂക്കപ്പെട്ട ഒരു തോൽപ്പാത്രമുണ്ടായിരുന്നു. റസൂലുല്ലാഹി(സ) വെള്ളം ചോദിച്ചു. അപ്പോഴവർ പറഞ്ഞു: അല്ലാഹുവിന്റെ ദൂതരേ, നിശ്ചയം അത് ശവമാണ്. അപ്പോൾ അവിടന്നരുളി: "അതിനെ ഊറക്കിടലാണ് അതിന്റെ ശുദ്ധീകരണം." (ദ,ന)', 'سَلَمَةَ بْنِ الْمُحَبَّقِ', 'സലമതുബ്നുൽ മുഹബ്ബഖ്(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 686, 686, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=74 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 192, 'عَنِ الْعَالِيَةِ بِنْتِ سُبَيْعٍ رَضِيَ اللهُ عَنْهَا أَنَّهَا قَالَتْ: كَانَ لِي غَنَمٌ بِأُحُدٍ، فَوَقَعَ فِيهَا الْمَوْتُ، فَدَخَلْتُ عَلَى مَيْمُونَةَ زَوْجِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَذَكَرْتُ ذَلِكَ لَهَا، فَقَالَتْ لِي مَيْمُونَةُ رَضِيَ اللهُ عَنْهَا: لَوْ أَخَذْتِ جُلُودَهَا فَانْتَفَعْتِ بِهَا، فَقَالَتْ: أَوْ يَحِلُّ ذَلِكَ؟ فَقَالَتْ: نَعَمْ، مَرَّ عَلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ رِجَالٌ مِنْ قُرَيْشٍ يَجُرُّونَ شَاةً لَهُمْ مِثْلَ الْحِمَارِ، فَقَالَ لَهُمْ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَوْ أَخَذْتُمْ إِهَابَهَا". قَالُوا: إِنَّهَا مَيْتَةٌ؟ فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "يُطَهِّرُهَا الْمَاءُ وَالْقَرَظُ". (د،ن)', 'ആലിയതു ബിൻത് സുബൈഅ്(റ): എനിക്ക് ഉഹ്ദിൽ കുറച്ച് ആടുകളുണ്ടായിരുന്നു. അവയിൽ കൂട്ടമരണം സംഭവിച്ചു. അങ്ങനെ ഞാൻ നബി(സ)യുടെ പത്നി മൈമൂന(റ)യുടെ അടുക്കൽ ചെന്നു. ഞാനക്കാര്യം മഹതിയെ അറിയിച്ചു. അപ്പോൾ എന്നോട് മൈമൂന(റ) പറഞ്ഞു: നീ അതിന്റെ തോലുകളെടുത്ത് ഉപകാരമെടുത്തിരുന്നെങ്കിൽ. അപ്പോൾ ആലിയ(റ) ചോദിച്ചു: അത് അനുവദനീയമാകുമോ? മഹതി പറഞ്ഞു: അതെ. കഴുതയെപ്പോലെ ആടിനെ വലിച്ച് കൊണ്ട് ഖുറൈശികളിലെ ചിലയാളുകൾ റസൂലുല്ലാഹി(സ)യുടെ അരികിലൂടെ കടന്ന് പോയപ്പോൾ അവരോട് റസൂലുല്ലാഹി(സ) പറഞ്ഞു: "നിങ്ങൾക്കതിന്റെ തോൽ എടുത്തു കൂടേ?" അവർ പറഞ്ഞു: അത് ശവമല്ലേ? അപ്പോൾ റസൂലുല്ലാഹി(സ) പറഞ്ഞു: "വെള്ളവും (ഊറക്കിടാൻ ഉപയോഗിക്കുന്ന) കൊന്നയിലയും അതിനെ ശുദ്ധീകരിക്കുന്നതാണ്." (ദ,ന)', 'الْعَالِيَةِ بِنْتِ سُبَيْعٍ', 'ആലിയതു ബിൻത് സുബൈഅ്(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 686, 686, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=74 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 193, 'عَنْ عَبْدِ اللهِ بْنِ عُكَيْمٍ قَالَ: قُرِئَ عَلَيْنَا كِتَابُ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِأَرْضِ جُهَيْنَةَ وَأَنَا غُلَامٌ شَابٌّ: "أَنْ لَا تَسْتَمْتِعُوا مِنَ الْمَيْتَةِ بِإِهَابٍ وَلَا عَصَبٍ". وفي رواية: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَتَبَ إِلَى جُهَيْنَةَ قَبْلَ مَوْتِهِ بِشَهْرٍ أَنْ: "لَا تَنْتَفِعُوا مِنَ الْمَيْتَةِ بِإِهَابٍ وَلَا عَصَبٍ". (د،ت،ن،جه)', 'അബ്ദുല്ലാഹിബ്നു ഉകൈം(റ): ഞാൻ യുവാവായിരിക്കെ, ജുഹൈനയിൽ വെച്ച്, റസൂലുല്ലാഹി(സ)യുടെ എഴുത്ത് ഞങ്ങൾക്കായി വായിക്കപ്പെട്ടു: "ജഡത്തിന്റെ തോലുകൊണ്ടും ഞരമ്പ് കൊണ്ടും നിങ്ങൾ ഉപകാരമെടുക്കരുത്." മറ്റൊരു നിവേദനം: തന്റെ മരണത്തിന്റെ ഒരു മാസം മുമ്പ് ജുഹൈനയിലേക്ക് റസൂലുല്ലാഹി(സ) എഴുതി: "ജഡത്തിന്റെ തോൽ കൊണ്ടും ഞരമ്പ് കൊണ്ടും നിങ്ങൾ ഉപകാരമെടുക്കരുത്." (ദ,തു,ന,ജ)', 'عَبْدِ اللهِ بْنِ عُكَيْمٍ قَالَ', 'അബ്ദുല്ലാഹിബ്നു ഉകൈം(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 686, 687, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=75 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=8 and h.hadith_no=193), 1, 'وَفِي رِوَايَةٍ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَتَبَ إِلَى جُهَيْنَةَ قَبْلَ مَوْتِهِ بِشَهْرٍ أَنْ: "لَا تَنْتَفِعُوا مِنَ الْمَيْتَةِ بِإِهَابٍ وَلَا عَصَبٍ". (د،ت،ن،جه)', 'മറ്റൊരു നിവേദനം: തന്റെ മരണത്തിന്റെ ഒരു മാസം മുമ്പ് ജുഹൈനയിലേക്ക് റസൂലുല്ലാഹി(സ) എഴുതി: "ജഡത്തിന്റെ തോൽ കൊണ്ടും ഞരമ്പ് കൊണ്ടും നിങ്ങൾ ഉപകാരമെടുക്കരുത്." (ദ,തു,ന,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 194, 'عَنْ أُسَامَةَ بْنِ عُمَيْرِ بْنِ عَامِرٍ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنْ جُلُودِ السِّبَاعِ أَنْ تُفْتَرَشَ. (د،ت،ن)', 'ഉസാമതുബ്നു ഉമൈരിബ്നി ആമിർ(റ): നിശ്ചയം പിടിമൃഗത്തോൽ (കിടക്കാനുള്ള) വിരിപ്പാക്കുന്നത് നബി(സ) വിലക്കിയിരിക്കുന്നു. (ദ,തു,ന)', 'أُسَامَةَ بْنِ عُمَيْرِ بْنِ عَامِرٍ', 'ഉസാമതുബ്നു ഉമൈരിബ്നി ആമിർ(റ)', null, null, array['د','ت','ن']::text[], array['ദ','തു','ന']::text[], null, null, 687, 687, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=76 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 195, 'عَنْ سَلْمَانَ قَالَ: سُئِلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ السَّمْنِ وَالْجُبْنِ وَالْفِرَاءِ. فَقَالَ: "الْحَلَالُ مَا أَحَلَّ اللَّهُ فِي كِتَابِهِ، وَالْحَرَامُ مَا حَرَّمَ اللَّهُ فِي كِتَابِهِ، وَمَا سَكَتَ عَنْهُ فَهُوَ مِمَّا عَفَا عَنْهُ". (ت،جه)', 'സൽമാൻ(റ): നബി(സ)യോട് നെയ്യിനെക്കുറിച്ചും പാൽക്കട്ടിയെക്കുറിച്ചും രോമവസ്ത്രത്തെക്കുറിച്ചും ചോദിക്കപ്പെട്ടു. അപ്പോൾ അവിടന്നരുളി: "അല്ലാഹു തന്റെ കിതാബിൽ അനുവദനീയമാക്കിയവയാണ് ഹലാൽ. അല്ലാഹു തന്റെ കിതാബിൽ നിഷിദ്ധമാക്കിയതാണ് ഹറാം. അല്ലാഹു പ്രതിപാദിക്കാത്തത് അവൻ പൊറുക്കുന്നതാണ്." (തു,ജ)', 'سَلْمَانَ قَالَ', 'സൽമാൻ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 687, 687, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=77 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 196, 'عَنْ مُعَاوِيَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَا تَرْكَبُوا الْخَزَّ، وَلَا النِّمَارَ". (د،جه)', 'മുആവിയ (റ): റസൂലുല്ലാഹി(സ) പറഞ്ഞു: "പട്ട് കൊണ്ടോ പുലിത്തോൽ കൊണ്ടോ നിർമിച്ച ജീനിയിൽ നിങ്ങൾ യാത്രചെയ്യരുത്." (ദ,ജ)', 'مُعَاوِيَةَ', 'മുആവിയ (റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 687, 687, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=77 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 197, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا تَصْحَبُ الْمَلَائِكَةُ رُفْقَةً فِيهَا جِلْدُ نَمِرٍ". (د،جه)', 'അബൂഹുറൈറ(റ): നബി(സ) പറയുന്നു: "പുലിത്തോൽ ഉപയോഗിക്കുന്ന കൂട്ടരോട് മലക്കുകൾ സഹവസിക്കില്ല." (ദ,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 687, 687, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=77 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 198, 'عَنْ خَالِدِ بْنِ مَعْدَانَ رَضِيَ اللهُ عَنْهُ قَالَ: وَفَدَ الْمِقْدَامُ بْنُ مَعْدِي كَرِبَ وَعَمْرُو بْنُ الْأَسْوَدِ وَرَجُلٌ مِنْ بَنِي أَسَدٍ - مِنْ أَهْلِ قِنَّسْرِينَ - إِلَى مُعَاوِيَةَ بْنِ أَبِي سُفْيَانَ رَضِيَ الله عَنْهُ، فَقَالَ مُعَاوِيَةُ لِلْمِقْدَامِ: أَعَلِمْتَ أَنَّ الْحَسَنَ بْنَ عَلِيٍّ تُوُفِّيَ؟ فَرَجَّعَ الْمِقْدَامُ، فَقَالَ لَهُ رَجُلٌ: أَتَرَاهَا مُصِيبَةً؟ قَالَ لَهُ: وَلِمَ لَا أَرَاهَا مُصِيبَةً، وَقَدْ وَضَعَهُ رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي حِجْرِهِ فَقَالَ: "هَذَا مِنِّي وَحُسَيْنٌ مِنْ عَلِيٍّ". فَقَالَ الْأَسَدِيُّ: جَمْرَةٌ أَطْفَأَهَا اللَّهُ عَزَّ وَجَلَّ. فَقَالَ الْمِقْدَامُ: أَمَّا أَنَا فَلَا أَبْرَحُ الْيَوْمَ حَتَّى أُغِيظَكَ وَأُسْمِعَكَ مَا تَكْرَهُ، ثُمَّ قَالَ: يَا مُعَاوِيَةُ، إِنْ أَنَا صَدَقْتُ فَصَدِّقْنِي، وَإِنْ أَنَا كَذَبْتُ فَكَذِّبْنِي. قَالَ: أَفْعَلُ، قَالَ: فَأَنْشُدُكَ بِاللَّهِ: هَلْ تَعْلَمُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنْ لُبْسِ الذَّهَبِ؟ قَالَ: نَعَمْ، قَالَ: فَأَنْشُدُكَ بِاللَّهِ: هَلْ تَعْلَمُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنْ لُبْسِ الْحَرِيرِ؟ قَالَ: نَعَمْ، قَالَ: فَأَنْشُدُكَ بِاللَّهِ: هَلْ تَعْلَمُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنْ لُبْسِ جُلُودِ السِّبَاعِ وَالرُّكُوبِ عَلَيْهَا؟ قَالَ: نَعَمْ، قَالَ: فَوَاللَّهِ لَقَدْ رَأَيْتُ هَذَا كُلَّهُ فِي بَيْتِكَ يَا مُعَاوِيَةُ. فَقَالَ مُعَاوِيَةُ: قَدْ عَلِمْتُ أَنِّي لَنْ أَنْجُوَ مِنْكَ يَا مِقْدَامُ. قَالَ خَالِدٌ: فَأَمَرَ لَهُ مُعَاوِيَةُ بِمَا لَمْ يَأْمُرْ لِصَاحِبَيْهِ، وَفَرَضَ لِابْنِهِ فِي الْمِائَتَيْنِ، فَفَرَّقَهَا الْمِقْدَامُ فِي أَصْحَابِهِ، قَالَ: وَلَمْ يُعْطِ الْأَسَدِيُّ أَحَدًا شَيْئًا مِمَّا أَخَذَ، فَبَلَغَ ذَلِكَ مُعَاوِيَةَ، فَقَالَ: أَمَّا الْمِقْدَامُ فَرَجُلٌ كَرِيمٌ بَسَطَ يَدَهُ، وَأَمَّا الْأَسَدِيُّ فَرَجُلٌ حَسَنُ الْإِمْسَاكِ لِشَيْئِهِ. (د،ن)', 'ഖാലിദുബ്നു മിഅ്ദാൻ(റ): ഖിന്നസ്രീനുകാരിൽപ്പെട്ട മിഖ്ദാമുബ്നു മഅ്ദീകരിബ(റ)വും അംറുബ്നുൽ അസ്വദും ബനൂഅസദിൽപ്പെട്ട ഒരാളും മുആവിയതുബ്നു അബൂസുഫ്‌യാൻ(റ)വിനടുത്തേക്ക് സംഘമായി പുറപ്പെട്ടു. അപ്പോൾ മുആവിയ(റ) മിഖ്ദാം(റ)വിനോട് ചോദിച്ചു: ഹസനുബ്നു അലി(റ) വഫാത്തായത് നീ അറിഞ്ഞോ? അപ്പോൾ മിഖ്ദാം(റ), ''ഇന്നാലില്ലാഹി വഇന്നാ ഇലൈഹി റാജിഊൻ'' എന്ന് ചൊല്ലി. അപ്പോൾ അദ്ദേഹത്തോട് ഒരാൾ ചോദിച്ചു: താങ്കളിതിനെ ഒരു വിപത്തായാണോ കാണുന്നത്? അദ്ദേഹം അയാളോട് പറഞ്ഞു: ഞാനെന്തുകൊണ്ട് അതൊരു വിപത്തായി കാണാതിരിക്കും? തീർച്ചയായും റസൂലുല്ലാഹി(സ) അദ്ദേഹത്തെ മടിയിലിരുത്തിക്കൊണ്ട് പറഞ്ഞു: "ഇവൻ എന്നിൽ നിന്നും ഹുസൈൻ അലിയിൽ നിന്നുമാണ്." അപ്പോൾ അസദ് ഗോത്രക്കാരൻ പറഞ്ഞു: അല്ലാഹു അണച്ചുകളഞ്ഞ ഒരു തീക്കട്ടയാണദ്ദേഹം. അപ്പോൾ മിഖ്ദാം(റ) പറഞ്ഞു: ഇനി അങ്ങയെ ദേഷ്യം പിടിപ്പിക്കുന്നതും കേൾക്കാൻ വെറുക്കുന്നതുമായ ചില കാര്യങ്ങൾ ഞാൻ നിങ്ങളെ കേൾപ്പിക്കാം. എന്നിട്ട് പറഞ്ഞു: ഓ മുആവിയ, ഞാൻ സത്യമാണ് പറയുന്നതെങ്കിൽ താങ്കളെന്നെ സത്യമാക്കുക. ഞാൻ കളവാണ് പറയുന്നതെങ്കിൽ താങ്കളെന്നെ കളവാക്കുക. അദ്ദേഹം പറഞ്ഞു: ഞാൻ അപ്രകാരം ചെയ്യാം. മിഖ്ദാം(റ) പറഞ്ഞു: എന്നാൽ ഞാൻ അല്ലാഹുവിനെക്കൊണ്ട് താങ്കളോട് സത്യം ചെയ്യുന്നു, റസൂലുല്ലാഹി(സ) സ്വർണ്ണം ധരിക്കൽ നിരോധിച്ചതായി താങ്കൾക്കറിയാമോ? മുആവിയ പറഞ്ഞു: അതെ. മിഖ്ദാം(റ) പറഞ്ഞു: ഇനി, ഞാൻ അല്ലാഹുവിനെക്കൊണ്ട് താങ്കളോട് സത്യം ചെയ്യുന്നു, റസൂലുല്ലാഹി(സ) പട്ട് ധരിക്കുന്നത് നിരോധിച്ചതായി താങ്കൾക്കറിയാമോ? അദ്ദേഹം പറഞ്ഞു: അതെ. മിഖ്ദാം(റ) പറഞ്ഞു: ഇനി, ഞാൻ താങ്കളോട് അല്ലാഹുവിനെക്കൊണ്ട് സത്യം ചെയ്യുന്നു, പിടിമൃഗത്തിന്റെ തോൽ ധരിക്കലും അവയുടെ മേൽ യാത്ര ചെയ്യലും റസൂലുല്ലാഹി(സ) നിരോധിച്ചത് താങ്കൾക്കറിയാമോ? അദ്ദേഹം പറഞ്ഞു: അതെ. മിഖ്ദാം(റ) തുടർന്നു: എന്നാൽ ഞാൻ അല്ലാഹുവിനെക്കൊണ്ട് സത്യം ചെയ്യുന്നു, തീർച്ചയായും ഞാനിവയെല്ലാം താങ്കളുടെ വീട്ടിൽ കണ്ടിട്ടുണ്ട്. അപ്പോൾ മുആവിയ(റ) പറഞ്ഞു: മിഖ്ദാം, തീർച്ചയായും താങ്കളിൽ നിന്ന് ഞാൻ രക്ഷപ്പെടില്ലെന്ന് ഞാൻ മനസ്സിലാക്കുന്നു. ഖാലിദ്(റ) പറഞ്ഞു: അപ്പോൾ തന്റെ രണ്ട് കൂട്ടുകാർക്ക് നൽകാത്ത ചിലത് മുആവിയ(റ) അദ്ദേഹത്തിന് നൽകാൻ കൽപിച്ചു. മുആവിയ(റ) അദ്ദേഹത്തിന്റെ മകന് ഇരുനൂറ് (എന്തോ) നൽകാൻ ഉത്തരവിട്ടു. മിഖ്ദാം(റ) അത് തന്റെ അനുചരർക്കിടയിൽ വീതിച്ചുകൊടുത്തു. നിവേദകൻ പറയുന്നു: അസദ് ഗോത്രക്കാരൻ തനിക്ക് കിട്ടിയതിൽ നിന്ന് ഒന്നും ആർക്കും നൽകിയില്ല. ഈ വിവരം മുആവിയ(റ)വിന്റെ അടുക്കലെത്തിയപ്പോൾ അദ്ദേഹം പറഞ്ഞു: മിഖ്ദാം(റ) ധർമ്മിഷ്ഠനും മാന്യനുമാണ്. അസദിയാകട്ടെ, തന്റെ വസ്തുക്കളെ നന്നായി സൂക്ഷിച്ച് വെക്കുന്ന ഒരാളാണ്. (ദ,ന)', 'خَالِدِ بْنِ مَعْدَانَ', 'ഖാലിദുബ്നു മിഅ്ദാൻ(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 687, 688, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=77 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 199, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: قَالَ لِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِذَا أَرَدْتِ اللُّحُوقَ بِي فَلْيَكْفِكِ مِنَ الدُّنْيَا كَزَادِ الرَّاكِبِ، وَإِيَّاكِ وَمُجَالَسَةَ الْأَغْنِيَاءِ، وَلَا تَسْتَخْلِقِي ثَوْبًا حَتَّى تُرَقِّعِيهِ". (ت)', 'ആഇശ(റ): എന്നോട് റസൂലുല്ലാഹി(സ) പറഞ്ഞു: "നീ എന്നോട് ചേരാൻ ആഗ്രഹിക്കുന്നുവെങ്കിൽ നിനക്ക് ദുൻയാവിൽ നിന്ന് ഒരു യാത്രികന്റെ പാഥേയത്തോളം (മാത്രം) മതി. ധനികരോട് സഹവസിക്കുന്നത് നീ സൂക്ഷിക്കണം. ഒരു വസ്ത്രവും നീ കഷ്ണം വെക്കുംവരെ ദ്രവിപ്പിക്കരുത്." (തു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 689, 689, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=78 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 200, 'عَنِ الْبَرَاءِ بْنِ عَازِبٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: نَهَانَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ رُكُوبِ الْمَيَاثِرِ. حَسَنٌ صَحِيحٌ. (ق،ت،ن،جه)', 'ബറാഉബ്നു ആസിബ്(റ): ഇരപിടിക്കുന്ന മൃഗങ്ങളിൽ സവാരി നടത്തൽ ഞങ്ങളോട് റസൂലുല്ലാഹി(സ) നിരോധിച്ചിരിക്കുന്നു. ഹദീസ് ഹസനാണ് (ബു,മു,തു,ന,ജ)', 'الْبَرَاءِ بْنِ عَازِبٍ', 'ബറാഉബ്നു ആസിബ്(റ)', null, null, array['ق','ت','ن','جه']::text[], array['ബു','മു','തു','ന','ജ']::text[], null, null, 689, 689, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=78 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 201, 'عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَتَى فَاطِمَةَ رَضِيَ الله عَنْهَا، فَوَجَدَ عَلَى بَابِهَا سِتْرًا، فَلَمْ يَدْخُلْ، قَالَ: وَقَلَّمَا كَانَ يَدْخُلُ إِلَّا بَدَأَ بِهَا، فَجَاءَ عَلِيٌّ رَضِيَ الله عَنْهُ فَرَآهَا مُهْتَمَّةً، فَقَالَ: مَا لَكِ؟ قَالَتْ: جَاءَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَيَّ فَلَمْ يَدْخُلْ، فَأَتَاهُ عَلِيٌّ رَضِيَ الله عَنْهُ فَقَالَ: يَا رَسُولَ اللَّهِ، إِنَّ فَاطِمَةَ اشْتَدَّ عَلَيْهَا أَنَّكَ جِئْتَهَا فَلَمْ تَدْخُلْ عَلَيْهَا؟ قَالَ: "وَمَا أَنَا وَالدُّنْيَا؟ وَمَا أَنَا وَالرَّقْمَ". فَذَهَبَ إِلَى فَاطِمَةَ فَأَخْبَرَهَا بِقَوْلِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَتْ: قُلْ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَا يَأْمُرُنِي بِهِ؟ قَالَ: "قُلْ لَهَا فَلْتُرْسِلْ بِهِ إِلَى بَنِي فُلَانٍ". وَفِي رِوَايَةٍ: وَكَانَ سِتْرًا مَوْشِيًّا. (د)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): റസൂലുല്ലാഹി(സ) ഒരിക്കൽ ഫാതിമ(റ)യുടെ അടുത്ത് ചെന്നപ്പോൾ മഹതിയുടെ വാതിലിൽ ഒരു മറ(വിരി) കണ്ടു. അതിനാൽ അവിടുന്ന് അകത്തേക്ക് കടന്നില്ല. നിവേദകൻ പറയുന്നു: റസൂലുല്ലാഹി(സ) മഹതിയുടെ കാര്യത്തിലിടപെട്ടു കൊണ്ടല്ലാതെ അവിടെ കടന്നുവരൽ വളരെ വിരളമായിരുന്നു. അപ്പോൾ അലി(റ) വന്നു, അദ്ദേഹം മഹതിയെ ദുഃഖിതയായിക്കണ്ടു. അലി (റ) ചോദിച്ചു: നിനക്ക് എന്തു പറ്റി? മഹതി പറഞ്ഞു: നബി(സ) എന്റെ അടുത്ത് വന്നു, പക്ഷേ, അകത്ത് കടന്നില്ല. അപ്പോൾ അലി(റ) നബി(സ)യുടെ അടുക്കൽ ചെന്ന് പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, അവിടുന്ന് ഫാതിമയുടെ അടുത്തുവന്ന് അകത്ത് കയറാതിരുന്നത് തീർച്ചയായും അവർക്ക് വിഷമമായിരിക്കുന്നു. അവിടുന്ന് അരുളി: "ഞാനും ദുൻയാവും എന്താണ് ബന്ധം? ഞാനും വർണ്ണങ്ങളും രൂപങ്ങളുമുള്ള വസ്ത്രവും എന്താണ് ബന്ധം" ഉടനെ അലി(റ) ഫാതിമ(റ)യുടെ അടുത്തുചെന്ന് റസൂലുല്ലാഹി(സ) പറഞ്ഞതെല്ലാം പറഞ്ഞുകൊടുത്തു. അപ്പോൾ മഹതി പറഞ്ഞു: റസൂലുല്ലാഹി(സ)യോട് അവിടുന്നെന്നോട് എന്താണ് കൽപിക്കുന്നത് എന്ന് ചോദിക്കുക. അവിടുന്ന് അരുളി: "നിങ്ങളവളോട് പറയുക: അവളത് ഇന്നാലിന്ന കുടുംബത്തിലേക്ക് അയച്ചു കൊള്ളട്ടെ."
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=8 and h.hadith_no=201), 1, 'وَفِي رِوَايَةٍ: وَكَانَ سِتْرًا مَوْشِيًّا. (د)', 'മറ്റൊരു നിവേദനം: അത് ചിത്രങ്ങൾ കൊണ്ടലങ്കരിച്ച വിരിയായിരുന്നു. (ദ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 202, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ اضْطَجَعَ عَلَى نِطْعٍ فَعَرِقَ، فَقَامَتْ أُمُّ سُلَيْمٍ إِلَى عَرَقِهِ فَنَشَّفَتْهُ فَجَعَلَتْهُ فِي قَارُورَةٍ، فَرَآهَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَا هَذَا الَّذِي تَصْنَعِينَ يَا أُمَّ سُلَيْمٍ". قَالَتْ: أَجْعَلُ عَرَقَكَ فِي طِيبِي. فَضَحِكَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. (ن)', 'അനസുബ്നു മാലിക്(റ): നബി(സ) ഒരു തോൽ വിരിപ്പിൽ കിടന്നുറങ്ങി, അങ്ങനെ അവിടുന്ന് വിയർത്തു. അപ്പോൾ ഉമ്മുസുലൈം(റ) വന്ന് അവിടുത്തെ വിയർപ്പ് ഒപ്പിയെടുത്ത് അതൊപ്പിയെടുത്ത് ഒരു കുപ്പിയിലാക്കി. അപ്പോൾ നബി(സ) മഹതിയെക്കണ്ടു. അവിടുന്ന് പറഞ്ഞു: "എന്താണ് നീ ഈ ചെയ്യുന്നത്, ഉമ്മുസുലൈം" മഹതി പറഞ്ഞു: ഞാൻ അങ്ങയുടെ വിയർപ്പ് എന്റെ സുഗന്ധത്തിലാക്കുകയാണ്. അപ്പോൾ നബി(സ) ചിരിച്ചു. (ന)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 690, 690, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=80 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 203, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ لَا يَتْرُكُ فِي بَيْتِهِ شَيْئًا فِيهِ تَصْلِيبٌ إِلَّا قَضَبَهُ. (خ،د)', 'ആഇശ(റ): റസൂലുല്ലാഹി(സ) കുരിശടയാളമുള്ള ഒരു വസ്തുവും തങ്ങളുടെ വീട്ടിൽ കഷ്ണങ്ങളായി മുറിച്ചിട്ടല്ലാതെ ഒഴിവാക്കിയിട്ടില്ല. (ബു,ദ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['خ','د']::text[], array['ബു','ദ']::text[], null, null, 690, 690, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=81 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 204, 'عَنْ أَبِي كَبْشَةَ الْأَنْمَارِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَانَتْ كِمَامُ أَصْحَابِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بُطْحًا. منكر. (ت)', 'അബൂകബ്ശത്തുൽ അൻമാരി(റ): റസൂലുല്ലാഹി(സ)യുടെ അനുയായികളുടെ വട്ടത്തൊപ്പി തലക്ക് മേൽ വിശാലമായി കിടക്കുന്നതായിരുന്നു (ഉയർന്നതല്ലായിരുന്നു). ഹദീസ് മുൻകറാണ്. (തു)', 'أَبِي كَبْشَةَ الْأَنْمَارِيِّ', 'അബൂകബ്ശത്തുൽ അൻമാരി(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 690, 690, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=82 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 205, 'عَنْ أَسْمَاءَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: جَاءَتِ امْرَأَةٌ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَتْ: إِنَّ لِي ضَرَّةً، فَهَلْ عَلَيَّ جُنَاحٌ أَنْ أَتَشَبَّعَ مِنْ مَالِ زَوْجِي بِمَا لَمْ يُعْطِنِي؟ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "الْمُتَشَبِّعُ بِمَا لَمْ يُعْطَ كَلَابِسِ ثَوْبَيْ زُورٍ". (ن)', 'അസ്മാഅ്(റ): ഒരു സ്ത്രീ നബി(സ)യുടെ അടുക്കൽ വന്നു പറഞ്ഞു: "നിശ്ചയം എനിക്കൊരു സഹകളത്രം (സഹഭാര്യ) ഉണ്ട്. അതിനാൽ എനിക്ക് ഭർത്താവ് നൽകാത്തതു കാരണം അദ്ദേഹത്തിന്റെ സമ്പത്തിൽ നിന്ന് ഞാൻ വയർ നിറക്കുന്നതിൽ വല്ല കുഴപ്പവുമുണ്ടോ? അപ്പോൾ റസൂലുല്ലാഹി(സ) പറഞ്ഞു: "നൽകപ്പെടാത്തതുകൊണ്ട് വയർ നിറക്കുന്നവൻ രണ്ട് കള്ളവസ്ത്രങ്ങൾ ധരിച്ചവനെപ്പോലെയാണ്." (ന)', 'أَسْمَاءَ', 'അസ്മാഅ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 690, 691, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=83 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 206, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا، عَنْ أَبِي طَلْحَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا تَدْخُلُ الْمَلَائِكَةُ بَيْتًا فِيهِ كَلْبٌ وَلَا صُورَةٌ". وفي رواية: "وَلَا صُورَةُ تَمَاثِيلَ". (ن)', 'ഇബ്നുഅബ്ബാസ്(റ) അബൂത്വൽഹ(റ)വിൽ നിന്ന് നിവേദനം ചെയ്യുന്നു: നബി(സ) പറഞ്ഞു: "നായയോ രൂപങ്ങളോ ഉള്ള ഒരു വീട്ടിലും മലക്കുകൾ പ്രവേശിക്കുകയില്ല."
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=8 and h.hadith_no=206), 1, 'وَفِي رِوَايَةٍ: "وَلَا صُورَةُ تَمَاثِيلَ". (ن)', 'മറ്റൊരു നിവേദനം: "പ്രതിമകളുടെ രൂപങ്ങളും." (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 207, 'عَنْ عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ عُتْبَةَ رَضِيَ اللهُ عَنْهُ: أَنَّهُ دَخَلَ عَلَى أَبِي طَلْحَةَ الأَنْصَارِيِّ - رَضِيَ اللهُ عَنْهُ - يَعُودُهُ، فَوَجَدَ عِنْدَهُ سَهْلَ بْنَ حُنَيْفٍ، فَأَمَرَ أَبُو طَلْحَةَ إِنْسَانًا يَنْزِعُ نَمَطًا تَحْتَهُ، فَقَالَ لَهُ سَهْلٌ: لِمَ تَنْزِعُ؟ قَالَ: لِأَنَّ فِيهِ تَصَاوِيرَ، وَقَدْ قَالَ فِيهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَا قَدْ عَلِمْتَ. قَالَ: أَلَمْ يَقُلْ: "إِلَّا مَا كَانَ رَقْمًا فِي ثَوْبٍ". قَالَ: بَلَى، وَلَكِنَّهُ أَطْيَبُ لِنَفْسِي. (ن)', 'ഉബൈദുല്ലാഹിബ്നു അബ്ദില്ലാഹിബ്നി ഉത്ബ(റ): അദ്ദേഹം അബൂത്വൽഹത്തുൽ അൻസാരി(റ)വിന്റെ അടുക്കൽ രോഗസന്ദർശനത്തിനായി വന്നു. അപ്പോൾ അദ്ദേഹത്തിന്റെയടുക്കൽ സഹ്‌ലുബ്നു ഹുനൈഫ്(റ)വിനെ കണ്ടു. അപ്പോൾ തന്റെ താഴെയുള്ള ജീനിത്തുണി അഴിക്കാൻ ഒരു മനുഷ്യനോട് അബൂത്വൽഹ(റ) കൽപിച്ചു. അപ്പോൾ അദ്ദേഹത്തോട് സഹ്‌ല്(റ) പറഞ്ഞു: എന്തിനാണ് താങ്കളത് അഴിക്കുന്നത്? അദ്ദേഹം പറഞ്ഞു: കാരണം, അതിൽ ചിത്രങ്ങളുണ്ട്. അതേക്കുറിച്ച് റസൂലുല്ലാഹി(സ) താങ്കൾക്കറിയാവുന്ന ഒരു കാര്യം തീർച്ചയായും പറഞ്ഞിട്ടുണ്ട്. സഹ്‌ല് പറഞ്ഞു: "വസ്ത്രത്തിൽ വർണ്ണമായിട്ടുള്ളവയൊഴികെ" എന്ന് അവിടന്ന് അരുളിയില്ലേ? അബൂത്വൽഹ(റ) പറഞ്ഞു: അതെ, പക്ഷെ എനിക്കതാണ് ഏറ്റവും സംതൃപ്തിയായത്. (ന)', 'عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ عُتْبَةَ', 'ഉബൈദുല്ലാഹിബ്നു അബ്ദില്ലാഹിബ്നി ഉത്ബ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 691, 691, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=84 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 208, 'عَنْ عَلِيٍّ رَضِيَ اللَّهُ عَنْهُ قَالَ: صَنَعْتُ طَعَامًا، فَدَعَوْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَجَاءَ فَدَخَلَ، فَرَأَى سِتْرًا فِيهِ تَصَاوِيرُ فَخَرَجَ، وَقَالَ: "إِنَّ الْمَلَائِكَةَ لَا تَدْخُلُ بَيْتًا فِيهِ تَصَاوِيرُ". (ن)', 'അലി(റ): ഞാനൊരു ഭക്ഷണം ഉണ്ടാക്കി. നബി(സ)യെ അതിന് ക്ഷണിച്ചു. അങ്ങനെ അവിടന്ന് വന്നു. അകത്ത് കടന്നപ്പോൾ ചിത്രരൂപങ്ങളുള്ള ഒരുവിരി കണ്ടു. ഉടനെ അവിടെ നിന്നിറങ്ങി. എന്നിട്ട് പറഞ്ഞു: "ചിത്രരൂപങ്ങളുള്ള ഒരു വീട്ടിലും മലക്കുകൾ കടക്കുകയില്ല." (ന)', 'عَلِيٍّ', 'അലി(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 691, 691, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=84 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 209, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: خَرَجَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَرْجَةً، ثُمَّ دَخَلَ وَقَدْ عَلَّقْتُ قِرَامًا فِيهِ الْخَيْلُ أُولَاتُ الْأَجْنِحَةِ، قَالَتْ: فَلَمَّا رَآهُ قَالَ: "انْزِعِيهِ". وفي رواية قَالَتْ: كَانَ لَنَا سِتْرٌ فِيهِ تِمْثَالُ طَيْرٍ، مُسْتَقْبِلَ الْبَيْتِ إِذَا دَخَلَ الدَّاخِلُ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "يَا عَائِشَةُ، حَوِّلِيهِ، فَإِنِّي كُلَّمَا دَخَلْتُ فَرَأَيْتُهُ ذَكَرْتُ الدُّنْيَا". قَالَتْ: وَكَانَ لَنَا قَطِيفَةٌ لَهَا عَلَمٌ، فَكُنَّا نَلْبَسُهَا فَلَمْ نَقْطَعْهُ. وَفِي رِوَايَةٍ قَالَتْ: كَانَ فِي بَيْتِي ثَوْبٌ فِيهِ تَصَاوِيرُ، فَجَعَلْتُهُ إِلَى سَهْوَةٍ فِي الْبَيْتِ، فَكَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي إِلَيْهِ، ثُمَّ قَالَ: "يَا عَائِشَةُ، أَخِّرِيهِ عَنِّي". فَنَزَعْتُهُ فَجَعَلْتُهُ وَسَائِدَ. وَفِي رِوَايَةٍ: أَنَّهَا نَصَبَتْ سِتْرًا فِيهِ تَصَاوِيرُ، فَدَخَلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَنَزَعَهُ، فَقَطَّعَتْهُ وِسَادَتَيْنِ، وَفِي رِوَايَةٍ قَالَتْ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَرْتَفِقُ عَلَيْهِمَا. (ن)', 'ആഇശ(റ): റസൂലുല്ലാഹി(സ) ഒരു പോക്ക് പോയി. പിന്നീട് കടന്നു വന്നു. ചിറകുള്ള കുതിരകളുടെ ചിത്രമുള്ള ഒരു ചുവന്ന വിരി ഞാൻ കെട്ടിത്തൂക്കിയിരുന്നു. മഹതി പറഞ്ഞു: അത് കണ്ടപ്പോൾ തിരുമേനി(സ) പറഞ്ഞു: "അത് അഴിക്കൂ." മറ്റൊരു ഉദ്ധരണിയിൽ: മഹതി പറയുന്നു: വീട്ടിൽ കടക്കുന്നവനഭിമുഖമായി പക്ഷികളുടെ ചിത്രങ്ങളുള്ള ഒരു വിരി ഞങ്ങൾക്കുണ്ടായിരുന്നു. അപ്പോൾ റസൂലുല്ലാഹി(സ) പറഞ്ഞു: "ആഇശാ, അതഴിക്കൂ. കാരണം ഞാൻ ഇവിടെ കടന്നുവന്ന് ഇത് കാണുമ്പോഴൊക്കെ ദുൻയാവിനെ ഓർക്കുകയുണ്ടായി." മഹതി പറയുന്നു: കുറിയുള്ള ഒരു വില്ലൂസ്(വെൽവെറ്റ്) പട്ടിൻ വസ്ത്രം ഉണ്ടായിരുന്നു, ഞങ്ങൾത് ധരിക്കാറുണ്ടായിരുന്നു. ഞങ്ങൾത് മുറിച്ചുകളഞ്ഞില്ല.
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=8 and h.hadith_no=209), 1, 'وَفِي رِوَايَةٍ قَالَتْ: كَانَ لَنَا سِتْرٌ فِيهِ تِمْثَالُ طَيْرٍ، مُسْتَقْبِلَ الْبَيْتِ إِذَا دَخَلَ الدَّاخِلُ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "يَا عَائِشَةُ، حَوِّلِيهِ، فَإِنِّي كُلَّمَا دَخَلْتُ فَرَأَيْتُهُ ذَكَرْتُ الدُّنْيَا". قَالَتْ: وَكَانَ لَنَا قَطِيفَةٌ لَهَا عَلَمٌ، فَكُنَّا نَلْبَسُهَا فَلَمْ نَقْطَعْهُ.', 'മറ്റൊരു നിവേദനം: മഹതി പറഞ്ഞു: എന്റെ വീട്ടിൽ ചിത്രങ്ങളുള്ള ഒരു വസ്ത്രം ഉണ്ടായിരുന്നു. ഞാനതിനെ വീടിന്റെ മുൻവശത്തുള്ള മറയാക്കി. റസൂലുല്ലാഹി(സ) അതിലേക്ക് തിരിഞ്ഞ് നിസ്കരിക്കാറുണ്ടായിരുന്നു. പിന്നീടവിടന്ന് പറഞ്ഞു: "ഓ, ആഇശാ, എന്റെ മുമ്പിൽ നിന്നത് അഴിച്ചുമാറ്റൂ." അപ്പോൾ ഞാനത് അഴിച്ചു. അങ്ങനെ അത് തലയണകളാക്കി.');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=8 and h.hadith_no=209), 2, 'وَفِي رِوَايَةٍ قَالَتْ: كَانَ فِي بَيْتِي ثَوْبٌ فِيهِ تَصَاوِيرُ، فَجَعَلْتُهُ إِلَى سَهْوَةٍ فِي الْبَيْتِ، فَكَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي إِلَيْهِ، ثُمَّ قَالَ: "يَا عَائِشَةُ، أَخِّرِيهِ عَنِّي". فَنَزَعْتُهُ فَجَعَلْتُهُ وَسَائِدَ.', 'മറ്റൊരു നിവേദനം: മഹതി ചിത്രങ്ങളുള്ള ഒരു വിരി നാട്ടി. അങ്ങനെ റസൂലുല്ലാഹി(സ) കടന്ന് വന്നു. ഉടനെ അതഴിക്കുകയും ചെയ്തു. അപ്പോൾ മഹതി അത് വെട്ടി രണ്ട് തലയണകളാക്കി.');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=8 and h.hadith_no=209), 3, 'وَفِي رِوَايَةٍ: أَنَّهَا نَصَبَتْ سِتْرًا فِيهِ تَصَاوِيرُ، فَدَخَلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَنَزَعَهُ، فَقَطَّعَتْهُ وِسَادَتَيْنِ،', 'മറ്റൊരു നിവേദനം: മഹതി പറഞ്ഞു: റസൂലുല്ലാഹി(സ) അവക്ക് മേൽ തല ചായ്ക്കാറുണ്ടായിരുന്നു. (ന)');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=8 and h.hadith_no=209), 4, 'وَفِي رِوَايَةٍ قَالَتْ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَرْتَفِقُ عَلَيْهِمَا. (ن)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 210, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: وَاعَدَ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ جَبْرِيلُ عَلَيْهِ السَّلَامُ فِي سَاعَةٍ يَأْتِيهِ فِيهَا، فَرَاثَ عَلَيْهِ، فَخَرَجَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَإِذَا هُوَ بِجَبْرِيلَ قَائِمٌ عَلَى الْبَابِ، فَقَالَ: "مَا مَنَعَكَ أَنْ تَدْخُلَ". قَالَ: إِنَّ فِي الْبَيْتِ كَلْبًا، وَإِنَّا لَا نَدْخُلُ بَيْتًا فِيهِ كَلْبٌ وَلَا صُورَةٌ. (جه)', 'ആഇശ(റ): ഇന്നസമയത്ത് വരാമെന്ന് റസൂലുല്ലാഹി(സ)യോട് ജിബ്‌രീൽ(അ) വാഗ്ദാനം ചെയ്തു. പക്ഷേ, കുറെ പിന്തുകയുണ്ടായി. അപ്പോൾ നബി(സ) ഇറങ്ങിപ്പുറപ്പെട്ടു. അപ്പോഴതാ ജിബ്‌രീൽ(അ) വാതിൽക്കൽ നിൽക്കുന്നു; അപ്പോൾ അവിടന്ന് ചോദിച്ചു: "താങ്കളെ അകത്തു കടക്കുന്നതിന് തടസ്സമാക്കുന്നതെന്താണ്?" ജിബ്‌രീൽ(അ) പറഞ്ഞു: നിശ്ചയം (ഈ) വീട്ടിൽ ഒരു നായയുണ്ട്. ഞങ്ങൾ നായയും ചിത്രങ്ങളുമുള്ള ഒരു വീട്ടിലും പ്രവേശിക്കുകയില്ല." (ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 692, 692, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=84 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 211, 'عَنْ عَلِيِّ بْنِ أَبِي طَالِبٍ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: " لَا تَدْخُلُ الْمَلَائِكَةُ بَيْتًا فِيهِ صُورَةٌ وَلَا كَلْبٌ وَلَا جُنُبٌ". (د،ن،جه)', 'അലി(റ): നബി(സ) പറഞ്ഞു: "ചിത്രവും നായയും അശുദ്ധിക്കാരനും ഉള്ള ഒരു വീട്ടിലും മാലാഖമാർ കടന്നു വരികയില്ല." (ദ,ന,ജ)', 'عَلِيِّ بْنِ أَبِي طَالِبٍ', 'അലി(റ)', null, null, array['د','ن','جه']::text[], array['ദ','ന','ജ']::text[], null, null, 692, 692, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=84 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 212, 'عَنْ زَيْدِ بْنِ خَالِدٍ الْجُهَنِيِّ، عَنْ أَبِي طَلْحَةَ الْأَنْصَارِيِّ - رَضِيَ اللهُ عَنْهُمَا - قَالَ: سَمِعْتُ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "لَا تَدْخُلُ الْمَلَائِكَةُ بَيْتًا فِيهِ كَلْبٌ وَلَا تِمْثَالٌ". وَقَالَ: انْطَلِقْ بِنَا إِلَى أُمِّ الْمُؤْمِنِينَ عَائِشَةَ نَسْأَلُهَا عَنْ ذَلِكَ، فَانْطَلَقْنَا، فَقُلْنَا: يَا أُمَّ الْمُؤْمِنِينَ، إِنَّ أَبَا طَلْحَةَ حَدَّثَنَا عَنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِكَذَا وَكَذَا، فَهَلْ سَمِعْتِ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَذْكُرُ ذَلِكَ؟ قَالَتْ: لَا، وَلَكِنْ سَأُحَدِّثُكُمْ بِمَا رَأَيْتُهُ فَعَلَ، خَرَجَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي بَعْضِ مَغَازِيهِ، وَكُنْتُ أَتَحَيَّنُ قُفُولَهُ، فَأَخَذْتُ نَمَطًا كَانَ لَنَا فَسَتَرْتُهُ عَلَى الْعَرْضِ، فَلَمَّا جَاءَ اسْتَقْبَلْتُهُ، فَقُلْتُ: السَّلَامُ عَلَيْكَ يَا رَسُولَ اللهِ وَرَحْمَةُ اللهِ وَبَرَكَاتُهُ، اَلْحَمْدُ لِلَّهِ الَّذِي أَعَزَّكَ وَأَكْرَمَكَ. فَنَظَرَ إِلَى الْبَيْتِ فَرَأَى النَّمَطَ، فَلَمْ يَرُدَّ عَلَيَّ شَيْئًا، وَرَأَيْتُ الْكَرَاهِيَةَ فِي وَجْهِهِ، فَأَتَى النَّمَطَ حَتَّى هَتَكَهُ، ثُمَّ قَالَ: "إِنَّ اللَّهَ لَمْ يَأْمُرْنَا فِيمَا رَزَقَنَا أَنْ نَكْسُوَ الْحِجَارَةَ وَاللَّبِنَ". قَالَتْ: فَقَطَعْتُهُ وَجَعَلْتُهُ وِسَادَتَيْنِ وَحَشَوْتُهُمَا لِيفًا، فَلَمْ يُنْكِرْ ذَلِكَ عَلَيَّ. (ق،د،ت،ن،جه)', 'സൈദുബ്നു ഖാലിദിൽ ജുഹനി(റ) അബൂത്വൽഹത്തുൽ അൻസാരി(റ)വിൽ നിന്ന് നിവേദനം ചെയ്യുന്നു: അദ്ദേഹം പറഞ്ഞു: ഞാൻ നബി(സ) പറയുന്നത് കേട്ടു: "ജീവനുള്ളവയുടെ രൂപങ്ങളും നായയും ഉള്ള ഒരു വീട്ടിലും മാലാഖമാർ കടന്ന് വരികയില്ല." നിവേദകൻ പറഞ്ഞു: നീ ഞങ്ങളുമായി ഉമ്മുൽ മുഅ്മിനീൻ ആഇശ(റ)യുടെ പക്കൽ കൊണ്ട് പോവുക. നമുക്ക് അതേക്കുറിച്ച് മഹതിയോട് ചോദിക്കാം. അങ്ങനെ ഞങ്ങൾ യാത്രയായി. അങ്ങനെ ഞങ്ങൾ പറഞ്ഞു: ഉമ്മുൽ മുഅ്മിനീൻ, നിശ്ചയം അബൂത്വൽഹ(റ) റസൂലുല്ലാഹി(സ)യിൽ നിന്ന് ഞങ്ങൾക്ക് ഇങ്ങനെയൊക്കെ (ഹദീസ്) പറഞ്ഞു തന്നു. നബി(സ) അപ്രകാരം പറയുന്നത് താങ്കൾ കേട്ടിട്ടുണ്ടോ? മഹതി പറഞ്ഞു: ഇല്ല, പക്ഷേ, അവിടന്ന് ചെയ്തതായി ഞാൻ കണ്ടത് നിങ്ങൾക്ക് പറഞ്ഞ് തരാം: റസൂലുല്ലാഹി(സ) ഒരു യുദ്ധത്തിന് പുറപ്പെട്ടു. ഞാൻ അവിടത്തെ മടക്കയാത്ര എണ്ണിയെണ്ണി കാത്തിരിക്കുകയായിരുന്നു. അപ്പോൾ ഞാൻ ജീനിത്തുണി എടുത്തു. അതിനെ വീതിയിൽ മറയാക്കി. അവിടന്ന് വന്നപ്പോൾ ഞാൻ അവിടത്തെ അടുക്കലേക്ക് മുന്നിട്ട് പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, അസ്സലാമു അലൈകും വറഹ്മതുല്ലാഹി വബറകാതുഹു. അങ്ങയെ ബഹുമാനിക്കുകയും വന്ദിക്കുകയും ചെയ്ത അല്ലാഹുവിനാണ് സർവ്വ സ്തുതിയും. അപ്പോൾ അവിടന്ന് വീട്ടിലേക്ക് നോക്കി. (അവിടെ) ആ ജീനിത്തുണി കണ്ടു. എനിക്കൊന്നും മടക്കിയില്ല (സലാം മടക്കിയില്ല). അപ്പോൾ ഞാൻ അവിടത്തെ മുഖത്തിൽ വെറുപ്പ് കണ്ടു. ഉടൻ അവിടന്ന് ആ ജീനിത്തുണിയുടെ അടുത്ത് വന്നു. അത് തുണ്ടം തുണ്ടമാക്കി. പിന്നീട് പറഞ്ഞു: "നിശ്ചയം അല്ലാഹു അവൻ നമുക്ക് നൽകിയതിൽ ഇഷ്ടികക്കട്ടയെയും, കല്ലിനെയും വസ്ത്രം ധരിപ്പിക്കാൻ കൽപിച്ചിട്ടില്ല." മഹതി പറഞ്ഞു: പിന്നീട് ഞാനത് കഷ്ണിച്ചു. അത് നിറയെ ചകിരിനാരുള്ള രണ്ട് തലയണയാക്കി. അവിടന്ന് അതിൽ എന്നോട് വെറുപ്പ് കാണിച്ചില്ല. (ബു,മു,ദ,തു,ന,ജ)', 'زَيْدِ بْنِ خَالِدٍ الْجُهَنِيِّ، عَنْ أَبِي طَلْحَةَ الْأَنْصَارِيِّ -', 'സൈദുബ്നു ഖാലിദിൽ ജുഹനി(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 692, 693, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=84 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 213, 'عَنْ جَابِرٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الصُّورَةِ فِي الْبَيْتِ، وَنَهَى أَنْ يُصْنَعَ ذَلِكَ. حَسَنٌ صَحِيحٌ. (ت)', 'ജാബിർ(റ): റസൂലുല്ലാഹി(സ) വീട്ടിൽ ചിത്രരൂപങ്ങൾ നിരോധിച്ചിരിക്കുന്നു. അതുണ്ടാക്കലും അവിടന്ന് നിരോധിച്ചിരിക്കുന്നു. ഹദീസ് ഹസനും സ്വഹീഹുമാണ്. (തു)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 693, 693, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=84 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 214, 'عَنْ بُسْرِ بْنِ سَعِيدٍ، عَنْ زَيْدِ بْنِ خَالِدٍ، عَنْ أَبِي طَلْحَةَ رَضِيَ اللَّهُ عَنْهُمْ - صَاحِبِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - أَنَّهُ قَالَ: إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِنَّ الْمَلَائِكَةَ لَا تَدْخُلُ بَيْتًا فِيهِ صُورَةٌ". قَالَ بُسْرٌ: ثُمَّ اشْتَكَى زَيْدٌ بَعْدُ فَعُدْنَاهُ، فَإِذَا عَلَى بَابِهِ سِتْرٌ فِيهِ صُورَةٌ، قَالَ: فَقُلْتُ لِعُبَيْدِ اللَّهِ الْخَوْلَانِيِّ، رَبِيبِ مَيْمُونَةَ زَوْجِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَلَمْ يُخْبِرْنَا زَيْدٌ عَنِ الصُّوَرِ يَوْمَ الْأَوَّلِ؟ فَقَالَ عُبَيْدُ اللَّهِ: أَلَمْ تَسْمَعْهُ حِينَ قَالَ: "إِلَّا رَقْمًا فِي ثَوْبٍ". (م)', 'അബൂത്വൽഹ(റ)വിൽ -നബി(സ)യുടെ സഹചാരി- നിന്ന് സൈദുബ്നു ഖാലിദ്(റ), അദ്ദേഹത്തിൽ നിന്ന് ബുസ്റുബ്നു സഈദ്(റ) നിവേദനം ചെയ്യുന്നു: അദ്ദേഹം (അബൂത്വൽഹ) പറഞ്ഞു: റസൂലുല്ലാഹി(സ) പറഞ്ഞു: "തീർച്ചയായും മലക്കുകൾ ചിത്രങ്ങളുള്ള ഒരു വീട്ടിലും കയറുകയില്ല." ബുസ്റ്(റ) പറയുന്നു: പിന്നീട് സൈദ്(റ)വിന് അസുഖം ബാധിച്ചപ്പോൾ ഞങ്ങൾ അദ്ദേഹത്തെ സന്ദർശിക്കാൻ ചെന്നു. അന്നേരം അദ്ദേഹത്തിന്റെ വാതിലിന്മേൽ ചിത്രരൂപങ്ങളുള്ള ഒരു വിരിയുണ്ടായിരുന്നു. നിവേദകൻ പറയുന്നു: അപ്പോൾ ഞാൻ നബി(സ)യുടെ പത്നി മൈമൂന(സ)യുടെ മാതാവിന്റെ ഭർത്താവായ ഉബൈദുല്ലാഹിൽ ഖൗലാനി(റ)വിനോട് പറഞ്ഞു: ആദ്യ നാൾ സൈദ്(റ) രൂപചിത്രങ്ങളെക്കുറിച്ച് നമ്മോട് പറഞ്ഞിരുന്നില്ലെയോ? അപ്പോൾ ഉബൈദുല്ലാഹി(റ) പറഞ്ഞു: അവിടുന്ന് “വസ്ത്രത്തിലെ വരയൊഴികെ” എന്ന് പറഞ്ഞപ്പോൾ നീ കേട്ടിട്ടില്ലായിരുന്നോ? (മു)', 'بُسْرِ بْنِ سَعِيدٍ، عَنْ زَيْدِ بْنِ خَالِدٍ، عَنْ أَبِي طَلْحَةَ', 'അബൂത്വൽഹ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 693, 694, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=85 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 215, 'عَنْ مَيْمُونَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَصْبَحَ يَوْمًا وَاجِمًا، فَقَالَتْ مَيْمُونَةُ: يَا رَسُولَ اللَّهِ، لَقَدِ اسْتَنْكَرْتُ هَيْئَتَكَ مُنْذُ الْيَوْمِ؟ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: ”إِنَّ جِبْرِيلَ كَانَ وَعَدَنِي أَنْ يَلْقَانِي اللَّيْلَةَ فَلَمْ يَلْقَنِي، أَمَا وَاللَّهِ مَا أَخْلَفَنِي“. قَالَ: فَظَلَّ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَوْمَهُ ذَلِكَ عَلَى ذَلِكَ، ثُمَّ وَقَعَ فِي نَفْسِهِ جِرْوُ كَلْبٍ تَحْتَ فُسْطَاطٍ لَنَا، فَأَمَرَ بِهِ فَأُخْرِجَ، ثُمَّ أَخَذَ بِيَدِهِ مَاءً فَنَضَحَ مَكَانَهُ، فَلَمَّا أَمْسَى لَقِيَهُ جِبْرِيلُ عَلَيْهِ السَّلَام فَقَالَ لَهُ: ”قَدْ كُنْتَ وَعَدْتَنِي أَنْ تَلْقَانِي الْبَارِحَةَ“. قَالَ: أَجَلْ، وَلَكِنَّا لَا نَدْخُلُ بَيْتًا فِيهِ كَلْبٌ وَلَا صُورَةٌ. فَأَصْبَحَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَوْمَئِذٍ فَأَمَرَ بِقَتْلِ الْكِلَابِ، حَتَّى إِنَّهُ يَأْمُرُ بِقَتْلِ كَلْبِ الْحَائِطِ الصَّغِيرِ، وَيَتْرُكُ كَلْبَ الْحَائِطِ الْكَبِيرِ. (م)', 'മൈമൂന(റ): ഒരു പ്രഭാതത്തിൽ (ദുഃഖം കൊണ്ടോ കോപം കൊണ്ടോ) മൂകരായി താഴോട്ട് നോക്കിയിരിക്കുകയായിരുന്നു റസൂലുല്ലാഹി(സ). അപ്പോൾ മൈമൂന(റ) ചോദിച്ചു: അല്ലാഹുവിന്റെ ദൂതരേ, ഇന്ന് മുതൽ അവിടുത്തെ അവസ്ഥ തീർച്ചയായും എനിക്കിഷ്ടമില്ലാത്തതാണല്ലോ? റസൂലുല്ലാഹി(സ) പറഞ്ഞു: “നിശ്ചയം ജിബ്‌രീൽ(അ) എന്നോട് ഈ രാത്രിയിൽ കണ്ട് മുട്ടാമെന്ന് കരാർ ചെയ്തിരുന്നു. പക്ഷേ, എന്നെ കണ്ടുമുട്ടിയില്ല. അല്ലാഹുവാണ, ജിബ്‌രീൽ(അ) ഇതുവരെ എന്നോട് വാഗ്ദത്ത ലംഘനം നടത്തിയിട്ടില്ല.” നിവേദകൻ പറയുന്നു: റസൂലുല്ലാഹി(സ)യുടെ ആ ദിനം അങ്ങനെത്തന്നെയായി. പിന്നീട് ഞങ്ങളുടെ (പരുക്കൻ തുണി കൊണ്ടുണ്ടാക്കിയ) കൂടാരത്തിൽ ഒരു നായക്കുട്ടിയുള്ളതായി അവിടുത്തെ മനസ്സിൽ തോന്നി. അങ്ങനെ അവിടന്ന് കൽപന നൽകി. അതിനെ പുറത്തെടുത്തു. പിന്നീട് അവിടത്തെ കരം കൊണ്ട് ജലമെടുത്ത് ആ സ്ഥലത്ത് കുടഞ്ഞു. അന്ന് വൈകുന്നേരമായപ്പോൾ ജിബ്‌രീൽ(അ) വന്നു. അപ്പോൾ അവിടന്ന് ജിബ്‌രീലിനോട് പറഞ്ഞു: “താങ്കളെന്നോട് ഇന്നലെ രാത്രി കണ്ടുമുട്ടാമെന്ന് വാക്ക് തന്നിരുന്നു.” ജിബ്‌രീൽ(അ) പറഞ്ഞു: അതെ, പക്ഷേ, ഞങ്ങൾ രൂപചിത്രവും നായയുമുള്ള ഒരു വീട്ടിലും കടക്കുകയില്ല. അന്ന് നബി(സ) നേരം വെളുത്തയുടൻ നായകളെ കൊല്ലാൻ കൽപിച്ചു. അങ്ങനെ ചെറിയ തോട്ടത്തിലെ നായകളെ കൊല്ലാനും വലിയ തോട്ടത്തിലുള്ള നായകളെ ഒഴിവാക്കാനും കൽപിച്ചു. (മു)', 'مَيْمُونَةَ', 'മൈമൂന(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 694, 694, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=85 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 216, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: ”لَا تَدْخُلُ الْمَلَائِكَةُ بَيْتًا فِيهِ تَمَاثِيلُ، أَوْ: تَصَاوِيرُ“. (م)', 'അബൂഹുറൈറ(റ): റസൂലുല്ലാഹി(സ) പറഞ്ഞു: “ജീവരൂപങ്ങളോ ചിത്രരൂപങ്ങളോ ഉള്ള ഒരു വീട്ടിലും മലക്കുകൾ കടക്കുകയില്ല.” (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 694, 694, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=85 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 217, 'عَنْ عَائِشَةَ رَضِيَ الله عَنْهَا قَالَتْ: دَخَلَ عَلَيَّ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَقَدْ سَتَرْتُ سَهْوَةً لِي بِقِرَامٍ فِيهِ تَمَاثِيلُ، فَلَمَّا رَآهُ هَتَكَهُ وَتَلَوَّنَ وَجْهُهُ، وَقَالَ: ”يَا عَائِشَةُ، أَشَدُّ النَّاسِ عَذَابًا عِنْدَ اللَّهِ يَوْمَ الْقِيَامَةِ الَّذِينَ يُضَاهُونَ بِخَلْقِ اللَّهِ [تَعَالَى]". قَالَتْ عَائِشَةُ: فَقَطَّعْنَاهُ فَجَعَلْنَاهُ مِنْهُ وِسَادَةً أَوْ وِسَادَتَيْنِ. (م)', 'ആഇശ(റ): റസൂലുല്ലാഹി(സ) എന്റെ അടുത്തേക്ക് കടന്നുവന്നു. ഞാൻ എന്റെ അറ ജീവൽചിത്രങ്ങളുള്ള ഒരു ചുവന്ന വിരികൊണ്ട് മറച്ചിരുന്നു. തിരുമേനി(സ) അത് കണ്ടപ്പോൾ അത് തുണ്ടം തുണ്ടമാക്കി. അവിടത്തെ മുഖം വിവർണമാകുകയും ചെയ്തു. അവിടന്ന് പറഞ്ഞു: "ആഇശാ, അന്ത്യനാളിൽ അല്ലാഹുവിന്റെ അടുക്കൽ ജനങ്ങളിൽ ഏറ്റവും ശക്തമായ ശിക്ഷയുള്ളവർ അല്ലാഹു തആലയുടെ സൃഷ്ടിപ്പിനോട് സാദൃശ്യം കാണിക്കുന്നവരാണ്." ആഇശ(റ) പറഞ്ഞു: അപ്പോൾ ഞങ്ങൾത് മുറിച്ച് അതിൽ നിന്ന് ഒന്നോ രണ്ടോ തലയിണകൾ ഉണ്ടാക്കി. (മു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['م']::text[], array['മു']::text[], 'تَعَالَى', null, 694, 695, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=86 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 218, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: قَدِمَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مِنْ سَفَرٍ، وَقَدْ سَتَرْتُ عَلَى بَابِي دُرْنُوكًا فِيهِ الْخَيْلُ ذَوَاتُ الْأَجْنِحَةِ، فَأَمَرَنِي فَنَزَعْتُهُ. (م)', 'ആഇശ(റ): റസൂലുല്ലാഹി(സ) ഒരു യാത്രയിൽ നിന്ന് മടങ്ങി വന്നു. ഞാനാണെങ്കിൽ എന്റെ വാതിലിൻമേൽ ചിറകുകളുള്ള കുതിരകളുടെ ചിത്രമുള്ള, പൊന്തിനിൽക്കുന്ന രോമമുള്ള ഒരു വിരികൊണ്ട് മറയുണ്ടാക്കിയിരുന്നു. അപ്പോൾ അവിടത്തെ കൽപനപ്രകാരം ഞാനത് അഴിച്ചുമാറ്റി. (മു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 695, 695, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=86 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 219, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا أَنَّهَا اشْتَرَتْ نُمْرُقَةً فِيهَا تَصَاوِيرُ، فَلَمَّا رَآهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَامَ عَلَى الْبَابِ فَلَمْ يَدْخُلْ، فَعَرَفْتُ - أَوْ فَعُرِفَتْ - فِي وَجْهِهِ الْكَرَاهِيَةَ، فَقَالَتْ: يَا رَسُولَ اللَّهِ، أَتُوبُ إِلَى اللَّهِ وَإِلَى رَسُولِهِ فَمَاذَا أَذْنَبْتُ؟ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَا بَالُ هَذِهِ النُّمْرُقَةِ؟". فَقُلْتُ: اشْتَرَيْتُهَا لَكَ، تَقْعُدَ عَلَيْهَا وَتَوَسَّدَهَا. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ أَصْحَابَ هَذِهِ الصُّورَةِ يُعَذَّبُونَ، وَيُقَالُ لَهُمْ: أَحْيُوا مَا خَلَقْتُمْ". ثُمَّ قَالَ: "إِنَّ الْبَيْتَ الَّذِي فِيهِ الصُّوَرُ لَا تَدْخُلُهُ الْمَلَائِكَةُ". وفي رواية: قالت: فَأَخَذْتُهُ فَجَعَلْتُهُ مِرْفَقَتَيْنِ، فَكَانَ يَرْتَفِقُ بِهِمَا فِي البَيْتِ. (م)', 'ആഇശ(റ): മഹതി രൂപങ്ങളുള്ള ഒരു ജീനിത്തലയണ വാങ്ങി. അങ്ങനെ നബി(സ) അത് കണ്ടപ്പോൾ അകത്തു കടക്കാതെ വാതിൽക്കൽ തന്നെ നിന്നു. അപ്പോൾ അവിടത്തെ മുഖത്ത് വെറുപ്പുള്ളതായി മഹതി മനസ്സിലാക്കി. മഹതി ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, ഞാൻ അല്ലാഹുവിലേക്കും അവന്റെ റസൂലിലേക്കും തൗബ ചെയ്ത് മടങ്ങാം. ഞാൻ എന്തുതെറ്റാണ് ചെയ്തത്? അപ്പോൾ റസൂലുല്ലാഹി(സ) പറഞ്ഞു: "എന്താണീ ജീനിത്തലയിണയുടെ കാര്യം?" അപ്പോൾ ഞാൻ പറഞ്ഞു: ഞാനിത് അങ്ങേക്ക് വാങ്ങിച്ചതാണ്. അങ്ങേക്കതിൽ ഇരിക്കുകയും തലയണയാക്കുകയും ചെയ്യാം. അപ്പോൾ റസൂലുല്ലാഹി(സ) പറഞ്ഞു: "നിശ്ചയം ഈ രൂപങ്ങളുടെ ആളുകൾ ശിക്ഷിക്കപ്പെടും. അവരോട് നിങ്ങൾ പടച്ചവയെ, ''നിങ്ങൾ തന്നെ ജീവിപ്പിക്കുക'' എന്ന് പറയപ്പെടുകയും ചെയ്യും." പിന്നീടവിടന്ന് പറഞ്ഞു: "നിശ്ചയം, ചിത്രങ്ങളുള്ള വീടുകളിൽ മാലാഖമാർ പ്രവേശിക്കുകയില്ല."
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=8 and h.hadith_no=219), 1, 'وَفِي رِوَايَةٍ: قالت: فَأَخَذْتُهُ فَجَعَلْتُهُ مِرْفَقَتَيْنِ، فَكَانَ يَرْتَفِقُ بِهِمَا فِي البَيْتِ. (م)', 'മറ്റൊരു നിവേദനം: മഹതി പറഞ്ഞു: ഞാനതെടുത്ത് അതിനെ രണ്ട് തലയണകളാക്കി. അവ രണ്ടിൻമേലും നബി(സ) തല ചായ്ക്കാറുണ്ടായിരുന്നു. (മു)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 220, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: اسْتَأْذَنَ جِبْرِيلُ عَلَيْهِ السَّلَامُ عَلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: "ادْخُلْ. فَقَالَ: كَيْفَ أَدْخُلُ وَفِي بَيْتِكَ سِتْرٌ فِيهِ تَصَاوِيرُ؟ فَإِمَّا أَنْ تُقْطَعَ رُءُوسُهَا أَوْ تُجْعَلَ بِسَاطًا يُوطَأُ، فَإِنَّا مَعْشَرَ الْمَلَائِكَةِ لَا نَدْخُلُ بَيْتًا فِيهِ تَصَاوِيرُ"". (ن)', 'അബൂഹുറൈറ(റ): നബി(സ)യുടെ അടുത്തേക്ക് കടന്നുവരാൻ ജിബ്‌രീൽ(അ) സമ്മതം ചോദിച്ചു. നബി(സ) പറഞ്ഞു: "കടന്നുവരിക." ജിബ്‌രീൽ(അ) പറഞ്ഞു: താങ്കളുടെ വീട്ടിൽ ചിത്രമുള്ള വിരിയുണ്ടായിരിക്കെ ഞാനങ്ങനെ അകത്ത് കടക്കും? അതിനാൽ ഒന്നുകിൽ അവയുടെ തലകൾ കഷ്ണിച്ചിടുക. അല്ലെങ്കിൽ അത് ചവിട്ടിനടക്കാനുള്ള ചവിട്ടിയാക്കുക. കാരണം, ഞങ്ങൾ, മാലാഖമാർ ചിത്രരൂപങ്ങളുള്ള ഒരു വീട്ടിലും കയറുകയില്ല." (ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 695, 696, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=87 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 221, 'عَنْ أَبِي زُرْعَةَ رَضِيَ اللهُ عَنْهُ قَالَ: دَخَلْتُ مَعَ أَبِي هُرَيْرَةَ [فِي] دَارِ مَرْوَانَ، فَرَأَى فِيهَا تَصَاوِيرَ، فَقَالَ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "قَالَ اللهُ عَزَّ وَجَلَّ: وَمَنْ أَظْلَمُ مِمَّنْ ذَهَبَ يَخْلُقُ خَلْقًا كَخَلْقِي، فَلْيَخْلُقُوا ذَرَّةً، أَوْ لِيَخْلُقُوا حَبَّةً، أَوْ لِيَخْلُقُوا شَعِيرَةً". (م)', 'അബൂസുർഅ(റ): ഞാൻ അബൂഹുറൈറ(റ)വിന്റെ കൂടെ മർവാന്റെ വീട്ടിൽ കടന്നു. അപ്പോൾ അദ്ദേഹം (അബൂഹുറൈറ) അവിടെ കുറെ രൂപങ്ങൾ കണ്ടു. ഉടൻ അദ്ദേഹം പറഞ്ഞു: ഞാൻ റസൂൽ(സ) പറയുന്നത് കേട്ടു: "മഹോന്നതനും അന്തസ്സുറ്റവനുമായ അല്ലാഹു പറഞ്ഞിട്ടുണ്ട്: എന്റെ സൃഷ്ടിപ്പ് പോലെ സൃഷ്ടിപ്പ് നടത്തുന്നവനേക്കാൾ വലിയ അക്രമി ആരുണ്ട്? അവർ ഒരു അണുവിനെയെങ്കിലും സൃഷ്ടിക്കട്ടെ. അല്ലെങ്കിൽ ഒരു ധാന്യമെങ്കിലും സൃഷ്ടിക്കട്ടെ. അതുമല്ലെങ്കിൽ ഒരു ബാർളിയെയെങ്കിലും സൃഷ്ടിക്കട്ടെ." (മു)', 'أَبِي زُرْعَةَ', 'അബൂസുർഅ(റ)', null, null, array['م']::text[], array['മു']::text[], 'فِي', null, 696, 696, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=88 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 222, 'عَنْ سَعِيدِ بْنِ أَبِي الْحَسَنِ رَضِيَ اللهُ عَنْهُ قَالَ: جَاءَ رَجُلٌ إِلَى ابْنِ عَبَّاسٍ فَقَالَ: إِنِّي رَجُلٌ أُصَوِّرُ هَذِهِ الصُّوَرَ فَأَفْتِنِي فِيهَا، فَقَالَ لَهُ: ادْنُ مِنِّي، فَدَنَا مِنْهُ، ثُمَّ قَالَ: ادْنُ مِنِّي، فَدَنَا حَتَّى وَضَعَ يَدَهُ عَلَى رَأْسِهِ، وَقَالَ: أُنَبِّئُكَ بِمَا سَمِعْتُ مِنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ؟ سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "كُلُّ مُصَوِّرٍ فِي النَّارِ، يَجْعَلُ لَهُ بِكُلِّ صُورَةٍ صَوَّرَهَا نَفْسًا، فَتُعَذِّبُهُ فِي جَهَنَّمَ". وَ قَالَ: إِنْ كُنْتَ لَا بُدَّ فَاعِلًا فَاصْنَعِ الشَّجَرَ وَمَا لَا نَفْسَ لَهُ. (م،ن)', 'സഈദുബ്നു അബിൽഹസൻ(റ): ഒരാൾ വന്നു ഇബ്നുഅബ്ബാസ്(റ)വിനോട് പറഞ്ഞു: ഞാൻ ഈ രൂപങ്ങൾ നിർമ്മിക്കുന്നയാളാണ്. എനിക്കതിൽ ഒരു ഫത്‌വ താങ്കൾ തരുമോ? അപ്പോൾ ഇബ്നുഅബ്ബാസ്(റ) അദ്ദേഹത്തോട് പറഞ്ഞു: എന്റെ അടുത്തേക്ക് നിൽക്കൂ. അയാൾ അദ്ദേഹത്തിന്റെ അടുത്തേക്ക് നിന്നു. അദ്ദേഹം വീണ്ടും എന്റെ അടുത്തേക്ക് നിൽക്കൂ എന്ന് പറഞ്ഞു: അപ്പോൾ അയാൾ അടുത്തേക്ക് നിന്നു. അങ്ങനെ അദ്ദേഹത്തിന്റെ കരം അയാളുടെ തലയിൽ വെച്ചു. എന്നിട്ട് പറഞ്ഞു: ഞാൻ റസൂലുല്ലാഹി(സ)യിൽ നിന്ന് കേട്ടത് നിനക്ക് പറഞ്ഞുതരട്ടെയോ? റസൂലുല്ലാഹി(സ) പറയുന്നത് ഞാൻ കേട്ടു: "എല്ലാ രൂപനിർമ്മാതാക്കളും നരകത്തിലാണ്. അവൻ നിർമ്മിച്ച സകല രൂപങ്ങളുടെ രൂപത്തിലും അവന് ശരീരം ഉണ്ടാക്കപ്പെടും. അവ അവനെ നരകത്തിൽ ശിക്ഷിച്ച് കൊണ്ടിരിക്കും." അദ്ദേഹം പറഞ്ഞു: നിനക്കത് ചെയ്യാതെ കഴിയില്ല എന്നാണെങ്കിൽ നീ ജീവനില്ലാത്തവയെയോ മരത്തെയോ ഉണ്ടാക്കുക. (മു,ന)', 'سَعِيدِ بْنِ أَبِي الْحَسَنِ', 'സഈദുബ്നു അബിൽഹസൻ(റ)', null, null, array['م','ن']::text[], array['മു','ന']::text[], null, null, 696, 696, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=89 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 223, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ صَوَّرَ صُورَةً عَذَّبَهُ اللهُ حَتَّى يَنْفُخَ فِيهَا يَعْنِي الرُّوحَ وَلَيْسَ بِنَافِخٍ فِيهَا. وَمَنِ اسْتَمَعَ إِلَى حَدِيثِ قَوْمٍ - وَهُمْ يَفِرُّونَ بِهِ مِنْهُ - صُبَّ فِي أُذُنِهِ الْآنُكُ يَوْمَ الْقِيَامَةِ". حَسَنٌ صَحِيحٌ. (خ،ت،ن)', 'ഇബ്‌നുഅബ്ബാസ്(റ): റസൂലുല്ലാഹി(സ) പറഞ്ഞു: "ആരെങ്കിലും ഒരു രൂപം ഉണ്ടാക്കിയാൽ അതിലവൻ ആത്മാവ് ഊതും വരെ അല്ലാഹു അവനെ ശിക്ഷിക്കും. അവനാണെങ്കിൽ അതിൽ (ആത്മാവ്) ഊതാൻ കഴിയില്ലതാനും. ആരെങ്കിലും ഒരുകൂട്ടരുടെ സംസാരം -അവർ ആ സംസാരവുമായി അവനിൽ നിന്ന് മാറി നിൽക്കുകയായിരിക്കെ- ശ്രദ്ധിച്ചുകേട്ടാൽ അന്ത്യനാളിൽ അവന്റെ ചെവിയിൽ ഈയം ഒഴിക്കപ്പെടും." ഹദീസ് ഹസനും സ്വഹീഹുമാണ്. (ബു,തു,ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്‌നുഅബ്ബാസ്(റ)', null, null, array['خ','ت','ن']::text[], array['ബു','തു','ന']::text[], null, null, 696, 697, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=89 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 224, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِنَّ الَّذِينَ يَصْنَعُونَ هَذِهِ الصُّوَرَ يُعَذَّبُونَ يَوْمَ الْقِيَامَةِ يُقَالُ لَهُمْ: أَحْيُوا مَا خَلَقْتُمْ". (خ،ن)', 'ഇബ്‌നുഉമർ(റ): റസൂലുല്ലാഹി(സ) പറഞ്ഞു: "ഈ രൂപങ്ങൾ നിർമ്മിക്കുന്നവർ അന്ത്യനാളിൽ ശിക്ഷിക്കപ്പെടും. നിങ്ങൾ സൃഷ്ടിച്ചവയെ നിങ്ങൾ ജീവിപ്പിക്കൂ എന്നവരോട് പറയപ്പെടും." (ബു,ന)', 'ابْنِ عُمَرَ', 'ഇബ്‌നുഉമർ(റ)', null, null, array['خ','ن']::text[], array['ബു','ന']::text[], null, null, 697, 697, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=89 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 225, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: قَدِمَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنْ سَفَرٍ، وَقَدْ سَتَرْتُ بِقِرَامٍ عَلَى سَهْوَةٍ لِي فِيهِ تَصَاوِيرُ، فَنَزَعَهُ وَقَالَ: "أَشَدُّ النَّاسِ عَذَابًا يَوْمَ الْقِيَامَةِ الَّذِينَ يُضَاهُونَ بِخَلْقِ اللَّهِ". وفي رواية قَالَتْ: دَخَلَ عَلَيَّ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَقَدْ سَتَرْتُ بِقِرَامٍ فِيهِ تَمَاثِيلُ، فَلَمَّا رَآهُ تَلَوَّنَ وَجْهُهُ، ثُمَّ هَتَكَهُ بِيَدِهِ وَقَالَ: "إِنَّ أَشَدَّ النَّاسِ عَذَابًا يَوْمَ الْقِيَامَةِ الَّذِينَ يُشَبِّهُونَ بِخَلْقِ اللَّهِ". (ن)', 'ആഇശ(റ): റസൂലുല്ലാഹി(സ) ഒരു യാത്ര കഴിഞ്ഞ് മടങ്ങി വന്നു. ഞാൻ ചിത്രങ്ങളുള്ള ഒരു ചുവന്ന വിരികൊണ്ട് വീടിന്റെ മുൻവശം മറച്ചിട്ടുണ്ടായിരുന്നു. അവിടന്ന് അതഴിച്ചു. എന്നിട്ട് പറഞ്ഞു: "അല്ലാഹുവിന്റെ സൃഷ്ടിപ്പിനെ സമാനമാക്കുന്നവരാണ് അന്ത്യനാളിൽ ജനങ്ങളിൽ ഏറ്റവും ശക്തമായ ശിക്ഷയുള്ളവർ." മറ്റൊരു ഉദ്ധരണിയിൽ: മഹതി പറഞ്ഞു: രൂപങ്ങളുള്ള ഒരു ചുവന്ന വിരികൊണ്ട് ഞാൻ മറച്ചിരിക്കെ റസൂലുല്ലാഹി(സ) എന്റെ അടുത്തേക്ക് കയറി വന്നു. അതുകണ്ടപ്പോൾ അവിടത്തെ മുഖം വിവർണമായി. അവിടുന്ന് തന്റെ കൈകൊണ്ടത് തുണ്ടം തുണ്ടമാക്കി. അവിടന്ന് പറഞ്ഞു: "നിശ്ചയം, അല്ലാഹുവിന്റെ സൃഷ്ടിപ്പിനോട് സദൃശ്യമാക്കുന്നവരാണ് അന്ത്യനാളിൽ ജനങ്ങളിൽ ഏറ്റവും ശക്തമായ ശിക്ഷയുള്ളവർ." (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 697, 697, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=90 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=8 and h.hadith_no=225), 1, 'وَفِي رِوَايَةٍ قَالَتْ: دَخَلَ عَلَيَّ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَقَدْ سَتَرْتُ بِقِرَامٍ فِيهِ تَمَاثِيلُ، فَلَمَّا رَآهُ تَلَوَّنَ وَجْهُهُ، ثُمَّ هَتَكَهُ بِيَدِهِ وَقَالَ: "إِنَّ أَشَدَّ النَّاسِ عَذَابًا يَوْمَ الْقِيَامَةِ الَّذِينَ يُشَبِّهُونَ بِخَلْقِ اللَّهِ". (ن)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 226, 'عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ رضي الله عنهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ مِنْ أَشَدِّ النَّاسِ عَذَابًا يَوْمَ الْقِيَامَةِ الْمُصَوِّرُونَ". (م،ن)', 'അബ്ദുല്ലാഹിബ്‌നു മസ്ഊദ്(റ): റസൂലുല്ലാഹി(സ) പറഞ്ഞു: "അന്ത്യനാളിൽ ജനങ്ങളിൽ ഏറ്റവും ശക്തമായ ശിക്ഷയുള്ളവരിൽ പെട്ടവരാണ് രൂപ നിർമ്മാതാക്കൾ." (മു,ന)', 'عَبْدِ اللَّهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്‌നു മസ്ഊദ്(റ)', null, null, array['م','ن']::text[], array['മു','ന']::text[], null, null, 697, 697, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=90 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 227, 'عَنْ عَلِيٍّ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ لِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "قُلْ: اللَّهُمَّ سَدِّدْنِي وَاهْدِنِي". وَنَهَانِي عَنِ الْجُلُوسِ عَلَى الْمَيَاثِرِ. وَالْمَيَاثِرُ: قَسِيٌّ كَانَتْ تَصْنَعُهُ النِّسَاءُ لِبُعُولَتِهِنَّ عَلَى الرَّحْلِ كَالْقَطَائِفِ مِنَ الْأُرْجُوَانِ. (ن)', 'അലി(റ): എന്നോട് റസൂലുല്ലാഹി(സ) പറഞ്ഞു: "നിങ്ങൾ പറയുക: അല്ലാഹുവേ, എന്നെ നേരെയാക്കണേ, എന്നെ നേർമാർഗ്ഗത്തിലാക്കണേ." ചുവന്ന ''മയാസീർ''ൽ ഇരിക്കുന്നത് പ്രവാചകർ(സ) എനിക്ക് നിരോധിച്ചിരിക്കുന്നു. ''മയാസിർ'' എന്നാൽ ചുവന്ന വെൽവെറ്റ് വസ്ത്രങ്ങൾ പോലെ, ജീനിയിൽ വിരിക്കാൻ ഭർത്താക്കൻമാർക്കായി സ്ത്രീകൾ ചണവും പട്ടും ഉപയോഗിച്ച് ഉണ്ടാക്കുന്ന ഒരു തരം വസ്ത്രമാണ്. (ന)', 'عَلِيٍّ', 'അലി(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 697, 698, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=91 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 228, 'عَنْ أَبِي رِفَاعَةَ العَدَوِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: انْتَهَيْتُ إِلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَهُوَ يَخْطُبُ، فَقُلْتُ: يَا رَسُولَ اللهِ، رَجُلٌ غَرِيبٌ جَاءَ يَسْأَلُ عَنْ دِينِهِ، لَا يَدْرِي مَا دِينُهُ؟ فَأَقْبَلَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَتَرَكَ خُطْبَتَهُ حَتَّى انْتَهَى إِلَيَّ، فَأُتِيَ بِكُرْسِيٍّ خِلْتُ قَوَائِمَهُ حَدِيدًا، فَقَعَدَ عَلَيْهِ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَجَعَلَ يُعَلِّمُنِي مِمَّا عَلَّمَهُ اللهُ، ثُمَّ أَتَى خُطْبَتَهُ فَأَتَمَّهَا. (ن)', 'അബൂരിഫാഅത്തിൽ അദവി(റ): റസൂലുല്ലാഹി(സ) ഖുത്ബ നടത്തിക്കൊണ്ടിരിക്കെ ഞാൻ തിരുമേനി(സ)യുടെയടുക്കൽ എത്തിപ്പെട്ടു. അപ്പോൾ ഞാൻ പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, തന്റെ മതത്തെക്കുറിച്ച് ചോദിക്കാൻ വന്ന വിദേശിയാണ് ഞാൻ. അയാളുടെ ദീൻ ഏതാണെന്നയാൾക്കറിയില്ല. അപ്പോൾ റസൂലുല്ലാഹി(സ) മുന്നിലേക്ക് തിരിഞ്ഞു ഖുത്ബ നിർത്തി എന്റെ അടുത്തേക്ക് വന്നു. അങ്ങനെ ഒരു കസേര കൊണ്ടുവന്നു. അതിന്റെ കാലുകൾ ഇരുമ്പാണെന്നെനിക്ക് തോന്നുന്നു. റസൂലുല്ലാഹി(സ) അതിലിരുന്നു. അങ്ങനെ അവിടത്തേക്ക് അല്ലാഹു പഠിപ്പിച്ച് തന്നവയിൽ നിന്ന് എനിക്ക് പഠിപ്പിച്ച് തരാൻ തുടങ്ങി. പിന്നീട് ഖുത്ബക്ക് വന്നു അത് പൂർത്തിയാക്കി. (ന)', 'أَبِي رِفَاعَةَ العَدَوِيِّ', 'അബൂരിഫാഅത്തിൽ അദവി(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 698, 698, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=92 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 229, 'عَنْ أَبِي جُحَيْفَةَ رَضِيَ اللهُ عَنْهُ قَالَ: كُنَّا مَعَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِالْبَطْحَاءِ وَهُوَ فِي قُبَّةٍ حَمْرَاءَ، وَعِنْدَهُ أُنَاسٌ يَسِيرٌ، فَجَاءَهُ بِلَالٌ فَأَذَّنَ، فَجَعَلَ يُتْبِعُ فَاهُ هَاهُنَا وَهَاهُنَا. (ن)', 'അബൂജുഹൈഫ(റ): ഞാൻ നബി(സ)യുടെ കൂടെ ചരൽമരുഭൂമിയിലായിരുന്നു. അവിടന്ന് ഒരു ചുവന്ന തമ്പിനുള്ളിലിരിക്കുകയാണ്. തിരുമേനി(സ)യുടെയടുക്കൽ ചിലയാളുകളുമുണ്ട്. അന്നേരം ബിലാൽ(റ) അങ്ങോട്ടുവന്നു. ശേഷം അദ്ദേഹം ബാങ്ക് വിളിച്ചു. അദ്ദേഹം തന്റെ വായ പലഭാഗത്തേക്കും തിരിക്കുന്നുണ്ടായിരുന്നു. (ന)', 'أَبِي جُحَيْفَةَ', 'അബൂജുഹൈഫ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 698, 698, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=93 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 230, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "بَيْنَمَا رَجُلٌ يَمْشِي، قَدْ أَعْجَبَتْهُ جُمَّتُهُ وَبُرْدَاهُ، إِذْ خُسِفَ بِهِ الْأَرْضُ، فَهُوَ يَتَجَلْجَلُ فِي الْأَرْضِ حَتَّى تَقُومَ السَّاعَةُ". (م)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "ഒരാൾ തന്റെ മുറ്റിവളരുന്ന മുടിയിലും വരയുള്ള രണ്ട് വസ്ത്രങ്ങളിലും അഹങ്കരിച്ച് നടന്നുകൊണ്ടിരിക്കെ പെട്ടെന്ന് അയാളെ ഭൂമി വിഴുങ്ങി. അങ്ങനെ അയാൾ അന്ത്യനാൾ വരെ ഭൂമിയിൽ താഴ്ന്നു കൊണ്ടിരിക്കുന്നു." (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 698, 699, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=94 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 231, 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ اتَّخَذَ خَاتَمًا مِنْ وَرِقٍ فَصُّهُ حَبَشِيٌّ، وَنُقِشَ فِيهِ: مُحَمَّدٌ رَسُولُ اللَّهِ. وفي رواية: كَانَ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَاتَمُ فِضَّةٍ يَتَخَتَّمُ بِهِ فِي يَمِينِهِ، فَصُّهُ حَبَشِيٌّ. يَجْعَلُ فَصَّهُ مِمَّا يَلِي كَفَّهُ. وفي رواية: كَانَ خَاتَمُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنْ فِضَّةٍ، وَكَانَ فَصُّهُ مِنْهُ. وفي رواية: كَانَ خَاتَمُهُ مِنْ وَرِقٍ، فَصُّهُ مِنْهُ. (ق،د،ت،ن)', 'അനസ്(റ): നബി(സ) ഒരു വെള്ളിമോതിരം ഉണ്ടാക്കി. അതിന്റെ കല്ല് ഹബ്ശിയായിരുന്നു (അബ്സീനിയയിലെ ഒരു കല്ല്). അതിൽ ''മുഹമ്മദുർറസൂലുല്ലാഹി'' എന്ന് കൊത്തിവെക്കപ്പെട്ടിരുന്നു. മറ്റൊരു റിപ്പോർട്ടിൽ: റസൂൽ(സ) അവിടത്തെ വലതുകയ്യിൽ ധരിക്കാറുള്ള ഒരുവെള്ളി മോതിരമുണ്ടായിരുന്നു. അതിന്റേത് അബ്സീനിയൻ കല്ലായിരുന്നു. അതിന്റെ കല്ല് കൈപ്പടത്തിനോടടുപ്പിക്കുകയും ചെയ്യുമായിരുന്നു. മറ്റൊരു റിപ്പോർട്ടിൽ: റസൂൽ(സ)യുടെ മോതിരവും അതിന്റെ കല്ലും വെള്ളിയിൽ നിർമ്മിതമായിരുന്നു. (ബു,മു,ദ,തു,ന)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['ق','د','ت','ن']::text[], array['ബു','മു','ദ','തു','ന']::text[], null, null, 699, 699, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=95 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=8 and h.hadith_no=231), 1, 'وَفِي رِوَايَةٍ: كَانَ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَاتَمُ فِضَّةٍ يَتَخَتَّمُ بِهِ فِي يَمِينِهِ، فَصُّهُ حَبَشِيٌّ. يَجْعَلُ فَصَّهُ مِمَّا يَلِي كَفَّهُ.', 'മറ്റൊരു നിവേദനിൽ: റസൂൽ(സ) അവിടത്തെ വലതുകയ്യിൽ ധരിക്കാറുള്ള ഒരുവെള്ളി മോതിരമുണ്ടായിരുന്നു. അതിന്റേത് അബ്സീനിയൻ കല്ലായിരുന്നു. അതിന്റെ കല്ല് കൈപ്പടത്തിനോടടുപ്പിക്കുകയും ചെയ്യുമായിരുന്നു.');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=8 and h.hadith_no=231), 2, 'وَفِي رِوَايَةٍ: كَانَ خَاتَمُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنْ فِضَّةٍ، وَكَانَ فَصُّهُ مِنْهُ.', 'മറ്റൊരു നിവേദനിൽ: റസൂൽ(സ)യുടെ മോതിരവും അതിന്റെ കല്ലും വെള്ളിയിൽ നിർമ്മിതമായിരുന്നു. (ബു,മു,ദ,തു,ന)');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=8 and h.hadith_no=231), 3, 'وَفِي رِوَايَةٍ: كَانَ خَاتَمُهُ مِنْ وَرِقٍ، فَصُّهُ مِنْهُ. (ق،د،ت،ن)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 232, 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: أَرَادَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ يَكْتُبَ إِلَى الرُّومِ، فَقَالُوا: إِنَّهُمْ لَا يَقْرَءُونَ كِتَابًا إِلَّا مَخْتُومًا. فَاتَّخَذَ خَاتَمًا مِنْ فِضَّةٍ، كَأَنِّي أَنْظُرُ إِلَى بَيَاضِهِ فِي يَدِهِ، وَنُقِشَ فِيهِ: مُحَمَّدٌ رَسُولُ اللَّهِ. (ن)', 'അനസ്(റ): റസൂലുല്ലാഹി(സ) റോമിലേക്ക് ഒരു കത്തെഴുതാൻ ഉദ്ദേശിച്ചപ്പോൾ അവർ പറഞ്ഞു: മുദ്രവെക്കപ്പെടാത്ത എഴുത്ത് അവർ വായിക്കുകയില്ല. അപ്പോൾ തിരുമേനി(സ) വെള്ളിയുടെ ഒരു മോതിരമുണ്ടാക്കി. അവിടത്തെ കയ്യിൽ അതിന്റെ വെള്ളയിലേക്ക് ഞാനിപ്പോഴും നോക്കുന്നതുപോലെയുണ്ട്. അതിൽ ''മുഹമ്മദുർറസൂലുല്ലാഹി'' എന്ന് കൊത്തിവെക്കപ്പെട്ടിരുന്നു. (ന)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 699, 699, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=95 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 233, 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: أَخَّرَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ صَلَاةَ الْعِشَاءِ الْآخِرَةِ حَتَّى مَضَى شَطْرُ اللَّيْلِ، ثُمَّ خَرَجَ فَصَلَّى بِنَا، كَأَنِّي أَنْظُرُ إِلَى بَيَاضِ خَاتَمِهِ فِي يَدِهِ مِنْ فِضَّةٍ. (ن)', 'അനസ്(റ): റസൂൽ(സ) ഇശാ നമസ്കാരം രാത്രിയുടെ പകുതി കഴിയുംവരെ പിന്തിപ്പിച്ചു. പിന്നെ പുറത്ത് വന്ന് ഞങ്ങൾക്ക് ഇമാമായി നിസ്കരിച്ചു. അപ്പോൾ അവിടത്തെ കൈയ്യിൽ വെള്ളിമോതിരത്തിന്റെ വെള്ള ഞാനിപ്പോഴും കാണുന്നപോലെയുണ്ട്. (ന)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 699, 699, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=95 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 234, 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "قَدِ اصْطَنَعْنَا خَاتَمًا وَنَقَشْنَا عَلَيْهِ نَقْشًا، فَلَا يَنْقُشْ عَلَيْهِ أَحَدٌ". (ن)', 'അനസ്(റ): റസൂൽ(സ) പറയുന്നു: "നാം ഒരു മോതിരമുണ്ടാക്കാൻ കൽപിച്ചു. അതിൽ ഒന്ന് കൊത്തിവെക്കുകയും ചെയ്തു. ഇനി അപ്രകാരം ആരും കൊത്തിവെക്കരുത്." (ന)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 699, 699, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=95 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 235, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: أَرَادَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ يَكْتُبَ إِلَى بَعْضِ الأَعَاجِمِ، فَقِيلَ لَهُ: إِنَّهُمْ لَا يَقْرَءُونَ كِتَابًا إِلَّا بِخَاتَمٍ، فَاتَّخَذَ خَاتَمًا مِنْ فِضَّةٍ، وَنَقَشَ فِيهِ: مُحَمَّدٌ رَسُولُ اللَّهِ. وفي رواية: فَكَانَ فِي يَدِهِ حَتَّى قُبِضَ، وَفِي يَدِ أَبِي بَكْرٍ حَتَّى قُبِضَ، وَفِي يَدِ عُمَرَ حَتَّى قُبِضَ، وَفِي يَدِ عُثْمَانَ، فَبَيْنَمَا هُوَ عِنْدَ بِئْرٍ إِذْ سَقَطَ فِي الْبِئْرِ، فَأَمَرَ بِهَا فَنُزِحَتْ، فَلَمْ يَقْدِرْ عَلَيْهِ. (ق،د،ت،ن،جه)', 'അനസുബ്‌നു മാലിക്(റ): ചില അനറബികൾക്ക് കത്തെഴുതാൻ റസൂൽ(സ) ഉദ്ദേശിച്ചു. അവർ മുദ്രയില്ലാത്ത എഴുത്ത് വായിക്കാറില്ല എന്ന് പറഞ്ഞപ്പോൾ റസൂൽ(സ) വെള്ളിയുടെ ഒരു മോതിരം ഉണ്ടാക്കി. അതിൽ ''മുഹമ്മദുർറസൂലുല്ലാഹി'' എന്നെഴുതി. മറ്റൊരു റിപ്പോർട്ടിൽ: അവിടന്ന് വഫാത്താകുന്നതുവരെ തൃക്കയ്യിൽ അതുണ്ടായിരുന്നു. ശേഷം അബൂബക്കർ(റ) വഫാത്താകുന്നതുവരെ അദ്ദേഹത്തിന്റെ കയ്യിലും പിന്നീട് ഉമർ(റ) വഫാത്താകുന്നതുവരെ അദ്ദേഹത്തിന്റെ കയ്യിലും അതുണ്ടായിരുന്നു. ശേഷം ഉസ്മാൻ(റ)വിന്റെ കയ്യിലായി. അങ്ങനെ ഉസ്മാൻ(റ) ഒരു കിണറിന്റെ അടുത്തിരിക്കുമ്പോൾ അത് കിണറ്റിലേക്ക് വീണു. അദ്ദേഹം കിണർ വറ്റിക്കാൻ കൽപിച്ചു. പക്ഷേ, മോതിരം കണ്ടെത്താനായില്ല. (ബു,മു,ദ,തു,ന,ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്‌നു മാലിക്(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 699, 700, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=96 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=8 and h.hadith_no=235), 1, 'وَفِي رِوَايَةٍ: فَكَانَ فِي يَدِهِ حَتَّى قُبِضَ، وَفِي يَدِ أَبِي بَكْرٍ حَتَّى قُبِضَ، وَفِي يَدِ عُمَرَ حَتَّى قُبِضَ، وَفِي يَدِ عُثْمَانَ، فَبَيْنَمَا هُوَ عِنْدَ بِئْرٍ إِذْ سَقَطَ فِي الْبِئْرِ، فَأَمَرَ بِهَا فَنُزِحَتْ، فَلَمْ يَقْدِرْ عَلَيْهِ. (ق،د،ت،ن،جه)', 'മറ്റൊരു നിവേദനിൽ: അവിടന്ന് വഫാത്താകുന്നതുവരെ തൃക്കയ്യിൽ അതുണ്ടായിരുന്നു. ശേഷം അബൂബക്കർ(റ) വഫാത്താകുന്നതുവരെ അദ്ദേഹത്തിന്റെ കയ്യിലും പിന്നീട് ഉമർ(റ) വഫാത്താകുന്നതുവരെ അദ്ദേഹത്തിന്റെ കയ്യിലും അതുണ്ടായിരുന്നു. ശേഷം ഉസ്മാൻ(റ)വിന്റെ കയ്യിലായി. അങ്ങനെ ഉസ്മാൻ(റ) ഒരു കിണറിന്റെ അടുത്തിരിക്കുമ്പോൾ അത് കിണറ്റിലേക്ക് വീണു. അദ്ദേഹം കിണർ വറ്റിക്കാൻ കൽപിച്ചു. പക്ഷേ, മോതിരം കണ്ടെത്താനായില്ല. (ബു,മു,ദ,തു,ന,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 236, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: اتَّخَذَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَاتَمًا مِنْ ذَهَبٍ، وَجَعَلَ فَصَّهُ مِمَّا يَلِي بَطْنَ كَفِّهِ، وَنَقَشَ فِيهِ: ''مُحَمَّدٌ رَسُولُ اللَّهِ''. فَاتَّخَذَ النَّاسُ خَوَاتِمَ الذَّهَبِ، فَلَمَّا رَآهُمْ قَدِ اتَّخَذُوهَا رَمَى بِهِ وَقَالَ: "لَا أَلْبَسُهُ أَبَدًا". ثُمَّ اتَّخَذَ خَاتَمًا مِنْ فِضَّةٍ نَقْشُ فِيهِ:''مُحَمَّدٌ رَسُولُ اللَّهِ''. وفي رواية: قَالَ: "لَا يَنْقُشْ أَحَدٌ عَلَى نَقْشِ خَاتَمِي هَذَا". ثُمَّ لَبِسَ الْخَاتَمَ بَعْدَهُ أَبُو بَكْرٍ، ثُمَّ لَبِسَهُ بَعْدَ أَبِي بَكْرٍ عُمَرُ، ثُمَّ لَبِسَهُ بَعْدَهُ عُثْمَانُ حَتَّى وَقَعَ فِي بِئْرِ أَرِيسٍ. وفي رواية: قَالَ: فَالْتَمَسُوهُ فَلَمْ يَجِدُوهُ، فَاتَّخَذَ عُثْمَانُ خَاتَمًا وَنَقَشَ فِيهِ: ''مُحَمَّدٌ رَسُولُ اللَّهِ''. قَالَ: فَكَانَ يَخْتِمُ بِهِ. أَوْ: يَتَخَتَّمُ بِهِ. (ق،د،ت،ن،جه)', 'ഇബ്‌നുഉമർ(റ): റസൂൽ(സ) ഒരു സ്വർണ്ണമോതിരമുണ്ടാക്കി. അതിന്റെ കല്ല് അവിടത്തെ കൈപ്പടത്തിനോടടുത്ത് വെച്ചു. അതിൽ ''മുഹമ്മദുർറസൂലുല്ലാഹി'' എന്ന് കൊത്തിവെക്കുകയും ചെയ്തു. അപ്പോൾ ജനങ്ങളും സ്വർണ്ണമോതിരമുണ്ടാക്കി. അത് കണ്ടപ്പോൾ റസൂൽ(സ) അവിടത്തെ മോതിരം വലിച്ചെറിഞ്ഞു. തിരുമേനി(സ) പറഞ്ഞു: "ഇത് ഒരിക്കലും ഞാൻ ധരിക്കുകയില്ല." പിന്നെ വെള്ളിമോതിരമുണ്ടാക്കി. അതിൽ ''മുഹമ്മദുർറസൂലുല്ലാഹി'' എന്ന് കൊത്തിവെച്ചു. മറ്റൊരു റിപ്പോർട്ടിൽ: അവിടന്ന് പറഞ്ഞു: "എന്റെ ഈ മോതിരത്തിന്റെ എഴുത്തു പോലെ ആരും കൊത്തിവെക്കരുത്." പിന്നെ, ആ മോതിരം അബൂബക്കർ(റ)വും അബൂബക്കർ(റ)ന് ശേഷം ഉമർ(റ)വും അത് ധരിച്ചു. അദ്ദേഹത്തിന്റെ ശേഷം ഉസ്മാൻ(റ) ധരിച്ചു. പിന്നീടത് ''അരീസ്'' എന്ന കിണറ്റിൽ വീണു. മറ്റൊരു റിപ്പോർട്ടിൽ: അവർ തെരച്ചിൽ നടത്തി. പക്ഷേ, കിട്ടിയില്ല. അപ്പോൾ ഉസ്മാൻ(റ) ഒരു മോതിരമുണ്ടാക്കുകയും അതിൽ ''മുഹമ്മദുർറസൂലുല്ലാഹി'' എന്ന് കൊത്തിവെക്കുകയും ചെയ്തു. നിവേദകൻ പറയുന്നു: പിന്നീടദ്ദേഹം അതായിരുന്നു ധരിച്ചിരുന്നത്. (ബു,മു,ദ,തു,ന,ജ)', 'ابْنِ عُمَرَ', 'ഇബ്‌നുഉമർ(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 700, 700, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=96 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=8 and h.hadith_no=236), 1, 'وَفِي رِوَايَةٍ: قَالَ: "لَا يَنْقُشْ أَحَدٌ عَلَى نَقْشِ خَاتَمِي هَذَا". ثُمَّ لَبِسَ الْخَاتَمَ بَعْدَهُ أَبُو بَكْرٍ، ثُمَّ لَبِسَهُ بَعْدَ أَبِي بَكْرٍ عُمَرُ، ثُمَّ لَبِسَهُ بَعْدَهُ عُثْمَانُ حَتَّى وَقَعَ فِي بِئْرِ أَرِيسٍ.', 'മറ്റൊരു നിവേദനിൽ: അവിടന്ന് പറഞ്ഞു: "എന്റെ ഈ മോതിരത്തിന്റെ എഴുത്തു പോലെ ആരും കൊത്തിവെക്കരുത്." പിന്നെ, ആ മോതിരം അബൂബക്കർ(റ)വും അബൂബക്കർ(റ)ന് ശേഷം ഉമർ(റ)വും അത് ധരിച്ചു. അദ്ദേഹത്തിന്റെ ശേഷം ഉസ്മാൻ(റ) ധരിച്ചു. പിന്നീടത് ''അരീസ്'' എന്ന കിണറ്റിൽ വീണു.');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=8 and h.hadith_no=236), 2, 'وَفِي رِوَايَةٍ: قَالَ: فَالْتَمَسُوهُ فَلَمْ يَجِدُوهُ، فَاتَّخَذَ عُثْمَانُ خَاتَمًا وَنَقَشَ فِيهِ: ''مُحَمَّدٌ رَسُولُ اللَّهِ''. قَالَ: فَكَانَ يَخْتِمُ بِهِ. أَوْ: يَتَخَتَّمُ بِهِ. (ق،د،ت،ن،جه)', 'മറ്റൊരു നിവേദനിൽ: അവർ തെരച്ചിൽ നടത്തി. പക്ഷേ, കിട്ടിയില്ല. അപ്പോൾ ഉസ്മാൻ(റ) ഒരു മോതിരമുണ്ടാക്കുകയും അതിൽ ''മുഹമ്മദുർറസൂലുല്ലാഹി'' എന്ന് കൊത്തിവെക്കുകയും ചെയ്തു. നിവേദകൻ പറയുന്നു: പിന്നീടദ്ദേഹം അതായിരുന്നു ധരിച്ചിരുന്നത്. (ബു,മു,ദ,തു,ന,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 237, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: اتَّخَذَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَاتَمَ الذَّهَبِ، فَلَبِسَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَاتَّخَذَ النَّاسُ خَوَاتِيمَ الذَّهَبِ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِنِّي كُنْتُ أَلْبَسُ هَذَا الْخَاتَمَ، وَإِنِّي لَنْ أَلْبَسَهُ أَبَدًا". فَنَبَذَهُ، فَنَبَذَ النَّاسُ خَوَاتِيمَهُمْ. (ن)', 'ഇബ്‌നുഉമർ(റ): റസൂൽ(സ) സ്വർണ്ണ മോതിരമുണ്ടാക്കി ധരിച്ചു. അപ്പോൾ ജനങ്ങളും സ്വർണ്ണ മോതിരങ്ങൾ ഉണ്ടാക്കി. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "ഞാൻ ഈ മോതിരം ധരിക്കാറുണ്ടായിരുന്നു. ഇനി ഞാനിത് ഒരിക്കലും ധരിക്കുകയില്ല." ശേഷം അത് വലിച്ചെറിഞ്ഞു. അപ്പോൾ ജനങ്ങളും അവരുടെ മോതിരങ്ങൾ വലിച്ചെറിഞ്ഞു. (ന)', 'ابْنِ عُمَرَ', 'ഇബ്‌നുഉമർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 700, 701, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=97 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 238, 'عَنْ عَلِيٍّ رَضِيَ اللَّهُ عَنْهُ قَالَ: نَهَانِي النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ خَاتَمِ الذَّهَبِ، وَعَنِ الْقَسِّيِّ، وَعَنِ الْمَيَاثِرِ الْحُمْرِ، وَعَنِ الْجِعَةِ. وَفِي رِوَايَةٍ قَالَ: نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ حَلْقَةِ الذَّهَبِ، وَعَنِ الْمِيثَرَةِ الْحَمْرَاءِ، وَعَنِ الثِّيَابِ الْقَسِّيَّةِ، وَعَنِ الْجِعَةِ: شَرَابٌ يُصْنَعُ مِنَ الشَّعِيرِ وَالْحِنْطَةِ. وَفِي رِوَايَةٍ قَالَ: نَهَانِي عَنِ الدُّبَّاءِ وَالْحَنْتَمِ وَحَلْقَةِ الذَّهَبِ، وَلُبْسِ الْحَرِيرِ وَالْقَسِّيِّ وَالْمِيثَرَةِ الْحَمْرَاءِ. وَفِي رِوَايَةٍ قَالَ: نَهَانَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الدُّبَّاءِ وَالْحَنْتَمِ وَحَلْقَةِ الذَّهَبِ، وَلُبْسِ الْحَرِيرِ، وَالْقَسِّيِّ وَالْمِيثَرَةِ الْحَمْرَاءِ. وَفِي رِوَايَةٍ قَالَ: نَهَانَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الدُّبَّاءِ وَالْحَنْتَمِ وَالنَّقِيرِ وَالْجِعَةِ، وَنَهَانَا عَنْ حَلْقَةِ - حَلْقِ - الذَّهَبِ وَلُبْسِ الْحَرِيرِ وَلُبْسِ الْقَسِّيِّ وَالْمِيثَرَةِ الْحَمْرَاءِ. (ن)', 'അലി(റ): സ്വർണ്ണമോതിരം, ഖസ്സിയ്യ് (ചണവും പട്ടും ഉപയോഗിച്ചുണ്ടാക്കിയ വസ്ത്രം), യാത്ര ചെയ്യുമ്പോൾ യാത്രികൻ അടിയിൽ വെക്കുന്ന ചുവന്ന ഇരിപ്പിടം, വീഞ്ഞ് എന്നിവ എനിക്ക് നബി(സ) നിരോധിച്ചിരിക്കുന്നു.
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=8 and h.hadith_no=238), 1, 'وَفِي رِوَايَةٍ قَالَ: نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ حَلْقَةِ الذَّهَبِ، وَعَنِ الْمِيثَرَةِ الْحَمْرَاءِ، وَعَنِ الثِّيَابِ الْقَسِّيَّةِ، وَعَنِ الْجِعَةِ: شَرَابٌ يُصْنَعُ مِنَ الشَّعِيرِ وَالْحِنْطَةِ.', 'മറ്റൊരു നിവേദനം: റസൂൽ(സ) സ്വർണ്ണത്തിന്റെ പടയങ്കിയും യാത്രക്കാരൻ താഴെ വെക്കുന്ന ചുവന്ന ഇരിപ്പിടവും ഖസ്സിയ്യ് വസ്ത്രങ്ങളും ജിഅതും - ബാർളിയും ഗോതമ്പും ചേർത്തുണ്ടാക്കുന്ന ഒരു പാനീയം - നിരോധിച്ചിരിക്കുന്നു.');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=8 and h.hadith_no=238), 2, 'وَفِي رِوَايَةٍ قَالَ: نَهَانِي عَنِ الدُّبَّاءِ وَالْحَنْتَمِ وَحَلْقَةِ الذَّهَبِ، وَلُبْسِ الْحَرِيرِ وَالْقَسِّيِّ وَالْمِيثَرَةِ الْحَمْرَاءِ.', 'മറ്റൊരു നിവേദനം: തണ്ടില്ലാത്ത ചെടിയിൽ നിന്നും ഉണ്ടാക്കിയ പാത്രവും (ചുരങ്ങാത്തോട് പോലെ) പച്ചച്ചായം തേച്ച പാത്രവും സ്വർണ്ണത്തിന്റെ പടയങ്കിയും പട്ട്, ഖസ്സിയ്യ് എന്നിവ ധരിക്കലും, യാത്രക്കാരൻ അടിയിൽ വെക്കുന്ന ചുവന്ന ഇരിപ്പിടം ഉപയോഗിക്കലും എനിക്ക് നിരോധിച്ചിരിക്കുന്നു.');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=8 and h.hadith_no=238), 3, 'وَفِي رِوَايَةٍ قَالَ: نَهَانَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الدُّبَّاءِ وَالْحَنْتَمِ وَحَلْقَةِ الذَّهَبِ، وَلُبْسِ الْحَرِيرِ، وَالْقَسِّيِّ وَالْمِيثَرَةِ الْحَمْرَاءِ.', 'മറ്റൊരു നിവേദനം: തണ്ടില്ലാത്ത ചെടിയിൽ നിന്നും ഉണ്ടാക്കിയ പാത്രവും പച്ചച്ചായം തേച്ച പാത്രവും സ്വർണ്ണപ്പടയങ്കിയും പട്ട് ഖസിയ്യ് എന്നിവ ധരിക്കലും യാത്ര ചെയ്യുന്നവൻ വെക്കുന്ന ചുവന്ന ഇരിപ്പിടം ഉപയോഗിക്കലും ഞങ്ങൾക്ക് റസൂൽ(സ) നിരോധിച്ചിരിക്കുന്നു.');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=8 and h.hadith_no=238), 4, 'وَفِي رِوَايَةٍ قَالَ: نَهَانَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الدُّبَّاءِ وَالْحَنْتَمِ وَالنَّقِيرِ وَالْجِعَةِ، وَنَهَانَا عَنْ حَلْقَةِ - حَلْقِ - الذَّهَبِ وَلُبْسِ الْحَرِيرِ وَلُبْسِ الْقَسِّيِّ وَالْمِيثَرَةِ الْحَمْرَاءِ. (ن)', 'മറ്റൊരു നിവേദന്: തണ്ടില്ലാത്ത ചെടിയിൽ നിന്നുമുണ്ടാക്കിയ പാത്രവും പച്ചച്ചായം തേച്ച പാത്രവും മരം കുഴിച്ചുണ്ടാക്കിയ പാത്രവും ''ജിഅതും'' റസൂൽ(സ) ഞങ്ങൾക്ക് നിരോധിച്ചിരിക്കുന്നു. സ്വർണ്ണത്തിന്റെ പടയങ്കിയും പട്ട് ധരിക്കലും ഖസ്സിയ്യ് ധരിക്കലും യാത്രക്കാരൻ അടിയിൽ വെക്കുന്ന ചുവന്ന ഇരിപ്പിടവും ഞങ്ങൾക്ക് നിരോധിച്ചിരിക്കുന്നു. (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 239, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا، عَنْ عَلِيٍّ رَضِيَ اللَّهُ عَنْهُ قَالَ: نَهَانِي حِبِّي صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ ثَلَاثٍ، لَا أَقُولُ نَهَى النَّاسَ: نَهَانِي عَنْ تَخَتُّمِ الذَّهَبِ، وَعَنْ لُبْسِ الْقَسِّيِّ وَعَنِ الْمُعَصْفَرِ الْمُفَدَّمَةِ، وَلَا أَقْرَأُ سَاجِدًا وَلَا رَاكِعًا. (ن)', 'ഇബ്നുഅബ്ബാസ്(റ): അലി(റ) പറയുന്നു: എന്റെ സ്നേഹഭാജനം റസൂൽ(സ) മൂന്ന് കാര്യങ്ങൾ എനിക്ക് നിരോധിച്ചിരിക്കുന്നു, ജനങ്ങൾക്ക് നിരോധിച്ചിരിക്കുന്നുവെന്ന് ഞാൻ പറയുന്നില്ല, സ്വർണ്ണമോതിരം, ഖസ്സിയ്യും ശക്തമായ ചായം മുക്കപ്പെട്ട വസ്ത്രവും ധരിക്കൽ, റുകൂഇലോ സുജൂദിലോ ഖുർആൻ ഓതൽ എന്നിവയാണവ. (ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 701, 701, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=97 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 240, 'عَنْ عِمْرَانَ رَضِيَ اللَّهُ عَنْهُ قَالَ: نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ لُبْسِ الْحَرِيرِ، وَعَنِ التَّخَتُّمِ بِالذَّهَبِ، وَعَنِ الشُّرْبِ فِي الْحَنَاتِمِ. (ن)', 'ഇംറാൻ(റ): പട്ട് ധരിക്കൽ, സ്വർണ്ണമോതിരം ധരിക്കൽ, പച്ചച്ചായം തേച്ച പാത്രത്തിൽ വെള്ളം കുടിക്കൽ എന്നിവ റസൂൽ(സ) നിരോധിച്ചിരിക്കുന്നു. (ന)', 'عِمْرَانَ', 'ഇംറാൻ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 701, 702, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=97 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 241, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ: أَنَّ رَجُلًا قَدِمَ مِنْ نَجْرَانَ إِلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَعَلَيْهِ خَاتَمٌ مِنْ ذَهَبٍ، فَأَعْرَضَ عَنْهُ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَقَالَ: "إِنَّكَ جِئْتَنِي وَفِي يَدِكَ جَمْرَةٌ مِنْ نَارٍ". (ن)', 'അബൂസഈദുൽ ഖുദ്‌രി(റ): നജ്‌റാനിൽ നിന്ന് ഒരാൾ റസൂൽ(സ)യുടെ സന്നിധിയിലേക്ക് വന്നു. അദ്ദേഹത്തിന്റെ കയ്യിൽ ഒരു സ്വർണ്ണമോതിരവുമുണ്ടായിരുന്നു, അപ്പോൾ റസൂൽ(സ) അയാളിൽ നിന്ന് മുഖം തിരിച്ചിരുന്നു. എന്നിട്ട് പറഞ്ഞു: "താങ്കൾ എന്റെയടുത്ത് വന്നത് നരകത്തിലെ ഒരു തീകട്ട കയ്യിലിട്ടുകൊണ്ടാണ്." (ന)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദുൽ ഖുദ്‌രി(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 702, 702, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=97 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 242, 'عَنِ الْبَرَاءِ بْنِ عَازِبٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَجُلًا كَانَ جَالِسًا عِنْدَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَعَلَيْهِ خَاتَمٌ مِنْ ذَهَبٍ، وَفِي يَدِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مِخْصَرَةٌ أَوْ جَرِيدَةٌ، فَضَرَبَ بِهَا النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِصْبَعَهُ، فَقَالَ الرَّجُلُ: مَا لِي يَا رَسُولَ اللهِ؟ قَالَ: "أَلَا تَطْرَحُ هَذَا الَّذِي فِي إِصْبَعِكَ". فَأَخَذَهُ الرَّجُلُ فَرَمَى بِهِ، فَرَآهُ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بَعْدَ ذَلِكَ فَقَالَ: "مَا فَعَلَ الْخَاتَمُ". قَالَ: رَمَيْتُ بِهِ. قَالَ: "مَا بِهَذَا أَمَرْتُكَ، إِنَّمَا أَمَرْتُكَ أَنْ تَبِيعَهُ فَتَسْتَعِينَ بِثَمَنِهِ". (ن)', 'ബറാഉബ്നു ആസിബ്(റ): ഒരാൾ നബി(സ)യുടെ അടുത്ത് ഇരിക്കുകയായിരുന്നു. അയാളുടെ കയ്യിൽ ഒരു സ്വർണ്ണമോതിരവും, റസൂലുല്ലാഹി(സ)യുടെ തിരുകരങ്ങളിൽ ഒരു കുന്തവും, അല്ലെങ്കിൽ, ഇലകളഞ്ഞ ഒരു ഈത്തപ്പന വടിയുമുണ്ടായിരുന്നു. അപ്പോൾ അദ്ദേഹത്തിന്റെ വിരലിൽ നബി(സ) അതുകൊണ്ടടിച്ചു. അപ്പോൾ അദ്ദേഹം ചോദിച്ചു: ഞാനെന്താണ് ചെയ്തത് തിരുദൂതരേ?, അവിടുന്ന് പറഞ്ഞു: "താങ്കളുടെ വിരലിലുള്ള ഇത് കളയുന്നില്ലേ?" ഉടനെ അദ്ദേഹം അതെടുത്ത് എറിഞ്ഞു. അതിന് ശേഷം നബി(സ) അദ്ദേഹത്തെ കണ്ടു. അപ്പോൾ തിരുമേനി(സ) ചോദിച്ചു: "ആ മോതിരം എന്ത് ചെയ്തു?" അദ്ദേഹം പറഞ്ഞു: ഞാൻ അത് എറിഞ്ഞുകളഞ്ഞു. റസൂൽ(സ) പറഞ്ഞു: "ഇതല്ല ഞാൻ നിങ്ങളോട് പറഞ്ഞത്, അത് വിറ്റ് അതിന്റെ മൂല്യം ഉപകാരപ്പെടുത്താനായിരുന്നു ഞാൻ പറഞ്ഞത്." (ന)', 'الْبَرَاءِ بْنِ عَازِبٍ', 'ബറാഉബ്നു ആസിബ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 702, 702, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=97 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 243, 'عَنْ أَبِي ثَعْلَبَةَ الْخُشَنِيِّ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَبْصَرَ فِي يَدِهِ خَاتَمًا مِنْ ذَهَبٍ، فَجَعَلَ يَقْرَعُهُ بِقَضِيبٍ مَعَهُ، فَلَمَّا غَفَلَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَلْقَاهُ، قَالَ: "مَا أُرَانَا إِلَّا قَدْ أَوْجَعْنَاكَ وَأَغْرَمْنَاكَ". (ن)', 'അബൂസഅ്‌ലബതുൽ ഖുശനി(റ): നബി(സ) അദ്ദേഹത്തിന്റെ കയ്യിൽ ഒരു സ്വർണ്ണ മോതിരം കണ്ടു. അപ്പോൾ തിരുമേനി(സ) അവിടത്തെപ്പക്കലുണ്ടായിരുന്ന വടികൊണ്ട് അദ്ദേഹത്തെ അടിക്കാൻ തുടങ്ങി. അങ്ങനെ നബി(സ) അതിനെക്കുറിച്ച് അശ്രദ്ധരായപ്പോൾ അദ്ദേഹം അത് ഇട്ടുകളഞ്ഞു. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "നാം താങ്കളെ വേദനിപ്പിക്കുകയും, കടക്കാരനാക്കുകയുമല്ലാതെ ഒന്നും ചെയ്തില്ല." (ന)', 'أَبِي ثَعْلَبَةَ الْخُشَنِيِّ', 'അബൂസഅ്‌ലബതുൽ ഖുശനി(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 702, 702, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=97 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 244, 'عَنْ عَبْدِ اللهِ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ نَبِيُّ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَكْرَهُ عَشْرَ خِصَالٍ: الصُّفْرَةَ - يَعْنِي الْخَلُوقَ - وَتَغْيِيرَ الشَّيْبِ، وَجَرَّ الْإِزَارِ، وَالتَّخَتُّمَ بِالذَّهَبِ، وَالتَّبَرُّجَ بِالزِّينَةِ لِغَيْرِ مَحَلِّهَا، وَالضَّرْبَ بِالْكِعَابِ، وَالرُّقَى إِلَّا بِالْمُعَوَّذَاتِ، وَعَقْدَ التَّمَائِمِ، وَعَزْلَ الْمَاءِ لِغَيْرِ - أَوْ: غَيْرِمَحَلِّهِ، أَوْ: عَنْ - مَحَلِّهِ، وَفَسَادَ الصَّبِيِّ، غَيْرَ مُحَرَّمِهِ. (د،ن)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): നബി(സ) പത്ത് കാര്യങ്ങൾ വെറുത്തിരുന്നു: മഞ്ഞച്ചായം, - അഥവാ ഖലൂഖ് - നരയ്ക്ക് ചായം നൽകൽ, തുണി ഞെരിയാണിക്ക് താഴെ വലിച്ചിഴക്കൽ, സ്വർണ്ണമോതിരം ധരിക്കൽ, ഭംഗിയിൽ ചമഞ്ഞ് അനുവദനീയമല്ലാത്തവരുടെ മുമ്പിൽ പ്രത്യക്ഷപ്പെടൽ, പകിട എറിയൽ, മുഅവ്വിദാതുകൾ കൊണ്ടല്ലാതെ മന്ത്രിക്കൽ, ഏലസ്സുകൾ തൂക്കിയിടൽ, (സംയോഗ സമയത്ത്) ഇന്ദ്രിയം (അകത്ത് പ്രവേശിക്കാതിരിക്കാൻ) അതിന്റെ സ്ഥാനത്ത് നിന്ന് തെറ്റിച്ച് വിടൽ, മുലകുടിക്കുന്ന കുട്ടിയുണ്ടായിരിക്കെ ഭാര്യയെ ഗർഭം ധരിപ്പിച്ച് കുട്ടിക്ക് നാശം വരുത്തൽ. ഇത് നിഷിദ്ധമല്ലെങ്കിലും. (ദ,ന)', 'عَبْدِ اللهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 702, 703, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=97 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 245, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُ ، عَنْ عَلِيٍّ كَرَّمَ اللَّهُ وَجْهَهُ قَالَ: نَهَانِي النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ خَاتَمِ الذَّهَبِ، وَأَنْ أَقْرَأَ الْقُرْآنَ وَأَنَا رَاكِعٌ، وَعَنِ الْقَسِّيِّ، وَعَنِ الْمُعَصْفَرِ. (ن)', 'ഇബ്നുഅബ്ബാസ്(റ): അലി(റ) പറയുന്നു: സ്വർണ്ണമോതിരം, റുകൂഇൽ നിൽക്കെ ഖുർആൻ ഓതൽ, ഖസ്സിയ്യ് വസ്ത്രം, മഞ്ഞച്ചായം മുക്കപ്പെട്ടത് എന്നിവ നബി(സ) എനിക്ക് നിരോധിച്ചിരിക്കുന്നു. (ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 703, 703, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=97 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 246, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: أُهْدِيَ النَّجَاشِيُّ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَلْقَةً فِيهَا خَاتَمُ ذَهَبٍ، فِيهِ فَصٌّ حَبَشِيٌّ، فَأَخَذَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِعُودٍ وَإِنَّهُ لَمُعْرِضٌ عَنْهُ، أَوْ بِبَعْضِ أَصَابِعِهِ، ثُمَّ دَعَا ابْنَةَ ابْنَتِهِ أُمَامَةَ ابْنَةَ أَبِي الْعَاصِ، فَقَالَ: "تَحَلَّيْ بِهَذَا يَا بُنَيَّةُ". (د،جه)', 'ആഇശ(റ): റസൂൽ(സ)ക്ക് നജാശി ഒരു പടയങ്കി കൊടുത്തയച്ചു. അതിൽ ഒരു സ്വർണ്ണ മോതിരവും ഉണ്ടായിരുന്നു. അതിന്റെ കല്ല് ഹബ്ശിയായിരുന്നു (അബ്സീനിയയിലെ ഒരു കല്ല്). അപ്പോൾ റസൂൽ(സ) മുഖം തിരിച്ച് അത് ഒരു വടികൊണ്ട്, അല്ലെങ്കിൽ ചില വിരലുകൾ കൊണ്ട് എടുത്തു. ശേഷം അവിടുത്തെ മകളുടെ മകളായ ഉമാമതുബ്നതു അബിൽആസ്(റ)യെ വിളിച്ച് പറഞ്ഞു: "എന്റെ പൊന്നുമോളേ, നീ ഇത് ആഭരണമായി ഉപയോഗിക്കുക." (ദ,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 703, 703, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=97 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 247, 'عَنِ الْبَرَاءِ بْنِ عَازِبٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: أَمَرَنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِسَبْعٍ، وَنَهَانَا عَنْ سَبْعٍ: أَمَرَنَا بِعِيَادَةِ الْمَرِيضِ، وَاتِّبَاعِ الْجَنَائِزِ، وَتَشْمِيتِ الْعَاطِسِ، وَإِبْرَارِ الْقَسَمِ أَوِ الْمُقْسِمِ، وَنَصْرِ الْمَظْلُومِ، وَإِجَابَةِ الدَّاعِي، وَإِفْشَاءِ السَّلَامِ. وَنَهَانَا عَنْ خَوَاتِيمَ - أَوْ: عَنْ تَخَتُّمٍ - بِالذَّهَبِ وَعَنْ شُرْبٍ بِالْفِضَّةِ، وَعَنِ الْمَيَاثِرِ، وَعَنِ الْقَسِّيِّ، وَعَنْ لُبْسِ الْحَرِيرِ، وَالْإِسْتَبْرَقِ، وَالدِّيبَاجِ. (م)', 'ബറാഉബ്നു ആസിബ്(റ): റസൂൽ(സ) ഞങ്ങളോട് ഏഴ് കാര്യങ്ങൾ കൽപ്പിച്ചു. ഏഴെണ്ണം ഞങ്ങൾക്ക് നിരോധിക്കുകയും ചെയ്തു. രോഗിയെ സന്ദർശിക്കൽ, ജനാസയെ അനുഗമിക്കൽ, തുമ്മിയവനെ അനുമോദിക്കൽ, സത്യം പാലിക്കൽ, അക്രമിക്കപ്പെട്ടവനെ സഹായിക്കൽ, ക്ഷണിച്ചവന് ഉത്തരം നൽകൽ, സലാം വ്യാപിപ്പിക്കൽ എന്നിവ ഞങ്ങളോട് അവിടുന്ന് കൽപ്പിച്ചു; സ്വർണ്ണമോതിരം ധരിക്കൽ, വെള്ളിപ്പാത്രത്തിൽ കുടിക്കൽ, ജീനിയിൽ വിരിക്കുന്ന പട്ടും ചണവും ഉപയോഗിച്ച് നെയ്തുണ്ടാക്കുന്ന ചുവന്ന വസ്ത്രം, ഖസ്സിയ്യ് (ചണവും പട്ടും ഉപയോഗിച്ചുണ്ടാക്കുന്ന ഒരുതരം വസ്ത്രം), ഹരീറും ഇസ്തബ്റഖും ദീബാജും (പട്ടിന്റെ മൂന്നിനങ്ങൾ) ധരിക്കൽ എന്നിവ ഞങ്ങൾക്ക് അവിടുന്ന് നിരോധിക്കുകയും ചെയ്തു. (മു)', 'الْبَرَاءِ بْنِ عَازِبٍ', 'ബറാഉബ്നു ആസിബ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 703, 703, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=98 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 248, 'عَنْ سَعِيدِ بْنِ الْمُسَيَّبِ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ عُمَرُ رَضِيَ اللَّهُ عَنْهُ لِصُهَيْبٍ رَضِيَ اللَّهُ عَنْهُ: مَا لِي أَرَى عَلَيْكَ خَاتَمَ الذَّهَبِ؟ قَالَ: قَدْ رَآهُ مَنْ هُوَ خَيْرٌ مِنْكَ فَلَمْ يَعِبْهُ. قَالَ: مَنْ هُوَ؟ قَالَ: رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. (ن)', 'സഈദുബ്നുൽ മുസയ്യബ്(റ): ഉമർ(റ) സുഹൈബ്(റ)വിനോട് ചോദിച്ചു: നിങ്ങളുടെയടുത്ത് ഒരു സ്വർണ്ണമോതിരം ഞാൻ കാണുന്നുണ്ടല്ലോ? അദ്ദേഹം പറഞ്ഞു: താങ്കളെക്കാൾ ഉത്തമരായവർ അത് കണ്ടിട്ടുണ്ട്, എന്നിട്ട് ഒരു ആക്ഷേപവും പറഞ്ഞിട്ടില്ല. ഉമർ(റ) ചോദിച്ചു: ആരാണത്? അദ്ദേഹം പറഞ്ഞു: അല്ലാഹുവിന്റെ തിരുദൂതർ(സ). (ന)', 'سَعِيدِ بْنِ الْمُسَيَّبِ', 'സഈദുബ്നുൽ മുസയ്യബ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 704, 704, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=99 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 249, 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَانَ خَاتَمُ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنْ وَرِقٍ، وَكَانَ فَصُّهُ حَبَشِيًّا. حَسَنٌ صَحِيحٌ. (ق,د,ت,ن,جه)', 'അനസ്(റ): നബി(സ)യുടെ മോതിരം വെള്ളിയായിരുന്നു. അതിന്റെ കല്ല് ഹബ്ശിയുമായിരുന്നു (അബ്സീനിയായിലെ ഒരു കല്ല്). ഹദീസ് ഹസനും സ്വഹീഹുമാണ്. (ബു,മു,ദ,തു,ന,ജ)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 704, 704, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=100 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 250, 'عَنْ بُرَيْدَةَ رضي الله عنه: أَنَّ رَجُلًا جَاءَ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَعَلَيْهِ خَاتَمٌ مِنْ حَدِيدٍ، فَقَالَ: "مَا لِي أَرَى عَلَيْكَ حِلْيَةَ أَهْلِ النَّارِ". فَطَرَحَهُ ثُمَّ جَاءَهُ وَعَلَيْهِ خَاتَمٌ مِنْ شَبَهِ، فَقَالَ: "مَا لِي أَجِدُ مِنْكَ رِيحَ الْأَصْنَامِ". فَطَرَحَهُ، قَالَ: يَا رَسُولَ اللَّهِ، مِنْ أَيِّ شَيْءٍ أَتَّخِذُهُ؟ قَالَ: "مِنْ وَرِقٍ، وَلَا تُتِمَّهُ مِثْقَالًا". (ن)', 'ബുറൈദ(റ): ഒരാൾ നബി(സ)യുടെ തിരുസന്നിധിയിൽ വന്നു. അദ്ദേഹത്തിന്റെ (കയ്യിൽ) ഇരുമ്പ് മോതിരമുണ്ടായിരുന്നു. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "താങ്കളുടെ മേൽ നരകവാസികളുടെ ആഭരണം ഞാൻ കാണുന്നുണ്ടല്ലോ?" ഉടനെ അദ്ദേഹം അത് വലിച്ചെറിഞ്ഞു. പിന്നെ പിച്ചളയുടെ മോതിരവുമായി അദ്ദേഹം വന്നു. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "താങ്കളിൽ ഞാൻ ബിംബങ്ങളുടെ വാസനയെത്തിക്കുന്നു." ഉടനെ അദ്ദേഹമത് വലിച്ചെറിഞ്ഞു. എന്നിട്ട് ചോദിച്ചു: തിരുദൂതരേ, ഞാൻ എന്തുപയോഗിച്ചാണ് മോതിരം ഉണ്ടാക്കേണ്ടത്? അവിടന്ന് പറഞ്ഞു: "വെള്ളിയുപയോഗിച്ച്, അത് ഒരു മിസ്ഖാൽ (ഒന്നര ദിർഹം തൂക്കം) തികയരുത്." (ന)', 'بُرَيْدَةَ', 'ബുറൈദ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 704, 704, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=101 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 251, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: اتَّخَذَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَاتَمًا مِنْ وَرِقٍ، فَكَانَ فِي يَدِهِ، ثُمَّ كَانَ فِي يَدِ أَبِي بَكْرٍ رَضِيَ اللَّهُ عَنْهُ، ثُمَّ كَانَ فِي يَدِ عُمَرَ رَضِيَ اللَّهُ عَنْهُ، ثُمَّ كَانَ فِي يَدِ عُثْمَانَ رَضِيَ اللَّهُ عَنْهُ، حَتَّى وَقَعَ مِنْهُ فِي بِئْرِ أَرِيسٍ، نَقْشُهُ: مُحَمَّدٌ رَسُولُ اللَّهِ. (م)', 'ഇബ്‌നുഉമർ(റ): റസൂൽ(സ) ഒരു വെള്ളിമോതിരമുണ്ടാക്കി. അത് അവിടുത്തെ കയ്യിലിട്ടിരുന്നു. പിന്നീട് അബൂബക്കർ(റ)വിന്റെ കയ്യിലും, ശേഷം ഉമർ(റ)വിന്റെ കയ്യിലുമായിരുന്നു. പിന്നീട് ''അരീസ്'' കിണറ്റിൽ വീഴുന്നത് വരെ അത് ഉസ്മാൻ(റ)വിന്റെ കയ്യിലായിരുന്നു. അതിൽ കൊത്തിവെക്കപ്പെട്ടത് ''മുഹമ്മദുർറസൂലുല്ലാഹി'' എന്നായിരുന്നു. (മു)', 'ابْنِ عُمَرَ', 'ഇബ്‌നുഉമർ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 704, 705, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=102 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 252, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ اتَّخَذَ خَاتَمًا مِنْ فِضَّةٍ، وَنَقَشَ فِيهِ مُحَمَّدٌ رَسُولُ اللَّهِ، وَقَالَ لِلنَّاسِ: "إِنِّي اتَّخَذْتُ خَاتَمًا مِنْ فِضَّةٍ، وَنَقَشْتُ فِيهِ مُحَمَّدٌ رَسُولُ اللَّهِ، فَلَا يَنْقُشْ أَحَدٌ عَلَى نَقْشِهِ". (م)', 'അനസുബ്‌നു മാലിക്(റ): നബി(സ) ഒരു വെള്ളിമോതിരമുണ്ടാക്കി. അതിൽ ''മുഹമ്മദുർറസൂലുല്ലാഹി'' എന്ന് കൊത്തിവെച്ചു. എന്നിട്ട് ജനങ്ങളോട് പറഞ്ഞു: "ഞാൻ ഒരു വെള്ളിമോതിരമുണ്ടാക്കി, അതിൽ ''മുഹമ്മദുർറസൂലുല്ലാഹി'' എന്ന് കൊത്തിവെച്ചിട്ടുണ്ട്. ഇനിയാരും തന്നെ മുഹമ്മദുർറസൂലുല്ലാഹി എന്ന് തന്റെ മോതിരത്തിൽ കൊത്തിവെക്കരുത്." (മു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്‌നു മാലിക്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 705, 705, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=102 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 253, 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَرَادَ أَنْ يَكْتُبَ إِلَى كِسْرَى وَقَيْصَرَ وَالنَّجَاشِيِّ، فَقِيلَ: إِنَّهُمْ لَا يَقْبَلُونَ كِتَابًا إِلَّا بِخَاتَمٍ، فَصَاغَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَاتَمًا حَلْقَتُهُ فِضَّةٌ، وَنَقَشَ فِيهِ: مُحَمَّدٌ رَسُولُ اللَّهِ. (م)', 'അനസ്(റ): നബി(സ) കിസ്‌റ, കൈസർ, നജാശി എന്നിവരിലേക്ക് കത്തെഴുതാൻ ഉദ്ദേശിച്ചപ്പോൾ പറയപ്പെട്ടു: അവർ മുദ്രയില്ലാത്ത എഴുത്ത് സ്വീകരിക്കുകയില്ല. അപ്പോൾ റസൂൽ(സ) ഒരു മോതിരമുണ്ടാക്കി. അതിന്റെ കണ്ണി വെള്ളിയായിരുന്നു. അതിൽ ''മുഹമ്മദുർറസൂലുല്ലാഹി'' എന്ന് കൊത്തിവെച്ചു. (മു)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 705, 705, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=102 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 254, 'عَنِ الْمُعَيْقِيبِ بْنِ أَبِي فَاطِمَةَ الدَّوْسِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَانَ خَاتَمُ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنْ حَدِيدٍ، مَلْوِيٌّ عَلَيْهِ فِضَّةٌ، قَالَ: فَرُبَّمَا كَانَ فِي يَدِي قَالَ: وَكَانَ الْمُعَيْقِيبُ عَلَى خَاتَمِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ . (د,ن)', 'മുഅയ്‌ഖീബുബ്‌നു അബീഫാത്തിമതിദ്ദൗസീ(റ): നബി(സ)യുടെ മോതിരം വെള്ളിയിൽ പൊതിഞ്ഞു, ഇരുമ്പിന്റേതായിരുന്നു. ചിലപ്പോൾ അത് എന്റെ കൈയിലാവും. നിവേദകൻ പറയുന്നു: മുഅയ്‌ഖീബ് നബി(സ)യുടെ മോതിരത്തിന്റെ ഉത്തരവാദിത്തമുള്ള ആളായിരുന്നു. (ദ,ന)', 'الْمُعَيْقِيبِ بْنِ أَبِي فَاطِمَةَ الدَّوْسِيِّ', 'മുഅയ്‌ഖീബുബ്‌നു അബീഫാത്തിമതിദ്ദൗസീ(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 705, 705, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=103 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 255, 'عَنْ بُرَيْدَةَ رضي اللَّهُ عَنْهُ قَالَ: جَاءَ رَجُلٌ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَعَلَيْهِ خَاتَمٌ مِنْ حَدِيدٍ، فَقَالَ: "مَا لِي أَرَى عَلَيْكَ حِلْيَةَ أَهْلِ النَّارِ". ثُمَّ جَاءَهُ وَعَلَيْهِ خَاتَمٌ مِنْ صُفْرٍ، فَقَالَ: "مَا لِي أَجِدُ مِنْكَ رِيحَ الْأَصْنَامِ". ثُمَّ أَتَاهُ وَعَلَيْهِ خَاتَمٌ مِنْ ذَهَبٍ. فَقَالَ: "ارْمِ عَنْكَ حِلْيَةَ أَهْلِ الْجَنَّةِ". قَالَ: مِنْ أَيِّ شَيْءٍ أَتَّخِذُهُ؟ قَالَ: "مِنْ وَرِقٍ، وَلَا تُتِمَّهُ مِثْقَالًا". (د,ت)', 'ബുറൈദ(റ): നബി(സ)യുടെ തിരുസന്നിധിയിൽ ഒരാൾ വന്നു. അയാളുടെ പക്കൽ ഒരു ഇരുമ്പ് മോതിരവുമുണ്ട്. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങളിൽ നരകവാസികളുടെ ആഭരണം ഞാൻ കാണുന്നല്ലോ." പിന്നെ അയാൾ പിച്ചള കൊണ്ടുള്ള ഒരു മോതിരവുമായി വന്നപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങളിൽ ബിംബത്തിന്റെ വാസന ഞാൻ എത്തിക്കുന്നു." പിന്നെ സ്വർണ്ണമോതിരവുമായി വന്നപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "സ്വർഗ്ഗവാസികളുടെ ആഭരണങ്ങൾ നിങ്ങൾ വലിച്ചെറിയുക." അദ്ദേഹം ചോദിച്ചു: എന്തിൽ നിന്നാണ് ഞാൻ മോതിരമുണ്ടാക്കേണ്ടത്? അവിടന്ന് പറഞ്ഞു: "വെള്ളിയിൽ നിന്ന്, അത് ഒരു മിസ്ഖാൽ (ഒന്നര ദിർഹമിന്റെ തൂക്കം) തികയരുത്." (ദ,തു)', 'بُرَيْدَةَ', 'ബുറൈദ(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 705, 706, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=103 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 256, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: أَقْبَلَ رَجُلٌ مِنَ الْبَحْرَيْنِ إِلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَسَلَّمَ فَلَمْ يَرُدَّ عَلَيْهِ، وَكَانَ فِي يَدِهِ خَاتَمٌ مِنْ ذَهَبٍ، وَجُبَّةُ حَرِيرٍ، فَأَلْقَاهُمَا ثُمَّ سَلَّمَ، فَرَدَّ عَلَيْهِ السَّلَامَ، ثُمَّ قَالَ: يَا رَسُولَ اللهِ، أَتَيْتُكَ آنِفًا، فَأَعْرَضْتَ عَنِّي؟ فَقَالَ: "إِنَّهُ كَانَ فِي يَدِكَ جَمْرَةٌ مِنْ نَارٍ". قَالَ: لَقَدْ جِئْتُ إِذًا بِجَمْرٍ كَثِيرٍ قَالَ: "مَا جِئْتَ بِهِ لَيْسَ بِأَجْزَأَ عَنَّا مِنْ حِجَارَةِ الْحَرَّةِ، وَلَكِنَّهُ مَتَاعُ الْحَيَاةِ الدُّنْيَا". قَالَ: فَمَاذَا أَتَّخِذُ؟ قَالَ: "حَلْقَةً مِنْ حَدِيدٍ، أَوْ وَرِقٍ، أَوْ صُفْرٍ". (ن)', 'അബൂസഈദുൽ ഖുദ്‌രി(റ): ബഹ്‌റൈനിൽ നിന്നൊരാൾ നബി(സ)യുടെ സന്നിധിയിൽ വന്നു സലാം പറഞ്ഞു. പക്ഷേ, തിരുമേനി(സ) സലാം മടക്കിയില്ല. അദ്ദേഹത്തിന്റെ കയ്യിൽ സ്വർണ്ണമോതിരവും പട്ടു ജുബ്ബയുമുണ്ടായിരുന്നു. പിന്നീടയാൾ അവ താഴെവെച്ച് വീണ്ടും സലാം പറഞ്ഞു. അന്നേരം അവിടന്ന് സലാം മടക്കുകയും ചെയ്തു. അപ്പോൾ അദ്ദേഹം ചോദിച്ചു: തിരുദൂതരേ, അൽപം മുമ്പ് ഞാൻ വന്നപ്പോൾ അവിടന്ന് മുഖം തിരിച്ചുകളഞ്ഞല്ലോ? അപ്പോൾ തിരുമേനി(സ) പറഞ്ഞു: "കാരണം, നിങ്ങളുടെ കയ്യിൽ നരകത്തിലെ തീക്കട്ടയുണ്ടായിരുന്നു." അദ്ദേഹം പറഞ്ഞു: ഇപ്പോൾ ഞാൻ ധാരാളം തീക്കട്ടകളുമായി വന്നിരിക്കുന്നു. തിരുമേനി(സ) പറഞ്ഞു: "നിങ്ങൾ കൊണ്ടുവന്നത് ''ഹർറ''യിലെ കല്ലിനേക്കാൾ വിലമതിക്കുന്നതല്ല. നിശ്ചയം അവ ഈ ജീവിതത്തിന്റെ സുഖങ്ങളാകുന്നു." അദ്ദേഹം ചോദിച്ചു: അപ്പോൾ ഞാൻ എന്ത് മോതിരം ധരിക്കും? തിരുമേനി(സ) പറഞ്ഞു: "ഇരുമ്പ്, അല്ലെങ്കിൽ വെള്ളി, അല്ലെങ്കിൽ പിച്ചള എന്നിവയിൽ നിന്നുള്ള മോതിരം." (ന)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദുൽ ഖുദ്‌രി(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 706, 706, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=104 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 257, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ قَالَ: خَرَجَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَقَدِ اتَّخَذَ حَلْقَةً مِنْ فِضَّةٍ، فَقَالَ: "مَنْ أَرَادَ أَنْ يَصُوغَ عَلَيْهِ فَلْيَفْعَلْ، وَلَا تَنْقُشُوا عَلَى نَقْشِهِ". (ن)', 'അനസ്(റ): കയ്യിലൊരു വെള്ളിമോതിരം ധരിച്ച് റസൂൽ(സ) പുറത്തിറങ്ങി. അന്നേരം അവിടന്ന് പറഞ്ഞു: "ഇപ്രകാരം മോതിരമുണ്ടാക്കാൻ ആഗ്രഹിക്കുന്നവർ ഉണ്ടാക്കുക. പക്ഷേ, അതിൽ ഇപ്രകാരം കൊത്തിവെക്കരുത്." (ന)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 706, 706, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=104 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 258, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لَبِسَ خَاتَمَ فِضَّةٍ، فِيهِ فَصٌّ حَبَشِيٌّ، كَانَ يَجْعَلُ فَصَّهُ فِي بَطْنِ كَفِّهِ. (م,د,ن,جه)', 'അനസുബ്‌നു മാലിക്(റ): റസൂൽ(സ) അവിടുത്തെ വലതുകയ്യിൽ ഒരു വെള്ളിമോതിരം ധരിച്ചു. അതിൽ ഹബ്‌ശി (അബ്സീനിയയിൽ നിന്നും കൊണ്ടുവന്ന) കല്ലുണ്ടായിരുന്നു. അവിടന്ന് മോതിരത്തിന്റെ കല്ല് കൈപ്പടത്തിനോടടുത്ത് വെക്കുമായിരുന്നു. (മു,ദ,ന,ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്‌നു മാലിക്(റ)', null, null, array['م','د','ن','جه']::text[], array['മു','ദ','ന','ജ']::text[], null, null, 706, 707, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=105 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 259, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ اتَّخَذَ خَاتَمًا مِنْ ذَهَبٍ، وَكَانَ فَصُّهُ فِي بَاطِنِ كَفِّهِ، فَاتَّخَذَ النَّاسُ خَوَاتِيمَ مِنْ ذَهَبٍ، فَطَرَحَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَطَرَحَ النَّاسُ خَوَاتِيمَهُمْ، وَاتَّخَذَ خَاتَمًا مِنْ فِضَّةٍ، فَكَانَ يَخْتِمُ بِهِ وَلَا يَلْبَسُهُ. (ن)', 'ഇബ്‌നുഉമർ(റ): റസൂൽ(സ) സ്വർണ്ണത്തിന്റെ ഒരു മോതിരമുണ്ടാക്കി, അതിന്റെ കല്ല് കൈപ്പടത്തിനോടടുത്തായിരുന്നു. അപ്പോൾ ജനങ്ങളും സ്വർണ്ണമോതിരം ഉണ്ടാക്കി. അപ്പോൾ റസൂൽ(സ) അത് വലിച്ചെറിഞ്ഞു. ജനങ്ങളും അതുപോലെ ചെയ്തു. ശേഷം റസൂൽ(സ) വെള്ളി മോതിരമുണ്ടാക്കി. അതുകൊണ്ട് റസൂൽ(സ) മുദ്രവെക്കാറുണ്ടായിരുന്നു. അത് ധരിക്കാറില്ലായിരുന്നു. (ന)', 'ابْنِ عُمَرَ', 'ഇബ്‌നുഉമർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 707, 707, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=105 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 260, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ تَخَتَّمَ خَاتَمًا مِنْ ذَهَبٍ، ثُمَّ طَرَحَهُ وَلَبِسَ خَاتَمًا مِنْ وَرِقٍ، وَنَقَشَ فِيهِ: ''مُحَمَّدٌ رَسُولُ اللَّهِ''. وَقَالَ: "لَا يَنْبَغِي لِأَحَدٍ أَنْ يَنْقُشَ عَلَى نَقْشِ خَاتَمِي هَذَا". ثُمَّ جَعَلَ فَصَّهُ فِي بَطْنِ كَفِّهِ. (ن)', 'ഇബ്‌നുഉമർ(റ): നബി(സ) ഒരു സ്വർണ്ണമോതിരം ഉണ്ടാക്കിച്ചു. ശേഷം അത് വലിച്ചെറിഞ്ഞു. അങ്ങനെ അവിടന്ന് ഒരു വെള്ളിമോതിരം ധരിച്ചു. അതിൽ ''മുഹമ്മദുർറസൂലുല്ലാഹി'' എന്ന് കൊത്തിവെച്ചു. എന്നിട്ട് പറഞ്ഞു: "എന്റെ ഈ മോതിരത്തിൽ കൊത്തിവെച്ച പ്രകാരം ആരും കൊത്തിവെക്കരുത്." പിന്നെ നബി(സ) അതിന്റെ കല്ല് ഉള്ളം കൈക്ക് ചേർത്തുവെച്ചു. (ന)', 'ابْنِ عُمَرَ', 'ഇബ്‌നുഉമർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 707, 707, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=105 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 261, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ نَقْشُ خَاتَمِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ثَلَاثَةَ أَسْطُرٍ: مُحَمَّدٌ سَطْرٌ، وَرَسُولٌ سَطْرٌ، وَاللَّهِ سَطْرٌ. حَسَنٌ صَحِيحٌ. (ق،د،ت،ن)', 'അനസുബ്‌നു മാലിക്(റ): നബി(സ)യുടെ മോതിരത്തിലെ കൊത്തുപണി മൂന്ന് വരികളായിരുന്നു: ''മുഹമ്മദ്'' എന്ന് ഒരു വരിയും ''റസൂൽ'' എന്ന് ഒരുവരിയും ''അല്ലാഹു'' എന്ന് ഒരു വരിയും. ഹദീസ് ഹസനും സ്വഹീഹുമാണ്. (ബു,മു,ദ,തു,ന)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്‌നു മാലിക്(റ)', null, null, array['ق','د','ت','ن']::text[], array['ബു','മു','ദ','തു','ന']::text[], null, null, 707, 707, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=106 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 262, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَبِسَ خَاتَمًا مِنْ ذَهَبٍ ثَلَاثَةَ أَيَّامٍ، فَلَمَّا رَآهُ أَصْحَابُهُ فَشَتْ خَوَاتِيمُ الذَّهَبِ، فَرَمَى بِهِ، فَلَا نَدْرِي مَا فَعَلَ، ثُمَّ أَمَرَ بِخَاتَمٍ مِنْ فِضَّةٍ، فَأَمَرَ أَنْ يُنْقَشَ فِيهِ: مُحَمَّدٌ رَسُولُ اللَّهِ، وَكَانَ فِي يَدِ رَسُولِ اللَّهِ حَتَّى مَاتَ، وَفِي يَدِ أَبِي بَكْرٍ رَضِيَ اللهُ عَنْهُ حَتَّى مَاتَ، وَفِي يَدِ عُمَرَ رَضِيَ اللهُ عَنْهُ حَتَّى مَاتَ، وَفِي يَدِ عُثْمَانَ رَضِيَ اللهُ عَنْهُ سِتَّ سِنِينَ مِنْ عَمَلِهِ، فَلَمَّا كَثُرَتْ عَلَيْهِ الْكُتُبُ دَفَعَهُ إِلَى رَجُلٍ مِنَ الْأَنْصَارِ فَكَانَ يَخْتِمُ بِهِ، فَخَرَجَ الْأَنْصَارِيُّ إِلَى قَلِيبٍ لِعُثْمَانَ فَسَقَطَ، فَالْتُمِسَ فَلَمْ يُوجَدْ، فَأَمَرَ بِخَاتَمٍ مِثْلِهِ، وَنَقَشَ فِيهِ: مُحَمَّدٌ رَسُولُ اللَّهِ. (ن)', 'ഇബ്‌നുഉമർ(റ): റസൂൽ(സ) മൂന്നുദിവസം സ്വർണ്ണമോതിരം ധരിച്ചു, അങ്ങനെ അത് അവിടുത്തെ അനുചരന്മാർ കണ്ടപ്പോൾ അവരിലും സ്വർണ്ണമോതിരം വ്യാപകമായി. അപ്പോൾ തിരുമേനി(സ) അത് വലിച്ചെറിഞ്ഞു. അത് എന്തുചെയ്തുവെന്ന് ഞങ്ങൾക്കറിയില്ല. പിന്നെ , വെള്ളിയിലുള്ള മോതിരമുണ്ടാക്കാനും അതിൽ ''മുഹമ്മദുർറസൂലുല്ലാഹി'' എന്ന് കൊത്തി വെക്കാനും തിരുമേനി(സ) ആജ്ഞാപിച്ചു. റസൂൽ (സ) വഫാത്താകുന്നത് വരെ അവിടുത്തെ തൃക്കൈയിലും ശേഷം അബൂബക്കർ(റ) വഫാത്താകുന്നത് വരെ അദ്ദേഹത്തിന്റെ കയ്യിലും ഉമർ(റ) വഫാത്താകുന്നത് വരെ അദ്ദേഹത്തിന്റെ കയ്യിലും അതുണ്ടായിരുന്നു. പിന്നീട് ഉസ്മാൻ(റ)വിന്റെ കയ്യിൽ, അദ്ദേഹത്തിന്റെ പ്രവർത്തനത്തുടക്കം മുതൽ ആറ് വർഷം വരെ തുടർന്നു. അങ്ങനെ അദ്ദേഹത്തിന് എഴുത്തുകൾ കൂടുതലായപ്പോൾ അൻസാറുകളിലൊരാൾക്ക് നൽകി. അതുകൊണ്ടദ്ദേഹം മുദ്രവെക്കാറുണ്ടായിരുന്നു. അങ്ങനെ ആ അൻസാരി ഉസ്മാൻ(റ)വിന്റെ കിണറിന്റെ അടുത്ത് ചെന്നപ്പോൾ മോതിരം അതിൽ വീണു. തിരഞ്ഞുനോക്കിയെങ്കിലും കിട്ടിയില്ല. അപ്പോൾ മറ്റൊരു മോതിരം ഉണ്ടാക്കാൻ പറയുകയും അതിൽ ''മുഹമ്മദുർറസൂലുല്ലാഹി'' എന്ന് കൊത്തിവെക്കാൻ കൽപിക്കുകയും ചെയ്തു. (ന)', 'ابْنِ عُمَرَ', 'ഇബ്‌നുഉമർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 707, 708, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=106 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 263, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَا تَسْتَضِيئُوا بِنَارِ الْمُشْرِكِينَ، وَلَا تَنْقُشُوا عَلَى خَوَاتِيمِكُمْ عَرَبِيًّا". (ن)', 'അനസുബ്നു മാലിക്(റ): റസൂൽ(സ) പറയുന്നു: "ബഹുദൈവാരാധകരുടെ തീ കൊണ്ട് നിങ്ങൾ പ്രകാശിപ്പിക്കരുത്. നിങ്ങളുടെ മോതിരത്തിൽ അറബി കൊത്തിവെക്കുകയുമരുത്." (ന)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 708, 708, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=107 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 264, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ اتَّخَذَ خَاتَمًا مِنْ وَرِقٍ، وَنَقَشَ فِيهِ: مُحَمَّدٌ رَسُولُ اللَّهِ، وَقَالَ: "إِنِّي اتَّخَذْتُ خَاتَمًا مِنْ وَرِقٍ، وَنَقَشْتُ فِيهِ: مُحَمَّدٌ رَسُولُ اللَّهِ، فَلَا يَنْقُشَنَّ أَحَدٌ عَلَى نَقْشِهِ". (خ)', 'അനസുബ്നു മാലിക്(റ): റസൂൽ(സ) വെള്ളിയാലുള്ള ഒരു മോതിരം ഉണ്ടാക്കി. അതിൽ ''മുഹമ്മദുർറസൂലുല്ലാഹി'' എന്ന് കൊത്തിവെക്കുകയും ചെയ്തു. എന്നിട്ട് പറഞ്ഞു: "ഞാൻ വെള്ളിയുടെ മോതിരമുണ്ടാക്കി. അതിൽ ''മുഹമ്മദുർറസൂലുല്ലാഹി'' എന്ന് കൊത്തിവെക്കുകയും ചെയ്തു. ഇനി അത് ആരും കൊത്തിവെക്കരുത്." (ബു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 708, 708, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=107 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 265, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ صَنَعَ خَاتَمًا مِنْ ذَهَبٍ فَتَخَتَّمَ بِهِ فِي يَمِينِهِ، ثُمَّ جَلَسَ عَلَى الْمِنْبَرِ فَقَالَ: "إِنِّي كُنْتُ اتَّخَذْتُ هَذَا الْخَاتَمَ فِي يَمِينِي". ثُمَّ نَبَذَهُ وَنَبَذَ النَّاسُ خَوَاتِيمَهُمْ. حَسَنٌ صَحِيحٌ. (م،ت)', 'ഇബ്നുഉമർ(റ): നബി(സ) സ്വർണ്ണമോതിരമുണ്ടാക്കി. അത് അവിടുത്തെ വലതുകയ്യിൽ ധരിച്ചു. പിന്നെ മിമ്പറിൽ ഇരുന്നിട്ട് പറഞ്ഞു: "ഞാൻ ഈ മോതിരം എന്റെ വലതുകയ്യിൽ ധരിച്ചിരിക്കുന്നു." പിന്നെ അത് വലിച്ചെറിഞ്ഞു. ജനങ്ങൾ അവരുടെ മോതിരവും വലിച്ചെറിഞ്ഞു. ഹദീസ് ഹസനും സ്വഹീഹുമാണ്. (മു,തു)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['م','ت']::text[], array['മു','തു']::text[], null, null, 708, 708, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=108 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 266, 'عَنِ الصَّلْتِ بْنِ عَبْدِ اللَّهِ بْنِ نَوْفَلٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: رَأَيْتُ ابْنَ عَبَّاسٍ يَتَخَتَّمُ فِي يَمِينِهِ، وَلَا إِخَالُهُ إِلَّا قَالَ: رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَتَخَتَّمُ فِي يَمِينِهِ. حَسَنٌ صَحِيحٌ. (ت)', 'സ്വൽതുബ്നു അബ്ദില്ലാഹിബ്നി നൗഫൽ(റ): ഇബ്നുഅബ്ബാസ്(റ) തന്റെ വലതുകയ്യിൽ മോതിരം ധരിക്കുന്നത് ഞാൻ കണ്ടു. അദ്ദേഹം ഇങ്ങനെ പറഞ്ഞുവെന്ന് ഞാൻ വിചാരിക്കുന്നു: റസൂൽ(സ) അവിടുത്തെ വലതുകയ്യിൽ മോതിരം ധരിക്കുന്നത് ഞാൻ കണ്ടിട്ടുണ്ട്. ഹദീസ് ഹസനും സ്വഹീഹുമാണ്. (തു)', 'الصَّلْتِ بْنِ عَبْدِ اللَّهِ بْنِ نَوْفَلٍ', 'സ്വൽതുബ്നു അബ്ദില്ലാഹിബ്നി നൗഫൽ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 708, 709, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=108 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 267, 'عَنْ مُحَمَّدِ بْنِ عَلِيِّ بْنِ الْحُسَيْنِ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ الْحَسَنُ وَالْحُسَيْنُ رَضِيَ الله عَنْهُمَا يَتَخَتَّمَانِ فِي يَسَارِهِمَا. حَسَنٌ صَحِيحٌ. (ت)', 'മുഹമ്മദുബ്നു അലിയ്യുബ്നുൽ ഹുസൈൻ(റ): ഹസൻ(റ)വും ഹുസൈൻ(റ)വും ഇടത്തേകൈകളിൽ മോതിരം ധരിക്കാറുണ്ടായിരുന്നു. ഹദീസ്‌ ഹസനും സ്വഹീഹുമാണ്. (തു)', 'مُحَمَّدِ بْنِ عَلِيِّ بْنِ الْحُسَيْنِ', 'മുഹമ്മദുബ്നു അലിയ്യുബ്നുൽ ഹുസൈൻ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 709, 709, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=109 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 268, 'عَنْ عَلِيٍّ رَضِيَ اللَّهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَتَخَتَّمُ فِي يَمِينِهِ. (د,ت,ن)', 'അലി(റ): നബി(സ) അവിടുത്തെ വലതുകയ്യിലായിരുന്നു മോതിരം ധരിക്കാറുണ്ടായിരുന്നത്. (ദ,തു,ന)', 'عَلِيٍّ', 'അലി(റ)', null, null, array['د','ت','ن']::text[], array['ദ','തു','ന']::text[], null, null, 709, 709, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=109 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 269, 'عَنِ ابْنِ عُمَرَ رَضِيَ الله عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَتَخَتَّمُ فِي يَسَارِهِ، وَكَانَ فَصُّهُ فِي بَاطِنِ كَفِّهِ. وفي رواية: فِي يَمِينِهِ. وفي رواية: أَنَّ ابْنَ عُمَرَ كَانَ يَلْبَسُ خَاتَمَهُ فِي يَدِهِ الْيُسْرَى. (د)', 'ഇബ്നുഉമർ(റ): നബി(സ) അവിടുത്തെ ഇടതുകയ്യിൽ മോതിരം ധരിക്കാറുണ്ടായിരുന്നു. അതിന്റെ കല്ല് അവിടുത്തെ കൈപ്പടത്തിന്റെ ഉൾഭാഗത്തേക്കായിരുന്നു. (ദ)
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=8 and h.hadith_no=269), 1, 'وَفِي رِوَايَةٍ: فِي يَمِينِهِ.', 'മറ്റൊരു നിവേദനിൽ: ഇബ്നുഉമർ(റ) തന്റെ ഇടത് കയ്യിലായിരുന്നു മോതിരം ധരിച്ചിരുന്നത്. (ദ)');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=8 and h.hadith_no=269), 2, 'وَفِي رِوَايَةٍ: أَنَّ ابْنَ عُمَرَ كَانَ يَلْبَسُ خَاتَمَهُ فِي يَدِهِ الْيُسْرَى. (د)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 270, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ قَالَ: كَأَنِّي أَنْظُرُ إِلَى بَيَاضِ خَاتَمِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي إِصْبَعِهِ الْيُسْرَى. (ن)', 'അനസ്(റ): നബി(സ)യുടെ ഇടത് വിരലുകളിലുള്ള മോതിരത്തിന്റെ വെള്ളിയിലേക്ക് ഞാൻ നോക്കുന്നത് പോലെയുണ്ട്. (ന)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 709, 709, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=109 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 271, 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ، وَقَدْ سُئِلَ عَنْ خَاتَمِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؟ قَالَ: كَأَنِّي أَنْظُرُ إِلَى وَبِيصِ خَاتَمِهِ مِنْ فِضَّةٍ. وَرَفَعَ إِصْبَعَهُ الْيُسْرَى. (ن)', 'അനസ്(റ): റസൂൽ(സ)യുടെ മോതിരത്തെക്കുറിച്ച് അദ്ദേഹത്തോട് ചോദിച്ചപ്പോൾ അദ്ദേഹം പറഞ്ഞു: അവിടുത്തെ വെള്ളിമോതിരത്തിന്റെ ആ തിളക്കത്തിലേക്ക് ഞാൻ നോക്കുന്നത് പോലെ. എന്നിട്ട് തന്റെ ഇടത് വിരൽ ഉയർത്തി. (ന)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 709, 709, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=109 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 272, 'عَنْ أَنَسٍ رَضِيَ الله عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ اصْطَنَعَ خَاتَمًا، فَقَالَ: "إِنَّا قَدِ اتَّخَذْنَا خَاتَمًا وَنَقَشْنَا عَلَيْهِ نَقْشًا، فَلَا يَنْقُشْ عَلَيْهِ أَحَدٌ". وَإِنِّي لَأَرَى بَرِيقَهُ فِي خِنْصَرِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. (ن)', 'അനസ്(റ): നബി(സ) ഒരു മോതിരം ഉണ്ടാക്കാൻ ആവശ്യപ്പെട്ടു. എന്നിട്ട് പറഞ്ഞു: "നാം മോതിരമുണ്ടാക്കി. നാം അതിൽ ഒന്ന് കൊത്തിവെച്ചു. ഇനി അത് ആരും കൊത്തിവെക്കരുത്." നിശ്ചയം റസൂൽ(സ)യുടെ ചെറുവിരലിലെ മോതിരത്തിന്റെ തിളക്കം ഞാൻ കാണുന്നു. (ന)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 709, 709, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=110 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 273, 'عَنْ مُحَمَّدِ بْنِ إِسْحَاقَ رَضِيَ الله عَنْهُ قَالَ: رَأَيْتُ عَلَى الصَّلْتِ بْنِ عَبْدِ اللَّهِ بْنِ نَوْفَلِ بْنِ عَبْدِ الْمُطَّلِبِ خَاتَمًا فِي خِنْصِرِهِ الْيُمْنَى، فَقُلْتُ: مَا هَذَا؟ قَالَ: رَأَيْتُ ابْنَ عَبَّاسٍ يَلْبَسُ خَاتَمَهُ هَكَذَا، وَجَعَلَ فَصَّهُ عَلَى ظَهْرِهَا، قَالَ: وَلَا يَخَالُ ابْنُ عَبَّاسٍ إِلَّا قَدْ كَانَ يَذْكُرُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يَلْبَسُ خَاتَمَهُ كَذَلِكَ. (د،ت)', 'മുഹമ്മദ്ബ്നു ഇസ്ഹാഖ്(റ): സ്വൽതുബ്നി അബ്ദില്ലാഹിബ്നി നൗഫലിബ്നി അബ്ദുൽ മുത്വലിബ്(റ)വിന്റെ വലതുകയ്യിന്റെ ചെറുവിരലിൽ ഞാൻ ഒരു മോതിരം കണ്ടു. അപ്പോൾ ഞാൻ ചോദിച്ചു: ഇതെന്താണ്? അദ്ദേഹം പറഞ്ഞു: ഇബ്നുഅബ്ബാസ്(റ) മോതിരം ഇപ്രകാരം ധരിക്കുന്നത് ഞാൻ കണ്ടിട്ടുണ്ട്. അതിന്റെ കല്ല് വിരലിന്റെ പുറം ഭാഗത്തേക്കാക്കുകയും ചെയ്തു. ഇബ്നുഅബ്ബാസ്(റ) ഇങ്ങനെ പറയുന്നതായി അദ്ദേഹം വിചാരിക്കുന്നു: റസൂൽ(സ) അവിടുത്തെ മോതിരം അപ്രകാരം തന്നെയാണ് ധരിക്കാറുണ്ടായിരുന്നത്. (ദ,തു)', 'مُحَمَّدِ بْنِ إِسْحَاقَ', 'മുഹമ്മദ്ബ്നു ഇസ്ഹാഖ്(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 709, 710, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=110 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 274, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ خَاتَمُ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي هَذِهِ. وَأَشَارَ إِلَى الْخِنْصِرِ مِنْ يَدِهِ الْيُسْرَى. (م)', 'അനസ്(റ): നബി(സ)യുടെ മോതിരമുണ്ടായിരുന്നത് ഇതിലായിരുന്നു. അദ്ദേഹം തന്റെ ഇടതുകയ്യിന്റെ ചെറുവിരലിലേക്ക് ചൂണ്ടി. (മു)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 710, 710, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=111 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 275, 'عَنْ عَلِيٍّ رضي الله عنه قَالَ: نَهَانِي رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنْ أَتَخَتَّمَ فِي إِصْبَعِي هَذِهِ أَوْ هَذِهِ، قَالَ: فَأَوْمَأَ إِلَى الْوُسْطَى وَالَّتِي تَلِيهَا. (م)', 'അലി(റ): ഈ വിരലിൽ അല്ലെങ്കിൽ ഈ വിരലിൽ മോതിരം ധരിക്കൽ എനിക്ക് നബി(സ) നിരോധിച്ചിരിക്കുന്നു. നിവേദകൻ പറയുന്നു: അന്നേരം അലി(റ) നടുവിരലും അതിന്റെ തൊട്ടടുത്തുള്ള വിരലും സൂചിപ്പിച്ചു. (മു)', 'عَلِيٍّ', 'അലി(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 710, 710, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=112 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 276, 'عَنْ عَلِيٍّ رَضِيَ اللهُ عَنْهُ قَالَ: نَهَانِي نَبِيُّ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَنِ الْخَاتَمِ فِي السَّبَّابَةِ وَالْوُسْطَى. وفي رواية قال: نَهَانِي رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنْ أَلْبَسَ فِي إِصْبَعِي هَذِهِ وَفِي الْوُسْطَى وَالَّتِي تَلِيهَا. (ن)', 'അലി(റ): ചൂണ്ടുവിരലിലും നടുവിരലിലും മോതിരം ധരിക്കുന്നത് നബി(സ) എനിക്ക് നിരോധിച്ചിരിക്കുന്നു. മറ്റൊരു റിപ്പോർട്ടിൽ: എന്റെ ഈ വിരലിലും നടുവിരലിലും അതിനടുത്തുള്ള വിരലിലും മോതിരം ധരിക്കൽ റസൂൽ(സ) എനിക്ക് നിരോധിച്ചിരിക്കുന്നു. (ന)', 'عَلِيٍّ', 'അലി(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 710, 710, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=112 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=8 and h.hadith_no=276), 1, 'وَفِي رِوَايَةٍ قال: نَهَانِي رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنْ أَلْبَسَ فِي إِصْبَعِي هَذِهِ وَفِي الْوُسْطَى وَالَّتِي تَلِيهَا. (ن)', 'മറ്റൊരു നിവേദനിൽ: എന്റെ ഈ വിരലിലും നടുവിരലിലും അതിനടുത്തുള്ള വിരലിലും മോതിരം ധരിക്കൽ റസൂൽ(സ) എനിക്ക് നിരോധിച്ചിരിക്കുന്നു. (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 277, 'عَنْ عَلِيٍّ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ لِي رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "يَا عَلِيُّ، سَلِ اللَّهَ الْهُدَى وَالسَّدَادَ". وَنَهَانِي أَنْ أَجْعَلَ الْخَاتَمَ فِي هَذِهِ وَهَذِهِ. وَأَشَارَ يَعْنِي بِالسَّبَّابَةِ وَالْوُسْطَى. وفي رواية قَالَ: نَهَانِي رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَنِ الْخَاتَمِ فِي هَذِهِ وَهَذِهِ. يَعْنِي السَّبَّابَةَ وَالْوُسْطَى. وفي رواية قَالَ: قَالَ لِي رَسُولُ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "قُلِ: اللَّهُمَّ اهْدِنِي وَسَدِّدْنِي". وَنَهَانِي أَنْ أَضَعَ الْخَاتَمَ فِي هٰذِهِ وَهٰذِهِ. وَأَشَارَ بِالسَّبَّابَةِ وَالْوُسْطَى. (ن)', 'അലി(റ): റസൂൽ(സ) എന്നോട് പറഞ്ഞു: "അലി, താങ്കൾ അല്ലാഹുവിനോട് നേർമാർഗ്ഗവും യാഥാർത്ഥ്യവും തേടുക." നടുവിരലും ചൂണ്ടുവിരലും സൂചിപ്പിച്ചു കൊണ്ട് അദ്ദേഹം പറഞ്ഞു: ഇതിലും ഇതിലും മോതിരം ധരിക്കൽ അവിടുന്ന് എനിക്ക് നിരോധിച്ചിരിക്കുന്നു.
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=8 and h.hadith_no=277), 1, 'وَفِي رِوَايَةٍ قَالَ: نَهَانِي رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَنِ الْخَاتَمِ فِي هَذِهِ وَهَذِهِ. يَعْنِي السَّبَّابَةَ وَالْوُسْطَى.', 'മറ്റൊരു നിവേദനിൽ: നടുവിരലും ചൂണ്ടു വിരലും ഉദ്ദേശിച്ചുകൊണ്ട് അദ്ദേഹം പറഞ്ഞു: ഇതിലും ഇതിലും മോതിരം ധരിക്കൽ റസൂൽ(സ) എനിക്ക് നിരോധിച്ചിരിക്കുന്നു.');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=8 and h.hadith_no=277), 2, 'وَفِي رِوَايَةٍ قَالَ: قَالَ لِي رَسُولُ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "قُلِ: اللَّهُمَّ اهْدِنِي وَسَدِّدْنِي". وَنَهَانِي أَنْ أَضَعَ الْخَاتَمَ فِي هٰذِهِ وَهٰذِهِ. وَأَشَارَ بِالسَّبَّابَةِ وَالْوُسْطَى. (ن)', 'മറ്റൊരു നിവേദനിൽ: എന്നോട് റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങൾ പറയുക: അല്ലാഹുവേ, നീയെനിക്ക് നേർമാർഗ്ഗം കാണിച്ചുതരണമേ, എന്നെ യാഥാർത്ഥ്യത്തിലാക്കണമേ." നടുവിരലും ചൂണ്ടുവിരലും സൂചിപ്പിച്ചുകൊണ്ട് അദ്ദേഹം പറഞ്ഞു: ഇതിലും ഇതിലും മോതിരം ധരിക്കൽ എനിക്ക് അവിടന്ന് നിരോധിച്ചിരിക്കുന്നു. (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 278, 'عَنْ عَلِيٍّ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ لِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ "قُلْ: اللَّهُمَّ اهْدِنِي وَسَدِّدْنِي، وَاذْكُرْ بِالْهِدَايَةِ هِدَايَةَ الطَّرِيقِ، وَاذْكُرْ بِالسَّدَادِ تَسْدِيدَكَ السَّهْمَ". قَالَ: وَنَهَانِي أَنْ أَضَعَ الْخَاتَمَ فِي هٰذِهِ أَوْ فِي هٰذِهِ، لِلسَّبَّابَةِ وَالْوُسْطَى، وَنَهَانِي عَنِ الْقَسِّيَّةِ وَالْمِيثَرَةِ، فَقِيلَ لِعَلِيٍّ: مَا الْقَسِّيَّةُ؟ قَالَ: ثِيَابٌ تَأْتِينَا مِنَ الشَّأْمِ أَوْ مِنْ مِصْرَ مُضَلَّعَةٌ فِيهَا أَمْثَالُ الْأُتْرُجِّ، قَالَ: وَالْمِيثَرَةُ: شَيْءٌ كَانَتْ تَصْنَعُهُ النِّسَاءُ لِبُعُولَتِهِنَّ. (م,د,ت,ن,جه)', 'അലി(റ): എന്നോട് റസൂൽ(സ) പറഞ്ഞു: "നീ പറയുക: അല്ലാഹുവേ, എനിക്ക് വഴികാണിക്കണേ, എന്നെ നേർവഴിയിലാക്കണേ. ''വഴികാണിക്കൽ'' എന്നതുകൊണ്ട് നീ നേരായ വഴിയിലേക്ക് വഴി നടത്തൽ എന്ന് കരുതണം. ''നേർവഴിയിലാക്കൽ'' എന്നതുകൊണ്ട് അമ്പെയ്ത്ത് നേരെയാക്കലും കരുതുക." അലി(റ) പറയുന്നു: ഇതിൽ, അല്ലെങ്കിൽ ഇതിൽ, അഥവാ നടുവിരൽ അല്ലെങ്കിൽ ചൂണ്ടു വിരൽ, മോതിരമിടൽ അവിടുന്ന് എനിക്ക് നിരോധിക്കുകയും ചെയ്തു. സ്ത്രീകൾ തങ്ങളുടെ ഭർത്താക്കന്മാർക്ക് വേണ്ടി ഉണ്ടാക്കാറുള്ള ജീനിത്തുണിയും ഖസിയ്യ് വസ്ത്രവും എന്നോടവിടുന്ന് നിരോധിച്ചു. അപ്പോൾ അലി(റ)വിനോട് ചോദിച്ചു: എന്താണ് ഖസിയ്യ് വസ്ത്രങ്ങൾ? അദ്ദേഹം പറഞ്ഞു: ശാമിൽ നിന്നും ഈജിപ്തിൽ നിന്നും വരുന്ന, മാതളനാരങ്ങയുടെ ചിത്രങ്ങൾ കൊത്തിവെക്കപ്പെട്ട വസ്ത്രങ്ങളാണവ. അലി(റ) പറയുന്നു: ''മീസറത്ത്'' എന്നാൽ, സ്ത്രീകൾ തങ്ങളുടെ ഭർത്താവിന് വേണ്ടി നിർമ്മിക്കുന്നവയാണ്. (മു,ദ,തു,ന,ജ)', 'عَلِيٍّ', 'അലി(റ)', null, null, array['م','د','ت','ن','جه']::text[], array['മു','ദ','തു','ന','ജ']::text[], null, null, 711, 711, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=113 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 279, 'عَنْ عَلِيٍّ رَضِيَ اللَّهُ عَنْهُ قَالَ: نَهَانِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ أَتَخَتَّمَ فِي هٰذِهِ وَفِي هٰذِهِ. يَعْنِي الْخِنْصِرَ وَالْإِبْهَامَ. (ق,د,ت,ن,جه)', 'അലി(റ): ചെറുവിരലിനെയും തള്ളവിരലിനെയും സൂചിപ്പിച്ച് കൊണ്ട് അദ്ദേഹം പറഞ്ഞു: ഇതിലും ഇതിലും മോതിരം ധരിക്കൽ റസൂൽ(സ) എനിക്ക് നിരോധിച്ചിരിക്കുന്നു. (ബു,മു,ദ,തു,ന,ജ)', 'عَلِيٍّ', 'അലി(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 711, 711, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=114 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 280, 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا دَخَلَ الْخَلَاءَ نَزَعَ خَاتَمَهُ. حَسَنٌ صَحِيحٌ. (د,ت,ن,جه)', 'അനസ്(റ): തിരുമേനി(സ) വിസർജ്ജന സ്ഥലത്തേക്ക് പ്രവേശിച്ചാൽ അവിടുത്തെ മോതിരം ഊരുമായിരുന്നു. ഹദീസ് ഹസനും സ്വഹീഹുമാണ്. (ദ,തു,ന,ജ)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 711, 712, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=115 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 281, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا تَصْحَبُ الْمَلَائِكَةُ رَكْبًا مَعَهُمْ - فِي رواية: رُفْقَةً فِيهَا - جُلْجُلٌ". (ن)', 'ഇബ്നുഉമർ(റ): നബി(സ) പറഞ്ഞു: "മലക്കുകൾ ചിലങ്കകളുള്ള യാത്രക്കാരുടെ കൂടെ സഹവസിക്കില്ല."
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=8 and h.hadith_no=281), 1, null, 'മറ്റൊരു നിവേദനത്തിൽ: "കൂട്ടുകാരുടെ കൂടെ (ചിലങ്ക ധരിച്ച)" എന്ന് കാണാം. (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 282, 'عَنْ أُمِّ سَلَمَةَ رَضِيَ اللَّهُ عَنْهَا، زَوْجِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، قَالَتْ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "لَا تَدْخُلُ الْمَلَائِكَةُ بَيْتًا فِيهِ جُلْجُلٌ وَلَا جَرَسٌ، وَلَا تَصْحَبُ الْمَلَائِكَةُ رُفْقَةً فِيهَا جَرَسٌ". (ن)', 'നബി(സ)യുടെ പത്നി ഉമ്മു സലമ(റ): റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടു: "മണിയോ ചിലങ്കയോ ഉള്ള വീട്ടിൽ മലക്കുകൾ പ്രവേശിക്കില്ല. കൂടെ മണിയുള്ള കൂട്ടുകാരിലും മലക്കുകൾ സഹവസിക്കില്ല." (ന)', 'أُمِّ سَلَمَةَ', 'നബി(സ)യുടെ പത്നി ഉമ്മു സലമ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 712, 712, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=116 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 283, 'عَنْ مَالِكِ بْنِ نَضْلَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: كُنْتُ جَالِسًا عِنْدَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَرَآنِي رَثَّ الثِّيَابِ، فَقَالَ: "أَلَكَ مَالٌ"، قُلْتُ: نَعَمْ يَا رَسُولَ اللَّهِ، مِنْ كُلِّ الْمَالِ. قَالَ: "فَإِذَا آتَاكَ اللَّهُ مَالًا فَلْيُرَ أَثَرُهُ عَلَيْكَ". وَفِي رواية: أَنَّهُ أَتَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي ثَوْبٍ دُونٍ، فَقَالَ لَهُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَلَكَ مَالٌ". قَالَ: قَدْ آتَانِي اللَّهُ مِنَ الْإِبِلِ وَالْغَنَمِ وَالْخَيْلِ وَالرَّقِيقِ. قَالَ: "فَإِذَا آتَاكَ اللَّهُ مَالًا فَلْيُرَ عَلَيْكَ أَثَرُ نِعْمَةِ اللَّهِ وَكَرَامَتِهِ". (ن)', 'മാലികുബ്നു നള്ല(റ): ഞാൻ റസൂൽ(സ)യുടെ കൂടെ ഇരിക്കുകയായിരുന്നു. അന്നേരം എന്റെ വസ്ത്രങ്ങൾ നുരുമ്പിയത് അവിടുന്ന് കണ്ടു. അപ്പോൾ റസൂൽ(സ) ചോദിച്ചു: "നിങ്ങൾക്ക് സമ്പത്തില്ലേ?" ഞാൻ പറഞ്ഞു: ഉണ്ട് റസൂലേ, എല്ലാവിധ സമ്പത്തുമുണ്ട്. റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങൾക്കല്ലാഹു സമ്പത്ത് തന്നിട്ടുണ്ടെങ്കിൽ അതിന്റെ അടയാളം നിങ്ങളിൽ കാണണം."
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=8 and h.hadith_no=283), 1, 'وَفِي رِوَايَةٍ: أَنَّهُ أَتَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي ثَوْبٍ دُونٍ، فَقَالَ لَهُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَلَكَ مَالٌ". قَالَ: قَدْ آتَانِي اللَّهُ مِنَ الْإِبِلِ وَالْغَنَمِ وَالْخَيْلِ وَالرَّقِيقِ. قَالَ: "فَإِذَا آتَاكَ اللَّهُ مَالًا فَلْيُرَ عَلَيْكَ أَثَرُ نِعْمَةِ اللَّهِ وَكَرَامَتِهِ". (ن)', 'മറ്റൊരു നിവേദനത്തിൽ: നുരുമ്പി വില കുറഞ്ഞ വസ്ത്രം ധരിച്ച് അദ്ദേഹം നബി(സ)യുടെ അടുത്തുചെന്നു. അന്നേരം അദ്ദേഹത്തോട് നബി(സ) ചോദിച്ചു: "നിങ്ങളുടെയടുത്ത് സമ്പത്തുണ്ടോ?" അദ്ദേഹം പറഞ്ഞു: എനിക്കല്ലാഹു ഒട്ടകങ്ങളെയും ആടുകളെയും കുതിരകളെയും അടിമകളെയും നൽകിയിരിക്കുന്നു. നബി(സ) പറഞ്ഞു: "നിങ്ങൾക്കല്ലാഹു സമ്പത്ത് നൽകിയെങ്കിൽ അല്ലാഹുവിന്റെ ഔദാര്യത്തിന്റെയും അനുഗ്രഹത്തിന്റെയും അടയാളങ്ങൾ നിങ്ങളിൽ കാണണം." (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 284, 'عَنْ عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ مَوْلَاةً لَهُمْ ذَهَبَتْ بِابْنَةِ الزُّبَيْرِ إِلَى عُمَرَ بْنِ الْخَطَّابِ، وَفِي رِجْلِهَا أَجْرَاسٌ، فَقَطَعَهَا عُمَرُ ثُمَّ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "إِنَّ مَعَ كُلِّ جَرَسٍ شَيْطَانًا". (د)', 'അബ്ദുല്ലാഹിബ്നു സുബൈർ(റ): അവരുടെ ഒരു അടിമസ്ത്രീ സുബൈർ(റ)വിന്റെ മകളുമായി ഉമറുബ്നുൽ ഖത്താബ്(റ)വിന്റെ അടുത്തേക്ക് പോയി. അവളുടെ കാലിൽ മണികളുണ്ടായിരുന്നു. ഉമർ(റ) അത് മുറിച്ച് കളഞ്ഞു. എന്നിട്ട് പറഞ്ഞു: റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടിട്ടുണ്ട്: "എല്ലാ മണിയുടെ കൂടെയും ഒരു പിശാചുണ്ട്." (ദ)', 'عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ', 'അബ്ദുല്ലാഹിബ്നു സുബൈർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 712, 712, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=116 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 285, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا، إِذْ دُخِلَ عَلَيْهَا بِجَارِيَةٍ وَعَلَيْهَا جَلَاجِلُ يُصَوِّتْنَ، فَقَالَتْ: لَا تُدْخِلْنَهَا عَلَيَّ إِلَّا أَنْ تَقْطَعُوا جَلَاجِلَهَا، وَقَالَتْ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "لَا تَدْخُلُ الْمَلَائِكَةُ بَيْتًا فِيهِ جَرَسٌ". (م,د,ت)', 'ആഇശ(റ): കിലുക്കമുണ്ടാക്കുന്ന ചിലങ്കകൾ ധരിച്ച ഒരു അടിമസ്ത്രീയെ അവരുടെയടുത്തേക്ക് കൊണ്ടുവന്നപ്പോൾ അവർ പറഞ്ഞു: ചിലങ്കകൾ മുറിച്ചല്ലാതെ, അവളെ എന്റെയടുത്ത് പ്രവേശിപ്പിക്കരുത്. മഹതി ഇപ്രകാരം പറയുകയും ചെയ്തു. റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടിട്ടുണ്ട്: "ചിലങ്കയുള്ള വീട്ടിൽ മലക്കുകൾ പ്രവേശിക്കില്ല." (മു,ദ,തു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['م','د','ت']::text[], array['മു','ദ','തു']::text[], null, null, 713, 713, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=116 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 286, 'عَنْ عَبْدِ اللهِ بْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ رَأَى خَاتَمًا مِنْ ذَهَبٍ فِي يَدِ رَجُلٍ فَنَزَعَهُ فَطَرَحَهُ، وَقَالَ: "يَعْمِدُ أَحَدُكُمْ إِلَى جَمْرَةٍ مِنْ نَارٍ فَيَجْعَلُهَا فِي يَدِهِ". فَقِيلَ لِلرَّجُلِ بَعْدَمَا ذَهَبَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: خُذْ خَاتَمَكَ انْتَفِعْ بِهِ، قَالَ: لَا وَاللهِ لَا آخُذُهُ أَبَدًا وَقَدْ طَرَحَهُ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. (م)', 'അബ്ദുല്ലാഹിബ്നു അബ്ബാസ്(റ): റസൂൽ(സ) ഒരാളുടെ കൈയ്യിൽ സ്വർണ്ണമോതിരം കണ്ടു. തിരുമേനി(സ) അത് ഊരിയെടുത്ത് എറിഞ്ഞു. എന്നിട്ടവിടുന്ന് ചോദിച്ചു: "നിങ്ങളിലൊരാൾ നരകത്തിലെ തീകട്ടയാഗ്രഹിച്ച് അത് കയ്യിൽ വെക്കുമോ?" റസൂൽ(സ) പോയപ്പോൾ അയാളോട് പറയപ്പെട്ടു: നീ നിന്റെ മോതിരമെടുത്ത് ഉപകാരം നേടുക. അദ്ദേഹം പറഞ്ഞു: ഇല്ല, അല്ലാഹു തന്നെ സത്യം. അത് ഞാൻ ഒരിക്കലുമെടുക്കില്ല. റസൂൽ(സ) എറിഞ്ഞതാണത്. (മു)', 'عَبْدِ اللهِ بْنِ عَبَّاسٍ', 'അബ്ദുല്ലാഹിബ്നു അബ്ബാസ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 713, 713, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=117 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 287, 'عَنْ عَبْدِ اللهِ بْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ اصْطَنَعَ خَاتَمًا مِنْ ذَهَبٍ، فَكَانَ يَجْعَلُ فَصَّهُ فِي بَاطِنِ كَفِّهِ إِذَا لَبِسَهُ، فَصَنَعَ النَّاسُ، ثُمَّ إِنَّهُ جَلَسَ عَلَى الْمِنْبَرِ، فَنَزَعَهُ فَقَالَ: "إِنِّي كُنْتُ أَلْبَسُ هَذَا الْخَاتَمَ، وَأَجْعَلُ فَصَّهُ مِنْ دَاخِلٍ". فَرَمَى بِهِ، ثُمَّ قَالَ: "وَاللهِ لَا أَلْبَسُهُ أَبَدًا". فَنَبَذَ النَّاسُ خَوَاتِيمَهُمْ. (م)', 'അബ്ദുല്ലാഹബ്നു ഉമർ(റ): റസൂൽ(സ) സ്വർണ്ണം കൊണ്ടൊരു മോതിരമുണ്ടാക്കി. തിരുമേനി അത് ധരിക്കുമ്പോൾ അതിന്റെ കല്ല് ഉള്ളംകയ്യിലാക്കുമായിരുന്നു. ജനങ്ങളും അതുണ്ടാക്കി. പിന്നീടവിടുന്ന് മിമ്പറിലിരുന്ന് മോതിരം ഊരിയിട്ട് പറഞ്ഞു: "ഞാനീ മോതിരം ധരിച്ചിരുന്നു. അതിന്റെ കല്ല് ഞാൻ കൈവെള്ളയിൽ ആക്കുകയും ചെയ്തിരുന്നു." അങ്ങനെ നബി(സ) അത് വലിച്ചെറിഞ്ഞു. പിന്നീട് അവിടന്ന് പറഞ്ഞു: "അല്ലാഹു തന്നെ സത്യം! ഞാനൊരിക്കലുമത് ധരിക്കില്ല." അങ്ങനെ ജനങ്ങളും അവരുടെ മോതിരങ്ങളൊഴിവാക്കി. (മു)', 'عَبْدِ اللهِ بْنِ عُمَرَ', 'അബ്ദുല്ലാഹബ്നു ഉമർ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 713, 713, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=117 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 288, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ اتَّخَذَ خَاتَمًا فَلَبِسَهُ، قَالَ: "شَغَلَنِي هَذَا عَنْكُمْ مُنْذُ الْيَوْمَ: إِلَيْهِ نَظْرَةٌ، وَإِلَيْكُمْ نَظْرَةٌ". ثُمَّ أَلْقَاهُ. (ن)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂൽ(സ) ഒരു മോതിരമുണ്ടാക്കി ധരിച്ചു. അവിടന്ന് പറഞ്ഞു: "ഈ മോതിരം നിങ്ങളിൽ നിന്ന് എന്നെ അശ്രദ്ധനാക്കിയിരിക്കുന്നു. അതിലേക്കൊരു നോട്ടം, പിന്നെ നിങ്ങളിലേക്കൊരു നോട്ടം." ശേഷം നബി(സ) അത് ഒഴിവാക്കി. (ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 713, 713, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=117 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 289, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ: أَنَّهُ رَأَى فِي يَدِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ خَاتَمًا مِنْ وَرِقٍ يَوْمًا وَاحِدًا، فَصَنَعُوهُ فَلَبِسُوهُ، فَطَرَحَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَطَرَحَ النَّاسُ. (ن)', 'അനസ്(റ): അദ്ദേഹം ഒരുദിവസം റസൂൽ(സ)യുടെ കയ്യിൽ ഒരു വെള്ളിമോതിരം കണ്ടു. ജനങ്ങളും മോതിരം ഉണ്ടാക്കിധരിച്ചു. അപ്പോൾ റസൂൽ(സ) അത് ഒഴിവാക്കി. ജനങ്ങൾ അവരുടെ മോതിരങ്ങളും വലിച്ചെറിഞ്ഞു. (ന)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 713, 714, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=117 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 290, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ اتَّخَذَ خَاتَمًا مِنْ ذَهَبٍ، وَكَانَ جَعَلَ فَصَّهُ فِي بَاطِنِ كَفِّهِ، فَاتَّخَذَ النَّاسُ خَوَاتِيمَ مِنْ ذَهَبٍ، فَطَرَحَهُ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَطَرَحَ النَّاسُ خَوَاتِيمَهُمْ، وَاتَّخَذَ خَاتَمًا مِنْ فِضَّةٍ، فَكَانَ يَخْتِمُ بِهِ وَلَا يَلْبَسُهُ. (ن)', 'ഇബ്നുഉമർ(റ): നബി(സ) ഒരു സ്വർണ്ണമോതിരമുണ്ടാക്കി. അവിടന്ന് അതിന്റെ കല്ല് തന്റെ ഉള്ളൻകയ്യിലാക്കിയിരുന്നു. അതോടെ ജനങ്ങളും സ്വർണ്ണമോതിരങ്ങളുണ്ടാക്കി. അപ്പോൾ റസൂൽ(സ) തന്റെ മോതിരം ഒഴിവാക്കി. അന്നേരം ജനങ്ങളും അതൊഴിവാക്കി. അങ്ങനെ അവിടന്ന് വെള്ളിയുടെ ഒരു മോതിരമുണ്ടാക്കി. അവിടന്ന് അതുകൊണ്ട് സീൽ വെക്കുമായിരുന്നു. അത് പക്ഷെ, ധരിക്കാറില്ലായിരുന്നു. (ന)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 714, 714, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=117 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 291, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: اتَّخَذَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ خَاتَمًا مِنْ ذَهَبٍ وَجَعَلَ فَصَّهُ مِمَّا يَلِي بَطْنَ كَفِّهِ، فَاتَّخَذَ النَّاسُ الْخَوَاتِيمَ، فَأَلْقَاهُ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: "لَا أَلْبَسُهُ أَبَدًا"، ثُمَّ اتَّخَذَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ خَاتَمًا مِنْ وَرِقٍ فَأَدْخَلَهُ فِي يَدِهِ، ثُمَّ كَانَ فِي يَدِ أَبِي بَكْرٍ، ثُمَّ كَانَ فِي يَدِ عُمَرَ، ثُمَّ كَانَ فِي يَدِ عُثْمَانَ، حَتَّى هَلَكَ فِي بِئْرِ أَرِيسَ. (ن)', 'ഇബ്നുഉമർ(റ): റസൂൽ(സ) ഒരു സ്വർണ്ണമോതിരം നിർമ്മിക്കുകയും അതിന്റെ കല്ല് അവിടുത്തെ ഉള്ളൻ കയ്യോട് ചേർത്ത് വെക്കുകയും ചെയ്തു. അങ്ങനെ ജനങ്ങളും മോതിരമുണ്ടാക്കി. അപ്പോൾ റസൂൽ(സ) അത് എറിഞ്ഞുകളഞ്ഞു. എന്നിട്ട് പറഞ്ഞു: "ഞാനതൊരിക്കലും ധരിക്കില്ല." പിന്നീട് തിരുമേനി(സ) വെള്ളിമോതിരം ഉണ്ടാക്കി കയ്യിലിട്ടു. നബി(സ)ക്ക് ശേഷം അത് അബൂബക്കർ(റ)വിന്റെ കയ്യിലുണ്ടായിരുന്നു. പിന്നീട് ഉമർ(റ)വിന്റെ കയ്യിലും ശേഷം ഉസ്മാൻ(റ)വിന്റെ കയ്യിലുമായി. അവസാനം അത് ''അരീസ്'' കിണറ്റിൽ വീണ് നഷ്ടപ്പെട്ടു. (ന)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 714, 714, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=117 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 292, 'عَنْ أَبِي مُوسَى رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِنَّ اللَّهَ عَزَّ وَجَلَّ أَحَلَّ لِإِنَاثِ أُمَّتِي الْحَرِيرَ وَالذَّهَبَ، وَحَرَّمَهُ عَلَى ذُكُورِهَا". (ن)', 'അബൂമൂസ(റ): റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹു എന്റെ സമുദായത്തിലെ സ്ത്രീകൾക്ക് സ്വർണ്ണവും പട്ടും അനുവദനീയമാക്കിയിരിക്കുന്നു. പുരുഷന്മാർക്ക് അത് നിഷിദ്ധവുമാക്കിയിരിക്കുന്നു." (ന)', 'أَبِي مُوسَى', 'അബൂമൂസ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 714, 714, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=118 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 293, 'عَنْ عَلِيِّ ابْنِ أَبِي طَالِبٍ رَضِيَ اللهُ عَنْهُ قَالَ: إِنَّ نَبِيَّ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَخَذَ حَرِيرًا فَجَعَلَهُ فِي يَمِينِهِ، وَأَخَذَ ذَهَبًا فَجَعَلَهُ فِي شِمَالِهِ، ثُمَّ قَالَ: "إِنَّ هَذَيْنِ حَرَامٌ عَلَى ذُكُورِ أُمَّتِي". (ن)', 'അലിയ്യുബ്നു അബീത്വാലിബ്(റ): നബി(സ) പട്ടെടുത്ത് അവിടുത്തെ വലത്തെ കയ്യിൽ വെച്ചു. സ്വർണ്ണമെടുത്ത് ഇടത്തെ കയ്യിലും വെച്ചു. എന്നിട്ട് പറഞ്ഞു: "ഇവ രണ്ടും എന്റെ സമുദായത്തിലെ പുരുഷന്മാർക്ക് നിഷിദ്ധമാണ്." (ന)', 'عَلِيِّ ابْنِ أَبِي طَالِبٍ', 'അലിയ്യുബ്നു അബീത്വാലിബ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 714, 714, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=118 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 294, 'عَنْ مُعَاوِيَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنْ لُبْسِ الْحَرِيرِ وَالذَّهَبِ إِلَّا مُقَطَّعًا. وفي رواية: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنْ لُبْسِ الذَّهَبِ إِلَّا مُقَطَّعًا، وَعَنْ رُكُوبِ الْمَيَاثِرِ. وفي رواية: انَّ مُعَاوِيَةَ رَضِيَ اللهُ عَنْهُ قَالَ، وَعِنْدَهُ جَمْعٌ - وفي رواية: جَمَعَ رَهْطًا - مِنْ أَصْحَابِ مُحَمَّدٍ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: أَتَعْلَمُونَ - أَلَسْتُمْ تَعْلَمُونَ - أَنَّ نَبِيَّ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنْ لُبْسِ الذَّهَبِ إِلَّا مُقَطَّعًا؟ قَالُوا: اللَّهُمَّ نَعَمْ. وفي رواية: أَنَّ مُعَاوِيَةَ رَضِيَ اللهُ عَنْهُ عَامَ حَجَّ جَمَعَ نَفَرًا مِنْ أَصْحَابِ رَسُولِ اللهِ صَلَّى اللهُ عليه وسلم فِي الْكَعْبَةِ، فَقَالَ لَهُمْ: أَنْشُدُكُمُ اللهَ، أَنَهَى رَسُولُ اللهِ صلّى الله عليه وسلّم عَنْ لُبْسِ - لُبُوسِ - الذَّهَبِ؟ قَالُوا: نَعَمْ. قَالَ: وَأَنَا أَشْهَدُ. وفي رواية: فَدَعَا نَفَرًا مِنَ الْأَنْصَارِ فِي الْكَعْبَةِ فَقَالَ: أَنْشُدُكُمْ بِاللَّهِ، أَلَمْ تَسْمَعُوا رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَنْهَى عَنِ الذَّهَبِ؟ قَالُوا: نَعَمْ. قَالَ: وَأَنَا أَشْهَدُ. وفي رواية قال: وَحَوْلَهُ نَاسٌ مِنَ الْمُهَاجِرِينَ وَالْأَنْصَارِ، فَقَالَ لَهُمْ: أَتَعْلَمُونَ أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنْ لُبْسِ الْحَرِيرِ؟ فَقَالُوا: اللَّهُمَّ نَعَمْ. قَالَ: وَنَهَى عَنْ لُبْسِ الذَّهَبِ إِلَّا مُقَطَّعًا؟ قَالُوا: نَعَمْ. (ن)', 'മുആവിയ(റ): സ്വര്‍ണ്ണവും പട്ടും അല്‍പ്പമല്ലാതെ ധരിക്കുന്നത് നബി(സ) നിരോധിച്ചിരിക്കുന്നു. മറ്റൊരു നിവേദനം: സ്വര്‍ണ്ണം അല്‍പമല്ലാതെ ധരിക്കുന്നതും ''മയാസിറില്‍'' (ചണവും പട്ടും ഉപയോഗിച്ച് നെയ്ത ജീനിയില്‍ വിരിക്കുന്ന ഒരു വിരി) യാത്രചെയ്യുന്നതും നബി(സ) നിരോധിച്ചിരിക്കുന്നു. മറ്റൊരു നിവേദനം: മുഹമ്മദ്‌നബി(സ)യുടെ അനുയായികളുടെ ഒരു കൂട്ടം തന്റെ കൂടെയുണ്ടായിരിക്കെ മുആവിയ(റ) ചോദിച്ചു: അല്‍പമല്ലാതെ സ്വര്‍ണ്ണം ധരിക്കുന്നത് നബി(സ) നിരോധിച്ചിരിക്കുന്നുവെന്നത് നിങ്ങള്‍ക്കറിയില്ലേ? അവര്‍ പറഞ്ഞു: അതെ, അല്ലാഹുവാണ് സത്യം. മറ്റൊരു നിവേദനം: മുആവിയ(റ) ഹജ്ജിന്റെ വര്‍ഷത്തില്‍ റസൂല്‍(സ)യുടെ സ്വഹാബികളുടെ ഒരു കൂട്ടത്തെ കഅ്ബയില്‍ ഒരുമിച്ചുകൂട്ടി. എന്നിട്ടവരോട് പറഞ്ഞു: അല്ലാഹുവിനെ മുന്‍നിറുത്തി നിങ്ങളോട് ഞാന്‍ ചോദിക്കുന്നു: സ്വര്‍ണ്ണം ധരിക്കുന്നത് റസൂല്‍(സ) നിരോധിച്ചിട്ടില്ലെയോ? അവര്‍ പറഞ്ഞു: അതെ. മുആവിയ(റ) പറഞ്ഞു: ഞാനും സാക്ഷ്യം വഹിക്കുന്നു. മറ്റൊരു നിവേദനം: മുആവിയ(റ) ഒരു കൂട്ടം അന്‍സാറുകളെ കഅ്ബയില്‍ വിളിച്ച് ചേര്‍ത്തു. എന്നിട്ടവരോട് പറഞ്ഞു: അല്ലാഹുവിനെ മുന്‍നിറുത്തി നിങ്ങളോട് ഞാന്‍ ചോദിക്കുന്നു: റസൂല്‍(സ) സ്വര്‍ണ്ണം നിരോധിക്കുന്നത് നിങ്ങള്‍ കേട്ടിട്ടില്ലേ?. അവര്‍ പറഞ്ഞു: അതെ. മുആവിയ(റ) പറഞ്ഞു: ഞാന്‍ സാക്ഷ്യം വഹിക്കുന്നു. മറ്റൊരു നിവേദനം: അദ്ദേഹത്തിന്റെ കൂടെ അന്‍സാറുകളും മുഹാജിറുകളുമായ ജനങ്ങളുണ്ട്. അവരോട് മുആവിയ(റ) ചോദിച്ചു: പട്ട് റസൂല്‍(സ) ധരിക്കുന്നത് നിരോധിച്ചത് നിങ്ങള്‍ക്കറിയില്ലേ. അവര്‍ പറഞ്ഞു: അല്ലാഹു തന്നെ സത്യം, അതെ. മുആവിയ(റ) ചോദിച്ചു: സ്വര്‍ണ്ണം അല്‍പമല്ലാതെ ധരിക്കുന്നത് റസൂല്‍(സ) നിരോധിച്ചിട്ടില്ലേ? അവര്‍ പ്രതിവചിച്ചു: അതെ. (ന)', 'مُعَاوِيَةَ', 'മുആവിയ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 715, 715, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=118 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=8 and h.hadith_no=294), 1, 'وَفِي رِوَايَةٍ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنْ لُبْسِ الذَّهَبِ إِلَّا مُقَطَّعًا، وَعَنْ رُكُوبِ الْمَيَاثِرِ.', 'മറ്റൊരു നിവേദനം: സ്വര്‍ണ്ണം അല്‍പമല്ലാതെ ധരിക്കുന്നതും ''മയാസിറില്‍'' (ചണവും പട്ടും ഉപയോഗിച്ച് നെയ്ത ജീനിയില്‍ വിരിക്കുന്ന ഒരു വിരി) യാത്രചെയ്യുന്നതും നബി(സ) നിരോധിച്ചിരിക്കുന്നു.');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=8 and h.hadith_no=294), 2, 'وَفِي رِوَايَةٍ: انَّ مُعَاوِيَةَ رَضِيَ اللهُ عَنْهُ قَالَ، وَعِنْدَهُ جَمْعٌ -', 'മറ്റൊരു നിവേദനം: മുഹമ്മദ്‌നബി(സ)യുടെ അനുയായികളുടെ ഒരു കൂട്ടം തന്റെ കൂടെയുണ്ടായിരിക്കെ മുആവിയ(റ) ചോദിച്ചു: അല്‍പമല്ലാതെ സ്വര്‍ണ്ണം ധരിക്കുന്നത് നബി(സ) നിരോധിച്ചിരിക്കുന്നുവെന്നത് നിങ്ങള്‍ക്കറിയില്ലേ? അവര്‍ പറഞ്ഞു: അതെ, അല്ലാഹുവാണ് സത്യം.');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=8 and h.hadith_no=294), 3, 'وَفِي رِوَايَةٍ: جَمَعَ رَهْطًا - مِنْ أَصْحَابِ مُحَمَّدٍ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: أَتَعْلَمُونَ - أَلَسْتُمْ تَعْلَمُونَ - أَنَّ نَبِيَّ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنْ لُبْسِ الذَّهَبِ إِلَّا مُقَطَّعًا؟ قَالُوا: اللَّهُمَّ نَعَمْ.', 'മറ്റൊരു നിവേദനം: മുആവിയ(റ) ഹജ്ജിന്റെ വര്‍ഷത്തില്‍ റസൂല്‍(സ)യുടെ സ്വഹാബികളുടെ ഒരു കൂട്ടത്തെ കഅ്ബയില്‍ ഒരുമിച്ചുകൂട്ടി. എന്നിട്ടവരോട് പറഞ്ഞു: അല്ലാഹുവിനെ മുന്‍നിറുത്തി നിങ്ങളോട് ഞാന്‍ ചോദിക്കുന്നു: സ്വര്‍ണ്ണം ധരിക്കുന്നത് റസൂല്‍(സ) നിരോധിച്ചിട്ടില്ലെയോ? അവര്‍ പറഞ്ഞു: അതെ. മുആവിയ(റ) പറഞ്ഞു: ഞാനും സാക്ഷ്യം വഹിക്കുന്നു.');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=8 and h.hadith_no=294), 4, 'وَفِي رِوَايَةٍ: أَنَّ مُعَاوِيَةَ رَضِيَ اللهُ عَنْهُ عَامَ حَجَّ جَمَعَ نَفَرًا مِنْ أَصْحَابِ رَسُولِ اللهِ صَلَّى اللهُ عليه وسلم فِي الْكَعْبَةِ، فَقَالَ لَهُمْ: أَنْشُدُكُمُ اللهَ، أَنَهَى رَسُولُ اللهِ صلّى الله عليه وسلّم عَنْ لُبْسِ - لُبُوسِ - الذَّهَبِ؟ قَالُوا: نَعَمْ. قَالَ: وَأَنَا أَشْهَدُ.', 'മറ്റൊരു നിവേദനം: മുആവിയ(റ) ഒരു കൂട്ടം അന്‍സാറുകളെ കഅ്ബയില്‍ വിളിച്ച് ചേര്‍ത്തു. എന്നിട്ടവരോട് പറഞ്ഞു: അല്ലാഹുവിനെ മുന്‍നിറുത്തി നിങ്ങളോട് ഞാന്‍ ചോദിക്കുന്നു: റസൂല്‍(സ) സ്വര്‍ണ്ണം നിരോധിക്കുന്നത് നിങ്ങള്‍ കേട്ടിട്ടില്ലേ?. അവര്‍ പറഞ്ഞു: അതെ. മുആവിയ(റ) പറഞ്ഞു: ഞാന്‍ സാക്ഷ്യം വഹിക്കുന്നു.');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=8 and h.hadith_no=294), 5, 'وَفِي رِوَايَةٍ: فَدَعَا نَفَرًا مِنَ الْأَنْصَارِ فِي الْكَعْبَةِ فَقَالَ: أَنْشُدُكُمْ بِاللَّهِ، أَلَمْ تَسْمَعُوا رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَنْهَى عَنِ الذَّهَبِ؟ قَالُوا: نَعَمْ. قَالَ: وَأَنَا أَشْهَدُ.', 'മറ്റൊരു നിവേദനം: അദ്ദേഹത്തിന്റെ കൂടെ അന്‍സാറുകളും മുഹാജിറുകളുമായ ജനങ്ങളുണ്ട്. അവരോട് മുആവിയ(റ) ചോദിച്ചു: പട്ട് റസൂല്‍(സ) ധരിക്കുന്നത് നിരോധിച്ചത് നിങ്ങള്‍ക്കറിയില്ലേ. അവര്‍ പറഞ്ഞു: അല്ലാഹു തന്നെ സത്യം, അതെ. മുആവിയ(റ) ചോദിച്ചു: സ്വര്‍ണ്ണം അല്‍പമല്ലാതെ ധരിക്കുന്നത് റസൂല്‍(സ) നിരോധിച്ചിട്ടില്ലേ? അവര്‍ പ്രതിവചിച്ചു: അതെ. (ന)');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=8 and h.hadith_no=294), 6, 'وَفِي رِوَايَةٍ قال: وَحَوْلَهُ نَاسٌ مِنَ الْمُهَاجِرِينَ وَالْأَنْصَارِ، فَقَالَ لَهُمْ: أَتَعْلَمُونَ أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنْ لُبْسِ الْحَرِيرِ؟ فَقَالُوا: اللَّهُمَّ نَعَمْ. قَالَ: وَنَهَى عَنْ لُبْسِ الذَّهَبِ إِلَّا مُقَطَّعًا؟ قَالُوا: نَعَمْ. (ن)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 295, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: قَدِمَتْ عَلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حِلْيَةٌ مِنْ عِنْدِ النَّجَاشِيِّ أَهْدَاهَا لَهُ، فِيهَا خَاتَمٌ مِنْ ذَهَبٍ فِيهِ فَصٌّ حَبَشِيٌّ، قَالَتْ: فَأَخَذَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِعُودٍ مُعْرِضًا عَنْهُ، أَوْ بِبَعْضِ أَصَابِعِهِ، ثُمَّ دَعَا أُمَامَةَ ابْنَةَ أَبِي الْعَاصِ - ابْنَةَ ابْنَتِهِ زَيْنَبَ - فَقَالَ: "تَحَلَّيْ بِهَذَا يَا بُنَيَّةُ". (د,جه)', 'ആഇശ(റ): നജാശി രാജാവ് സമ്മാനമായി നല്‍കിയ ഒരു ആഭരണം നബി(സ)ക്ക് ലഭിച്ചു. അബ്‌സീനിയന്‍ കല്ല് പതിച്ച ഒരു സ്വര്‍ണ്ണമോതിരവും അതിലുണ്ടായിരുന്നു. അവഗണനാഭാവത്തോടെ ഒരു വടി കൊണ്ടോ അല്ലെങ്കിൽ വിരൽ കൊണ്ടോ റസൂൽ(സ) അതെടുത്തു. പിന്നെ ഉമാമതുബിൻത് അബിൽആസ്(റ)വിനെ - നബി(സ)യുടെ മകളായ സൈനബ്(റ)യുടെ മകൾ - വിളിച്ചുകൊണ്ടു പറഞ്ഞു: "പൊന്നുമോളേ, നീ ഇത് ധരിച്ചുകൊള്ളുക." (ദ,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 715, 716, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=119 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 296, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ أَحَبَّ أَنْ يُحَلِّقَ حَبِيبَهُ حَلْقَةً مِنْ نَارٍ فَلْيُحَلِّقْهُ حَلْقَةً مِنْ ذَهَبٍ، وَمَنْ أَحَبَّ أَنْ يُسَوِّرَ حَبِيبَهُ سِوَارًا مِنْ نَارٍ فَلْيُسَوِّرْهُ سِوَارًا مِنْ ذَهَبٍ، وَلَكِنْ عَلَيْكُمْ بِالْفِضَّةِ فَالْعَبُوا بِهَا". (د)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "ആരെങ്കിലും തന്റെ സ്നേഹിതന് നരകത്തിലെ വളയം ധരിപ്പിക്കാൻ ആഗ്രഹിക്കുന്നുവെങ്കിൽ അവന്റെ കഴുത്തിൽ സ്വർണ്ണവളയം ധരിപ്പിക്കട്ടെ. ആരെങ്കിലും തന്റെ സ്നേഹിതന് നരകത്തിലെ വള ധരിപ്പിക്കാൻ ആഗ്രഹിക്കുന്നുണ്ടെങ്കിൽ അവൻ അവനെ സ്വർണ്ണവള ധരിപ്പിക്കട്ടെ. എങ്കിലും വെള്ളി നിങ്ങൾ ധരിക്കുക, അതിൽ നിങ്ങൾ വിനോദം കണ്ടെത്തുക." (ദ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 716, 716, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=119 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 297, 'عَنْ أُخْتِ لِحُذَيْفَةَ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "يَا مَعْشَرَ النِّسَاءِ، أَمَا لَكُنَّ فِي الْفِضَّةِ مَا تَحَلَّيْنَ بِهِ، أَمَا إِنَّهُ لَيْسَ مِنْكُنَّ امْرَأَةٌ تُحَلَّى ذَهَبًا تُظْهِرُهُ إِلَّا عُذِّبَتْ بِهِ". (د,ن)', 'ഹുദൈഫ(റ)വിന്റെ സഹോദരി: റസൂൽ(സ) പറഞ്ഞു: "സ്ത്രീ സമൂഹമേ, അണിയാൻ നിങ്ങൾക്ക് വെള്ളിയിലില്ലേ. സ്വർണ്ണം ധരിച്ച് അത് പുറത്തുകാണിക്കുന്ന നിങ്ങളിൽപ്പെട്ട ഒരു സ്ത്രീയും അത് കാരണത്താൽ ശിക്ഷിക്കപ്പെടാതിരിക്കില്ല." (ദ,ന)', 'أُخْتِ لِحُذَيْفَةَ', 'ഹുദൈഫ(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 716, 716, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=119 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 298, 'عَنْ أَسْمَاءَ بِنْتِ يَزِيدَ رَضِيَ اللَّهُ عَنْهَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "أَيُّمَا امْرَأَةٍ تَقَلَّدَتْ قِلَادَةً مِنْ ذَهَبٍ قُلِّدَتْ فِي عُنُقِهَا مِثْلَهُ مِنَ النَّارِ يَوْمَ الْقِيَامَةِ، وَأَيُّمَا امْرَأَةٍ جَعَلَتْ فِي أُذُنِهَا خُرْصًا مِنْ ذَهَبٍ جُعِلَ فِي أُذُنِهَا مِثْلُهُ مِنَ النَّارِ يَوْمَ الْقِيَامَةِ". (د,ن)', 'അസ്മാഉബിൻത് യസീദ്(റ): റസൂൽ(സ) പറഞ്ഞു: ഏതെങ്കിലുമൊരു സ്ത്രീ സ്വർണ്ണമാല ധരിച്ചാൽ അന്ത്യദിനത്തിൽ അവളുടെ കഴുത്തിൽ അതുപോലെയുള്ളൊരു തീയിനാലുള്ള മാല ധരിപ്പിക്കപ്പെടും. ഏതെങ്കിലുമൊരു സ്ത്രീ തന്റെ കാതിൽ സ്വർണ്ണക്കമ്മൽ ധരിച്ചാൽ അന്ത്യനാളിൽ തീയിനാലുള്ള അതുപോലോത്ത കമ്മൽ അവളുടെ കാതിൽ ധരിപ്പിക്കപ്പെടും. (ദ,ന)', 'أَسْمَاءَ بِنْتِ يَزِيدَ', 'അസ്മാഉബിൻത് യസീദ്(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 716, 716, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=119 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 299, 'عَنْ مُعَاوِيَةَ بْنِ أَبِي سُفْيَانَ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنْ رُكُوبِ النِّمَارِ، وَعَنْ لُبْسِ الذَّهَبِ إِلَّا مُقَطَّعًا. (د,ن)', 'മുആവിയ(റ): പുലിയുടെ പുറത്തിരുന്ന് യാത്രചെയ്യുന്നതും സ്വർണ്ണം വളരെ കുറച്ചല്ലാതെ ധരിക്കുന്നതും റസൂൽ(സ) നിരോധിച്ചിരിക്കുന്നു. (ദ,ന)', 'مُعَاوِيَةَ بْنِ أَبِي سُفْيَانَ', 'മുആവിയ(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 716, 716, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=119 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 300, 'عَنْ عُقْبَةَ بْنِ عَامِرٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَمْنَعُ أَهْلَهُ الْحِلْيَةَ وَالْحَرِيرَ، وَيَقُولُ: "إِنْ كُنْتُمْ تُحِبُّونَ حِلْيَةَ الْجَنَّةِ وَحَرِيرَهَا فَلَا تَلْبَسُوهَا فِي الدُّنْيَا". (ن)', 'ഉഖ്ബതുബ്നു ആമിർ(റ): റസൂൽ(സ) അവിടത്തെ കുടുംബത്തിന് ആഭരണങ്ങളും പട്ടും വിലക്കിയിരുന്നു. അവിടന്ന് പറയുമായിരുന്നു: "നിങ്ങൾക്ക് സ്വർഗത്തിലെ ആഭരണങ്ങളും പട്ടും ഇഷ്ടമാണെങ്കിൽ അത് നിങ്ങൾ ദുൻയാവിൽ വെച്ച് ധരിക്കരുത്." (ന)', 'عُقْبَةَ بْنِ عَامِرٍ', 'ഉഖ്ബതുബ്നു ആമിർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 716, 716, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=120 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 301, 'عَنْ ثَوْبَانَ رَضِيَ اللهُ عَنْهُ، مَوْلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: جَاءَتْ بِنْتُ هُبَيْرَةَ إِلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَفِي يَدِهَا فَتَخٌ، وفِي رِوَايَةٍ: مِنْ ذَهَبٍ، فَجَعَلَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَضْرِبُ يَدَهَا، فَدَخَلَتْ عَلَى فَاطِمَةَ بِنْتِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ تَشْكُو إِلَيْهَا الَّذِي صَنَعَ بِهَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَانْتَزَعَتْ فَاطِمَةُ سِلْسِلَةً فِي عُنُقِهَا مِنْ ذَهَبٍ وَقَالَتْ: هَذِهِ أَهْدَاهَا إِلَيَّ أَبُو حَسَنٍ. فَدَخَلَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَالسِّلْسِلَةُ فِي يَدِهَا، فَقَالَ: "يَا فَاطِمَةُ، أَيَغُرُّكِ أَنْ يَقُولَ النَّاسُ: ابْنَةُ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، وَفِي يَدِهَا سِلْسِلَةٌ مِنْ نَارٍ". ثُمَّ خَرَجَ وَلَمْ يَقْعُدْ، فَأَرْسَلَتْ فَاطِمَةُ بِالسِّلْسِلَةِ إِلَى السُّوقِ فَبَاعَتْهَا وَاشْتَرَتْ بِثَمَنِهَا غُلَامًا - عَبْدًا - فَأَعْتَقَتْهُ، فَحُدِّثَ بِذَلِكَ فَقَالَ: "الْحَمْدُ لِلَّهِ الَّذِي أَنْجَى فَاطِمَةَ مِنَ النَّارِ". (ن)', 'റസൂൽ(സ)യുടെ അടിമയായ സൗബാൻ(റ): ഹുബൈറയുടെ മകൾ അല്ലാഹുവിന്റെ റസൂൽ(സ)യുടെ സന്നിധിയിൽ വന്നു. അവളുടെ കയ്യിൽ സ്വർണ്ണത്തിന്റെ വലിയ വലിയ മോതിരങ്ങളുണ്ട്. റസൂൽ(സ) അവളുടെ കയ്യിൽ അടിക്കാൻ തുടങ്ങി. റസൂൽ(സ) അടിച്ചതിൽ വേവലാതി പറഞ്ഞുകൊണ്ട് അവൾ റസൂൽ(സ)യുടെ മകളായ ഫാതിമ(റ)യുടെ അടുത്ത് ചെന്നു. അപ്പോൾ ഫാതിമ(റ) അവരുടെ കഴുത്തിലെ സ്വർണ്ണമാലയൂരിവെച്ചു. അവർ പറഞ്ഞു: ഇതെനിക്ക് ഹസന്റെ പിതാവ് സമ്മാനമായി നൽകിയതാണ്. അപ്പോൾ റസൂൽ(സ)കടന്നുവന്നു, മാല അപ്പോൾ അവരുടെ കയ്യിലുണ്ട്. റസൂൽ(സ) പറഞ്ഞു: "ഓ ഫാതിമ, കൈയിൽ നരകത്തിലെ മാലയുമായി ഇതാ പ്രവാചക പുത്രി, എന്ന് ജനങ്ങൾ പറയുന്നത് നിനക്കിഷ്ടമുണ്ടോ?" ശേഷം നബി(സ) പുറപ്പെട്ടു, അവിടന്ന് ഇരുന്നില്ല. ഫാതിമബീവി(റ) അങ്ങാടിയിലേക്ക് മാലയുമായി ആളെ അയച്ചു. അവരത് വിറ്റ് അതിന്റെ വിലക്ക് ഒരു അടിമയെ വാങ്ങി മോചിപ്പിച്ചു. ഈ വിഷയം നബി(സ)യെ ധരിപ്പിച്ചു. അവിടന്ന് പറഞ്ഞു: "ഫാതിമയെ നരകത്തിൽ നിന്ന് രക്ഷപ്പെടുത്തിയ അല്ലാഹുവിനാണ് സർവ്വസ്തുതിയും." (ന)', 'ثَوْبَانَ', 'റസൂൽ(സ)യുടെ അടിമയായ സൗബാൻ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 717, 717, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=120 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=8 and h.hadith_no=301), 1, 'وَفِي رِوَايَةٍ: مِنْ ذَهَبٍ، فَجَعَلَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَضْرِبُ يَدَهَا، فَدَخَلَتْ عَلَى فَاطِمَةَ بِنْتِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ تَشْكُو إِلَيْهَا الَّذِي صَنَعَ بِهَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَانْتَزَعَتْ فَاطِمَةُ سِلْسِلَةً فِي عُنُقِهَا مِنْ ذَهَبٍ وَقَالَتْ: هَذِهِ أَهْدَاهَا إِلَيَّ أَبُو حَسَنٍ. فَدَخَلَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَالسِّلْسِلَةُ فِي يَدِهَا، فَقَالَ: "يَا فَاطِمَةُ، أَيَغُرُّكِ أَنْ يَقُولَ النَّاسُ: ابْنَةُ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، وَفِي يَدِهَا سِلْسِلَةٌ مِنْ نَارٍ". ثُمَّ خَرَجَ وَلَمْ يَقْعُدْ، فَأَرْسَلَتْ فَاطِمَةُ بِالسِّلْسِلَةِ إِلَى السُّوقِ فَبَاعَتْهَا وَاشْتَرَتْ بِثَمَنِهَا غُلَامًا - عَبْدًا - فَأَعْتَقَتْهُ، فَحُدِّثَ بِذَلِكَ فَقَالَ: "الْحَمْدُ لِلَّهِ الَّذِي أَنْجَى فَاطِمَةَ مِنَ النَّارِ". (ن)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 302, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: كُنْتُ قَاعِدًا عِنْدَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَأَتَتْهُ امْرَأَةٌ فَقَالَتْ: يَا رَسُولَ اللهِ، سِوَارَيْنِ مِنْ ذَهَبٍ. قَالَ: "سِوَارَانِ مِنْ نَارٍ". قَالَتْ: يَا رَسُولَ اللهِ، طَوْقٌ مِنْ ذَهَبٍ. قَالَ: "طَوْقٌ مِنْ نَارٍ". قَالَتْ: قُرْطَيْنِ مِنْ ذَهَبٍ. قَالَ: "قُرْطَيْنِ مِنْ نَارٍ". قَالَ: وَكَانَ عَلَيْهَا سِوَارَانِ مِنْ ذَهَبٍ فَرَمَتْ بِهِمَا، قَالَتْ: يَا رَسُولَ اللهِ، إِنَّ الْمَرْأَةَ إِذَا لَمْ تَتَزَيَّنْ لِزَوْجِهَا صَلِفَتْ عِنْدَهُ. قَالَ: "مَا يَمْنَعُ إِحْدَاكُنَّ أَنْ تَصْنَعَ قُرْطَيْنِ مِنْ فِضَّةٍ، ثُمَّ تُصَفِّرَهُ بِزَعْفَرَانٍ. أَوْ: بِعَبِيرٍ". (ن)', 'അബൂഹുറൈറ(റ): ഞാൻ നബി(സ)യുടെ കൂടെ ഇരിക്കുകയായിരുന്നു. അപ്പോൾ ഒരു സ്ത്രീ തിരുസന്നിധിയിലേക്ക് വന്നുകൊണ്ട് ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, സ്വർണ്ണത്തിന്റെ രണ്ട് വളകൾ. റസൂൽ(സ) പറഞ്ഞു: "നരകത്തിലെ രണ്ട് വളകൾ." അവർ വീണ്ടും ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, സ്വർണ്ണത്തിന്റെ കണ്ഠാഭരണം? റസൂൽ(സ) പറഞ്ഞു: "നരകത്തിലെ കണ്ഠാഭരണം." അവർ ചോദിച്ചു: സ്വർണ്ണത്തിന്റെ രണ്ട് കമ്മലുകൾ? റസൂൽ(സ) പറഞ്ഞു: "നരകത്തിലെ രണ്ട് കമ്മലുകൾ." അബൂഹുറൈറ(റ) പറയുന്നു: അവളുടെ ശരീരത്തിൽ സ്വർണ്ണത്തിന്റെ രണ്ട് വളകളുണ്ടായിരുന്നു. അവ രണ്ടും അവളെടുത്തെറിഞ്ഞു. അവൾ പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, സ്ത്രീ ഭർത്താവിന് വേണ്ടി അണിഞ്ഞൊരുങ്ങിയിട്ടില്ലെങ്കിൽ അവൾ ഭർത്താവിന് ഭാരമായിത്തീരും. നബി(സ) പറഞ്ഞു: "വെള്ളി കൊണ്ട് രണ്ട് കമ്മലുകൾ ഉണ്ടാക്കി പിന്നെയതിന് കുങ്കുമം കൊണ്ട് മഞ്ഞനിറം നൽകാൻ നിങ്ങളിലൊരാളെ തടയുന്നതെന്താണ്?" (ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 717, 717, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=120 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 303, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ رَأَى عَلَيْهَا مَسَكَتَيْ ذَهَبٍ، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَلَا أُخْبِرُكِ بِمَا هُوَ أَحْسَنُ مِنْ هَذَا؟ لَوْ نَزَعْتِ هَذَا وَجَعَلْتِ مَسَكَتَيْنِ مِنْ وَرِقٍ، ثُمَّ صَفَّرْتِهِمَا بِزَعْفَرَانٍ، كَانَتَا حَسَنَتَيْنِ". (ن)', 'ആഇശ(റ): മഹതിയുടെ കയ്യിൽ റസൂൽ(സ) സ്വർണ്ണത്തിന്റെ രണ്ട് വളകൾ കണ്ടു. അപ്പോൾ അവിടുന്ന് പറഞ്ഞു: "ഇതിനേക്കാൾ സുന്ദരമായത് നിനക്ക് ഞാൻ പറഞ്ഞുതരട്ടെയോ? ഇതുരിക്കളഞ്ഞ് പകരം നീ വെള്ളിയുടെ രണ്ട് വളകൾ ധരിച്ച് അതിന് കുങ്കുമം കൊണ്ട് മഞ്ഞനിറം പൂശിയാൽ അത് നന്നായിരിക്കും." (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 717, 718, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=120 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 304, 'عَنْ أَبِي أُمَامَةَ بْنِ سَهْلٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَانَتْ قَبِيعَةُ سَيْفِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنْ فِضَّةٍ. (ن)', 'അബൂഉമാമതുബ്നു സഹ്‌ൽ(റ): നബി(സ)യുടെ വാളിന്റെ പിടി വെള്ളിയാലുള്ളതായിരുന്നു. (ന)', 'أَبِي أُمَامَةَ بْنِ سَهْلٍ', 'അബൂഉമാമതുബ്നു സഹ്‌ൽ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 718, 718, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=121 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 305, 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَانَ نَعْلُ سَيْفِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنْ فِضَّةٍ، وَقَبِيعَةُ سَيْفِهِ فِضَّةً، وَمَا بَيْنَ ذَلِكَ حِلَقُ فِضَّةٍ. (ن)', 'അനസ്(റ): റസൂൽ(സ)യുടെ വാളുറയുടെ താഴ്‍ഭാഗവും വാളിന്റെ പിടിയും വെള്ളികൊണ്ടുള്ളതായിരുന്നു. അതിനിടയിലുള്ളത് വെള്ളിയുടെ വളയങ്ങളായിരുന്നു. (ന)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 718, 718, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=121 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 306, 'عَنْ عَرْفَجَةَ بْنِ أَسْعَدَ رَضِيَ اللَّهُ عَنْهُ: أَنَّهُ أُصِيبَ أَنْفُهُ يَوْمَ الْكُلَابِ فِي الْجَاهِلِيَّةِ، فَاتَّخَذَ أَنْفًا مِنْ وَرِقٍ فَأَنْتَنَ عَلَيْهِ، فَأَمَرَهُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ يَتَّخِذَ أَنْفًا مِنْ ذَهَبٍ. (ن)', 'അർഫജതുബ്നു അസ്അദ്(റ): ജാഹിലിയ്യാ കാലത്തെ ''കുലാബ്'' ദിനത്തിൽ അദ്ദേഹത്തിന്റെ മൂക്കിന് പരുക്കു പറ്റി. വെള്ളി കൊണ്ടദ്ദേഹമൊരു മൂക്ക് വെച്ചപ്പോൾ അതിൽ നിന്ന് ദുർഗന്ധം വമിച്ചു. അദ്ദേഹത്തോട് നബി(സ) സ്വർണ്ണം കൊണ്ടൊരു മൂക്കുണ്ടാക്കാൻ കൽപിച്ചു. (ന)', 'عَرْفَجَةَ بْنِ أَسْعَدَ', 'അർഫജതുബ്നു അസ്അദ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 718, 718, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=122 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 307, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا أُتِيَ بِطِيبٍ لَمْ يَرُدَّهُ. (ن)', 'അനസുബ്നു മാലിക്(റ): സുഗന്ധം നൽകപ്പെട്ടാൽ, നബി(സ) അത് നിരസിക്കുമായിരുന്നില്ല. (ന)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 718, 718, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=123 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 308, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ عُرِضَ عَلَيْهِ طِيبٌ فَلَا يَرُدَّهُ، فَإِنَّهُ خَفِيفُ الْمَحْمَلِ طَيِّبُ الرَّائِحَةِ". (ن)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "ആർക്കെങ്കിലും സുഗന്ധം നൽകപ്പെട്ടാൽ അവനത് നിരസിക്കരുത്. ഭാരം കുറഞ്ഞതും നല്ല സുഗന്ധമുള്ളതുമാണത്." (ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 718, 718, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=123 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 309, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ امْرَأَةً مِنْ بَنِي إِسْرَائِيلَ اتَّخَذَتْ خَاتَمًا مِنْ ذَهَبٍ وَحَشَتْهُ مِسْكًا". قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "هُوَ أَطْيَبُ الطِّيبِ". (ن)', 'അബൂസഈദിൽ ഖുദ്രീ(റ): റസൂൽ(സ) പറഞ്ഞു: "ബനൂഇസ്രാഈലിൽ പെട്ട ഒരുസ്ത്രീ സ്വർണ്ണം കൊണ്ടൊരു മോതിരമുണ്ടാക്കി. അതിൽ അവൾ കസ്തൂരി നിറച്ചു". റസൂൽ(സ) പറഞ്ഞു: "അതാണ് ഏറ്റവും നല്ല സുഗന്ധം." (ന)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദിൽ ഖുദ്രീ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 719, 719, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=124 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 310, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا، سُئِلَتْ: أَكَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَتَطَيَّبُ؟ قَالَتْ: نَعَمْ، بِذِكَارَةِ الطِّيبِ: الْمِسْكِ وَالْعَنْبَرِ. (ن)', 'ആഇശ(റ): മഹതിയോട് ചോദിക്കപ്പെട്ടു: റസൂൽ(സ) സുഗന്ധമുപയോഗിച്ചിരുന്നോ? അവർ പറഞ്ഞു: അതെ, പുരുഷൻമാരുടെ സുഗന്ധം: കസ്തൂരിയും അമ്പറും. (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 719, 719, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=125 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 311, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: طَيَّبْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِيَدَيَّ بِذَرِيرَةٍ فِي حَجَّةِ الْوَدَاعِ لِلْحِلِّ وَالْإِحْرَامِ. (خ)', 'ആഇശ(റ): ഹജ്ജതുൽ വിദാഇന്റെ അവസരത്തിൽ, ഇഹ്‌റാമിന്റെ അവസ്ഥയിലും ഇഹ്‌റാമിന്റേതല്ലാത്ത അവസ്ഥയിലും ഞാൻ റസൂൽ(സ)ക്ക് എന്റെ കൈകൊണ്ട് ദരീറത്ത് (ഒരുതരം സുഗന്ധ ദ്രവ്യം) പുരട്ടിക്കൊടുത്തു. (ബു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 719, 719, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=126 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 312, 'عَنْ يَعْلَى بْنِ مُرَّةَ رَضِيَ اللَّهُ عَنْهُ: أَنَّهُ مَرَّ عَلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهُوَ مُتَخَلِّقٌ، فَقَالَ لَهُ: "هَلْ لَكَ امْرَأَةٌ". قُلْتُ: لَا قَالَ: "فَاغْسِلْهُ، ثُمَّ اغْسِلْهُ، ثُمَّ لَا تَعُدْ". وَفِي رِوَايَةٍ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَبْصَرَ رَجُلًا مُتَخَلِّقًا، قَالَ: "اذْهَبْ فَاغْسِلْهُ، ثُمَّ اغْسِلْهُ، وَلَا تَعُدْ". وَفِي رِوَايَةٍ: قَالَ: أَبْصَرَنِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَبِي رَدْعٌ مِنْ خَلُوقٍ، قَالَ: "يَا يَعْلَى ، لَكَ امْرَأَةٌ". قُلْتُ: لَا قَالَ: "اغْسِلْهُ، ثُمَّ لَا تَعُدْ. ثُمَّ اغْسِلْهُ، ثُمَّ لَا تَعُدْ. ثُمَّ اغْسِلْهُ، ثُمَّ لَا تَعُدْ". قَالَ: فَغَسَلْتُهُ ثُمَّ لَمْ أَعُدْ، ثُمَّ غَسَلْتُهُ ثُمَّ لَمْ أَعُدْ، ثُمَّ غَسَلْتُهُ ثُمَّ لَمْ أَعُدْ، وَفِي رِوَايَةٍ قَالَ: مَرَرْتُ عَلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَأَنَا مُتَخَلِّقٌ، فَقَالَ: "أَيْ يَعْلَى، هَلْ لَكَ امْرَأَةٌ؟". قُلْتُ: لَا. قَالَ: "اذْهَبْ فَاغْسِلْهُ، ثُمَّ اغْسِلْهُ، ثُمَّ اغْسِلْهُ، ثُمَّ لَا تَعُدْ". قَالَ: فَذَهَبْتُ فَغَسَلْتُهُ، ثُمَّ غَسَلْتُهُ، ثُمَّ غَسَلْتُهُ، ثُمَّ لَمْ أَعُدْ. (ن)', 'യഅ്‌ലബ്‌നു മുർറ(റ): അദ്ദേഹം നബി(സ)യുടെ അരികിലൂടെ ഖലൂഖ് പുരട്ടി നടന്നുപോയി. അപ്പോൾ അദ്ദേഹത്തോട് റസൂൽ(സ) ചോദിച്ചു: "നിങ്ങൾക്ക് ഭാര്യയുണ്ടോ?" അദ്ദേഹം പറഞ്ഞു: ഇല്ല. നബി(സ) പറഞ്ഞു: "നിങ്ങളത് കഴുകുക. പിന്നെയും കഴുകുക. ഇനി മടങ്ങരുത്."
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=8 and h.hadith_no=312), 1, 'وَفِي رِوَايَةٍ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَبْصَرَ رَجُلًا مُتَخَلِّقًا، قَالَ: "اذْهَبْ فَاغْسِلْهُ، ثُمَّ اغْسِلْهُ، وَلَا تَعُدْ".', 'മറ്റൊരു നിവേദനം: ഖലൂഖ് പുരട്ടിയ ഒരാളെ കണ്ടപ്പോൾ നബി(സ) പറഞ്ഞു: "നിങ്ങൾ പോയി അത് കഴുകുക. പിന്നെയും കഴുകുക. പിന്നെ നിങ്ങൾ മടങ്ങരുത്."');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=8 and h.hadith_no=312), 2, 'وَفِي رِوَايَةٍ: قَالَ: أَبْصَرَنِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَبِي رَدْعٌ مِنْ خَلُوقٍ، قَالَ: "يَا يَعْلَى ، لَكَ امْرَأَةٌ". قُلْتُ: لَا قَالَ: "اغْسِلْهُ، ثُمَّ لَا تَعُدْ. ثُمَّ اغْسِلْهُ، ثُمَّ لَا تَعُدْ. ثُمَّ اغْسِلْهُ، ثُمَّ لَا تَعُدْ". قَالَ: فَغَسَلْتُهُ ثُمَّ لَمْ أَعُدْ، ثُمَّ غَسَلْتُهُ ثُمَّ لَمْ أَعُدْ، ثُمَّ غَسَلْتُهُ ثُمَّ لَمْ أَعُدْ،', 'മറ്റൊരു നിവേദനം: എന്റെ ശരീരത്തിൽ ഖലൂഖിന്റെ അവശിഷ്ടങ്ങളുണ്ടായിരിക്കെ എന്നെ റസൂൽ(സ) കണ്ടു. അവിടന്ന് ചോദിച്ചു: "ഓ യഅ്‌ല, നിനക്ക് ഭാര്യയുണ്ടോ?" ഞാൻ പറഞ്ഞു: ഇല്ല. നബി(സ) പറഞ്ഞു: "നിങ്ങളത് കഴുകുക. പിന്നെ മടങ്ങരുത്. വീണ്ടും കഴുകുക. പിന്നെ മടങ്ങരുത്. വീണ്ടും കഴുകുക. വീണ്ടും നിങ്ങൾ മടങ്ങരുത്." നിവേദകൻ പറയുന്നു: ഞാനത് കഴുകി. പിന്നെ ഞാൻ മടങ്ങിയില്ല. വീണ്ടും കഴുകി. ഞാൻ മടങ്ങിയില്ല. വീണ്ടും കഴുകി. ഞാൻ മടങ്ങിയില്ല.');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=8 and h.hadith_no=312), 3, 'وَفِي رِوَايَةٍ قَالَ: مَرَرْتُ عَلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَأَنَا مُتَخَلِّقٌ، فَقَالَ: "أَيْ يَعْلَى، هَلْ لَكَ امْرَأَةٌ؟". قُلْتُ: لَا. قَالَ: "اذْهَبْ فَاغْسِلْهُ، ثُمَّ اغْسِلْهُ، ثُمَّ اغْسِلْهُ، ثُمَّ لَا تَعُدْ". قَالَ: فَذَهَبْتُ فَغَسَلْتُهُ، ثُمَّ غَسَلْتُهُ، ثُمَّ غَسَلْتُهُ، ثُمَّ لَمْ أَعُدْ. (ن)', 'മറ്റൊരു നിവേദനം: ഖലൂഖ് പുരട്ടി റസൂൽ(സ)യുടെ അടുത്തുകൂടെ ഞാൻ നടന്നു. അപ്പോൾ അവിടന്ന് ചോദിച്ചു. "ഓ, യഅ്‌ല, നിനക്ക് ഭാര്യയുണ്ടോ?" ഞാൻ പറഞ്ഞു: ഇല്ല. നബി(സ) പറഞ്ഞു: "നിങ്ങൾ പോയിത് കഴുകിക്കളയുക. വീണ്ടുമത് കഴുകുക. പിന്നെയുമത് കഴുകുക. പിന്നീട് നിങ്ങൾ മടങ്ങരുത്." ഞാൻ പോയി അതു കഴുകി. പിന്നെയുമത് കഴുകി. പിന്നെയുമത് കഴുകി. പിന്നെ ഞാൻ മടങ്ങിയിട്ടില്ല. (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 313, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: نَهَى رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَنِ التَّزَعْفُرِ لِلرِّجَالِ. حَسَنٌ صَحِيحٌ. (م,د,ت,ن)', 'അനസ്ബ്‌നു മാലിക്(റ): പുരുഷൻമാർ കുങ്കുമം പൂശുന്നത് റസൂൽ(സ) നിരോധിച്ചിരിക്കുന്നു. (മു,ദ,തു,ന)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസ്ബ്‌നു മാലിക്(റ)', null, null, array['م','د','ت','ن']::text[], array['മു','ദ','തു','ന']::text[], null, null, 720, 720, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=127 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 314, 'عَنْ عَمَّارِ بْنِ يَاسِرٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَدِمْتُ عَلَى أَهْلِي لَيْلًا وَقَدْ تَشَقَّقَتْ يَدَايَ، فَخَلَّقُونِي بِزَعْفَرَانٍ، فَغَدَوْتُ عَلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَسَلَّمْتُ عَلَيْهِ، فَلَمْ يَرُدَّ عَلَيَّ وَلَمْ يُرَحِّبْ بِي، وَقَالَ: "اذْهَبْ فَاغْسِلْ هَذَا عَنْكَ". فَذَهَبْتُ فَغَسَلْتُهُ، ثُمَّ جِئْتُ وَقَدْ بَقِيَ عَلَيَّ مِنْهُ رَدْعٌ، فَسَلَّمْتُ فَلَمْ يَرُدَّ عَلَيَّ وَلَمْ يُرَحِّبْ بِي، وَقَالَ: "اذْهَبْ فَاغْسِلْ عَنْكَ هَذَا". فَذَهَبْتُ فَغَسَلْتُهُ، ثُمَّ جِئْتُ فَسَلَّمْتُ عَلَيْهِ، فَرَدَّ عَلَيَّ وَرَحَّبَ بِي، وَقَالَ: "إِنَّ الْمَلَائِكَةَ لَا تَحْضُرُ جَنَازَةَ الْكَافِرِ بِخَيْرٍ، وَلَا الْمُتَضَمِّخَ بِالزَّعْفَرَانِ، وَلَا الْجُنُبَ". قَالَ: وَرَخَّصَ لِلْجُنُبِ إِذَا نَامَ أَوْ أَكَلَ أَوْ شَرِبَ أَنْ يَتَوَضَّأَ. (د)', 'അമ്മാറുബ്‌നു യാസിർ(റ): ഒരു രാത്രി ഞാനെന്റെ ഭാര്യയുടെ അടുത്തു ചെന്നു. എന്റെ കൈ രണ്ടും കീറിയിട്ടുണ്ട്. അവരെനിക്ക് കുങ്കുമം പുരട്ടിത്തന്നു. പ്രഭാതമായപ്പോൾ ഞാൻ നബി(സ)യുടെ സന്നിധിയിൽ ചെന്ന് സലാം പറഞ്ഞു. അവിടന്ന് സലാം മടക്കുകയോ എന്നെ സ്വീകരിക്കുകയോ ചെയ്തില്ല. അവിടന്ന് പറഞ്ഞു: "നീ പോയി അത് വൃത്തിയാക്കുക." പിന്നീട് ഞാൻ തിരുസന്നിധിയിലേക്ക് ചെന്നു. കുങ്കുമത്തിന്റെ പാട് അൽപ്പം ശേഷിപ്പുണ്ട്. ഞാൻ സലാം പറഞ്ഞു; നബി(സ) സലാം മടക്കുകയോ എന്നെ സ്വീകരിക്കുകയോ ചെയ്തില്ല. അവിടന്ന് പറഞ്ഞു: "നീ പോയി അത് വൃത്തിയാക്കി വരിക". ഞാൻ പോയി കഴുകി വൃത്തിയാക്കി. തിരുസന്നിധിയിൽ ചെന്ന് അവിടത്തോട് സലാം പറഞ്ഞു. എന്റെ സലാം മടക്കി, എനിക്ക് സ്വാഗതമോതി നബി(സ) പറഞ്ഞു: "സത്യനിഷേധിയുടെ ശവത്തിലോ, കുങ്കുമം പുരട്ടിയവന്റെ അടുത്തോ, ജനാബത്തുകാരന്റെയടുത്തോ മാലാഖമാർ നന്മയുമായി സന്നിഹിതരാവുകയില്ല". നിവേദകൻ പറയുന്നു: ജനാബത്തുകാരൻ ഉറങ്ങുകയോ തിന്നുകയോ കുടിക്കുകയോ ചെയ്യുകയാണെങ്കിൽ വുളു എടുത്താൽ മതിയെന്ന് നബി(സ) ഇളവ് നൽകിയിരിക്കുന്നു. (ദ)', 'عَمَّارِ بْنِ يَاسِرٍ', 'അമ്മാറുബ്‌നു യാസിർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 720, 720, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=127 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 315, 'عَنْ أَبِي مُوسَى رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا يَقْبَلُ اللَّهُ تَعَالَى صَلَاةَ رَجُلٍ فِي جَسَدِهِ شَيْءٌ مِنْ خَلُوقٍ". (د)', 'അബൂമൂസ(റ): റസൂൽ(സ) പറഞ്ഞു: "ശരീരത്തിൽ അൽപ്പം ഖലൂഖുള്ള ഒരാളുടെയും നിസ്കാരം അല്ലാഹു സ്വീകരിക്കുകയില്ല." (ദ)', 'أَبِي مُوسَى', 'അബൂമൂസ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 721, 721, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=127 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 316, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ قَالَ: نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ التَّزَعْفُرِ لِلرِّجَالِ، وَفِي رِوَايَةٍ: أَنْ يَتَزَعْفَرَ الرَّجُلُ. (م,د,ت)', 'അനസ്(റ): പുരുഷൻമാർ കുങ്കുമം പുരട്ടുന്നത് റസൂൽ(സ) നിരോധിച്ചിരിക്കുന്നു. (മു,ദ,തു)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['م','د','ت']::text[], array['മു','ദ','തു']::text[], null, null, 721, 721, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=127 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=8 and h.hadith_no=316), 1, 'وَفِي رِوَايَةٍ: أَنْ يَتَزَعْفَرَ الرَّجُلُ. (م,د,ت)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 317, 'عَنِ الْوَلِيدِ بْنِ عُقْبَةَ رَضِيَ اللهُ عَنْهُ قَالَ: لَمَّا فَتَحَ نَبِيُّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَكَّةَ جَعَلَ أَهْلُ مَكَّةَ يَأْتُونَهُ بِصِبْيَانِهِمْ، فَيَدْعُو لَهُمْ بِالْبَرَكَةِ وَيَمْسَحُ رُءُوسَهُمْ، قَالَ: فَجِيءَ بِي إِلَيْهِ وَأَنَا مُخَلَّقٌ، فَلَمْ يَمَسَّنِي مِنْ أَجْلِ الْخَلُوقِ. (د)', 'വലീദുബ്നു ഉഖ്ബ(റ): നബി(സ) മക്ക ജയിച്ചടക്കിയപ്പോൾ മക്കാനിവാസികൾ അവരുടെ കുട്ടികളുമായി തിരുസന്നിധിയിൽ വരാൻ തുടങ്ങി. അവിടന്ന് അവർക്ക് അനുഗ്രഹത്തിനായി പ്രാർഥിക്കുകയും അവരുടെ ശിരസ്സുകളിൽ തടവുകയും ചെയ്യുന്നു. നിവേദകൻ പറയുന്നു: ഖലൂഖ് പുരട്ടപ്പെട്ടനിലയിൽ എന്നെ തിരുസന്നിധിയിലേക്ക് കൊണ്ടുവന്നു. ഖലൂഖ് പുരട്ടിയതു കാരണം നബി(സ) എന്നെ സ്പർശിച്ചില്ല. (ദ)', 'الْوَلِيدِ بْنِ عُقْبَةَ', 'വലീദുബ്നു ഉഖ്ബ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 721, 721, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=127 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 318, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَجُلًا دَخَلَ عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَعَلَيْهِ أَثَرُ صُفْرَةٍ، وَكَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَلَّمَا يُوَاجِهُ رَجُلًا فِي وَجْهِهِ بِشَيْءٍ يَكْرَهُهُ، فَلَمَّا خَرَجَ قَالَ: "لَوْ أَمَرْتُمْ هَذَا أَنْ يَغْسِلَ هَذَا عَنْهُ". (د)', 'അനസുബ്നു മാലിക്(റ): ഒരാൾ നബി(സ)യുടെ സന്നിധിയിൽ വന്നു. അയാളുടെ ശരീരത്തിൽ മഞ്ഞയടയാളമുണ്ട്. നബി(സ)യാണെങ്കിൽ തനിക്ക് ഇഷ്ടമില്ലാത്ത വല്ലതും മുഖത്തുള്ള ഒരാളെ അഭിസംബോധനം ചെയ്യൽ വളരെ കുറവായിരുന്നു. അയാൾ പോയപ്പോൾ നബി(സ) പറഞ്ഞു: "നിങ്ങൾ അയാളോട് അത് കഴുകിക്കളയാൻ പറഞ്ഞിരുന്നുവെങ്കിൽ." (ദ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 721, 721, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=127 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 319, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: كَانَ يَصْبُغُ ثِيَابَهُ بِالزَّعْفَرَانِ، فَقِيلَ لَهُ؟ فَقَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَصْبُغُ. (ن)', 'ഇബ്നുഉമർ(റ): അദ്ദേഹം തന്റെ വസ്ത്രത്തിൽ കുങ്കുമം പുരട്ടുമായിരുന്നു. അതേക്കുറിച്ചു ചോദിക്കപ്പെട്ടപ്പോൾ അദ്ദേഹം പറഞ്ഞു: റസൂൽ(സ) പുരട്ടുമായിരുന്നു. (ന)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 721, 721, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=127 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 320, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "طِيبُ الرِّجَالِ مَا ظَهَرَ رِيحُهُ وَخَفِيَ لَوْنُهُ، وَطِيبُ النِّسَاءِ مَا ظَهَرَ لَوْنُهُ وَخَفِيَ رِيحُهُ". (ن)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "പുരുഷരുടെ സുഗന്ധം പരിമളം പരത്തുന്നതും നിറം മങ്ങിയതുമാണ്. സ്ത്രീകളുടെ സുഗന്ധം നിറം വ്യക്തമായതും പരിമളം നേരിയതുമാണ്." (ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 721, 721, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=128 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 321, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كُنْتُ أُطَيِّبُ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِأَطْيَبِ مَا يَجِدُ حَتَّى أَجِدَ وَبِيصَ الطِّيبِ فِي رَأْسِهِ وَلِحْيَتِهِ. (خ)', 'ആഇശ(റ): കിട്ടാവുന്നതിൽ വെച്ചേറ്റവും മുന്തിയ സുഗന്ധം റസൂൽ(സ)ക്ക് ഞാൻ പുരട്ടിക്കൊടുക്കുമായിരുന്നു. അങ്ങനെ അതിന്റെ തിളക്കം അവിടത്തെ ശിരസ്സിലും താടിയിലും ഞാൻ കണ്ടിരുന്നു. (ബു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 722, 722, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=129 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 322, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِذَا خَرَجَتِ الْمَرْأَةُ إِلَى الْمَسْجِدِ فَلْتَغْتَسِلْ مِنَ الطِّيبِ كَمَا تَغْتَسِلُ مِنَ الْجَنَابَةِ". (ن)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "സ്ത്രീ പള്ളിയിലേക്ക് പുറപ്പെടുമ്പോൾ, ജനാബത്ത് കുളി കുളിക്കുന്നത് പോലെ, സുഗന്ധം ഉപയോഗിച്ചതു കാരണം കുളിക്കട്ടെ." (ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 722, 722, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=130 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 323, 'عَنْ أَبِي مُوسَى رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِذَا اسْتَعْطَرَتِ الْمَرْأَةُ فَمَرَّتْ عَلَى الْقَوْمِ لِيَجِدُوا رِيحَهَا فَهِيَ كَذَا وَكَذَا". قَالَ قَوْلًا شَدِيدًا. (د,ت,ن)', 'അബൂമൂസ(റ): നബി(സ) പറഞ്ഞു: "ഒരു സ്ത്രീ സുഗന്ധം പുരട്ടി, തന്റെ വാസനയറിയിക്കാൻ ജനങ്ങൾക്കരികിലൂടെ നടന്നാൽ, അവൾ ഇന്നാലിന്നത് പോലെയാണ്." നബി(സ) രൂക്ഷമായ വാക്കുപയോഗിച്ചു. (ദ,തു,ന)', 'أَبِي مُوسَى', 'അബൂമൂസ(റ)', null, null, array['د','ت','ن']::text[], array['ദ','തു','ന']::text[], null, null, 722, 722, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=131 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 324, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ - وَلَقِيَتْهُ امْرَأَةٌ وَجَدَ مِنْهَا رِيحَ الطِّيبِ يَنْفَحُ وَلِذَيْلِهَا إِعْصَارٌ - فَقَالَ: يَا أَمَةَ الْجَبَّارِ، جِئْتِ مِنَ الْمَسْجِدِ؟ قَالَتْ نَعَمْ، قَالَ: وَلَهُ تَطَيَّبْتِ؟ قَالَتْ: نَعَمْ، قَالَ: إِنِّي سَمِعْتُ حِبِّي أَبَا الْقَاسِمِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "لَا تُقْبَلُ صَلَاةٌ لِامْرَأَةٍ تَطَيَّبَتْ لِهٰذَا الْمَسْجِدِ، حَتَّى تَرْجِعَ فَتَغْتَسِلَ غُسْلَهَا مِنَ الْجَنَابَةِ". (د,جه)', 'അബൂഹുറൈറ(റ): ഒരു സ്ത്രീ അദ്ദേഹത്തെ കണ്ടുമുട്ടി. അവളിൽ നിന്ന് സുഗന്ധം പരക്കുകയും അവളുടെ വസ്ത്രത്തിന്റെ താഴ്ഭാഗം പാറിക്കളിക്കുകയും ചെയ്യുന്നുണ്ട്. അബൂഹുറൈറ(റ) ചോദിച്ചു: ഓ, പരമാധികാരിയുടെ (അല്ലാഹുവിന്റെ) അടിമേ, നീ പള്ളിയിൽ നിന്നാണോ വരുന്നത്? അവൾ പറഞ്ഞു: അതെ. അബൂഹുറൈറ(റ) ചോദിച്ചു: അതിനു വേണ്ടിയാണോ നീ സുഗന്ധം പൂശിയത്? അതേയെന്ന് അവൾ പ്രതിവചിച്ചു. അബൂഹുറൈറ(റ) പറഞ്ഞു: എന്റെ സ്നേഹഭാജനമായ അബുൽ ഖാസിം(സ) പറയുന്നത് ഞാൻ കേട്ടിട്ടുണ്ട്: "ഈ പള്ളിയിലേക്ക് വരാൻ വേണ്ടി സുഗന്ധമുപയോഗിച്ച ഒരു സ്ത്രീയുടെയും നിസ്കാരം സ്വീകരിക്കപ്പെടില്ല, അവൾ മടങ്ങിച്ചെന്ന്, ജനാബത്തിൽ നിന്ന് ശുദ്ധിയാകാൻ വേണ്ടി കുളിക്കുന്നതു പോലെ കുളിക്കുന്നത് വരെ." (ദ,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 722, 722, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=131 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 325, 'عَنْ أَبِي مُوسَى الْأَشْعَرِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَيُّمَا امْرَأَةٍ اسْتَعْطَرَتْ، فَمَرَّتْ عَلَى قَوْمٍ لِيَجِدُوا مِنْ رِيحِهَا، فَهِيَ زَانِيَةٌ". (ن)', 'അബൂമൂസൽ അശ്അരീ(റ): റസൂൽ(സ) പറഞ്ഞു: "ഒരു സ്ത്രീ സുഗന്ധം പുരട്ടി, അവളുടെ വാസന അറിയിക്കാൻ വേണ്ടി ജനങ്ങളുടെയടുത്ത് കൂടി നടന്നു പോയാൽ , അവൾ വ്യഭിചാരിയാണ്." (ന)', 'أَبِي مُوسَى الْأَشْعَرِيِّ', 'അബൂമൂസൽ അശ്അരീ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 723, 723, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=131 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 326, 'عَنْ جَابِرِ بْنِ سَمُرَةَ رَضِيَ اللهُ عَنْهُ: سُئِلَ عَنْ شَيْبِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ؟ قَالَ: كَانَ إِذَا ادَّهَنَ رَأْسَهُ لَمْ يُرَ مِنْهُ، وَإِذَا لَمْ يُدْهَنْ رُئِيَ مِنْهُ. (ن)', 'ജാബിറുബ്നു സമുറ(റ): അദ്ദേഹത്തോട് റസൂൽ(സ)യുടെ നരയെക്കുറിച്ച് ചോദിക്കപ്പെട്ടു. അദ്ദേഹം പറഞ്ഞു: അവിടന്ന് തലയിൽ എണ്ണ തേച്ചാൽ നര കാണില്ല. എണ്ണ തേച്ചിട്ടില്ലെങ്കിൽ നര കാണുകയും ചെയ്യും. (ന)', 'جَابِرِ بْنِ سَمُرَةَ', 'ജാബിറുബ്നു സമുറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 723, 723, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=132 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 327, 'عَنْ أُمِّ سَلَمَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا اطَّلَى بَدَأَ بِعَوْرَتِهِ فَطَلَاهَا بِالنُّورَةِ، وَسَائِرَ جَسَدِهِ أَهْلُهُ. وفي رواية: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ اطَّلَى، وَوَلِيَ عَانَتَهُ بِيَدِهِ. [ز: فِي سَنَدِهِ انْقِطَاعٌ] (جه)', 'ഉമ്മുസലമ(റ): നബി(സ) അനാവശ്യമുടികളയുന്ന ഒരുതരം കുഴമ്പ് തേക്കുമ്പോൾ തന്റെ നഗ്നതയിൽ തേച്ച് തുടങ്ങും. ബാക്കി ശരീരത്തിൽ അവിടത്തെ ഭാര്യമാരും പുരട്ടും.
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=8 and h.hadith_no=327), 1, 'وَفِي رِوَايَةٍ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ اطَّلَى، وَوَلِيَ عَانَتَهُ بِيَدِهِ. [ز: فِي سَنَدِهِ انْقِطَاعٌ] (جه)', 'മറ്റൊരു നിവേദനിൽ: നബി(സ) എണ്ണതേച്ചു, സ്വന്തം കൈകൊണ്ട് അവിടത്തെ ഗുഹ്യരോമത്തിൽ പുരട്ടി. (പരമ്പരയിൽ ഇൻഖിതാഅ് ഉണ്ട്.) (ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 328, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "اكْتَحِلُوا بِالإِثْمِدِ، فَإِنَّهُ يَجْلُو الْبَصَرَ وَيُنْبِتُ الشَّعْرَ". وَزَعَمَ أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَتْ لَهُ مُكْحُلَةٌ يَكْتَحِلُ بِهَا كُلَّ لَيْلَةٍ: ثَلَاثَةً فِي هَذِهِ، وَثَلَاثَةً فِي هَذِهِ. حَسَنٌ صَحِيحٌ. (د,ت)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ) പറയുന്നു: "നിങ്ങൾ നീല അഞ്ജനക്കല്ല് കൊണ്ട് സുറുമയിടുക, അത് കണ്ണ് ശുദ്ധീകരിക്കുകയും മുടി വളർത്തുകയും ചെയ്യും." അദ്ദേഹം പറയുന്നു: എല്ലാ രാത്രിയും മൂന്ന് പ്രാവശ്യം ഈ കണ്ണിലും മൂന്ന് പ്രാവശ്യം ഈ കണ്ണിലും സുറുമയിടാറുള്ള ഒരു സുറുമക്കുപ്പി തിരുമേനി(സ)ക്കുണ്ടായിരുന്നു. (ദ,തു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 723, 723, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=134 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 329, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِنَّ مِنْ خَيْرِ أَكْحَالِكُمُ الْإِثْمِدَ، إِنَّهُ يَجْلُو الْبَصَرَ وَيُنْبِتُ الشَّعْرَ". (ن)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂൽ(സ) പറയുന്നു: "നിങ്ങളുടെ സുറുമക്കല്ലിൽ വെച്ചേറ്റവും നല്ലത് നീല അഞ്ജനക്കല്ലാണ്. കാരണമത് കണ്ണിനെ ജ്വലിപ്പിക്കുകയും രോമത്തെ വളർത്തുകയും ചെയ്യും." (ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 723, 724, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=134 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 330, 'عَنْ عَبْدِ اللَّهِ بْنِ بُرَيْدَةَ بْنِ الْحَصِيبِ الْأَسْلَمِيِّ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَجُلًا مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُقَالُ لَهُ عُبَيْدٌ قَالَ: إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَنْهَى عَنْ كَثِيرٍ مِنَ الْإِرْفَاهِ. سُئِلَ ابْنُ بُرَيْدَةَ عَنِ الْإِرْفَاهِ؟ قَالَ: مِنْهُ التَّرَجُّلُ. (ن)', 'അബ്ദുല്ലാഹിബ്നു ബുറൈദതുബ്നിൽ ഹസീബ് അൽ അസ്ലമി(റ): നബി(സ)യുടെ അനുചരന്മാരിൽപ്പെട്ട ഉബൈദ്(റ) എന്ന സ്വഹാബി പറയുന്നു: റസൂൽ(സ) അധിക ജീവിത സുഖങ്ങളെയും നിരോധിക്കാറുണ്ടായിരുന്നു. ഇബ്നുബുറൈദ(റ)വിനോട് ജീവിത സുഖങ്ങളെക്കുറിച്ച് ചോദിക്കപ്പെട്ടു: അദ്ദേഹം പറഞ്ഞു: അതിൽപ്പെട്ടതാണ് മുടിവാരൽ. (ന)', 'عَبْدِ اللَّهِ بْنِ بُرَيْدَةَ بْنِ الْحَصِيبِ الْأَسْلَمِيِّ', 'അബ്ദുല്ലാഹിബ്നു ബുറൈദതുബ്നിൽ ഹസീബ് അൽ അസ്ലമി(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 724, 724, true from books b left join chapters c on c.book_id=b.id and c.chapter_no=135 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 331, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يُحِبُّ التَّيَامُنَ مَا اسْتَطَاعَ: فِي طُهُورِهِ وَتَنَعُّلِهِ وَتَرَجُّلِهِ. (ن)', 'ആഇശ(റ): റസൂൽ(സ) കഴിവതും വലതിനെ മുന്തിക്കാനിഷ്ടപ്പെട്ടിരുന്നു: അവിടന്ന് ശുദ്ധിയാക്കുമ്പോഴും ചെരുപ്പ് ധരിക്കുമ്പോഴും മുടിവാരുമ്പോഴും. (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 724, 724, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=135 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 332, 'عَنْ عَبْدِ اللَّهِ بْنِ مُغَفَّلٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ التَّرَجُّلِ إِلَّا غِبًّا. (د,ت,ن)', 'അബ്ദുല്ലാഹിബ്നു മുഗഫ്ഫൽ(റ): ഇടവിട്ട ദിവസങ്ങളിലല്ലാതെ മുടിവാരൽ റസൂൽ(സ) നിരോധിച്ചിരിക്കുന്നു. (ദ,തു,ന)', 'عَبْدِ اللَّهِ بْنِ مُغَفَّلٍ', 'അബ്ദുല്ലാഹിബ്നു മുഗഫ്ഫൽ(റ)', null, null, array['د','ت','ن']::text[], array['ദ','തു','ന']::text[], null, null, 724, 724, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=135 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 333, 'عَنْ عَبْدِ اللَّهِ بْنِ شَقِيقٍ الْعَقِيلِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَانَ رَجُلٌ مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَامِلًا بِمِصْرَ، فَأَتَاهُ رَجُلٌ مِنْ أَصْحَابِهِ فَإِذَا هُوَ شَعِثُ الرَّأْسِ مُشْعَانٌّ، قَالَ: مَا لِي أَرَاكَ مُشْعَانًّا وَأَنْتَ أَمِيرٌ؟ قَالَ: كَانَ نَبِيُّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَنْهَانَا عَنِ الْإِرْفَاهِ. قُلْنَا: وَمَا الْإِرْفَاهُ؟ قَالَ: "التَّرَجُّلُ كُلَّ يَوْمٍ". (ن)', 'അബ്ദുല്ലാഹിബ്നു ശഖീഖ് അൽ അഖീലി(റ): നബി(സ)യുടെ അനുചരരിൽപ്പെട്ട ഒരാൾ മിസ്റിലെ ഗവർണ്ണറായിരുന്നു. അവരുടെയടുക്കൽ അദ്ദേഹത്തിന്റെ ആളുകളിൽപ്പെട്ട ഒരാൾ വന്നപ്പോൾ അദ്ദേഹത്തിന്റെ തല ജടകുത്തിയിരുന്നു. അദ്ദേഹം ചോദിച്ചു: ഇതെന്താ നിങ്ങളുടെ തല ജടകുത്തിയിരിക്കുന്നത്, നിങ്ങൾ അമീറല്ലെയോ? അദ്ദേഹം പറഞ്ഞു: നബി(സ) ജീവിത സുഖങ്ങൾ ഞങ്ങൾക്ക് നിരോധിക്കാറുണ്ടായിരുന്നു. ഞങ്ങൾ ചോദിച്ചു: എന്താണ് ജീവിത സുഖം? അവിടന്ന് പറഞ്ഞു. "എല്ലാ ദിവസവും മുടിവാരൽ" (ന)', 'عَبْدِ اللَّهِ بْنِ شَقِيقٍ الْعَقِيلِيِّ', 'അബ്ദുല്ലാഹിബ്നു ശഖീഖ് അൽ അഖീലി(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 724, 724, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=135 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 334, 'عَنْ حُمَيْدِ بْنِ عَبْدِ الرَّحْمَنِ الْحِمْيَرِيِّ قَالَ: لَقِيتُ رَجُلًا صَحِبَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَمَا صَحِبَهُ أَبُو هُرَيْرَةَ أَرْبَعَ سِنِينَ، قَالَ: نَهَانَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ يَمْتَشِطَ أَحَدُنَا كُلَّ يَوْمٍ. (ن)', 'ഹുമൈദുബ്നു അബ്ദിർറഹ്മാനുൽ ഹിംയരി(റ): അബൂഹുറൈറ(റ) നാല് വർഷം റസൂൽ(സ)യോട് സഹവസിച്ചത് പോലെ, റസൂൽ(സ)യോട് സഹവാസം പുലർത്തിയ ഒരാളെ ഞാൻ കണ്ടു. അദ്ദേഹം പറഞ്ഞു: ഞങ്ങൾ എല്ലാ ദിവസവും മുടിചീകുന്നത് റസൂൽ(സ) നിരോധിച്ചിരിക്കുന്നു. (ന)', 'حُمَيْدِ بْنِ عَبْدِ الرَّحْمَنِ الْحِمْيَرِيِّ قَالَ', 'ഹുമൈദുബ്നു അബ്ദിർറഹ്മാനുൽ ഹിംയരി(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 724, 725, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=135 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 335, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: كَانَ إِذَا اسْتَجْمَرَ اسْتَجْمَرَ بِالْأَلُوَّةِ غَيْرَ مُطَرَّاةٍ، وَبِكَافُورٍ يَطْرَحُهُ مَعَ الْأَلُوَّةِ، ثُمَّ قَالَ: هَكَذَا كَانَ يَسْتَجْمِرُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. (ن)', 'ഇബ്നുഉമർ(റ): അദ്ദേഹം പുകക്കുകയാണെങ്കിൽ നനവില്ലാത്ത ഉലുവാനും അതിന്റെ കൂടെ കർപ്പൂരവും ഇട്ടു കൊണ്ടായിരുന്നു പുകച്ചിരുന്നത്. ശേഷം പറയുമായിരുന്നു: ഇപ്രകാരമായിരുന്നു റസൂൽ(സ) പുകച്ചിരുന്നത്. (ന)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 725, 725, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=136 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 336, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَيُّمَا امْرَأَةٍ أَصَابَتْ بَخُورًا فَلَا تَشْهَدْ مَعَنَا الْعِشَاءَ الْآخِرَةَ". (ن)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറയുന്നു: "(ഉലുവാൻ) പുകകൊണ്ട് സ്ത്രീകൾ ഞങ്ങളുടെ കൂടെ ഇശാ നിസ്കാരത്തിൽ പങ്കെടുക്കരുത്." (ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 725, 725, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=137 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 337, 'عَنْ زَيْنَبَ امْرَأَةِ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ -رَضِيَ اللَّهُ عَنْهُمَا- قَالَتْ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِذَا شَهِدَتْ إِحْدَاكُنَّ صَلَاةَ الْعِشَاءِ-وَفِي رِوَايَةٍ: الصَّلَاةَ - فَلَا تَمَسَّ طِيبًا". وَفِي رِوَايَةٍ: أَنَّ نَبِيَّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "أَيَّتُكُنَّ خَرَجَتْ إِلَى الْمَسْجِدِ فَلَا تَقْرَبَنَّ طِيبًا". وَفِي رِوَايَةٍ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَمَرَهَا أَنْ لَا تَمَسَّ الطِّيبَ إِذَا خَرَجَتْ إِلَى الْعِشَاءِ الْآخِرَةِ. وَفِي رِوَايَةٍ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِذَا خَرَجَتِ الْمَرْأَةُ إِلَى الْعِشَاءِ الْآخِرَةِ فَلَا تَمَسَّ طِيبًا". (ن)', 'സൈനബ്(റ) - അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)വിന്റെ ഭാര്യ: റസൂൽ(സ) പറയുന്നു: "നിങ്ങളിൽ ആരെങ്കിലും (സ്ത്രീകൾ) ഇശാഅ് നിസ്കാരത്തിൽ (മറ്റൊരു നിവേദനപ്രകാരം നിസ്കാരത്തിൽ) പങ്കെടുക്കുകയാണെങ്കിൽ സുഗന്ധം തൊടരുത്." മറ്റൊരു റിപ്പോർട്ടിൽ: നബി(സ) പറയുന്നു: "നിങ്ങൾ സ്ത്രീകൾ ആരെങ്കിലും പള്ളിയിലേക്ക് വരികയാണെങ്കിൽ സുഗന്ധത്തോട് അടുത്ത് പോകരുത്?".
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=8 and h.hadith_no=337), 1, 'وَفِي رِوَايَةٍ: الصَّلَاةَ - فَلَا تَمَسَّ طِيبًا".', 'മറ്റൊരു നിവേദനപ്രകാരം നിസ്കാരത്തിൽ) പങ്കെടുക്കുകയാണെങ്കിൽ സുഗന്ധം തൊടരുത്."');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=8 and h.hadith_no=337), 2, 'وَفِي رِوَايَةٍ: أَنَّ نَبِيَّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "أَيَّتُكُنَّ خَرَجَتْ إِلَى الْمَسْجِدِ فَلَا تَقْرَبَنَّ طِيبًا".', 'മറ്റൊരു നിവേദനിൽ: നബി(സ) പറയുന്നു: "നിങ്ങൾ സ്ത്രീകൾ ആരെങ്കിലും പള്ളിയിലേക്ക് വരികയാണെങ്കിൽ സുഗന്ധത്തോട് അടുത്ത് പോകരുത്?".');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=8 and h.hadith_no=337), 3, 'وَفِي رِوَايَةٍ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَمَرَهَا أَنْ لَا تَمَسَّ الطِّيبَ إِذَا خَرَجَتْ إِلَى الْعِشَاءِ الْآخِرَةِ.', 'മറ്റൊരു നിവേദനം: ഇശാഇന് പുറപ്പെട്ടാൽ സുഗന്ധം തൊടരുതെന്ന് റസൂൽ(സ) അവരോട് കൽപിച്ചു.');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=8 and h.hadith_no=337), 4, 'وَفِي رِوَايَةٍ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِذَا خَرَجَتِ الْمَرْأَةُ إِلَى الْعِشَاءِ الْآخِرَةِ فَلَا تَمَسَّ طِيبًا". (ن)', 'മറ്റൊരു നിവേദനം: റസൂൽ(സ) പറയുന്നു: "ഇശാഇന് വേണ്ടി സ്ത്രീ പുറപ്പെടുകയാണെങ്കിൽ അവൾ സുഗന്ധം തൊടരുത്." (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 338, 'عَنِ الْبَرَاءِ رَضِيَ اللَّهُ عَنْهُ قَالَ: مَا رَأَيْتُ أَحَدًا - وَفِي رِوَايَةٍ: رَجُلًا- أَحْسَنَ فِي حُلَّةٍ حَمْرَاءَ مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَجُمَّتُهُ تَضْرِبُ مَنْكِبَيْهِ. وَفِي رِوَايَةٍ: وَرَأَيْتُ لَهُ لِمَّةً تَضْرِبُ قَرِيبًا مِنْ مَنْكِبَيْهِ. (ن)', 'ബറാഅ്(റ): ശരീരം മുഴുവൻ മറക്കുന്ന ചുവന്ന വസ്ത്രത്തിൽ റസൂൽ(സ)യേക്കാൾ ഭംഗിയുള്ളവനായി ഞാൻ ആരെയും കണ്ടിട്ടില്ല. അവിടത്തെ മുടി ചുമലിൽ തട്ടുന്നുണ്ടായിരുന്നു. മറ്റൊരു നിവേദനം: അവിടത്തെ ചെവിയിലേക്ക് തൂങ്ങിക്കിടക്കുന്ന മുടി ചുമലിനോടടുത്ത് വരെയെത്തി നിൽക്കുന്നത് ഞാൻ കണ്ടു. (ന)', 'الْبَرَاءِ', 'ബറാഅ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 725, 726, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=138 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=8 and h.hadith_no=338), 1, 'وَفِي رِوَايَةٍ: رَجُلًا- أَحْسَنَ فِي حُلَّةٍ حَمْرَاءَ مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَجُمَّتُهُ تَضْرِبُ مَنْكِبَيْهِ.', 'മറ്റൊരു നിവേദനം: അവിടത്തെ ചെവിയിലേക്ക് തൂങ്ങിക്കിടക്കുന്ന മുടി ചുമലിനോടടുത്ത് വരെയെത്തി നിൽക്കുന്നത് ഞാൻ കണ്ടു. (ന)');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=8 and h.hadith_no=338), 2, 'وَفِي رِوَايَةٍ: وَرَأَيْتُ لَهُ لِمَّةً تَضْرِبُ قَرِيبًا مِنْ مَنْكِبَيْهِ. (ن)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 339, 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَانَ شَعْرُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَى أَنْصَافِ أُذُنَيْهِ. (ن)', 'അനസ്(റ): റസൂൽ(സ)യുടെ മുടി രണ്ട് ചെവികളുടെയും പകുതി വരെയുണ്ടായിരുന്നു. (ന)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 726, 726, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=138 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 340, 'عَنِ الْبَرَاءِ رَضِيَ اللَّهُ عَنْهُ قَالَ: مَا رَأَيْتُ مِنْ ذِي لِمَّةٍ أَحْسَنَ فِي حُلَّةٍ حَمْرَاءَ مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، لَهُ شَعْرٌ يَضْرِبُ شَحْمَةَ أُذُنَيْهِ. وفي رواية: يَبْلُغُ شَحْمَةَ أُذُنَيْهِ. (م,د,ت,ن,جه)', 'ബറാഅ്(റ): ശരീരം മുഴുവൻ മറക്കുന്ന ചുവന്ന വസ്ത്രം ധരിച്ച, ചെവിയിലേക്ക് തൂങ്ങിക്കിടക്കുന്ന മുടിയുള്ളവരിൽ റസൂൽ(സ)യേക്കാൾ ഭംഗിയുള്ള ആരെയും ഞാൻ കണ്ടിട്ടില്ല. തിരുമേനി(സ)ക്ക് ചെവിക്കുന്നിയിൽ തട്ടുന്ന മുടിയുണ്ടായിരുന്നു. മറ്റൊരു റിപ്പോർട്ടിൽ: ചെവിയുടെ കുന്നിയിൽ എത്തുന്ന. (മു,ദ,തു,ന,ജ)', 'الْبَرَاءِ', 'ബറാഅ്(റ)', null, null, array['م','د','ت','ن','جه']::text[], array['മു','ദ','തു','ന','ജ']::text[], null, null, 726, 726, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=138 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=8 and h.hadith_no=340), 1, 'وَفِي رِوَايَةٍ: يَبْلُغُ شَحْمَةَ أُذُنَيْهِ. (م,د,ت,ن,جه)', 'മറ്റൊരു നിവേദനിൽ: ചെവിയുടെ കുന്നിയിൽ എത്തുന്ന. (മു,ദ,തു,ന,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 341, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: كَانَ شَعْرُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَوْقَ الْوَفْرَةِ وَدُوْنَ الْجُمَّةِ. (د,ت,جه)', 'ആഇശ(റ): റസൂൽ(സ)യുടെ മുടി അവിടത്തെ രണ്ട് ചെവിക്കുറ്റിയുടെ മുകളിലും ചുമലിനു താഴെയുമായിരുന്നു. (ദ,തു,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 726, 726, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=138 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 342, 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَبْعَةً، لَيْسَ بِالطَّوِيلِ وَلَا بِالْقَصِيرِ، حَسَنَ الْجِسْمِ أَسْمَرَ اللَّوْنِ، وَكَانَ شَعْرُهُ لَيْسَ بِجَعْدٍ وَلَا سَبِطٍ، إِذَا مَشَى يَتَكَفَّأُ. حسن صحيح. (ق,ت,ن)', 'അനസ്(റ): റസൂൽ(സ) ഒരു ഒത്ത ആളായിരുന്നു. നീളമധികമുള്ളവരോ കുറവുള്ളവരോ ആയിരുന്നില്ല. നല്ല ഭംഗിയുള്ള ശരീരം, ചുവപ്പ് കലർന്ന വെള്ള നിറമായിരുന്നു. അവിടത്തെ മുടി വല്ലാതെ ചുരുണ്ടതോ, അല്ലെങ്കിൽ വല്ലാതെ നീണ്ടതോ ആയിരുന്നില്ല. അവിടന്ന് നടക്കുകയാണെങ്കിൽ കാലുകൾ എടുത്തുവെക്കുമായിരുന്നു, വലിക്കാറില്ല. (ബു,മു,തു,ന)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['ق','ت','ن']::text[], array['ബു','മു','തു','ന']::text[], null, null, 726, 726, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=138 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 343, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: كُنْتُ أَغْتَسِلُ أَنَا وَرَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنْ إِنَاءٍ وَاحِدٍ، وَكَانَ لَهُ شَعْرٌ فَوْقَ الْجُمَّةِ وَدُوْنَ الْوَفْرَةِ. حسن صحيح. (د,ت,جه)', 'ആഇശ(റ): റസൂൽ(സ)യും ഞാനും ഒരു പാത്രത്തിൽ നിന്ന് കുളിക്കാറുണ്ടായിരുന്നു. അവിടത്തേക്ക് ചുമലിന്റെ മുകളിലും ചെവിയുടെ അടിയിലുമെത്തുന്ന മുടിയുണ്ടായിരുന്നു. (ദ,തു,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 726, 726, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=138 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 344, 'عَنِ الْبَرَاءِ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَجُلًا مَرْبُوعًا، عَرِيضَ مَا بَيْنَ الْمَنْكِبَيْنِ، كَثَّ اللِّحْيَةِ، تَعْلُوهُ حُمْرَةٌ، جُمَّتُهُ إِلَى شَحْمَتَيْ أُذُنَيْهِ، لَقَدْ رَأَيْتُهُ فِي حُلَّةٍ حَمْرَاءَ مَا رَأَيْتُ أَحْسَنَ مِنْهُ. وَفِي رِوَايَةٍ: مَا رَأَيْتُ مِنْ ذِي لِمَّةٍ أَحْسَنَ فِي حُلَّةٍ مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَلَهُ شَعْرٌ يَضْرِبُ مَنْكِبَيْهِ. (ن)', 'ബറാഅ്(റ): റസൂൽ(സ) ഒരു ഒത്ത ആളായിരുന്നു, രണ്ട് ചുമലിന്റെയിടയിലും നല്ല വീതിയുള്ളവരും, താടി തിങ്ങിയവരും കവിൾ ചുവന്ന് തുടുത്തവരുമായിരുന്നു. അവിടത്തെ മുടി ചെവിയുടെ കുന്നി വരെ എത്തിയതുമായിരുന്നു. അവിടത്തെ മുഴുവൻ മറക്കുന്ന ചുവന്ന വസ്ത്രത്തിൽ ഞാൻ കണ്ടു, അതിനേക്കാൾ ഭംഗിയിൽ ഞാൻ ആരെയും കണ്ടിട്ടില്ല.
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=8 and h.hadith_no=344), 1, 'وَفِي رِوَايَةٍ: مَا رَأَيْتُ مِنْ ذِي لِمَّةٍ أَحْسَنَ فِي حُلَّةٍ مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَلَهُ شَعْرٌ يَضْرِبُ مَنْكِبَيْهِ. (ن)', 'മറ്റൊരു നിവേദനിൽ: റസൂൽ(സ)യേക്കാൾ ഭംഗിയിൽ ചെവിയുടെ കുന്നി വരെ മുടിയുള്ള ആരെയും ഞാൻ കണ്ടിട്ടില്ല. അവിടത്തേക്ക് ചുമലിൽ തട്ടുന്ന മുടിയുണ്ടായിരുന്നു. (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 345, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: كَانَ أَهْلُ الْكِتَابِ - يَعْنِي يَسْدِلُونَ أَشْعَارَهُمْ - وَكَانَ الْمُشْرِكُونَ يَفْرُقُونَ رُءُوسَهُمْ، وَكَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ تُعْجِبُهُ مُوَافَقَةُ أَهْلِ الْكِتَابِ فِيمَا لَمْ يُؤْمَرْ بِهِ، فَسَدَلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَاصِيَتَهُ، ثُمَّ فَرَقَ بَعْدُ. (ق،ت،ن،جه)', 'ഇബ്നുഅബ്ബാസ്(റ): വേദക്കാർ അവരുടെ മുടി താഴ്ത്തിയിടും, മുശ്രിക്കുകൾ മുടിചീകി ചാലുണ്ടാക്കും. തങ്ങൾക്ക് കൽപ്പിക്കപ്പെടാത്ത വിഷയത്തിൽ അഹ്ലു കിതാബിനോട് യോജിക്കുന്നത് റസൂൽ(സ)യെ സന്തോഷിപ്പിക്കുമായിരുന്നു. അപ്പോൾ റസൂൽ(സ) അവിടത്തെ മൂർദ്ധാവ് ചീകി താഴ്ത്തിയിട്ടു. ശേഷം ചീകി ചാലുണ്ടാക്കി. (ബു,മു,ദ,തു,ന,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ق','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 727, 727, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=139 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 346, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: كُنْتُ إِذَا أَرَدْتُ أَنْ أَفْرُقَ رَأْسَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ صَدَعْتُ الْفَرْقَ مِنْ يَافُوخِهِ، وَأُرْسِلُ نَاصِيَتَهُ بَيْنَ عَيْنَيْهِ. (د)', 'ആഇശ(റ): റസൂൽ(സ)യുടെ തലചീകി ചാലുണ്ടാക്കാനുദ്ദേശിച്ചാൽ തലയുടെ മധ്യത്തെ മുൻവശവും പിൻവശവും കൂടിച്ചേരുന്ന ഭാഗത്തിൽ നിന്നും മാറ്റിനിർത്തുകയും അവിടത്തെ നെറ്റിയിലെ മുടി രണ്ട് കണ്ണുകൾക്കിടയിലൂടെ ഇറക്കിയിടുകയും ചെയ്യുമായിരുന്നു. (ദ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 727, 727, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=139 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 347, 'عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ - رَضِيَ اللَّهُ عَنْهُ - أَنَّ امْرَأَةً أَتَتْهُ فَقَالَتْ: إِنِّي امْرَأَةٌ زَعْرَاءُ، أَيَصْلُحُ أَنْ أَصِلَ فِي شَعْرِي؟ فَقَالَ: لَا. قَالَتْ: أَشَيْءٌ سَمِعْتَهُ مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، أَوْ تَجِدُهُ فِي كِتَابِ اللَّهِ؟ قَالَ: لَا، بَلْ سَمِعْتُهُ مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَأَجِدُهُ فِي كِتَابِ اللَّهِ. وَسَاقَ الْحَدِيثَ. (ن)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): ഒരു സ്ത്രീ അദ്ദേഹത്തിനടുത്ത് വന്നുപറഞ്ഞു: ഞാൻ മുടി വളരെ കുറഞ്ഞ ഒരു സ്ത്രീയാകുന്നു. എന്റെ മുടിയിൽ കൃത്രിമമായി ചേർക്കാൻ പറ്റുമോ? അദ്ദേഹം പറഞ്ഞു: ഇല്ല. അവർ ചോദിച്ചു: താങ്കൾ റസൂൽ(സ)യിൽ നിന്നും കേട്ട വല്ല കാര്യവുമാണോ ഇത്. അതോ അല്ലാഹുവിന്റെ കിതാബിൽ കണ്ടകാര്യമാണോ? അദ്ദേഹം പറഞ്ഞു: അല്ല, മറിച്ച് ഞാനത് റസൂൽ(സ)യിൽ നിന്ന് കേൾക്കുകയും അല്ലാഹുവിന്റെ കിതാബിൽ കാണുകയും ചെയ്തിട്ടുണ്ട്. ശേഷം ഹദീസ് പറഞ്ഞു. (ന)', 'عَبْدِ اللَّهِ بْنِ مَسْعُودٍ -', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 727, 727, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=140 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 348, 'عَنْ سَعِيدِ بْنِ جُبَيْرٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: لَا بَأْسَ بِالْقَرَامِلِ. قَالَ أَبُو دَاوُد: كَأَنَّهُ يَذْهَبُ إِلَى أَنَّ الْمَنْهِيَّ عَنْهُ شُعُورُ النِّسَاءِ. قَالَ أَبُو دَاوُدَ : كَانَ أَحْمَدُ يَقُولُ: الْقَرَامِلُ لَيْسَ بِهِ بَأْسٌ. (د)', 'സഈദുബ്നു ജുബൈർ(റ): മുടിപ്പിൻ പ്രശ്നമില്ല. അബൂദാവൂദ്(റ) പറയുന്നു: അദ്ദേഹം സ്ത്രീകളുടെ മുടി(ചേർക്കൽ) നിരോധിക്കപ്പെട്ടതാണെന്ന് പറയാനടുത്ത പോലെ. അബൂദാവൂദ് പറഞ്ഞു: അഹ്‌മദ് പറയാറുണ്ടായിരുന്നു: മുടിപ്പിൻ കുഴപ്പമില്ല. (ദ)', 'سَعِيدِ بْنِ جُبَيْرٍ', 'സഈദുബ്നു ജുബൈർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 727, 727, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=140 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 349, 'عَنْ أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: جَاءَتِ امْرَأَةٌ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَتْ: يَا رَسُولَ اللَّهِ، إِنَّ لِي ابْنَةً عُرَيِّسًا، أَصَابَتْهَا حَصْبَةٌ فَتَمَرَّقَ شَعْرُهَا، أَفَأَصِلُهُ؟ فَقَالَ: "لَعَنَ اللَّهُ الْوَاصِلَةَ وَالْمُسْتَوْصِلَةَ". (م)', 'അസ്മാഉബിൻത് അബീബക്കർ(റ): നബി(സ)യുടെ അടുക്കൽ ഒരു സ്ത്രീ വന്നുപറഞ്ഞു: തിരുദൂതരേ, എനിക്ക് പുതുപ്പെണ്ണായ ഒരു മകളുണ്ട്. അവൾക്ക് അഞ്ചാം പനി പിടിപെട്ട് മുടികൊഴിഞ്ഞ് പോയി. ഞാൻ അവൾക്ക് കൃത്രിമമുടി വെച്ചുകൊടുക്കട്ടെയോ? റസൂൽ(സ) പറഞ്ഞു: "കൃത്രിമമുടി വെക്കുന്നവളെയും വെച്ചുകൊടുക്കാനാവശ്യപ്പെടുന്നവളെയും അല്ലാഹു ശപിച്ചിരിക്കുന്നു." (മു)', 'أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ', 'അസ്മാഉബിൻത് അബീബക്കർ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 727, 728, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=140 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 350, 'عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: زَجَرَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ تَصِلَ الْمَرْأَةُ بِرَأْسِهَا شَيْئًا. (م)', 'ജാബിറുബ്നു അബ്ദുല്ല(റ): ഒരു സ്ത്രീ തന്റെ തലയിൽ എന്തെങ്കിലും കൃത്രിമമായി ചേർക്കുന്നത് നബി(സ) നിരോധിച്ചിരിക്കുന്നു. (മു)', 'جَابِرِ بْنِ عَبْدِ اللَّهِ', 'ജാബിറുബ്നു അബ്ദുല്ല(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 728, 728, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=140 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 351, 'عَنْ حُمَيْدِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ: أَنَّهُ سَمِعَ مُعَاوِيَةَ بْنَ أَبِي سُفْيَانَ رَضِيَ اللَّهُ عَنْهُمْ عَامَ حَجَّ وَهُوَ عَلَى الْمِنْبَرِ - وَتَنَاوَلَ قُصَّةً مِنْ شَعَرٍ كَانَتْ فِي يَدِ حَرَسِيٍّ - يَقُولُ: يَا أَهْلَ الْمَدِينَةِ أَيْنَ عُلَمَاؤُكُمْ؟ سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَنْهَى عَنْ مِثْلِ هَذِهِ، وَيَقُولُ: "إِنَّمَا هَلَكَتْ بَنُو إِسْرَائِيلَ حِينَ اتَّخَذَ هَذِهِ نِسَاؤُهُمْ". (ق,د,ت,ن)', 'ഹുമൈദുബ്നു അബ്ദുർറഹ്മാൻ ബിൻ ഔഫ്(റ): മുആവിയ(റ) ഹജ്ജ് ചെയ്ത വർഷം മിമ്പറിൽ കയറി, സേവകരുടെ കയ്യിലുണ്ടായിരുന്ന ഒരു മുടിക്കെട്ടെടുത്ത് കൊണ്ട് പറയുന്നതായി അദ്ദേഹം കേട്ടു: മദീനാനിവാസികളേ, എവിടെയാണ് നിങ്ങളുടെ പണ്ഡിതന്മാർ? ഇതുപോലോത്തതിനെ റസൂൽ(സ) നിരോധിക്കുന്നതായി ഞാൻ കേട്ടിട്ടുണ്ട്. റസൂൽ(സ) പറയുന്നു: "ബനൂ ഇസ്റാഈൽ നശിച്ചത് അവരിലെ സ്ത്രീകൾ ഇങ്ങനെ ചെയ്ത സമയത്തായിരുന്നു." (ബു,മു,ദ,തു,ന)', 'حُمَيْدِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ', 'ഹുമൈദുബ്നു അബ്ദുർറഹ്മാൻ ബിൻ ഔഫ്(റ)', null, null, array['ق','د','ت','ن']::text[], array['ബു','മു','ദ','തു','ന']::text[], null, null, 728, 728, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=140 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 352, 'عَنْ سَعِيدِ بْنِ الْمُسَيَّبِ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَدِمَ مُعَاوِيَةُ رَضِيَ اللَّهُ عَنْهُ الْمَدِينَةَ، فَخَطَبَنَا، وَأَخَذَ كُبَّةً مِنْ شَعَرٍ، وَقَالَ: مَا كُنْتُ أَرَى أَحَدًا يَفْعَلُهُ إِلَّا الْيَهُودَ، وَإِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَلَغَهُ فَسَمَّاهُ: الزُّورَ. (ن)', 'സഈദുബ്നുൽ മുസയ്യബ്(റ): മുആവിയ(റ) മദീനയിൽ വന്ന് ഞങ്ങളോട് പ്രസംഗിച്ചു. ഒരു മുടിക്കെട്ട് എടുത്ത് അദ്ദേഹം പറഞ്ഞു: യഹൂദികളെയല്ലാതെ ഇങ്ങനെ ചെയ്യുന്നത് ഞാൻ കണ്ടിട്ടില്ല. റസൂൽ(സ)ക്ക് ഇതേക്കുറിച്ച് വിവരം ലഭിച്ചപ്പോൾ അവിടന്ന് അതിനെ ''വ്യാജം'' എന്ന് വിളിച്ചു. (ന)', 'سَعِيدِ بْنِ الْمُسَيَّبِ', 'സഈദുബ്നുൽ മുസയ്യബ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 728, 728, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=140 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 353, 'عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُ قَالَ: لَعَنَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْوَاصِلَةَ وَالْمُسْتَوْصِلَةَ، وَالْوَاشِمَةَ وَالْمُسْتَوْشِمَةَ. (ق,د,ت,ن,جه)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): റസൂൽ(സ), കൃത്രിമമുടി ധരിക്കുന്നവളെയും സ്വന്തം മുടിയോട് കള്ളമുടി ചേർക്കാൻ ആവശ്യപ്പെടുന്നവളെയും പച്ചകുത്തുന്നവളെയും പച്ചകുത്താനാവശ്യപ്പെടുന്നവളെയും ശപിച്ചിരിക്കുന്നു. (ബു,മു,ദ,തു,ന,ജ)', 'عَبْدِ اللَّهِ بْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 728, 728, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=141 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 354, 'عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: لَعَنَ اللَّهُ الْوَاشِمَاتِ وَالْمُسْتَوْشِمَاتِ، وَالْوَاصِلَاتِ، وَالْمُتَنَمِّصَاتِ، وَالْمُتَفَلِّجَاتِ لِلْحُسْنِ الْمُغَيِّرَاتِ خَلْقَ اللَّهِ عَزَّ وَجَلَّ. فَبَلَغَ ذَلِكَ امْرَأَةً مِنْ بَنِي أَسَدٍ يُقَالُ لَهَا أُمُّ يَعْقُوبَ، كَانَتْ تَقْرَأُ الْقُرْآنَ، فَأَتَتْهُ فَقَالَتْ: بَلَغَنِي عَنْكَ أَنَّكَ لَعَنْتَ الْوَاشِمَاتِ وَالْمُسْتَوْشِمَاتِ وَالْوَاصِلَاتِ وَالْمُتَنَمِّصَاتِ، وَالْمُتَفَلِّجَاتِ لِلْحُسْنِ الْمُغَيِّرَاتِ خَلْقَ اللَّهِ تَعَالَى. فَقَالَ: وَمَا لِيَ لَا أَلْعَنُ مَنْ لَعَنَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَهُوَ فِي كِتَابِ اللَّهِ تَعَالَى؟ قَالَتْ: لَقَدْ قَرَأْتُ مَا بَيْنَ لَوْحَيِ الْمُصْحَفِ فَمَا وَجَدْتُهُ. فَقَالَ: وَاللَّهِ لَئِنْ كُنْتِ قَرَأْتِيهِ لَقَدْ وَجَدْتِيهِ، ثُمَّ قَرَأَ: {وَمَا آتَاكُمُ الرَّسُولُ فَخُذُوهُ وَمَا نَهَاكُمْ عَنْهُ فَانْتَهُوا} [الحشر: ٧]. قَالَتْ: إِنِّي أَرَى بَعْضَ هَذَا عَلَى امْرَأَتِكَ؟ قَالَ: فَادْخُلِي فَانْظُرِي. فَدَخَلَتْ ثُمَّ خَرَجَتْ، فَقَالَ: مَا رَأَيْتِ؟ فَقَالَتْ: مَا رَأَيْتُ، فَقَالَ: لَوْ كَانَ ذَلِكَ مَا كَانَتْ مَعَنَا. (ق،د،ت،ن،جه)', 'അബ്ദുല്ലാഹിബ്‌നു മസ്ഊദ്(റ): പച്ചകുത്തുന്നവരെയും, പച്ച കുത്താനാവശ്യപ്പെടുന്നവരെയും, കള്ള മുടി വെക്കുന്നവരെയും, മുഖത്തെ മുടി പറിച്ചുകളയുന്നവരെയും, ഭംഗിക്ക് വേണ്ടി പല്ലിനിടയിൽ വിടവുണ്ടാക്കി അല്ലാഹുവിന്റെ സൃഷ്ടിപ്പിന് മാറ്റം വരുത്തുന്നവരെയും അല്ലാഹു ശപിച്ചിരിക്കുന്നു. ഈ വിഷയം ബനുസഅ്ദിൽ പെട്ട ഉമ്മുയഅ്ഖൂബ് എന്ന ഒരു സ്ത്രീയുടെ അടുക്കലെത്തി. അവർ ഖുർആൻ ഓതാറുണ്ടായിരുന്നു. അങ്ങനെ ആ സ്ത്രീ അബ്ദുല്ലാഹിബ്‌നു മസ്ഊദി(റ)വിന്റെ അടുക്കൽ ചെന്നു പറഞ്ഞു: പച്ചകുത്തുന്നവരെയും അതിനാവശ്യപ്പെടുന്നവരെയും കള്ള മുടി വെക്കുന്നവരെയും സ്വന്തം മുടി പറിച്ച് കളയുന്നവരെയും ഭംഗിക്ക് വേണ്ടി പല്ലിനിടയിൽ വിടവ് ഉണ്ടാക്കി അല്ലാഹുവിന്റെ സൃഷ്ടിപ്പിൽ മാറ്റം വരുത്തുന്നവരെയും താങ്കൾ ശപിച്ചിരിക്കുന്നുവെന്ന് ഞാൻ അറിഞ്ഞു. അപ്പോൾ അദ്ദേഹം പറഞ്ഞു: റസൂൽ(സ) ശപിച്ചവരെ ഞാനെങ്ങനെ ശപിക്കാതിരിക്കും, അത് അല്ലാഹുവിന്റെ കിതാബിലുള്ളതാണ്? അവർ ചോദിച്ചു: ഞാൻ മുസ്ഹഫ് മുഴുവൻ വായിച്ചിട്ടുണ്ട്. പക്ഷേ ഞാനത് കണ്ടിട്ടില്ലല്ലോ. അപ്പോൾ അദ്ദേഹം പറഞ്ഞു: അല്ലാഹുവാണ് സത്യം. നിങ്ങൾ അത് വായിച്ചിട്ടുണ്ടെങ്കിൽ തീർച്ചയായും അത് കിട്ടും. ശേഷം ഇങ്ങനെ ഓതി: ''റസൂൽ നിങ്ങളിൽ കൊണ്ടുവന്നത് മുഴുവൻ സ്വീകരിക്കുക, അവിടന്ന് നിരോധിച്ചത് മുഴുവൻ നിങ്ങൾ വെടിയുക'' (ഹശ്‌ർ:7) അവർ പറഞ്ഞു: ഇതിൽ ചിലത് താങ്കളുടെ ഭാര്യയിൽ ഞാൻ കാണുന്നു? അദ്ദേഹം പറഞ്ഞു: കയറി നോക്കുക. അപ്പോൾ അവൾ കയറി. പിന്നെ പുറത്ത് വന്നു. അപ്പോൾ അദ്ദേഹം ചോദിച്ചു: എന്താണ് കണ്ടത്? അവർ പറഞ്ഞു: ഞാൻ കണ്ടില്ല. അപ്പോൾ അബ്ദുല്ലാഹി(റ) പറഞ്ഞു: അങ്ങനെയുണ്ടായിരുന്നെങ്കിൽ അവൾ നമ്മുടെ കൂടെയുണ്ടാകുകയില്ല. (ബു,മു,ദ,തു,ന,ജ)', 'عَبْدِ اللَّهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്‌നു മസ്ഊദ്(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], 'الحشر: ٧', null, 728, 729, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=141 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 355, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: لُعِنَتِ الْوَاصِلَةُ وَالْمُسْتَوْصِلَةُ، وَالنَّامِصَةُ وَالْمُتَنَمِّصَةُ، وَالْوَاشِمَةُ وَالْمُسْتَوْشِمَةُ، مِنْ غَيْرِ دَاءٍ. (د)', 'ഇബ്‌നുഅബ്ബാസ്(റ): കൃത്രിമ മുടി വെക്കുന്നവളും, വെച്ചു തരാനാവശ്യപ്പെടുന്നവളും, മുഖത്തെ മുടി പറിക്കുന്നവളും പറിക്കാനാവശ്യപ്പെടുന്നവളും, പച്ചകുത്തുന്നവളും അസുഖത്തിനല്ലാതെ പച്ച കുത്താനാവശ്യപ്പെടുന്നവളും ശപിക്കപ്പെട്ടിരിക്കുന്നു. (ദ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്‌നുഅബ്ബാസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 729, 729, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=141 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 356, 'عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ رضي الله عنه قَالَ: آكِلُ الرِّبَا وَمُوكِلُهُ وَكَاتِبُهُ إِذَا عَلِمُوا ذَلِكَ، وَالْوَاشِمَةُ وَالْمَوْشُومَةُ لِلْحُسْنِ، وَلَاوِي الصَّدَقَةِ، وَالْمُرْتَدُّ أَعْرَابِيًّا بَعْدَ الْهِجْرَةِ، مَلْعُونُونَ عَلَى لِسَانِ مُحَمَّدٍ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَوْمَ الْقِيَامَةِ. (ن)', 'അബ്ദുല്ലാഹിബ്‌നു മസ്ഊദ്(റ): ബോധപൂർവ്വം പലിശ തിന്നുന്നവനും തീറ്റിക്കുന്നവനും അത് എഴുതുന്നവനും, ഭംഗിക്ക് വേണ്ടി പച്ച കുത്തുന്നവനും പച്ചകുത്തപ്പെടുന്നവനും, ധർമ്മം തടയുന്നവനും, ഹിജ്‌റക്ക് ശേഷം അഅ്‌റാബിയായി മുർതദ്ദായവനും, അന്ത്യനാളിൽ മുഹമ്മദ്(സ)യുടെ നാവിനാൽ ശപിക്കപ്പെട്ടവരാകുന്നു. (ന)', 'عَبْدِ اللَّهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്‌നു മസ്ഊദ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 729, 729, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=141 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 357, 'عَنِ الْحَارِثِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: لَعَنَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ آكِلَ الرِّبَا وَمُوكِلَهُ وَشَاهِدَهُ وَكَاتِبَهُ، وَالْوَاشِمَةَ وَالْمُسْتَوْشِمَةَ إِلَّا مِنْ دَاءٍ، وَالْحَالَّ وَالْمُحَلَّلَ لَهُ، وَمَانِعَ الصَّدَقَةِ، وَكَانَ يَنْهَى عَنِ النَّوْحِ. (ن)', 'ഹാരിസുബ്നു മാലിക്(റ): പലിശതിന്നുന്നവനെയും അത് തീറ്റിക്കുന്നവനെയും അതിന്റെ സാക്ഷിയെയും അത് എഴുതുന്നവനെയും അസുഖത്തിനല്ലാതെ പച്ചകുത്തുന്നവനെയും പച്ചകുത്താനാവശ്യപ്പെടുന്നവനെയും വിവാഹമോചിതയെ ആദ്യ ഭർത്താവിന് തന്നെ വീണ്ടും അനുവദനീയമാക്കാൻ വേണ്ടി അവളെ വിവാഹം കഴിക്കുന്നവനെയും ആർക്ക് വേണ്ടിയാണോ വിവാഹം കഴിക്കുന്നത് അവനെയും, ധർമ്മം തടയുന്നവനെയും റസൂൽ(സ) ശപിച്ചിരിക്കുന്നു. മരിച്ച വീട്ടിലുള്ള പ്രത്യേകമായ കരച്ചിൽ അവിടന്ന് നിരോധിക്കാറുണ്ടായിരുന്നു. (ന)', 'الْحَارِثِ بْنِ مَالِكٍ', 'ഹാരിസുബ്നു മാലിക്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 729, 730, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=141 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 358, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: أُتِيَ عُمَرُ - رَضِيَ اللَّهُ عَنْهُ - بِامْرَأَةٍ تَشِمُ، فَقَالَ: أَنْشُدُكُمْ بِاللَّهِ، هَلْ سَمِعَ أَحَدٌ مِنْكُمْ مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؟ قَالَ أَبُو هُرَيْرَةَ: فَقُمْتُ فَقُلْتُ: يَا أَمِيرَ الْمُؤْمِنِينَ، أَنَا سَمِعْتُهُ. قَالَ: فَمَا سَمِعْتَهُ؟ قُلْتُ: سَمِعْتُهُ يَقُولُ: "لَا تَشِمْنَ وَلَا تَسْتَوْشِمْنَ". (ن)', 'അബൂഹുറൈറ(റ): പച്ചകുത്തുന്ന ഒരു സ്ത്രീയെ ഉമർ(റ)വിന്റെ അടുക്കൽ കൊണ്ടുവന്നു. അപ്പോൾ ഉമർ(റ) ചോദിച്ചു: അല്ലാഹുവിനെ മുൻനിറുത്തി ഞാൻ നിങ്ങളോട് ചോദിക്കുന്നു, റസൂൽ(സ)യിൽ നിന്നും ആരെങ്കിലും കേട്ടിട്ടുണ്ടോ? അബൂഹുറൈറ പറയുന്നു: ഞാൻ എഴുന്നേറ്റ് നിന്ന് പറഞ്ഞു: ഓ, അമീറുൽ മുഅ്മിനീൻ, ഞാൻ കേട്ടിട്ടുണ്ട്. ഉമർ(റ) ചോദിച്ചു: താങ്കൾ എന്താണ് കേട്ടത്? തിരുമേനി(സ) ഇങ്ങനെ പറയുന്നതായി ഞാൻ കേട്ടിട്ടുണ്ട്: "നിങ്ങൾ പച്ചകുത്തരുത്. അതിനാവശ്യപ്പെടുകയും ചെയ്യരുത്." (ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 730, 730, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=141 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 359, 'عَنْ مُعَاوِيَةَ رَضِيَ اللَّهُ عَنْهُ أَنَّهُ قَالَ: يَا أَيُّهَا النَّاسُ، إِنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَاكُمْ عَنِ الزُّورِ. قَالَ: وَجَاءَ بِخِرْقَةٍ سَوْدَاءَ فَأَلْقَاهَا بَيْنَ أَيْدِيهِمْ فَقَالَ: هُوَ هَذَا تَجْعَلُهُ الْمَرْأَةُ فِي رَأْسِهَا، ثُمَّ تَخْتَمِرُ عَلَيْهِ. وَفِي رِوَايَةٍ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنِ الزُّورِ. وَالزُّورُ: الْمَرْأَةُ تَلُفُّ عَلَى رَأْسِهَا. (ن)', 'മുആവിയ(റ): ഓ ജനങ്ങളേ, നബി(സ) ''സൂർ'' (വ്യാജം) നിങ്ങൾക്ക് നിരോധിച്ചിരിക്കുന്നു. ശേഷം ഒരു കറുത്ത തുണി കൊണ്ടുവന്നു. അവരുടെ മുമ്പിൽ വെച്ചു പറഞ്ഞു: ഇതാണത്, ഇത് സ്ത്രീകൾ അവരുടെ തലയിൽ വെച്ച്, ശേഷം അതിന് മേൽ തലമക്കന കൊണ്ട് മറക്കും.
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=8 and h.hadith_no=359), 1, 'وَفِي رِوَايَةٍ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنِ الزُّورِ. وَالزُّورُ: الْمَرْأَةُ تَلُفُّ عَلَى رَأْسِهَا. (ن)', 'മറ്റൊരു നിവേദനിൽ: റസൂൽ(സ) ''സൂർ'' (വ്യാജം) നിരോധിച്ചിരിക്കുന്നു. ''സൂർ'' എന്ന് പറഞ്ഞാൽ സ്ത്രീകൾ അവരുടെ തലക്ക് മേൽ ചുറ്റുന്ന വസ്ത്രം, (സ്ത്രീകൾ തലയിൽ മുടിയാണെന്ന് തോന്നിപ്പിക്കും വിധം തുണിച്ചുറ്റുന്നതിനാണ് സൂർ എന്ന് പറയുന്നത്.) (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 360, 'عَنْ مُعَاوِيَةَ بْنِ أَبِي سُفْيَانَ رَضِيَ اللَّهُ عَنْهُ - عَلَى الْمِنْبَرِ، وَمَعَهُ فِي يَدِهِ كُبَّةٌ مِنْ كُبَبِ النِّسَاءِ مِنْ شَعْرٍ - فَقَالَ: مَا بَالُ الْمُسْلِمَاتِ يَصْنَعْنَ مِثْلَ هَذَا؟ إِنِّي سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "أَيُّمَا امْرَأَةٍ زَادَتْ فِي رَأْسِهَا شَعْرًا لَيْسَ مِنْهُ فَإِنَّهُ زُورٌ تَزِيدُ فِيهِ". (ن)', 'മുആവിയ(റ): കയ്യിൽ സ്ത്രീകളുടെ മുടിക്കെട്ടുമായി മുആവിയ(റ) മിമ്പറിൽ കയറി ചോദിച്ചു: ഇങ്ങനെ വെക്കുന്ന മുസ്ലിം വനിതകളുടെ അവസ്ഥയെന്താണ്? റസൂൽ(സ) ഇങ്ങനെ പറയുന്നത് ഞാൻ കേട്ടിട്ടുണ്ട്: "തന്റെ തലമുടിയിൽ പെട്ടതല്ലാത്ത മുടികൊണ്ട് ഏതെങ്കിലും സ്ത്രീ തന്റെ തലയിൽ മുടി അധികരിപ്പിച്ചാൽ, വ്യാജമാണ് അതിൽ അധികമാകുന്നത്." (ന)', 'مُعَاوِيَةَ بْنِ أَبِي سُفْيَانَ', 'മുആവിയ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 730, 730, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=142 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 361, 'عَنْ أُمِّ هَانِئٍ رَضِيَ اللهُ عَنْهُ قَالَتْ: قَدِمَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِلَى مَكَّةَ، وَلَهُ أَرْبَعُ غَدَائِرَ، تَعْنِي عَقَائِصَ. (د,ت,جه)', 'ഉമ്മുഹാനിഅ്(റ): നബി(സ) മക്കയിൽ വന്നപ്പോൾ അവിടുത്തെ തലയിൽ (മെടഞ്ഞിട്ട) നാല് മുടിക്കെട്ടുകൾ ഉണ്ടായിരുന്നു. (ദ,തു,ജ)', 'أُمِّ هَانِئٍ', 'ഉമ്മുഹാനിഅ്(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 731, 731, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=143 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 362, 'عَنْ جَابِرِ ابْنِ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: أَتَانَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَرَأَى رَجُلًا ثَائِرَ الرَّأْسِ، فَقَالَ: "أَمَا يَجِدُ هَذَا مَا يُسَكِّنُ بِهِ شَعْرَهُ؟". (ن)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): ഞങ്ങളുടെയടുത്ത് നബി(സ) വന്നപ്പോൾ മുടിപാറിയ ഒരാളെ കണ്ടു. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "തന്റെ മുടി ഒതുക്കി നിർത്തുന്ന ഒന്നും ഇദ്ദേഹത്തിന് കിട്ടിയില്ലേ." (ന)', 'جَابِرِ ابْنِ عَبْدِ اللَّهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 731, 731, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=144 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 363, 'عَنْ أَبِي قَتَادَةَ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَتْ لَهُ جُمَّةٌ ضَخْمَةٌ، فَسَأَلَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَمَرَهُ أَنْ يُحْسِنَ إِلَيْهَا، وَأَنْ يَتَرَجَّلَ كُلَّ يَوْمٍ. (ن)', 'അബൂഖതാദ(റ): അദ്ദേഹത്തിന് കട്ടിയുള്ള മുറ്റിവളരുന്ന മുടിയുണ്ടായിരുന്നു. അതേക്കുറിച്ച് നബി(സ)യോട് ചോദിച്ചപ്പോൾ അത് നന്നാക്കാനും എല്ലാ ദിവസവും മുടിചീകിയിടാനും കൽപ്പിച്ചു. (ന)', 'أَبِي قَتَادَةَ', 'അബൂഖതാദ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 731, 731, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=144 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 364, 'عَنْ أَبِي رَيْحَانَةَ - شَمْعُونَ بْنِ زَيْدِ - رَضِيَ اللَّهُ عَنْهُ قَالَ: إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَرَّمَ الْوَشْرَ وَالْوَشْمَ وَالنَّتْفَ. وفي رواية قال: بَلَغَنَا أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنِ الْوَشْرِ وَالْوَشْمِ. (ن)', 'അബൂറൈഹാന(റ) ശംഊനുബ്നു സൈദ്(റ): പല്ല് മൂർച്ചയാക്കൽ, പച്ച കുത്തൽ, മുടി പറിച്ച് കളയൽ എന്നിവ റസൂൽ(സ) നിഷിദ്ധമാക്കിയിരിക്കുന്നു. മറ്റൊരു റിപ്പോർട്ടിൽ: പല്ല് മൂർച്ചയാക്കലും പച്ചകുത്തലും റസൂൽ(സ) നിരോധിച്ചതായി നാം അറിഞ്ഞു. (ന)', 'أَبِي رَيْحَانَةَ - شَمْعُونَ بْنِ زَيْدِ -', 'അബൂറൈഹാന(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 731, 731, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=145 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=8 and h.hadith_no=364), 1, 'وَفِي رِوَايَةٍ قال: بَلَغَنَا أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنِ الْوَشْرِ وَالْوَشْمِ. (ن)', 'മറ്റൊരു നിവേദനിൽ: പല്ല് മൂർച്ചയാക്കലും പച്ചകുത്തലും റസൂൽ(സ) നിരോധിച്ചതായി നാം അറിഞ്ഞു. (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 365, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: نَهَى رَسُولُ اللَّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَنِ الْقَزَعِ: أَنْ يُحْلَقَ رَأْسُ الصَّبِيِّ فَيُتْرَكَ بَعْضُ شَعْرِهِ. وفي رواية: فَتُتْرَكَ لَهُ ذُؤَابَةٌ. (ق,د,ن,جه)', 'ഇബ്നുഉമർ(റ): മുടി ക്രോപ്പ് ചെയ്യുന്നത് റസൂൽ(സ) നിരോധിച്ചിരിക്കുന്നു. അൽപ്പം മുടി ബാക്കിനിർത്തി കുട്ടിയുടെ മുടി ചുരണ്ടലാണ് ക്രോപ്പ്. മറ്റൊരു റിപ്പോർട്ടിൽ: കുട്ടിയുടെ തലയിൽ കുടുമ നിർത്തൽ (ബു,മു,ദ,ന,ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ق','د','ن','جه']::text[], array['ബു','മു','ദ','ന','ജ']::text[], null, null, 731, 731, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=146 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=8 and h.hadith_no=365), 1, 'وَفِي رِوَايَةٍ: فَتُتْرَكَ لَهُ ذُؤَابَةٌ. (ق,د,ن,جه)', 'മറ്റൊരു നിവേദനിൽ: കുട്ടിയുടെ തലയിൽ കുടുമ നിർത്തൽ (ബു,മു,ദ,ന,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 366, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ رَأَى صَبِيًّا قَدْ حُلِقَ بَعْضُ شَعْرِهِ وَتُرِكَ بَعْضُهُ، فَنَهَاهُمْ عَنْ ذلِكَ، وَقَالَ: "احْلِقُوهُ كُلَّهُ أَوِ اتْرُكُوهُ كُلَّهُ". (د, ن)', 'ഇബ്‌നുഉമർ(റ): മുടിയുടെ ചില ഭാഗം ബാക്കിനിർത്തി ചില ഭാഗം ചുരണ്ടിക്കളഞ്ഞ ഒരു കുട്ടിയെ നബി(സ) കണ്ടു. അപ്പോൾ നബി(സ) സഹാബികളോടത് വിരോധിച്ചു. അവിടുന്ന് പറഞ്ഞു: "നിങ്ങൾ മുടിമുഴുവനും ചുരണ്ടുക, അല്ലെങ്കിൽ തീരെ ചുരണ്ടാതിരിക്കുക." (ദ, ന)', 'ابْنِ عُمَرَ', 'ഇബ്‌നുഉമർ(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 732, 732, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=146 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 367, 'عَنْ عَبْدِ اللهِ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ قَالَ: عَلَى قِرَاءَةِ مَنْ تَأْمُرُونِّي أَقْرَأُ لَقَدْ قَرَأْتُ عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِضْعًا وَسَبْعِينَ سُورَةً ، وَإِنَّ زَيْدًا لَصَاحِبُ ذُؤَابَتَيْنِ يَلْعَبُ مَعَ الصِّبْيَانِ.
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=8 and h.hadith_no=367), 1, 'وَفِي رِوَايَةٍ قَالَ: كَيْفَ تَأْمُرُونِّي أَقْرَأُ عَلَى قِرَاءَةِ زَيْدِ بْنِ ثَابِتٍ، بَعْدَ مَا قَرَأْتُ مِنْ فِي رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِضْعًا وَسَبْعِينَ سُورَةً ، وَإِنَّ زَيْدًا مَعَ الْغِلْمَانِ لَهُ ذُؤَابَتَانِ. (ن)', 'മറ്റൊരു നിവേദനം: സൈദ് രണ്ട് കുടുമയും വെച്ച് കുട്ടികളുടെ കൂടെ കളിച്ചുകൊണ്ടിരിക്കെ ഞാൻ നബി(സ)യുടെ വായിൽ നിന്ന് നേരിട്ട് എഴുപതിൽ പരം സൂറത്തുകൾ ഓതിയ ശേഷമാണോ നിങ്ങളെന്നോട് സൈദുബ്‌നു സാബിത്തിന്റെ ഖിറാഅത്തിൽ ഓതാൻ കൽപിക്കുന്നത്. (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 368, 'عَنِ الحُصَيْنِ بْنِ أَوْسٍ رَضِيَ اللهُ عَنْهُ قَالَ: لَمَّا قَدِمَ عَلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِالْمَدِينَةِ، فَقَالَ لَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "ادْنُ مِنِّي". فَدَنَا مِنْهُ، فَوَضَعَ يَدَهُ عَلَى ذُؤَابَتِهِ، ثُمَّ أَجْرَى يَدَهُ وَسَمَّتْ عَلَيْهِ وَدَعَا لَهُ. (ن)', 'ഹുസൈനുബ്നു ഔസ്(റ): അദ്ദേഹം മദീനയിൽ വെച്ച് റസൂൽ(സ)യുടെ അടുത്ത് ചെന്നു. അദ്ദേഹത്തോട് റസൂൽ(സ) പറഞ്ഞു: "എന്റെ അടുത്ത് വരൂ." അദ്ദേഹം റസൂൽ(സ)യുടെ അടുത്ത് ചെന്നു. നബി(സ) അവിടുത്തെ തിരുകരം അദ്ദേഹത്തിന്റെ കുടുമയിൽ വെച്ചു. പിന്നെ നബി(സ) അവിടെ കൈ നടത്തുകയും അദ്ദേഹത്തിന് വേണ്ടി പ്രാർത്ഥിക്കുകയും ചെയ്തു. (ന)', 'الحُصَيْنِ بْنِ أَوْسٍ', 'ഹുസൈനുബ്നു ഔസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 732, 732, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=146 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 369, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنِ الْقَزَعِ. قَالَ: قُلْتُ لِنَافِعٍ: وَمَا الْقَزَعُ؟ قَالَ: يُحْلَقُ بَعْضُ رَأْسِ الصَّبِيِّ وَيُتْرَكُ بَعْضٌ. (ق, د, ن, ج)', 'ഇബ്‌നുഉമർ(റ): മുടി ക്രോപ്പ് ചെയ്യുന്നത് റസൂൽ(സ) നിരോധിച്ചിരിക്കുന്നു. ഞാൻ നാഫിഅ്(റ)വിനോട് ചോദിച്ചു: എന്താണ് ക്രോപ്പ്? അദ്ദേഹം പറഞ്ഞു: കുട്ടിയുടെ തലയുടെ ചിലഭാഗം വടിക്കലും ചിലഭാഗം വടിക്കാതിരിക്കലും. (ബു,മു,ദ,ന,ജ)', 'ابْنِ عُمَرَ', 'ഇബ്‌നുഉമർ(റ)', null, null, array['ق','د','ن','جه']::text[], array['ബു','മു','ദ','ന','ജ']::text[], null, null, 732, 732, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=146 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 370, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَانَتْ لِي ذُؤَابَةٌ، فَقَالَتْ لِي أُمِّي: لَا أَجُزُّهَا، كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَمُدُّهَا وَيَأْخُذُ بِهَا. (د)', 'അനസുബ്‌നു മാലിക്(റ): എനിക്കൊരു കുടുമയുണ്ടായിരുന്നു. അപ്പോഴെന്നോട് എന്റെ ഉമ്മ പറഞ്ഞു: ഞാനത് മുറിക്കില്ല. റസൂൽ(സ) അത് നീട്ടുകയും അതിൽ പിടിക്കുകയും ചെയ്യുമായിരുന്നു. (ദ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്‌നു മാലിക്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 732, 732, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=146 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 371, 'عَنِ الْحَجَّاجِ بْنِ حَسَّانَ قَالَ: دَخَلْنَا عَلَى أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ، فَحَدَّثَتْنِي أُخْتِي الْمُغِيرَةُ قَالَتْ: وَأَنْتَ يَوْمَئِذٍ غُلَامٌ وَلَكَ قَرْنَانِ، أَوْ قُصَّتَانِ، فَمَسَحَ رَأْسَكَ، وَبَرَّكَ عَلَيْكَ، وَقَالَ: احْلِقُوا هَذَيْنِ، أَوْ قُصُّوهُمَا، فَإِنَّ هَذَا زِيُّ الْيَهُودِ. (د)', 'ഹജ്ജാജുബ്‌നു ഹസ്സാൻ(റ): ഞങ്ങൾ അനസുബ്‌നു മാലിക്(റ)വിന്റെ അടുത്തുചെന്നു. അപ്പോൾ എന്റെ സഹോദരി മുഗീറ എന്നോട് പറഞ്ഞു: നീ അന്ന് ചെറിയ കുട്ടിയാണ്. നിനക്ക് രണ്ട് മുടിക്കെട്ടുകളുണ്ടായിരുന്നു. അനസ്(റ) നിന്റെ തല തടവിക്കൊണ്ട് നന്മക്കായി പ്രാർത്ഥിച്ചു. അദ്ദേഹം പറഞ്ഞു: ഇത് രണ്ടും നിങ്ങൾ വടിക്കുകയോ വെട്ടുകയോ ചെയ്യുക. ഇത് ജൂതരുടെ ശൈലിയാണ്. (ദ)', 'الْحَجَّاجِ بْنِ حَسَّانَ قَالَ', 'ഹജ്ജാജുബ്‌നു ഹസ്സാൻ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 732, 733, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=146 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 372, 'عَنْ وَائِلِ بْنِ حُجْرٍ رَضِيَ اللهُ عَنْهُ قَالَ: أَتَيْتُ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَلِي شَعْرٌ طَوِيلٌ، فَلَمَّا رَآنِي رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "ذُبَابٌ، ذُبَابٌ". قَالَ: فَرَجَعْتُ فَجَزَزْتُهُ، ثُمَّ أَتَيْتُهُ مِنَ الْغَدِ فَقَالَ: "إِنِّي لَمْ أَعْنِكَ، وَهَذَا أَحْسَنُ". (د, ن, جه)', 'വാഇലുബ്നു ഹുജ്ർ(റ): ഞാൻ നബി(സ)യുടെ അടുത്ത് ചെന്നു. അപ്പോൾ എനിക്ക് നീണ്ട മുടിയുണ്ട്. റസൂൽ(സ) എന്നെ കണ്ടപ്പോൾ പറഞ്ഞു: "നാശം, നാശം." ഞാൻ തിരിച്ച് വന്ന് മുടി വെട്ടിച്ചു. പിന്നെ, അടുത്ത ദിവസം ഞാൻ തിരുമേനി(സ)യുടെ സന്നിധിയിൽ ചെന്നു. അപ്പോൾ അവിടന്ന് പറഞ്ഞു: "നിശ്ചയം, ഞാൻ നിന്നെ ഉദ്ദേശിച്ചിരുന്നില്ല, എങ്കിലും ഇതാണ് കൂടുതൽ നല്ലത്." (ദ,ന,ജ)', 'وَائِلِ بْنِ حُجْرٍ', 'വാഇലുബ്നു ഹുജ്ർ(റ)', null, null, array['د','ن','جه']::text[], array['ദ','ന','ജ']::text[], null, null, 733, 733, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=147 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 373, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ شَعْرُ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ رَجِلًا لَيْسَ بِالسَّبِطِ وَلَا الْجَعْدِ بَيْنَ أُذُنَيْهِ وَعَاتِقِهِ. (خ)', 'അനസ്(റ): നബി(സ)യുടെ മുടി ചുരുണ്ടതായിരുന്നു. വല്ലാതെ ചുരുണ്ടതോ, നീണ്ടു നേർത്തതോ, ആയിരുന്നില്ല. അത് അവിടുത്തെ രണ്ട് ചെവിക്കും പിരടിക്കും ഇടയിൽ നീണ്ടുകിടക്കുകയായിരുന്നു. (ബു)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 733, 733, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=148 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 374, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ ضَخْمَ الْيَدَيْنِ وَالْقَدَمَيْنِ حَسَنَ الْوَجْهِ لَمْ أَرَ قَبْلَهُ وَلَا بَعْدَهُ مِثْلَهُ وَكَانَ بَسِطَ الْكَفَّيْنِ. (خ)', 'അനസ്(റ): ഇരുകൈകളും പാദങ്ങളും മുഴുത്ത സുമുഖനായ ഒരാളായിരുന്നു തിരുമേനി(സ) അവിടുത്തെപ്പോലെ ഒരാളെ അതിനു മുമ്പോ ശേഷമോ ഞാൻ കണ്ടിട്ടില്ല. അവിടുത്തെ കൈപ്പടങ്ങൾ വളരെ വിശാലമായിരുന്നു. (ബു)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 733, 733, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=148 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 375, 'عَنْ عَبْدِ اللهِ بْنِ جَعْفَرٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَمْهَلَ آلَ جَعْفَرٍ ثَلَاثًا أَنْ يَأْتِيَهُمْ، ثُمَّ أَتَاهُمْ فَقَالَ: "لَا تَبْكُوا عَلَى أَخِي بَعْدَ الْيَوْمِ". ثُمَّ قَالَ: "ادْعُوا لِي بَنِي أَخِي". فَجِيءَ بِنَا كَأَنَّا أَفْرُخٌ، فَقَالَ: "ادْعُوا لِيَ الْحَلَّاقَ". فَأَمَرَهُ فَحَلَقَ رُءُوسَنَا. (د, ن)', 'അബ്ദുല്ലാഹിബ്നു ജഅ്ഫർ(റ): നബി(സ) ജഅ്ഫർ(റ)വിന്റെ മരണത്തിന് ശേഷം മൂന്ന് ദിവസം അദ്ദേഹത്തിന്റെ കുടുംബത്തിന്റെയടുത്ത് പോയില്ല. പിന്നെ നബി(സ) അവരുടെ അടുത്ത് ചെന്നു. എന്നിട്ട് അവിടന്ന് പറഞ്ഞു: "ഈ ദിവസത്തിന് ശേഷം നിങ്ങൾ എന്റെ സഹോദരന് വേണ്ടി കരയരുത്." പിന്നെ അവിടന്ന് പറഞ്ഞു: "എന്റെ സഹോദരപുത്രന്മാരെ എന്റെയടുത്തേക്ക് വിളിക്കൂ." അപ്പോൾ ഞങ്ങളെ പക്ഷിക്കുഞ്ഞുങ്ങളെപ്പോലെ തിരുസന്നിധിയിലേക്ക് കൊണ്ട് ചെന്നു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "എനിക്ക് വേണ്ടി നിങ്ങൾ ബാർബറെ വിളിക്കുക. നബി(സ)യുടെ ആജ്ഞ പ്രകാരം അദ്ദേഹം ഞങ്ങളുടെ തല മുണ്ഡനം ചെയ്തു. (ദ,ന)', 'عَبْدِ اللهِ بْنِ جَعْفَرٍ', 'അബ്ദുല്ലാഹിബ്നു ജഅ്ഫർ(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 733, 734, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=149 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 376, 'عَنْ عَلِيٍّ رَضِيَ اللهُ عَنْهُ: نَهَى رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنْ تَحْلِقَ الْمَرْأَةُ رَأْسَهَا. (ن)', 'അലി(റ): സ്ത്രീ അവളുടെ തല മുണ്ഡനം ചെയ്യുന്നത് റസൂൽ(സ) നിരോധിച്ചിരിക്കുന്നു. (ന)', 'عَلِيٍّ', 'അലി(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 734, 734, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=150 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 377, 'عَنْ عَبْدِ اللهِ بْنِ الزُّبَيْرِ رَضِيَ اللهُ عَنْهُمَا، عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا، عَنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "عَشْرَةٌ مِنَ الْفِطْرَةِ: قَصُّ الشَّارِبِ، وَقَصُّ الْأَظْفَارِ، وَغَسْلُ الْبَرَاجِمِ، وَإِعْفَاءُ -وَتَوْفِيرُ- اللِّحْيَةِ، وَالسِّوَاكُ، وَالِاسْتِنْشَاقُ، وَنَتْفُ الْإِبْطِ، وَحَلْقُ الْعَانَةِ، وَانْتِقَاصُ الْمَاءِ". قَالَ مُصْعَبٌ: وَنَسِيتُ الْعَاشِرَةَ، إِلَّا أَنْ تَكُونَ الْمَضْمَضَةَ. وَفِي رِوَايَةٍ: "وَالْخِتَانُ، وَغَسْلُ الدُّبُرِ". (ن)', 'അബ്ദുല്ലാഹിബ്നു സുബൈർ(റ) ആഇശ(റ)യിൽ നിന്ന് ഉദ്ധരിക്കുന്നു: റസൂൽ(സ) പറഞ്ഞു: "പത്ത് കാര്യങ്ങൾ ശുദ്ധ പ്രകൃതിയിൽ പെട്ടതാണ്: മീശ വെട്ടുക, നഖം മുറിക്കുക, ചളിയുള്ള ഇടുങ്ങിയ സ്ഥലങ്ങൾ കഴുകുക, താടി നീട്ടിവളർത്തുക, മിസ്‌വാക് ചെയ്യുക, മൂക്കിൽ വെള്ളം കയറ്റിച്ചീറ്റുക, കക്ഷരോമം പറിക്കുക, ഗുഹ്യരോമം നീക്കം ചെയ്യുക, മൂത്രമൊഴിച്ചാൽ വെള്ളം കൊണ്ട് ഗുഹ്യസ്ഥാനം വൃത്തിയാക്കുക." മുസ്അബ്(റ) പറയുന്നു: പത്താമത്തേത് ഞാൻ മറന്ന് പോയി. അത് വായിൽ വെള്ളം കൊപ്ലിക്കലാകാം. മറ്റൊരു നിവേദനം: "മാർക്കം കഴിക്കുക, പിൻദ്വാരം വൃത്തിയാക്കുക." (ന)', 'عَبْدِ اللهِ بْنِ الزُّبَيْرِ', 'അബ്ദുല്ലാഹിബ്നു സുബൈർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 734, 734, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=151 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=8 and h.hadith_no=377), 1, 'وَفِي رِوَايَةٍ: "وَالْخِتَانُ، وَغَسْلُ الدُّبُرِ". (ن)', 'മറ്റൊരു നിവേദനം: "മാർക്കം കഴിക്കുക, പിൻദ്വാരം വൃത്തിയാക്കുക." (ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 378, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: وَقَّتَ لَنَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ -حَلْقَ الْعَانَةِ، وَتَقْلِيمَ الْأَظْفَارِ، وَقَصَّ الشَّارِبِ، وَنَتْفَ الْإِبْطِ- أَرْبَعِينَ يَوْمًا مَرَّةً. (م,د,ت)', 'അനസുബ്നു മാലിക്(റ): ഗുഹ്യ രോമം നീക്കുന്നതും, നഖങ്ങൾ വെട്ടുന്നതും, മീശ വെട്ടുന്നതും, കക്ഷരോമം പറിക്കുന്നതും, നാൽപത് ദിവസത്തിൽ ഒരു പ്രാവശ്യമാക്കി റസൂൽ(സ) സമയം നിശ്ചയിച്ച് തന്നു. (മു,ദ,തു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['م','د','ت']::text[], array['മു','ദ','തു']::text[], null, null, 734, 734, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=152 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 379, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: كُنَّا نُعْفِي السِّبَالَ إِلَّا فِي حَجٍّ أَوْ عُمْرَةٍ. (د)', 'ജാബിർ(റ): ഹജ്ജിലും ഉംറയിലുമല്ലാത്ത സമയത്ത് ഞങ്ങൾ മീശയുടെ രണ്ട് തലഭാഗവും നീട്ടാറുണ്ടായിരുന്നു. (ദ)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 734, 734, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=152 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 380, 'عَنْ زَيْدِ بْنِ أَرْقَمَ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "مَنْ لَمْ يَأْخُذْ شَارِبَهُ فَلَيْسَ مِنَّا". (ن)', 'സൈദുബ്നു അർഖം(റ): ഞാൻ റസൂൽ(സ) പറയുന്നത് കേട്ടു: "മീശ വെട്ടാത്തവൻ, നമ്മിൽ പെട്ടവനല്ല." (ന)', 'زَيْدِ بْنِ أَرْقَمَ', 'സൈദുബ്നു അർഖം(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 735, 735, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=152 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 381, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "خَالِفُوا الْمُشْرِكِينَ، وَفِّرُوا اللِّحَى، وَأَحْفُوا الشَّوَارِبَ". (ق,د,ت,ن)', 'ഇബ്നുഉമർ(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങൾ ബഹുദൈവാരാധകരോട് വിയോജിക്കുക. താടി നിങ്ങൾ നീട്ടിവളർത്തുക. മീശ നിങ്ങൾ താഴ്ത്തിവെട്ടുക." (ബു,മു,ദ,തു,ന)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ق','د','ت','ن']::text[], array['ബു','മു','ദ','തു','ന']::text[], null, null, 735, 735, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=152 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 382, 'عَنْ رُوَيْفِعِ بْنِ ثَابِتٍ رَضِيَ اللهُ عَنْهُ قَالَ: إِنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "يَا رُوَيْفِعُ، لَعَلَّ الْحَيَاةَ سَتَطُولُ بِكَ بَعْدِي، فَأَخْبِرِ النَّاسَ: أَنَّهُ مَنْ عَقَدَ لِحْيَتَهُ، أَوْ تَقَلَّدَ وَتَرًا، أَوِ اسْتَنْجَى بِرَجِيعِ دَابَّةٍ أَوْ عَظْمٍ، فَإِنَّ مُحَمَّدًا بَرِيءٌ مِنْهُ". (ن)', 'റുവൈഫിഉബ്നു സാബിത്(റ): റസൂൽ(സ) പറഞ്ഞു: "ഓ റുവൈഫിഅ്, എനിക്ക് ശേഷം നീ ഒരുപാട് ജീവിച്ചേക്കും. അപ്പോൾ ജനങ്ങൾക്ക് നീ പറഞ്ഞു കൊടുക്കുക: വല്ലവനും താടി ചുരുട്ടി വളർത്തുകയോ വില്ല് മാലയാക്കി ധരിക്കുകയോ, മൃഗത്തിന്റെ കാഷ്ഠം കൊണ്ടോ എല്ല് കൊണ്ടോ മനോഹരിക്കുകയോ ചെയ്താൽ നിശ്ചയം മുഹമ്മദ് അവനിൽ നിന്ന് മുക്തനാണ്." (ന)', 'رُوَيْفِعِ بْنِ ثَابِتٍ', 'റുവൈഫിഉബ്നു സാബിത്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 735, 735, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=153 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 383, 'عَنْ عُبَيْدِ بْنِ جُرَيْجٍ التَّيْمِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: رَأَيْتُ ابْنَ عُمَرَ يُصَفِّرُ لِحْيَتَهُ، فَقُلْتُ لَهُ فِي ذَلِكَ؟ فَقَالَ: رَأَيْتُ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُصَفِّرُ لِحْيَتَهُ. (ن)', 'ഉബൈദുബ്നു ജുറൈജ്(റ): ഇബ്നുഉമർ(റ) താടിക്ക് മഞ്ഞനിറം നൽകുന്നത് ഞാൻ കണ്ടു. അപ്പോൾ ഞാനദ്ദേഹത്തോട് ഇവ്വിഷയകമായി ചോദിച്ചു. അപ്പോൾ അദ്ദേഹം പറഞ്ഞു: റസൂൽ(സ) താടിക്ക് മഞ്ഞനിറം നൽകുന്നത് ഞാൻ കണ്ടിട്ടുണ്ട്. (ന)', 'عُبَيْدِ بْنِ جُرَيْجٍ التَّيْمِيِّ', 'ഉബൈദുബ്നു ജുറൈജ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 735, 735, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=154 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 384, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: كَانَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَلْبَسُ النِّعَالَ السِّبْتِيَّةَ ، وَيُصَفِّرُ لِحْيَتَهُ بِالْوَرْسِ وَالزَّعْفَرَانِ، وَكَانَ ابْنُ عُمَرَ يَفْعَلُ ذَلِكَ. (ن)', 'ഇബ്നുഉമർ(റ): നബി(സ) രോമമില്ലാത്ത ചെരുപ്പുകൾ ധരിക്കുമായിരുന്നു. അവിടുന്ന് താടിക്ക് വർസ് (ചായം കൊടുക്കാനുപയോഗിക്കുന്ന ഒരുതരം ചെടി) കൊണ്ടും കുങ്കുമം കൊണ്ടും മഞ്ഞനിറം നൽകുമായിരുന്നു. ഇബ്നുഉമറും അപ്രകാരം ചെയ്തിരുന്നു. (ന)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 735, 735, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=154 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 385, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ - يَبْلُغُ بِهِ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ- قَالَ: "إِنَّ الْيَهُودَ وَالنَّصَارَى لَا يَصْبُغُونَ، فَخَالِفُوهُمْ". (ق,د,ت,ن,جه)', 'അബൂഹുറൈറ(റ): "ജൂതരും ക്രൈസ്തവരും ചായം പൂശുകയില്ല. അത് കൊണ്ട് നിങ്ങൾ അവർക്ക് എതിർ പ്രവർത്തിക്കുക." (ബു,മു,ദ,തു,ന,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 735, 735, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=154 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 386, 'عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: أُتِيَ بِأَبِي قُحَافَةَ يَوْمَ فَتْحِ مَكَّةَ وَرَأْسُهُ وَلِحْيَتُهُ كَالثَّغَامَةِ بَيَاضًا، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "غَيِّرُوا هَذَا بِشَيْءٍ، وَاجْتَنِبُوا السَّوَادَ". (م،د،ن،جه)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): മക്കാവിജയ ദിനത്തിൽ അബൂഖുഹാഫയെ കൊണ്ടുവന്നു. അദ്ദേഹത്തിന്റെ താടിയും മുടിയും വെളുപ്പ് കാരണം കസ്തൂരിപ്പച്ചപോലെയുണ്ട്. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങൾ ഏതെങ്കിലും വസ്തു കൊണ്ട് ഇതിന്റെ നിറം മാറ്റുക, കറുപ്പ് നിങ്ങൾ ഒഴിവാക്കുക." (മു,ദ,ന,ജ)', 'جَابِرِ بْنِ عَبْدِ اللَّهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['م','د','ن','جه']::text[], array['മു','ദ','ന','ജ']::text[], null, null, 736, 736, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=154 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 387, 'عَنْ أَبِي ذَرٍّ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ أَحْسَنَ مَا غُيِّرَ بِهِ هَذَا الشَّيْبُ الْحِنَّاءُ وَالْكَتَمُ". (د،ت،ن،جه)', 'അബൂദർറ്(റ): റസൂൽ(സ) പറഞ്ഞു: മുടിയിലെ ഈ നര മാറ്റാനുപയോഗിക്കുന്നതിൽ വെച്ചേറ്റവും നല്ലത് മൈലാഞ്ചിയും കതം ചെടി (ചുവപ്പുകലർന്ന് ഒരു തരം കറുത്ത ചെടി) യുമാണ്. (ദ,തു,ന,ജ)', 'أَبِي ذَرٍّ', 'അബൂദർറ്(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 736, 736, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=154 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 388, 'عَنْ أَبِي رِمْثَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: انْطَلَقْتُ مَعَ أَبِي نَحْوَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَإِذَا هُوَ ذُو وَفْرَةٍ بِهَا رَدْعُ حِنَّاءٍ، وَعَلَيْهِ بُرْدَانِ أَخْضَرَانِ. وفي رواية: فَقَالَ لَهُ أَبِي: أَرِنِي هَذَا الَّذِي بِظَهْرِكَ، فَإِنِّي رَجُلٌ طَبِيبٌ. قَالَ: "اللَّهُ الطَّبِيبُ، بَلْ أَنْتَ رَجُلٌ رَفِيقٌ، طَبِيبُهَا الَّذِي خَلَقَهَا". وفي رواية: قَالَ: أَتَيْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَا وَأَبِي، فَقَالَ لِرَجُلٍ أَوْ لِأَبِيهِ: "مَنْ هَذَا؟". قَالَ: ابْنِي، قَالَ: "لَا تَجْنِي عَلَيْهِ". وَكَانَ قَدْ لَطَّخَ لِحْيَتَهُ بِالْحِنَّاءِ. (د،ت،ن)', 'അബൂറിംസ(റ): ഞാൻ എന്റെ ഉപ്പയോട് കൂടെ നബി(സ)യുടെ അടുത്തേക്ക് പോയി. അപ്പോൾ തിരുമേനി(സ)ക്ക് ചെവിയുടെ അടിവരെ എത്തുന്ന മുടിയുണ്ട്. അതിൽ മൈലാഞ്ചിയുടെ അടയാളമുണ്ടായിരുന്നു. തിരുമേനി(സ)യുടെ ശരീരത്തിൽ രണ്ട് പച്ചപ്പുതപ്പുകളുമുണ്ട്.
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=8 and h.hadith_no=388), 1, 'وَفِي رِوَايَةٍ: فَقَالَ لَهُ أَبِي: أَرِنِي هَذَا الَّذِي بِظَهْرِكَ، فَإِنِّي رَجُلٌ طَبِيبٌ. قَالَ: "اللَّهُ الطَّبِيبُ، بَلْ أَنْتَ رَجُلٌ رَفِيقٌ، طَبِيبُهَا الَّذِي خَلَقَهَا".', 'മറ്റൊരു നിവേദനം: അപ്പോൾ തിരുനബി(സ)യോട് എന്റെ പിതാവ് പറഞ്ഞു: അങ്ങയുടെ പുറത്തുള്ളത് എനിക്ക് കാണിച്ചു തന്നാലും. ഞാനൊരു വൈദ്യനാണ്. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹുവാണ് വൈദ്യൻ. എങ്കിലും നിങ്ങൾ കൃപയുള്ള ആളാണ്. രോഗത്തെ ഭേദമാക്കുന്നവൻ രോഗത്തെ സൃഷ്ടിച്ചവൻ തന്നെയാണ്."');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=8 and h.hadith_no=388), 2, 'وَفِي رِوَايَةٍ: قَالَ: أَتَيْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَا وَأَبِي، فَقَالَ لِرَجُلٍ أَوْ لِأَبِيهِ: "مَنْ هَذَا؟". قَالَ: ابْنِي، قَالَ: "لَا تَجْنِي عَلَيْهِ". وَكَانَ قَدْ لَطَّخَ لِحْيَتَهُ بِالْحِنَّاءِ. (د،ت،ن)', 'മറ്റൊരു നിവേദനം: ഞാനും എന്റെ ഉപ്പയും നബി(സ)യുടെ അടുത്തുചെന്നു. അവിടന്ന് എന്റെ പിതാവിനോടോ, അതോ മറ്റൊരാളോടോ ചോദിച്ചു: ഇതാരാണ്." അദ്ദേഹം പറഞ്ഞു: എന്റെ പുത്രനാണ്. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "നീ അവനോട് അക്രമം കാണിക്കരുത്." അവിടന്ന് താടിയിൽ മൈലാഞ്ചി പുരട്ടിയിരുന്നു. (ദ,തു,ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 389, 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّهُ سُئِلَ عَنْ خِضَابِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَذَكَرَ أَنَّهُ لَمْ يَخْضِبْ، وَلَكِنْ قَدْ خَضَبَ أَبُو بَكْرٍ وَعُمَرُ رَضِيَ اللَّهُ عَنْهُمَا. (ق،د)', 'അനസ്(റ): അദ്ദേഹത്തോട് നബി(സ)യുടെ ചായം തേക്കലിനെക്കുറിച്ച് ചോദിക്കപ്പെട്ടു. അപ്പോഴദ്ദേഹം പറഞ്ഞു: നബി(സ) ചായം പൂശിയിട്ടില്ല. എങ്കിലും അബൂബക്കർ(റ)വും ഉമർ(റ)വും ചായം പൂശിയിട്ടുണ്ട്. (ബു,മു,ദ)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['ق','د']::text[], array['ബു','മു','ദ']::text[], null, null, 736, 736, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=154 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 390, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "غَيِّرُوا الشَّيْبَ وَلَا تَشَبَّهُوا بِالْيَهُودِ". حسن صحيح. (ق،د،ت،ن،جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "തലയിലെ നരയിൽ നിങ്ങൾ മാറ്റം വരുത്തുക. നിങ്ങൾ ജൂതരോട് സാദൃശ്യരാകരുത്." (ബു,മു,ദ,തു,ന,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 736, 736, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=154 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 391, 'عَنْ زَيْدِ بْنِ أَسْلَمَ رَضِيَ اللَّهُ عَنْهُ قَالَ: رَأَيْتُ ابْنَ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا يُصَفِّرُ لِحْيَتَهُ بِالْخَلُوقِ؟ فَقُلْتُ: يَا أَبَا عَبْدِ الرَّحْمَنِ، إِنَّكَ تُصَفِّرُ لِحْيَتَكَ بِالْخَلُوقِ؟ قَالَ: إِنِّي رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُصَفِّرُ بِهَا لِحْيَتَهُ، وَلَمْ يَكُنْ شَيْءٌ مِنَ الصِّبْغِ أَحَبَّ إِلَيْهِ مِنْهَا، وَلَقَدْ كَانَ يَصْبُغُ بِهَا ثِيَابَهُ كُلَّهَا حَتَّى عِمَامَتَهُ. (ن)', 'സൈദുബ്നു അസ്‌ലം(റ): ഇബ്‌നുഉമർ(റ) ഖലൂഖുപയോഗിച്ച് താടിക്ക് മഞ്ഞനിറം നൽകുന്നത് ഞാൻ കണ്ടു. ഞാൻ ചോദിച്ചു: ഓ, അബൂ അബ്ദിർറഹ്‌മാൻ, നിങ്ങളെന്താണ് ഖലൂഖ് കൊണ്ട് താടിക്ക് മഞ്ഞനിറം കൊടുക്കുന്നത്?'' അദ്ദേഹം പറഞ്ഞു: റസൂൽ(സ) ഖലൂഖ് കൊണ്ട് താടിക്ക് മഞ്ഞനിറം നൽകുന്നത് ഞാൻ കണ്ടിട്ടുണ്ട്. ചായങ്ങളിൽ വെച്ച് അതിനേക്കാൾ നബി(സ)ക്ക് ഇഷ്ടപ്പെട്ട ഒന്നുമുണ്ടായിരുന്നില്ല. നബി(സ) അവിടുത്തെ തലപ്പാവടക്കമുള്ള എല്ലാ വസ്ത്രങ്ങളിലും ഖലൂഖുപയോഗിച്ച് ചായം കൊടുക്കുമായിരുന്നു. (ന)', 'زَيْدِ بْنِ أَسْلَمَ', 'സൈദുബ്നു അസ്‌ലം(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 736, 737, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=154 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 392, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ أَنَّهُ سُئِلَ: هَلْ خَضَبَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ؟ قَالَ: لَمْ يَبْلُغْ ذَلِكَ، إِنَّمَا كَانَ شَيْءٌ فِي صُدْغَيْهِ. (ن)', 'അനസ്(റ): അദ്ദേഹത്തോട് ചോദിക്കപ്പെട്ടു: നബി(സ) ചായം പൂശിയിരുന്നോ? അദ്ദേഹം പറഞ്ഞു: നബി(സ)ക്ക് അത്രത്തോളമൊന്നും നര വന്നിട്ടില്ല. അവിടുത്തെ രണ്ട് ചെവിയുടെ ഭാഗത്തും അൽപം നരയുണ്ടായിരുന്നു. (ന)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 737, 737, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=154 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 393, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لَمْ يَكُنْ يَخْضِبُ، إِنَّمَا كَانَ الشَّمَطُ عِنْدَ الْعَنْفَقَةِ يَسِيرًا، وَفِي الصُّدْغَيْنِ يَسِيرًا، وَفِي الرَّأْسِ يَسِيرًا. (ن)', 'അനസ്(റ): റസൂൽ(സ) ചായം തേക്കുമായിരുന്നില്ല. അവിടുത്തെ ശിരസ്സിലും ചെവിയുടെ ഭാഗത്തും താഴെ ചുണ്ടിന് അടിയിലും അൽപം നരയുണ്ടായിരുന്നു. (ന)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 737, 737, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=154 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 394, 'عَنْ عَبْدِ اللهِ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ: أَنَّ نَبِيَّ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يَكْرَهُ عَشْرَ خِصَالٍ: الصُّفْرَةَ، يَعْنِي الْخَلُوقَ، وَتَغْيِيرَ الشَّيْبِ، وَجَرَّ الْإِزَارِ، وَالتَّخَتُّمَ بِالذَّهَبِ، وَالضَّرْبَ بِالْكِعَابِ، وَالتَّبَرُّجَ بِالزِّينَةِ لِغَيْرِ مَحَلِّهَا، وَالرُّقَى إِلَّا بِالْمُعَوِّذَاتِ، وَتَعْلِيقَ التَّمَائِمِ، وَعَزْلَ الْمَاءِ بِغَيْرِ مَحَلِّهِ، وَإِفْسَادَ الصَّبِيِّ غَيْرَ مُحَرِّمِهِ. (ن)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): നബി(സ) പത്ത് കാര്യങ്ങൾ വെറുത്തിരുന്നു: ഖലൂഖ് (ഒരു തരം മിശ്രിത സുഗന്ധം) കൊണ്ട് മഞ്ഞനിറം കൊടുക്കുക, നരക്ക് ചായം കൊടുക്കുക, തുണി വലിച്ചിഴക്കുക, സ്വർണ്ണ മോതിരം ധരിക്കുക, പകിട കളിക്കുക, സൗന്ദര്യം അസ്ഥാനത്ത് പ്രകടമാക്കുക, മുഅവ്വദാത്ത് (കാവൽ ചോദിക്കപ്പെടാൻ നിർദ്ദേശിക്കപ്പെട്ട സൂറത്തുകൾ) കൊണ്ടല്ലാതെ മന്ത്രിക്കുക. ഏലസ്സുകൾ കെട്ടുക. അസ്ഥാനത്ത് ഇന്ദ്രിയം കളയുക, മുലകുടിക്കുന്ന കുഞ്ഞിന്റെ മാതാവിനെ ഭർത്താവ് ഗർഭിണിയാക്കുക, നിഷിദ്ധമല്ലെങ്കിലും. (ന)', 'عَبْدِ اللهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 737, 737, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=154 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 395, 'عَنْ عُبَيْدِ بْنِ جُرَيْجٍ رَضِيَ اللهُ عَنْهُ: سَأَلَ ابْنَ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: رَأَيْتُكَ تُصَفِّرُ لِحْيَتَكَ بِالْوَرْسِ؟ فَقَالَ ابْنُ عُمَرَ: أَمَّا تَصْفِيرِي لِحْيَتِي فَإِنِّي رَأَيْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُصَفِّرُ لِحْيَتَهُ. (ق,د,ن,جه)', 'ഉബൈദുബ്നു ജുറൈദ്(റ): അദ്ദേഹം ഇബ്‌നുഉമർ(റ)വിനോട് ചോദിച്ചു: താങ്കൾ വർസുപയോഗിച്ച് താടിക്ക് മഞ്ഞനിറം കൊടുക്കുന്നത് കണ്ടല്ലോ? അപ്പോൾ ഇബ്‌നുഉമർ(റ) പറഞ്ഞു: ഞാൻ താടിക്ക് മഞ്ഞനിറം കൊടുക്കുന്നത്, റസൂൽ(സ) താടിക്ക് മഞ്ഞനിറം നൽകുന്നത് ഞാൻ കണ്ടതുകൊണ്ടാണ്. (ബു,മു,ദ,ന,ജ)', 'عُبَيْدِ بْنِ جُرَيْجٍ', 'ഉബൈദുബ്നു ജുറൈദ്(റ)', null, null, array['ق','د','ن','جه']::text[], array['ബു','മു','ദ','ന','ജ']::text[], null, null, 737, 737, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=154 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 396, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: مَرَّ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَلَى رَجُلٍ قَدْ خَضَبَ بِالْحِنَّاءِ، فَقَالَ: "مَا أَحْسَنَ هَذَا". ثُمَّ مَرَّ بِآخَرَ قَدْ خَضَبَ بِالْحِنَّاءِ وَالْكَتَمِ، فَقَالَ: "هَذَا أَحْسَنُ مِنْ هَذَا". ثُمَّ مَرَّ بِآخَرَ قَدْ خَضَبَ بِالصُّفْرَةِ، فَقَالَ: "هَذَا أَحْسَنُ مِنْ هَذَا كُلِّهِ". (د,جه)', 'ഇബ്‌നുഅബ്ബാസ്(റ): മൈലാഞ്ചിയിട്ട ഒരാളുടെ അടുത്തുകൂടെ നബി(സ) നടന്നു പോയി. അപ്പോൾ അവിടുന്ന് പറഞ്ഞു: "ഇതെന്തൊരു ഭംഗിയാണ്!" പിന്നെ നബി(സ) കതമും മൈലാഞ്ചിയും ഇട്ട വേറൊരാളുടെ അടുത്തു കൂടെ നടന്നു പോയി. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "ഇത് മറ്റേതിനേക്കാൾ ഭംഗിയുണ്ട്." പിന്നീട് മഞ്ഞനിറം കൊണ്ട് ചായം പൂശിയ ഒരാളുടെ അടുത്തുകൂടെ അവിടുന്ന് നടന്നുപോയി. അപ്പോൾ നബി(സ) പറഞ്ഞു: "ഇത് എല്ലാറ്റിനേക്കാളും ഭംഗിയുണ്ട്." (ദ,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്‌നുഅബ്ബാസ്(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 737, 737, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=154 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 397, 'عَنْ جَابِرٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: جِيءَ بِأَبِي قُحَافَةَ يَوْمَ الْفَتْحِ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَكَأَنَّ رَأْسَهُ ثَغَامَةٌ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: ”اذْهَبُوا بِهِ إِلَى بَعْضِ نِسَائِهِ فَلْتُغَيِّرْهُ، وَجَنِّبُوهُ السَّوَادَ“. [ز: في سنده ضعيف، وأصله في مسلم] (جه)', 'ജാബിർ(റ): മക്കാവിജയ ദിനത്തിൽ അബൂഖുഹാഫ(റ)വിനെ നബി(സ)യുടെ അടുത്ത് കൊണ്ട് വരപ്പെട്ടു. അദ്ദേഹത്തിന്റെ ശിരസ്സ് കസ്തൂരിപ്പച്ച പോലെയുണ്ട്. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: “അദ്ദേഹത്തെ നിങ്ങൾ അദ്ദേഹത്തിന്റെ ഭാര്യയുടെ അടുത്തേക്ക് കൊണ്ട് പോകുക. അവർ അദ്ദേഹത്തിന്റെ നരയിൽ ചായം കൊടുക്കട്ടെ. അദ്ദേഹത്തിന് നിങ്ങൾ കറുപ്പ്ചായം പൂശരുത്.” (സനദിൽ ബലഹീനരുണ്ടെന്ന് ഇബ്നു മാജ) (ജ)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في سنده ضعيف، وأصله في مسلم', null, 738, 738, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=155 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 398, 'عَنْ صُهَيْبِ الْخَيْرِ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: ”إِنَّ أَحْسَنَ مَا اخْتَضَبْتُمْ بِهِ لَهَذَا السَّوَادُ، أَرْغَبُ لِنِسَائِكُمْ فِيكُمْ، وَأَهْيَبُ لَكُمْ فِي صُدُورِ عَدُوِّكُمْ“. (جه)', 'സുഹൈബുൽ ഖൈർ(റ): റസൂൽ(സ) പറഞ്ഞു: “നിങ്ങൾ ഈ മുടിക്ക് ചായം പൂശാൻ ഉപയോഗിച്ചതിൽ വെച്ച് ഏറ്റവും ഭംഗിയുള്ളത് ഈ കറുപ്പാണ്. അത് നിങ്ങളുടെ ഭാര്യമാർക്ക് നിങ്ങളിൽ ആഗ്രഹം നൽകുന്നതും, നിങ്ങളുടെ ശത്രുക്കളുടെ മനസ്സിൽ ഭയം ജനിപ്പിക്കുന്നതുമാണ്.” (ജ)', 'صُهَيْبِ الْخَيْرِ', 'സുഹൈബുൽ ഖൈർ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 738, 738, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=155 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 399, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: ”يَكُونُ قَوْمٌ يَخْضِبُونَ فِي آخِرِ الزَّمَانِ بِالسَّوَادِ كَحَوَاصِلِ الْحَمَامِ، لَا يَرِيحُونَ رَائِحَةَ الْجَنَّةِ“. (د,ن)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂൽ(സ) പറഞ്ഞു: “അവസാന നാളുകളിൽ പ്രാവിന്റെ ഉദരം പോലെ മുടിക്ക് കറുപ്പ്നിറം കൊടുക്കുന്ന ഒരു വിഭാഗം ആളുകളുണ്ടാകും. അവർക്ക് സ്വർഗ്ഗത്തിന്റെ പരിമളം ലഭിക്കില്ല.” (ദ,ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 738, 738, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=155 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 400, 'عَنْ عُثْمَانَ بْنِ مَوْهَبٍ قَالَ: دَخَلْتُ عَلَى أُمِّ سَلَمَةَ رَضِيَ اللَّهُ عَنْهَا، فَأَخْرَجَتْ إِلَيَّ شَعْرًا مِنْ شَعْرِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَخْضُوبًا بِالْحِنَّاءِ وَالْكَتَمِ. (خ,جه)', 'ഉസ്മാനുബ്നു മൗഹിബ്(റ): ഞാൻ ഉമ്മുസലമ(റ)യുടെ അടുത്ത് ചെന്നപ്പോൾ മൈലാഞ്ചിയും കതമും (മുടികറുപ്പിക്കാനുപയോഗിക്കുന്ന ഒരു ചെടി) ഉപയോഗിച്ച് ചായം തേക്കപ്പെട്ട റസൂൽ(സ)യുടെ ഒരു മുടി എനിക്കവർ എടുത്തുതന്നു. (ബു,ജ)', 'عُثْمَانَ بْنِ مَوْهَبٍ قَالَ', 'ഉസ്മാനുബ്നു മൗഹിബ്(റ)', null, null, array['خ','جه']::text[], array['ബു','ജ']::text[], null, null, 738, 738, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=156 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 401, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا: سَأَلَتْهَا امْرَأَةٌ عَنِ الْخِضَابِ بِالْحِنَّاءِ؟ قَالَتْ: لَا بَأْسَ بِهِ، وَلَكِنْ أَكْرَهُ هَذَا، لِأَنَّ حِبِّي صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَكْرَهُ رِيحَهُ. تَعْنِي النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. (ن)', 'ആഇശ(റ): മൈലാഞ്ചിയിടുന്നതിനെക്കുറിച്ച് ഒരു സ്ത്രീ അവരോട് ചോദിച്ചു. അവർ പറഞ്ഞു: അതിൽ കുഴപ്പമൊന്നുമില്ല, എങ്കിലും ഞാനത് വെറുക്കുന്നു. കാരണം എന്റെ സ്നേഹഭാജനമായ നബി(സ) അതിന്റെ വാസന വെറുത്തിരുന്നു. (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 738, 738, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=156 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 402, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا: أَنَّ امْرَأَةً مَدَّتْ يَدَهَا إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِكِتَابٍ، فَقَبَضَ يَدَهُ، فَقَالَتْ: يَا رَسُولَ اللَّهِ، مَدَدْتُ يَدِي إِلَيْكَ بِكِتَابٍ فَلَمْ تَأْخُذْهُ؟ فَقَالَ: ”إِنِّي لَمْ أَدْرِ أَيَدُ امْرَأَةٍ هِيَ أَوْ رَجُلٍ“. قَالَتْ: بَلْ يَدُ امْرَأَةٍ. قَالَ: "لَوْ كُنْتِ امْرَأَةً لَغَيَّرْتِ أَظْفَارَكِ بِالْحِنَّاءِ". (ن)', 'ആഇശ(റ): ഒരു സ്ത്രീ ഒരു ഗ്രന്ഥവുമായി നബി(സ)യുടെ അടുത്തേക്ക് കൈ നീട്ടി. നബി(സ) അവിടുത്തെ കരം അനക്കിയില്ല. അപ്പോൾ ആ സ്ത്രീ പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, ഞാൻ അങ്ങേക്ക് ഒരു ഗ്രന്ഥം നീട്ടിത്തന്നു. പക്ഷേ, അവിടന്നത് സ്വീകരിച്ചില്ല? അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "അതൊരു സ്ത്രീയുടെ കയ്യാണോ, അതോ പുരുഷന്റെ കയ്യാണോ എന്നെനിക്ക് മനസ്സിലായില്ല." അപ്പോൾ ആ സ്ത്രീ പറഞ്ഞു: സ്ത്രീയുടെ കയ്യാണ്. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "നീയൊരു സ്ത്രീയാണെങ്കിൽ നിന്റെ നഖങ്ങൾക്ക് നീ മൈലാഞ്ചി ഇടുമായിരുന്നു. (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 738, 739, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=156 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 403, 'عَنْ أَبِي جُحَيْفَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ هَذِهِ مِنْهُ بَيْضَاءَ، يَعْنِي: عَنْفَقَتَهُ. (ق,جه)', 'അബൂജുഹൈഫ(റ): നബി(സ)യുടെ താടിക്കും കീഴ്ചുണ്ടിനുമിടയിലെ രോമം വെളുത്തതായി ഞാൻ കണ്ടു. (ബു,മു,ജ)', 'أَبِي جُحَيْفَةَ', 'അബൂജുഹൈഫ(റ)', null, null, array['ق','جه']::text[], array['ബു','മു','ജ']::text[], null, null, 739, 739, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=157 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 404, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ سُئِلَ: أَخَضَبَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؟ قَالَ: إِنَّهُ لَمْ يَرَ مِنَ الشَّيْبِ إِلَّا نَحْوَ سَبْعَةَ عَشَرَ -أَوْ عِشْرِينَ- شَعَرَةً، فِي مُقَدَّمِ لِحْيَتِهِ. (جه)', 'അനസുബ്നു മാലിക്(റ): റസൂൽ(സ) ചായം തേച്ചിരുന്നോ എന്ന് അദ്ദേഹത്തോട് ചോദിക്കപ്പെട്ടു. അപ്പോൾ അനസ്(റ) പറഞ്ഞു: അവിടുത്തെ താടിയുടെ മുൻഭാഗത്തായി പതിനേഴോ ഇരുപതോ നരകൾ മാത്രമേ ഞാൻ കണ്ടിട്ടുള്ളൂ. (ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 739, 739, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=157 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 405, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: كَانَ شَيْبُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَحْوَ عِشْرِينَ شَعَرَةً. (جه)', 'ഇബ്നുഉമർ(റ): റസൂൽ(സ)യുടെ നരച്ചമുടി ഇരുപതോളമായിരുന്നു. (ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 739, 739, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=157 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 406, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: أَوْمَتِ امْرَأَةٌ مِنْ وَرَاءِ سِتْرٍ بِيَدِهَا كِتَابٌ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَبَضَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَدَهُ، فَقَالَ: "مَا أَدْرِي أَيَدُ رَجُلٍ أَمْ يَدُ امْرَأَةٍ؟". قَالَتْ: بَلِ امْرَأَةٌ، قَالَ: "لَوْ كُنْتِ امْرَأَةً لَغَيَّرْتِ أَظْفَارَكِ". يَعْنِي بِالْحِنَّاءِ. (د,ن)', 'ആഇശ(റ): വിരിയുടെ അപ്പുറത്ത് നിന്ന് ഒരു സ്ത്രീ അവരുടെ കയ്യിലുള്ള ഒരു ഗ്രന്ഥം റസൂൽ(സ)ക്ക് നീട്ടിക്കൊടുത്തു. അപ്പോൾ റസൂൽ(സ) അവിടുത്തെ കരം അനക്കിയില്ല. അവിടന്ന് പറഞ്ഞു: "അത് പുരുഷന്റെ കയ്യാണോ, അതോ സ്ത്രീയുടെ കരമാണോ എന്നെനിക്കറിയില്ല." ആ സ്ത്രീ പറഞ്ഞു: സ്ത്രീയുടെ കയ്യാണ്. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "നീയൊരു സ്ത്രീയായിരുന്നെങ്കിൽ നിന്റെ നഖങ്ങളിൽ നീ മൈലാഞ്ചിയിട്ട് മാറ്റം വരുത്തുമായിരുന്നു." (ദ,ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 739, 739, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=157 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 407, 'عَنْ أَبِي رَيْحَانَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ عَشْرٍ: عَنِ الْوَشْرِ، وَالْوَشْمِ، وَالنَّتْفِ، وَعَنْ مُكَامَعَةِ الرَّجُلِ الرَّجُلَ بِغَيْرِ شِعَارٍ، وَعَنْ مُكَامَعَةِ الْمَرْأَةِ الْمَرْأَةَ بِغَيْرِ شِعَارٍ، وَأَنْ يَجْعَلَ الرَّجُلُ أَسْفَلَ ثِيَابِهِ حَرِيرًا مِثْلَ الْأَعَاجِمِ، أَوْ يَجْعَلَ عَلَى مَنْكِبَيْهِ حَرِيرًا أَمْثَالَ الْأَعَاجِمِ، وَعَنِ النُّهْبَى، وَعَنْ رُكُوبِ النُّمُورِ، وَلُبُوسِ الْخَوَاتِيمِ إِلَّا لِذِي سُلْطَانٍ. (ن)', 'അബൂറൈഹാന(റ): റസൂൽ(സ) പത്തുകാര്യങ്ങൾ നിരോധിച്ചിരിക്കുന്നു: പല്ല് കനംകുറച്ച് മൂർച്ച കൂട്ടൽ, രോമം പറിച്ചെടുക്കുക, വിവസ്ത്രനായി ഒരാൾ മറ്റൊരാളുടെ കൂടെ കിടക്കുക, വിവസ്ത്രയായി ഒരു സ്ത്രീ മറ്റൊരു സ്ത്രീയുടെ കൂടെ കിടക്കുക, അനറബികളെപ്പോലെ വസ്ത്രത്തിന്റെ കര പട്ടാക്കുക, അനറബികളെ പോലെ രണ്ട് തോൾ ഭാഗത്ത് പട്ടണിയുക, കൊള്ള ചെയ്യുക, പുലിയുടെ തോലിൽ യാത്ര ചെയ്യുക, അധികാരമില്ലാത്തവൻ മോതിരങ്ങൾ ധരിക്കുക. (ന)', 'أَبِي رَيْحَانَةَ', 'അബൂറൈഹാന(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 739, 740, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=158 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 408, 'عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَا تَنْتِفُوا الشَّيْبَ، مَا مِنْ مُسْلِمٍ يَشِيبُ شَيْبَةً فِي الْإِسْلَامِ إِلَّا كَانَتْ لَهُ نُورًا يَوْمَ الْقِيَامَةِ". وفي رواية: "إِلَّا كَتَبَ اللَّهُ بِهَا حَسَنَةً وَحَطَّ عَنْهُ بِهَا خَطِيئَةً". (د،ت،ن،جه)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങൾ നരച്ച മുടി പറിക്കരുത്, ഇസ്‌ലാമിലായിരിക്കെ ഒരു മുസ്‌ലിമിന്റെ ഓരോ രോമം നരക്കുമ്പോഴും അതവന് അന്ത്യദിനത്തിൽ പ്രകാശമായി മാറും."
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=2 and b.book_no=8 and h.hadith_no=408), 1, 'وَفِي رِوَايَةٍ: "إِلَّا كَتَبَ اللَّهُ بِهَا حَسَنَةً وَحَطَّ عَنْهُ بِهَا خَطِيئَةً". (د،ت،ن،جه)', 'മറ്റൊരു നിവേദനം: "അതുമൂലം അവനൊരു നന്മയെഴുതപ്പെടുകയും ഒരു തിന്മ തള്ളിക്കളയപ്പെടുകയും ചെയ്യും." (ദ,തു,ന,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 409, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: لَعَنَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْمُخَنَّثِينَ مِنَ الرِّجَالِ وَالْمُتَرَجِّلَاتِ مِنَ النِّسَاءِ، وَقَالَ: "أَخْرِجُوهُمْ مِنْ بُيُوتِكُمْ". قَالَ: فَأَخْرَجَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فُلَانًا وَأَخْرَجَ عُمَرُ فُلَانًا. (خ)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ) സ്ത്രീകളുടെ വേഷം ധരിക്കുന്ന പുരുഷന്മാരെയും പുരുഷന്റെ വേഷം ധരിക്കുന്ന സ്ത്രീകളെയും ശപിച്ചിരിക്കുന്നു. അവിടുന്ന് പറഞ്ഞു: "അവരെ നിങ്ങളുടെ വീടുകളിൽ നിന്ന് പുറത്താക്കുക." നിവേദകൻ പറയുന്നു: നബി(സ) ഒരാളെ പുറത്താക്കി. ഉമർ(റ)വും ഒരാളെ പുറത്താക്കി. (ബു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 740, 740, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=159 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 410, 'عَنْ ثَوْبَانَ رَضِيَ اللَّهُ عَنْهُ - مَوْلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ- قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا سَافَرَ كَانَ آخِرُ عَهْدِهِ بِإِنْسَانٍ مِنْ أَهْلِهِ فَاطِمَةَ، وَأَوَّلُ مَنْ يَدْخُلُ عَلَيْهَا إِذَا قَدِمَ فَاطِمَةَ، فَقَدِمَ مِنْ غَزَاةٍ لَهُ وَقَدْ عَلَّقَتْ مِسْحًا أَوْ سِتْرًا عَلَى بَابِهَا، وَحَلَّتِ الْحَسَنَ وَالْحُسَيْنَ قُلْبَيْنِ مِنْ فِضَّةٍ، فَقَدِمَ فَلَمْ يَدْخُلْ، فَظَنَّتْ أَنَّ مَا مَنَعَهُ أَنْ يَدْخُلَ مَا رَأَى، فَهَتَكَتِ السِّتْرَ وَفَكَّكَتِ الْقُلْبَيْنِ عَنِ الصَّبِيَّيْنِ وَقَطَّعَتْهُ بَيْنَهُمَا، فَانْطَلَقَا إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهُمَا يَبْكِيَانِ، فَأَخَذَهُ مِنْهُمَا، وَقَالَ: "يَا ثَوْبَانُ، اذْهَبْ بِهَذَا إِلَى آلِ فُلَانٍ"، أَهْلِ بَيْتٍ بِالْمَدِينَةِ "إِنَّ هَؤُلَاءِ أَهْلُ بَيْتِي، أَكْرَهُ أَنْ يَأْكُلُوا طَيِّبَاتِهِمْ فِي حَيَاتِهِمُ الدُّنْيَا. يَا ثَوْبَانُ، اشْتَرِ لِفَاطِمَةَ قِلَادَةً مِنْ عَصَبٍ وَسِوَارَيْنِ مِنْ عَاجٍ". (د)', 'നബി(സ)യുടെ അടിമയായ സൗബാൻ(റ): റസൂൽ(സ) യാത്ര ചെയ്യുമ്പോൾ അവിടുത്തെ കുടുംബത്തിൽ നിന്ന് അവസാനത്തെ ഉപദേശം ഫാതിമ(റ)യോടായിരിക്കും. തിരിച്ചു വരുമ്പോൾ ആദ്യം കടക്കുന്നതും മഹതിയുടെ അടുത്തായിരിക്കും. നബി(സ) ഒരു യുദ്ധത്തിൽ നിന്ന് തിരിച്ചെത്തി. ഫാതിമ(റ) വീട്ടിന്റെ വാതിലിൽ ഒരു വിരി തൂക്കിയിട്ടുണ്ട്. മഹതി ഹസൻ(റ)വിനും ഹുസൈൻ(റ)വിനും വെള്ളിയുടെ വളകൾ ധരിപ്പിച്ചിരിക്കുന്നു. നബി(സ) വന്നു. പക്ഷേ വീട്ടിൽ കയറിയില്ല. നബി(സ)യെ വീട്ടിൽ പ്രവേശിക്കുന്നതിൽ നിന്ന് തടഞ്ഞത്, അവിടന്ന് അത് കണ്ടതാണെന്ന് ഫാതിമ(റ) വിചാരിച്ചു. അവർ വിരി കീറുകയും കുട്ടികളുടെ വളകളഴിച്ച് അവരുടെ മുന്നിൽ വെച്ച് അവ മുറിക്കുകയും ചെയ്തു. കുട്ടികൾ കരഞ്ഞു കൊണ്ട് റസൂൽ(സ)യുടെ അടുക്കൽ വന്നു. അപ്പോൾ റസൂൽ(സ) കുട്ടികളിൽ നിന്ന് അവ വാങ്ങി. എന്നിട്ട് പറഞ്ഞു: "ഓ, സൗബാൻ, ഇതുമായി നീ ഇന്ന കുടുംബത്തിലേക്ക് പോകുക." മദീനയിലുള്ള ഒരു കുടുംബം. "ഇതെന്റെ അഹ്‌ലുബൈത്താണ്, അവർ തങ്ങളുടെ മുന്തിയവയെല്ലാം ഈ ദുൻയാവിലെ ജീവിതത്തിൽ തിന്നുതീർക്കുന്നത് ഞാൻ വെറുക്കുന്നു, ഓ, സൗബാൻ, ഫാതിമ(റ)ക്ക് നിങ്ങൾ നാരിന്റെ മാലയും, ആനക്കൊമ്പിന്റെ രണ്ട് വളകളും വാങ്ങുക." (ദ)', 'ثَوْبَانَ', 'നബി(സ)യുടെ അടിമയായ സൗബാൻ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 740, 741, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=160 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 411, 'عَنْ أَبِي بَشِيرٍ الْأَنْصَارِيِّ رَضِيَ اللهُ عَنْهُ: أَنَّهُ كَانَ مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي بَعْضِ أَسْفَارِهِ، قَالَ: فَأَرْسَلَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ رَسُولًا -قَالَ عَبْدُ اللَّهِ بْنُ أَبِي بَكْرٍ: حَسِبْتُ أَنَّهُ قَالَ- وَالنَّاسُ فِي مَبِيتِهِمْ: "لَا يَبْقَيَنَّ فِي رَقَبَةِ بَعِيرٍ قِلَادَةٌ مِنْ وَتَرٍ - أَوْ قِلَادَةٌ - إِلَّا قُطِعَتْ". قَالَ مَالِكٌ: أَرَى ذَلِكَ مِنَ الْعَيْنِ. (م)', 'അബൂബശീറുൽ അൻസ്വാരി(റ): അദ്ദേഹം റസൂൽ(സ)യുടെ കൂടെ ഒരു യാത്രയിലുണ്ടായിരുന്നു. അദ്ദേഹം പറയുന്നു: അങ്ങനെ റസൂൽ(സ) ഒരു ദൂതനെ അയച്ചു. - അബ്ദുല്ലാഹിബ്നു അബൂബക്കർ(റ) പറയുന്നു: ജനങ്ങൾ ഉറക്കത്തിലായിരിക്കെയാണ് റസൂൽ(സ) പറഞ്ഞതെന്ന് ഞാൻ വിചാരിക്കുന്നു. - "ഒരു മൃഗത്തിന്റെ പിരടിയിലും ഞാൺ കൊണ്ടുള്ള പട്ട - അല്ലെങ്കിൽ മാല ഉണ്ടാകരുത്." മാലിക്(റ) പറയുന്നു: കണ്ണേറ് പോലോത്തത് തട്ടാതിരിക്കാൻ വേണ്ടി കെട്ടുന്ന പട്ടയാണ് നബി(സ) മുറിച്ചിടാൻ പറഞ്ഞതെന്ന് ഞാൻ മനസ്സിലാക്കുന്നു. (മു)', 'أَبِي بَشِيرٍ الْأَنْصَارِيِّ', 'അബൂബശീറുൽ അൻസ്വാരി(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 741, 741, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=161 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 412, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "الْجَرَسُ مَزَامِيرُ الشَّيْطَانِ". (م)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറയുന്നു: "മണി പിശാചിന്റെ വീണകളിൽ പെട്ടതാകുന്നു. " (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 741, 741, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=161 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 413, 'عَنْ جَابِرٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الضَّرْبِ فِي الْوَجْهِ، وَعَنِ الْوَسْمِ فِي الْوَجْهِ. (م)', 'ജാബിറുബ്നു അബ്ദുല്ല(റ): മുഖത്ത് അടിക്കലും കമ്പി ചൂടാക്കി അടയാളം വെക്കലും റസൂൽ(സ) നിരോധിച്ചിരിക്കുന്നു. (മു)', 'جَابِرٍ', 'ജാബിറുബ്നു അബ്ദുല്ല(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 741, 741, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=162 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 414, 'عَنْ نَاعِمٍ أَبِي عَبْدِ اللَّهِ مَوْلَى أُمِّ سَلَمَةَ رَضِيَ اللَّهُ عَنْهُ: أَنَّهُ سَمِعَ ابْنَ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا يَقُولُ: وَرَأَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حِمَارًا مَوْسُومَ الْوَجْهِ، فَأَنْكَرَ ذَلِكَ. قَالَ: فَوَاللَّهِ لَا أَسِمُهُ إِلَّا [فِي] أَقْصَى شَيْءٍ مِنَ الْوَجْهِ. فَأَمَرَ بِحِمَارٍ لَهُ فَكُوِيَ فِي جَاعِرَتَيْهِ، فَهُوَ أَوَّلُ مَنْ كَوَى الْجَاعِرَتَيْنِ. (م)', 'ഉമ്മുസലമ(റ)യുടെ അടിമ നാഇമുബ്‌നു അബ്ദില്ല(റ): ഇബ്‌നുഅബ്ബാസ്(റ) പറയുന്നത് അദ്ദേഹം കേട്ടു. റസൂൽ(സ) മുഖത്ത് അടയാളം വെക്കപ്പെട്ട ഒരു കഴുതയെ കണ്ടു. അപ്പോൾ അവിടുത്തേക്കത് ഇഷ്ടപ്പെട്ടില്ല. ഇബ്‌നുഅബ്ബാസ്(റ) പറഞ്ഞു: അല്ലാഹുവാണ് സത്യം, മുഖത്തിന്റെ അങ്ങേയറ്റത്ത് മാത്രമേ ഞാൻ അടയാളം വെക്കുകയുള്ളൂ. അദ്ദേഹത്തിന്റെ കഴുതയെ കൊണ്ടുവരാൻ ആജ്ഞാപിക്കുകയും അതിന്റെ വൃഷ്ഠ ഭാഗങ്ങളിൽ അടയാളം വെക്കുകയും ചെയ്തു. വൃഷ്ഠഭാഗങ്ങളിൽ ആദ്യമായി അടയാളം വെച്ച വ്യക്തി അദ്ദേഹമാണ്. (മു)', 'نَاعِمٍ أَبِي عَبْدِ اللَّهِ مَوْلَى أُمِّ سَلَمَةَ', 'ഉമ്മുസലമ(റ)', null, null, array['م']::text[], array['മു']::text[], 'فِي', null, 741, 742, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=162 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 415, 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: دَخَلْنَا عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِرْبَدًا وَهُوَ يَسِمُ غَنَمًا - قَالَ: أَحْسِبُهُ قَالَ- فِي آذَانِهَا. (م)', 'അനസ്(റ): ഞങ്ങൾ റസൂൽ(സ)യുടെ സന്നിധിയിൽ ചെന്നപ്പോൾ അവിടന്ന് കന്നുകാലികളെ കെട്ടുന്ന സ്ഥലത്ത് ആടിന് അടയാളം വെക്കുകയായിരുന്നു. നിവേദകൻ പറയുന്നു: അതിന്റെ ചെവികളിൽ എന്ന് അനസ്(റ) പറഞ്ഞിട്ടുണ്ടെന്നാണ് ഞാൻ വിചാരിക്കുന്നത്. (മു)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 742, 742, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=163 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 416, 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: لَمَّا وَلَدَتْ أُمُّ سُلَيْمٍ قَالَتْ لِي: يَا أَنَسُ، انْظُرْ هَذَا الْغُلَامَ فَلَا يُصِيبَنَّ شَيْئًا حَتَّى تَغْدُوَ بِهِ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُحَنِّكُهُ. قَالَ: فَغَدَوْتُ فَإِذَا هُوَ فِي الْحَائِطِ، وَعَلَيْهِ خَمِيصَةٌ حُرَيْثِيَّةٌ، وَهُوَ يَسِمُ الظَّهْرَ الَّذِي قَدِمَ عَلَيْهِ فِي الْفَتْحِ. (م)', 'അനസ്(റ): ഉമ്മുസുലൈം(റ) പ്രസവിച്ചപ്പോൾ എന്നോട് പറഞ്ഞു: ഓ അനസ്, ഈ കുട്ടിയെ താങ്കൾ നാളെ രാവിലെ നബി(സ)യുടെ തിരുസന്നിധിയിൽ കൊണ്ടുപോയി മധുരം നൽകുന്നത് വരെ അവൻ യാതൊന്നും കഴിക്കുകയോ കുടിക്കുകയോ ചെയ്യാതിരിക്കാൻ ശ്രദ്ധിക്കണം. അനസ്(റ) പറയുന്നു: അങ്ങനെ രാവിലെ ഞാൻ പോയപ്പോൾ തിരുമേനി(സ) തോട്ടപ്പണിക്കുള്ള വസ്ത്രം ധരിച്ച് തോട്ടത്തിലായിരുന്നു. അവിടന്ന് തനിക്ക് മക്കാവിജയത്തിന്റെ യുദ്ധമുതലായി ലഭിച്ച വാഹനമൃഗത്തിന് അടയാളം വെക്കുകയായിരുന്നു. (മു)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 742, 742, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=164 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 417, 'عَنْ عَبْدِ اللَّهِ بْنِ الْعَبَّاسِ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: كَانَ لِنَعْلِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قِبَالَانِ مَثْنِيٌّ شِرَاكُهُمَا. (جه)', 'അബ്ദുല്ലാഹിബ്‌നു അബ്ബാസ്(റ): നബി(സ)യുടെ ചെരുപ്പിന് രണ്ട് വാറുകളുണ്ടായിരുന്നു. വിരലുകൾക്കിടയിൽ വാറിനെ കെട്ടുന്ന വിരലിനെ പിടിച്ച് വെക്കുന്ന രണ്ട് വാറുകളുമുണ്ടായിരുന്നു. (ജ)', 'عَبْدِ اللَّهِ بْنِ الْعَبَّاسِ', 'അബ്ദുല്ലാഹിബ്‌നു അബ്ബാസ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 742, 742, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=165 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 418, 'عَنْ أَنَسٍ رضي الله عنه أَنَّهُ سئل :أَكَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي فِي نَعْلَيْهِ قَالَ: نَعَمْ. (خ)', 'അനസ്(റ): നബി(സ) അവിടുത്തെ രണ്ട് ചെരുപ്പുകളിലായിരുന്നോ നിസ്കരിച്ചതെന്ന് ചോദിക്കപ്പെട്ടപ്പോൾ അനസ്(റ) പറഞ്ഞു: അതെ. (ബു)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 742, 742, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=165 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 419, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: مِنَ السُّنَّةِ إِذَا جَلَسَ الرَّجُلُ أَنْ يَخْلَعَ نَعْلَيْهِ فَيَضَعَهُمَا بِجَنْبِهِ. (د)', 'ഇബ്നുഅബ്ബാസ്(റ): ഒരാൾ ഇരുന്നാൽ തന്റെ ചെരുപ്പ് അഴിച്ചുവെക്കലും അത് തന്റെ ഒരു ഭാഗത്ത് വെക്കലും സുന്നത്തിൽ പെട്ടതാകുന്നു. (ദ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 743, 743, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=166 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 420, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِذَا انْتَعَلَ أَحَدُكُمْ فَلْيَبْدَأْ بِالْيَمِينِ، وَإِذَا نَزَعَ فَلْيَبْدَأُ بِالشِّمَالِ، فَلْتَكُنِ الْيُمْنَى أَوَّلَهُمَا تُنْعَلُ وَآخِرَهُمَا تُنْزَعُ". حَسَنٌ صَحِيحٌ (ق,د,ت,ن,جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറയുന്നു. "നിങ്ങൾ ചെരുപ്പ് ധരിക്കുകയാണെങ്കിൽ വലതുകൊണ്ടും അഴിക്കുകയാണെങ്കിൽ ഇടതുകൊണ്ടും തുടങ്ങട്ടെ. വലതു കാലിലാവട്ടെ ആദ്യമായി ചെരുപ്പിടുന്നതും അവസാനമായി അഴിക്കുന്നതും." (ബു,മു,ദ,തു,ന,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 743, 743, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=166 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 421, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِذَا انْتَعَلَ أَحَدُكُمْ فَلْيَبْدَأْ بِالْيَمِينِ، وَإِذَا خَلَعَ فَلْيَبْدَأْ بِالشِّمَالِ، لِيُنْعِلْهُمَا جَمِيعًا أَوْ لِيَخْلَعْهُمَا جَمِيعًا". (م)', 'അബൂഹുറൈറ(റ): "നിങ്ങളാരെങ്കിലും ചെരുപ്പ് ധരിക്കുകയാണെങ്കിൽ വലതു കൊണ്ടും അഴിക്കുകയാണെങ്കിൽ ഇടതു കൊണ്ടും തുടങ്ങട്ടെ. ഒന്നുകിൽ അവ രണ്ടും ധരിക്കുകയും അല്ലെങ്കിൽ രണ്ടും അഴിച്ചുവെക്കുകയോ ചെയ്യട്ടെ." (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 743, 743, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=166 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 422, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُحِبُّ التَّيَمُّنَ مَا اسْتَطَاعَ فِي شَأْنِهِ كُلِّهِ: فِي طَهُورِهِ، وَتَرَجُّلِهِ، وَنَعْلِهِ، وَسِوَاكِهِ. (ق,د,ت,ن,جه)', 'ആഇശ(റ): എല്ലാ കാര്യത്തിലും കഴിയും വിധം വലതിനെ മുന്തിക്കാൻ നബി(സ) ഇഷ്ടപ്പെട്ടിരുന്നു; അവിടുന്ന് ശുദ്ധിയാക്കുമ്പോഴും, മുടിചീകുമ്പോഴും, ചെരുപ്പ് ധരിക്കുമ്പോഴും, മിസ്വാക്ക് ചെയ്യുമ്പോഴുമെല്ലാം. (ബു,മു,ദ,തു,ന,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 743, 743, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=166 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 423, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِذَا لَبِسْتُمْ وَإِذَا تَوَضَّأْتُمْ فَابْدَءُوا بِأَيَامِنِكُمْ". (د,ت,جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങൾ വസ്ത്രം ധരിക്കുകയോ വുളൂ ചെയ്യുകയോ ആണെങ്കിൽ നിങ്ങളുടെ വലത് കൊണ്ട് തുടങ്ങുക." (ദ,തു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 743, 743, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=166 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 424, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: نَهَى النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنْ يَنْتَعِلَ الرَّجُلُ قَائِمًا. (د,ت,جه)', 'അബൂഹുറൈറ(റ): നിന്ന് ചെരുപ്പ് ധരിക്കൽ റസൂൽ(സ) നിരോധിച്ചിരിക്കുന്നു. (ദ,തു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 743, 743, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=167 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 425, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا يَمْشِي أَحَدُكُمْ فِي نَعْلٍ وَاحِدٍ، وَلَا خُفٍّ وَاحِدٍ، لِيَخْلَعْهُمَا جَمِيعًا، أَوْ لِيَمْشِ فِيهِمَا جَمِيعًا". (ق,د,ت,ن,جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറയുന്നു: "നിങ്ങൾ ഒറ്റച്ചെരുപ്പിലോ ഒറ്റ ഖുഫ്ഫയിലോ നടക്കരുത്, അത് രണ്ടും അഴിച്ചുവെക്കുകയോ അല്ലെങ്കിൽ രണ്ടും ധരിക്കുകയോ ചെയ്യുക. (മു,ബു,ദ,തു,ന,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['മു','ബു','ദ','തു','ന','ജ']::text[], null, null, 743, 744, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=168 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 426, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِذَا انْقَطَعَ شِسْعُ أَحَدِكُمْ فَلَا يَمْشِ فِي نَعْلٍ وَاحِدَةٍ حَتَّى يُصْلِحَ شِسْعَهُ، وَلَا يَمْشِ فِي خُفٍّ وَاحِدٍ، وَلَا يَأْكُلْ بِشِمَالِهِ". (م,د)', 'ജാബിർ(റ): നബി(സ) പറയുന്നു: "നിങ്ങളിലാരുടെയെങ്കിലും ചെരുപ്പിന്റെ വാറ് പൊട്ടിയാൽ അത് ശരിയാക്കുന്നതുവരെ ഒറ്റ ചെരുപ്പിൽ നടക്കരുത്. ഒറ്റ ഖുഫ്ഫയിലും നടക്കരുത്. ഇടത് കൊണ്ട് ഭക്ഷിക്കുകയും ചെയ്യരുത്." (മു,ദ)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['م','د']::text[], array['മു','ദ']::text[], null, null, 744, 744, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=168 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 427, 'عَنْ أَبِي رَزِينٍ قَالَ: رَأَيْتُ أَبَا هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ، يَضْرِبُ بِيَدِهِ عَلَى جَبْهَتِهِ يَقُولُ: يَا أَهْلَ الْعِرَاقِ، تَزْعُمُونَ أَنِّي أَكْذِبُ عَلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ؟ أَشْهَدُ لَسَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "إِذَا انْقَطَعَ شِسْعُ نَعْلِ أَحَدِكُمْ فَلَا يَمْشِ فِي الْأُخْرَى حَتَّى يُصْلِحَهَا". (ن)', 'അബൂറസീൻ(റ): അബൂഹുറൈറ(റ) നെറ്റിയിലടിച്ച് പറയുന്നതായി ഞാൻ കണ്ടു: ഇറാഖുകാരെ, റസൂൽ(സ)യുടെ മേൽ ഞാൻ കള്ളം പറയുന്നുവെന്ന് നിങ്ങൾ വാദിക്കുന്നുവോ? റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടുവെന്ന് ഞാൻ സാക്ഷ്യം വഹിക്കുന്നു. "നിങ്ങളുടെ ചെരുപ്പിന്റെ വാറ് പൊട്ടിയാൽ അത് ശരിയാക്കുന്നത് വരെ മറ്റേതിൽ നിങ്ങൾ നടക്കരുത്." (ന)', 'أَبِي رَزِينٍ قَالَ', 'അബൂറസീൻ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 744, 744, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=168 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 428, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: قَالَتْ: رُبَّمَا مَشَى النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي نَعْلٍ وَاحِدَةٍ. (ت)', 'ആഇശ(റ): നബി(സ) ചിലപ്പോഴെല്ലാം ഒറ്റച്ചെരുപ്പിൽ നടന്നിട്ടുണ്ട്. (തു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 744, 744, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=169 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 429, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّهَا مَشَتْ بِنَعْلٍ وَاحِدَةٍ. (ت)', 'ആഇശ(റ): മഹതി ഒറ്റ ചെരുപ്പിൽ നടന്നിട്ടുണ്ട്. (തു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 744, 744, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=169 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 430, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ فِي غَزْوَةٍ غَزَوْنَاهَا: "اسْتَكْثِرُوا مِنَ النِّعَالِ، فَإِنَّ الرَّجُلَ لَا يَزَالُ رَاكِبًا مَا انْتَعَلَ". (م)', 'ജാബിറുബ്നു അബ്ദുല്ല(റ): ഞങ്ങൾ പങ്കെടുത്ത ഒരു യുദ്ധത്തിൽ നബി(സ) പറയുന്നതായി ഞാൻ കേട്ടു: "നിങ്ങൾ ചെരുപ്പ് ധരിക്കുന്നത് അധികരിപ്പിക്കുക. ചെരുപ്പുധരിക്കുന്നിടത്തോളം അവൻ വാഹനം കയറിയവനാണ്." (മു)', 'جَابِرٍ', 'ജാബിറുബ്നു അബ്ദുല്ല(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 744, 744, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=169 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 431, 'عَنْ بُرَيْدَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّجَاشِيَّ أَهْدَى لِرَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ خُفَّيْنِ سَاذَجَيْنِ أَسْوَدَيْنِ، فَلَبِسَهُمَا. (جه)', 'ബുറൈദ(റ): നജാശി രാജാവ് റസൂൽ(സ)ക്ക് കറുത്ത മൃദുവായ രണ്ട് ഖുഫ്ഫകൾ സമ്മാനമായി നൽകി. അവിടുന്ന് അവ ധരിച്ചു. (ജ)', 'بُرَيْدَةَ', 'ബുറൈദ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 744, 744, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=170 where b.volume_id=2 and b.book_no=8 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
